def _add_watermark(ax, text="@bot_radar", alpha=0.12):
    """Tambah watermark tipis di pojok kanan bawah axes."""
    ax.text(0.995, 0.012, text,
            transform=ax.transAxes,
            ha="right", va="bottom",
            fontsize=6.5, color=THEME["txt"],
            alpha=alpha, style="italic",
            zorder=99)

