# ── Patch 15-5: Shared HTTP Session (connection pooling + auto-retry) ─────────
def _make_http_session() -> requests.Session:
    """
    Singleton HTTP session dengan:
    - Connection pool (50 koneksi, 10 host simultan) → skip TCP handshake ulang
    - Auto-retry 3x dengan exponential backoff untuk 429/5xx
    - Default User-Agent supaya tidak 403 di Yahoo/IDX
    """
    sess = requests.Session()
    _retry_cfg = _UrlRetry(
        total=3,
        backoff_factor=0.4,          # delay: 0.4, 0.8, 1.6 detik
        status_forcelist=[429, 500, 502, 503, 504],
        allowed_methods=["HEAD", "GET", "POST"],
        raise_on_status=False,
    )
    _adapter = HTTPAdapter(
        max_retries=_retry_cfg,
        pool_connections=10,          # max host simultan
        pool_maxsize=50,              # max koneksi per host
        pool_block=False,
    )
    sess.mount("https://", _adapter)
    sess.mount("http://",  _adapter)
    sess.headers.update({
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                      "AppleWebKit/537.36 (KHTML, like Gecko) "
                      "Chrome/124.0.0.0 Safari/537.36",
        "Accept-Encoding": "gzip, deflate, br",
    })
    return sess

_http = _make_http_session()          # satu session, dipakai seluruh bot

