# ╔══════════════════════════════════════════════════════════════════════════════╗
# ║  YAHOO FINANCE RATE LIMITER + TICKER CACHE                                 ║
# ║  Anti-ban saat 20+ member hit bersamaan                                    ║
# ╠══════════════════════════════════════════════════════════════════════════════╣
# ║  1. CACHE  — hasil yf disimpan 5 menit. Request ke-2 ticker sama           ║
# ║             langsung dari cache, tanpa hit Yahoo sama sekali.               ║
# ║  2. QUEUE  — semua request masuk antrian global, max 2/detik.               ║
# ║  3. DEDUP  — ticker sama yang sedang diproses tidak duplikat request.       ║
# ╚══════════════════════════════════════════════════════════════════════════════╝

import queue   as _q_mod
import hashlib as _hashlib

_YF_CACHE: dict      = {}
_YF_CACHE_LOCK       = threading.Lock()
_YF_CACHE_TTL        = 300    # 5 menit
_YF_CACHE_TTL_LIVE   = 60     # 1 menit untuk harga live
_YF_QUEUE            = _q_mod.Queue()
_YF_PENDING: dict    = {}
_YF_PENDING_LOCK     = threading.Lock()
_YF_REQ_INTERVAL     = 0.5   # detik antar request (max 2/detik)

def _yf_cache_key(label: str, *args, **kwargs) -> str:
    raw = f"{label}|{args}|{sorted(kwargs.items())}"
    return _hashlib.md5(raw.encode()).hexdigest()

def _yf_cache_get(key: str):
    with _YF_CACHE_LOCK:
        entry = _YF_CACHE.get(key)
        if entry:
            result, exp = entry
            if _dt.datetime.now().timestamp() < exp:
                return result, True
            del _YF_CACHE[key]
    return None, False

def _yf_cache_set(key: str, result, ttl: int = _YF_CACHE_TTL):
    with _YF_CACHE_LOCK:
        _YF_CACHE[key] = (result, _dt.datetime.now().timestamp() + ttl)

def _yf_cache_clear_expired():
    now = _dt.datetime.now().timestamp()
    with _YF_CACHE_LOCK:
        for k in [k for k,(_, ts) in _YF_CACHE.items() if ts < now]:
            del _YF_CACHE[k]

def _yf_queue_worker():
    """Worker serial — proses request YF max 2/detik."""
    last_req = 0.0
    while True:
        try:
            item = _YF_QUEUE.get(timeout=5)
            if item is None: break
            fn, args, kwargs, cache_key, ttl, event, box = item

            # throttle
            gap = _dt.datetime.now().timestamp() - last_req
            if gap < _YF_REQ_INTERVAL:
                time.sleep(_YF_REQ_INTERVAL - gap)

            data, hit = _yf_cache_get(cache_key)
            if not hit:
                try:
                    data = fn(*args, **kwargs)
                    if data is not None:
                        _yf_cache_set(cache_key, data, ttl)
                except Exception as _e:
                    logger.warning("yf_worker: %s", _e)
                    data = None
                last_req = _dt.datetime.now().timestamp()

            box.append(data)
            event.set()
            with _YF_PENDING_LOCK:
                _YF_PENDING.pop(cache_key, None)
            _YF_QUEUE.task_done()
        except _q_mod.Empty:
            _yf_cache_clear_expired()
        except Exception as _e:
            logger.error("yf_worker fatal: %s", _e)

threading.Thread(target=_yf_queue_worker, daemon=True, name="yf_rate_limiter").start()

def yf_safe_call(fn, *args, ttl: int = _YF_CACHE_TTL, timeout: float = 30.0, **kwargs):
    """
    Wrapper aman semua panggilan Yahoo Finance.
    Cache 5 menit + rate limit 2/detik + dedup in-flight request.
    """
    label = fn.__name__ if hasattr(fn, '__name__') else str(fn)
    key   = _yf_cache_key(label, *args, **kwargs)

    # 1. Cache hit
    data, hit = _yf_cache_get(key)
    if hit:
        return data

    # 2. Dedup
    with _YF_PENDING_LOCK:
        if key in _YF_PENDING:
            ev, existing = _YF_PENDING[key], True
        else:
            ev = threading.Event()
            _YF_PENDING[key] = ev
            existing = False

    if existing:
        ev.wait(timeout=timeout)
        data, _ = _yf_cache_get(key)
        return data

    # 3. Queue
    box = []
    _YF_QUEUE.put((fn, args, kwargs, key, ttl, ev, box))
    ev.wait(timeout=timeout)
    return box[0] if box else None

# ── Helper wrappers siap pakai ──────────────────────────────
def _silent_yf_download_safe(*args, ttl=_YF_CACHE_TTL, **kwargs):
    """yf.download + cache + rate limit. Drop-in untuk _silent_yf_download."""
    import yfinance as _yfi
    def _do():
        with _contextlib.redirect_stdout(_io_sup.StringIO()), \
             _contextlib.redirect_stderr(_io_sup.StringIO()):
            return _yfi.download(*args, **kwargs)
    _do.__name__ = f"yf_dl_{args[0] if args else 'x'}"
    return yf_safe_call(_do, ttl=ttl)

def _safe_ticker_history(ticker: str, ttl=_YF_CACHE_TTL, **kwargs):
    """yf.Ticker.history + cache + rate limit."""
    import yfinance as _yfi
    def _do():
        with _contextlib.redirect_stdout(_io_sup.StringIO()), \
             _contextlib.redirect_stderr(_io_sup.StringIO()):
            return _yfi.Ticker(ticker).history(**kwargs)
    _do.__name__ = f"yf_hist_{ticker}"
    return yf_safe_call(_do, ttl=ttl)

def _safe_ticker_info(ticker: str, ttl=600):
    """yf.Ticker.info + cache 10 menit."""
    import yfinance as _yfi
    def _do():
        with _contextlib.redirect_stdout(_io_sup.StringIO()), \
             _contextlib.redirect_stderr(_io_sup.StringIO()):
            return _yfi.Ticker(ticker).info or {}
    _do.__name__ = f"yf_info_{ticker}"
    return yf_safe_call(_do, ttl=ttl) or {}

# Janitor: bersihkan cache expired tiap 10 menit
def _cache_janitor():
    while True:
        time.sleep(600)
        _yf_cache_clear_expired()
        with _YF_CACHE_LOCK:
            logger.info("YF Cache: %d entries aktif", len(_YF_CACHE))

threading.Thread(target=_cache_janitor, daemon=True, name="yf_cache_janitor").start()
