def get_admin_ids():
    """Ambil set admin_id dari DB + ADMIN_IDS hardcoded."""
    ids = set(ADMIN_IDS)
    try:
        with _db_lock:
            conn = _db_conn(); c = conn.cursor()
            c.execute("SELECT user_id FROM admins")
            ids.update(int(row[0]) for row in c.fetchall() if row[0])
            conn.close()
    except: pass
    return ids

def is_admin(user_id):
    """True jika user_id adalah admin (hardcoded atau dari DB).
    Normalize type: int vs string mismatch dari Telegram parser.
    """
    try:
        uid_int = int(user_id)
    except (TypeError, ValueError):
        return False
    return uid_int in get_admin_ids()

