def db_signal_update_result(kode, harga_now, result, ts_check):
    """Fix 3: Update result via rowid subquery — tidak bisa update sinyal yang salah."""
    with _db_lock:
        conn = _db_conn(); c = conn.cursor()
        c.execute("""UPDATE signal_history SET harga_check=?,result=?,ts_check=?
                     WHERE rowid=(
                         SELECT rowid FROM signal_history
                         WHERE kode=? AND result IS NULL
                         ORDER BY ts_signal DESC LIMIT 1
                     )""",
                  (harga_now, result, ts_check, kode))
        conn.commit(); conn.close()

def db_winrate_stats():
    """Hitung win rate dari signal_history."""
    with _db_lock:
        conn = _db_conn(); c = conn.cursor()
        c.execute("SELECT result, COUNT(*) FROM signal_history WHERE result IS NOT NULL GROUP BY result")
        rows = c.fetchall()
        c.execute("SELECT COUNT(*) FROM signal_history")
        total = c.fetchone()[0]
        c.execute("SELECT COUNT(*) FROM signal_history WHERE result IS NULL")
        pending = c.fetchone()[0]
        conn.close()
    stats = {r[0]: r[1] for r in rows}
    return stats, total, pending

