# ── 3. TTL DATA CACHE ────────────────────────────────────────
_data_cache  = {}
_cache_lock  = threading.Lock()
CACHE_TTL    = 300  # 5 menit

def cache_get(key):
    with _cache_lock:
        item = _data_cache.get(key)
        if item:
            ttl = item.get("ttl") or CACHE_TTL
            if (time.time() - item["ts"]) < ttl:
                return item["data"]
        return None

def cache_set(key, data, ttl=None):
    with _cache_lock:
        _data_cache[key] = {"data": data, "ts": time.time(), "ttl": ttl}

def cache_clear_expired():
    now = time.time()
    with _cache_lock:
        stale = [k for k, v in _data_cache.items()
                 if (now - v["ts"]) > CACHE_TTL * 2]
        for k in stale:
            del _data_cache[k]

# ── 4. MESSAGE QUEUE + RATE LIMIT HANDLER ───────────────────
_tg_queue       = _queue.Queue(maxsize=500)
_SEND_DELAY     = 0.07          # ~14 msg/detik, aman untuk Telegram
_MSG_LOG_LOCK   = threading.Lock()

def _tg_send_text_raw(chat_id, text, parse_mode="Markdown",
                       thread_id=None, token=None):
    """Kirim teks Telegram dengan retry + rate limit handling."""
    tok = token or BOT_TOKEN
    url = f"https://api.telegram.org/bot{tok}/sendMessage"
    payload = {"chat_id": chat_id, "text": text, "parse_mode": parse_mode}
    if thread_id:
        payload["message_thread_id"] = thread_id
    for attempt in range(4):
        try:
            r    = _http.post(url, data=payload, timeout=12)
            resp = r.json()
            if resp.get("ok"):
                mid = resp["result"]["message_id"]
                db_catat_msg(mid, "radar")
                return mid
            err = resp.get("description", "")
            if "429" in str(resp.get("error_code","")) or "Too Many" in err:
                wait = int(resp.get("parameters", {}).get("retry_after", 5)) + 1
                logger.warning("Rate limited, tunggu %ds (attempt %d)", wait, attempt+1)
                time.sleep(wait)
            elif "message is too long" in err.lower():
                # Potong dan kirim ulang
                text = text[:3500] + "\n...(dipotong)"
                payload["text"] = text
            else:
                logger.warning("Telegram error: %s", err)
                break
        except Exception as e:
            logger.warning("Send attempt %d gagal: %s", attempt+1, e)
            time.sleep(2 ** attempt)
    return None

def _tg_send_photo_raw(chat_id, photo_buf, caption="",
                        thread_id=None, token=None):
    tok = token or BOT_TOKEN
    url = f"https://api.telegram.org/bot{tok}/sendPhoto"
    for attempt in range(3):
        try:
            photo_buf.seek(0)
            data  = {"chat_id": chat_id, "caption": caption,
                     "parse_mode": "Markdown"}
            if thread_id:
                data["message_thread_id"] = thread_id
            files = {"photo": ("chart.png", photo_buf, "image/png")}
            r     = _http.post(url, files=files, data=data, timeout=60)
            resp  = r.json()
            if resp.get("ok"):
                mid = resp["result"]["message_id"]
                db_catat_msg(mid, "radar")
                return mid
            err = resp.get("description", "")
            if "429" in str(resp.get("error_code","")) or "Too Many" in err:
                wait = int(resp.get("parameters", {}).get("retry_after", 5)) + 1
                time.sleep(wait)
            else:
                break
        except Exception as e:
            logger.warning("Photo attempt %d gagal: %s", attempt+1, e)
            time.sleep(3)
    return None

# ── 5. WATCHDOG THREAD ───────────────────────────────────────
_BOT_START_TIME    = time.time()
_last_heartbeat    = time.time()
_heartbeat_lock    = threading.Lock()

def _hb():
    """Catat heartbeat — dipanggil di main loop."""
    global _last_heartbeat
    with _heartbeat_lock:
        _last_heartbeat = time.time()

def loop_watchdog():
    """Monitor kesehatan bot. Notif admin jika stall > 30 menit DI JAM TRADING (07:30-17:30 WIB).
    Di luar jam trading TIDAK kirim alert — normal tidak ada aktivitas.
    PENTING: watchdog TIDAK self-heartbeat agar elapsed benar-benar mencerminkan
    inaktivitas main loop. Maks 3 peringatan per incident, lalu diam (tidak spam)."""
    time.sleep(180)  # Grace period 3 menit setelah startup
    _last_alert_time  = [0.0]   # waktu terakhir kirim peringatan
    _warn_count       = [0]     # counter peringatan per incident
    while True:
        try:
            elapsed = time.time() - _last_heartbeat
            now_wib_dt = now_wib()
            now_h = now_wib_dt.hour + now_wib_dt.minute / 60.0

            # Reset counter kalau bot pulih (elapsed < 10 menit)
            if elapsed < 600:
                if _warn_count[0] > 0:
                    logger.info("Watchdog: bot pulih (elapsed %.0f detik)", elapsed)
                _warn_count[0] = 0

            elif elapsed > 1800:  # stall > 30 menit
                # Hanya alert di JAM TRADING: 07:30 – 17:30 WIB
                if 7.5 <= now_h < 17.5:
                    since_last_warn = time.time() - _last_alert_time[0]
                    # Throttle: maks 1x per 60 menit, maks 3 total per incident
                    if since_last_warn >= 3600 and _warn_count[0] < 3:
                        menit = int(elapsed / 60)
                        pesan_warn = (
                            f"⚠️ *RADAR BOT WARNING* (#{_warn_count[0]+1}/3)\n"
                            f"Tidak ada aktivitas selama *{menit} menit*.\n"
                            f"Main loop mungkin hang — cek server segera!\n"
                            f"⏰ {now_wib_dt.strftime('%H:%M:%S')} WIB"
                        )
                        for adm_id in get_admin_ids():
                            try: _tg_send_text_raw(adm_id, pesan_warn)
                            except: pass
                        logger.critical("Watchdog: bot stall %d menit! (warn #%d)",
                                        menit, _warn_count[0]+1)
                        _last_alert_time[0] = time.time()
                        _warn_count[0] += 1
                    elif _warn_count[0] >= 3:
                        logger.warning("Watchdog: sudah 3 peringatan, tidak kirim lagi")
        except Exception as e:
            logger.error("Watchdog error: %s", e)
        time.sleep(300)  # cek tiap 5 menit

# ── 6. WATCHLIST AUTO-REFRESH ────────────────────────────────
_wl_refresh_interval = 6 * 3600  # 6 jam
_last_wl_refresh     = 0.0

def loop_wl_autorefresh():
    """Refresh watchlist dari IDX secara periodik tanpa restart bot."""
    global watchlist, _last_wl_refresh
    time.sleep(60)  # Grace period
    while True:
        try:
            if (time.time() - _last_wl_refresh) >= _wl_refresh_interval:
                baru = refresh_watchlist()
                if len(baru) > 50:
                    watchlist       = baru
                    _last_wl_refresh = time.time()
                    logger.info("Watchlist auto-refresh: %d saham", len(watchlist))
        except Exception as e:
            logger.error("WL refresh error: %s", e)
        time.sleep(1800)  # cek tiap 30 menit

# ── 7. MULTI-ADMIN MANAGEMENT ───────────────────────────────
def proses_cmd_admin_mgmt(text_raw, user_id, dest):
    """Handler /addadmin /deladmin /listadmin."""
    parts = text_raw.strip().split()
    cmd   = parts[0].lower().lstrip("/")

    if cmd == "listadmin":
        rows = db_list_admins()
        base = list(ADMIN_IDS)
        pesan  = "👮 *DAFTAR ADMIN BOT*\n━━━━━━━━━━━━━━━━━━━━\n"
        pesan += f"🔒 Hardcoded: `{'`, `'.join(str(x) for x in base)}`\n"
        if rows:
            pesan += "\n📋 Dari DB:\n"
            for uid, nama in rows:
                pesan += f"• {nama} — `{uid}`\n"
        else:
            pesan += "\n_(Belum ada admin tambahan dari DB)_\n"
        pesan += f"\n⏰ {now_wib().strftime('%H:%M')} WIB"
        dest_kirim_teks(dest, pesan)
        return

    if cmd == "addadmin" and len(parts) >= 2:
        try:
            target_id = int(parts[1])
        except:
            dest_kirim_teks(dest, "⚠️ Format: `/addadmin USER_ID`"); return
        nama_new = " ".join(parts[2:]) if len(parts) > 2 else f"Admin-{target_id}"
        db_add_admin(target_id, nama_new)
        dest_kirim_teks(dest,
            f"✅ *Admin ditambahkan!*\n"
            f"🆔 ID   : `{target_id}`\n"
            f"👤 Nama : {nama_new}\n"
            f"Admin baru bisa gunakan semua command admin.")
        logger.info("Admin baru ditambahkan: %d (%s) oleh %d", target_id, nama_new, user_id)
        return

    if cmd == "deladmin" and len(parts) >= 2:
        try:
            target_id = int(parts[1])
        except:
            dest_kirim_teks(dest, "⚠️ Format: `/deladmin USER_ID`"); return
        if target_id in ADMIN_IDS:
            dest_kirim_teks(dest, "⛔ Admin hardcoded tidak bisa dihapus dari sini.\nEdit ADMIN_IDS di script.")
            return
        db_del_admin(target_id)
        dest_kirim_teks(dest, f"✅ Admin `{target_id}` dihapus dari DB.")
        logger.info("Admin dihapus: %d oleh %d", target_id, user_id)
        return

    dest_kirim_teks(dest,
        "👮 *Admin Management*\n"
        "`/addadmin USER_ID Nama` — Tambah admin\n"
        "`/deladmin USER_ID` — Hapus admin\n"
        "`/listadmin` — Lihat semua admin")

# ── 8. TRAILING STOP ALERT ───────────────────────────────────
def proses_cmd_alert_v2(user_id, args, dest):
    """
    Handler /alert — versi v2 dengan trailing stop.
    Contoh:
      /alert BBCA 9500          → alert jika harga <= 9500
      /alert BBCA 9500 up       → alert jika harga >= 9500
      /alert BBCA trail 3       → trailing stop 3% dari harga tertinggi
      /alert list               → lihat semua alert aktif
      /alert del BBCA           → hapus alert BBCA
    """
    if not args:
        dest_kirim_teks(dest,
            "🔔 *Price Alert V2*\n"
            "━━━━━━━━━━━━━━━━━━━━━━\n"
            "`/alert BBCA 9500` — Alert jika BBCA ≤ Rp9.500 (default: bawah)\n"
            "`/alert BBCA 9500 up` — Alert jika BBCA ≥ Rp9.500\n"
            "`/alert BBCA trail 3` — 🔥 *Trailing Stop* 3% dari harga peak\n"
            "`/alert list` — Lihat semua alert aktif\n"
            "`/alert del BBCA` — Hapus alert BBCA")
        return

    if args[0].lower() == "list":
        rows = db_alert_list(user_id)
        if not rows:
            dest_kirim_teks(dest, "📋 Tidak ada alert aktif saat ini."); return
        pesan = "🔔 *Alert Aktif Kamu*\n━━━━━━━━━━━━━━━━━━━━━━\n"
        for (aid, kode, tipe, nilai, trail_pct, peak) in rows:
            if tipe == "trailing":
                pesan += (f"📌 *{kode}* — 🔥 Trailing {trail_pct:.1f}%"
                          f" (Peak: Rp{int(peak):,})\n")
            elif tipe == "above":
                pesan += f"📌 *{kode}* — 📈 Naik ≥ Rp{int(nilai):,}\n"
            else:
                pesan += f"📌 *{kode}* — 📉 Turun ≤ Rp{int(nilai):,}\n"
        dest_kirim_teks(dest, pesan)
        return

    if args[0].lower() == "del" and len(args) >= 2:
        kode = args[1].upper()
        db_alert_del(user_id, kode)
        dest_kirim_teks(dest, f"✅ Alert *{kode}* dihapus.")
        return

    # Set alert baru
    if len(args) < 2:
        dest_kirim_teks(dest, "⚠️ Format: `/alert KODE HARGA` atau `/alert KODE trail PERSEN`")
        return

    kode = args[0].upper()

    # Trailing stop
    if len(args) >= 3 and args[1].lower() == "trail":
        try:
            trail_pct = float(args[2])
        except:
            dest_kirim_teks(dest, "⚠️ Format: `/alert BBCA trail 3`"); return
        # Ambil harga sekarang sebagai peak awal
        try:
            info      = ambil_info_saham(kode + ".JK")
            peak      = info["harga"] if info else 0
        except:
            peak = 0
        db_alert_add(user_id, kode, "trailing", 0, trail_pct, peak)
        dest_kirim_teks(dest,
            f"✅ *Trailing Stop Alert*\n"
            f"📌 Saham  : *{kode}*\n"
            f"📉 Trail  : *{trail_pct:.1f}%* dari harga tertinggi\n"
            f"💰 Peak awal: Rp{int(peak):,}\n"
            f"_Bot akan notif jika harga turun {trail_pct}% dari peak._")
        return

    # Regular alert
    try:
        nilai = float(args[1])
    except:
        dest_kirim_teks(dest, "⚠️ Harga harus angka. Contoh: `/alert BBCA 9500`"); return

    tipe = "above" if (len(args) >= 3 and args[2].lower() in ["up","atas","naik"]) else "below"
    db_alert_add(user_id, kode, tipe, nilai)
    label = "naik ke" if tipe == "above" else "turun ke"
    dest_kirim_teks(dest,
        f"✅ *Alert Set!*\n"
        f"📌 Saham  : *{kode}*\n"
        f"🎯 Kondisi: Jika {label} ≤ Rp{int(nilai):,}\n"
        f"🔔 Notif akan masuk ke DM kamu.")

def loop_alert_v2():
    """Loop cek semua alert aktif (price + trailing stop) tiap 60 detik."""
    time.sleep(90)
    while True:
        try:
            rows = db_alert_get_all_active()
            tickers_harga = {}
            for (aid, uid, kode, tipe, nilai, trail_pct, peak) in rows:
                ticker = kode + ".JK"
                if ticker not in tickers_harga:
                    try:
                        info = ambil_info_saham(ticker)
                        tickers_harga[ticker] = info["harga"] if info else None
                    except:
                        tickers_harga[ticker] = None
                harga = tickers_harga.get(ticker)
                if not harga: continue

                fired = False
                if tipe == "trailing":
                    # Update peak jika harga naik
                    if harga > peak:
                        db_alert_update_peak(aid, harga)
                        peak = harga
                    # Cek apakah harga turun melewati trailing level
                    sl_price = peak * (1 - trail_pct / 100)
                    if harga <= sl_price:
                        fired = True
                        pesan_alert = (
                            f"🔥 *TRAILING STOP TRIGGERED!*\n"
                            f"📌 *{kode}* menyentuh trailing stop\n"
                            f"💰 Harga sekarang : Rp{int(harga):,}\n"
                            f"📈 Peak harga     : Rp{int(peak):,}\n"
                            f"📉 Trail level    : Rp{int(sl_price):,} (-{trail_pct:.1f}%)\n"
                            f"⚠️ _Pertimbangkan exit sekarang!_\n"
                            f"⏰ {now_wib().strftime('%H:%M')} WIB")
                elif tipe == "above" and harga >= nilai:
                    fired = True
                    pesan_alert = (
                        f"📈 *ALERT NAIK!*\n"
                        f"📌 *{kode}* : Rp{int(harga):,}\n"
                        f"🎯 Target  : Rp{int(nilai):,}\n"
                        f"⏰ {now_wib().strftime('%H:%M')} WIB")
                elif tipe == "below" and harga <= nilai:
                    fired = True
                    pesan_alert = (
                        f"📉 *ALERT TURUN!*\n"
                        f"📌 *{kode}* : Rp{int(harga):,}\n"
                        f"🎯 Level   : Rp{int(nilai):,}\n"
                        f"⏰ {now_wib().strftime('%H:%M')} WIB")

                if fired:
                    try:
                        _tg_send_text_raw(uid, pesan_alert)
                    except: pass
                    db_alert_del_id(aid)
                    logger.info("Alert fired: %s %s uid=%s", tipe, kode, uid)
        except Exception as e:
            logger.error("loop_alert_v2: %s", e)
        time.sleep(60)

# ── 9. POSITION SIZING CALCULATOR ───────────────────────────
def proses_porto_size(user_id, args, dest):
    """
    /porto size KODE HARGA_BELI HARGA_SL MODAL [RISK%]
    Hitung berapa lot yang aman dibeli berdasarkan risk per trade.
    Contoh: /porto size BBCA 9500 9200 10000000 2
    """
    if len(args) < 4:
        dest_kirim_teks(dest,
            "📐 *Position Sizing Calculator*\n"
            "Format: `/porto size KODE HARGA_BELI SL MODAL [RISK%]`\n\n"
            "Contoh:\n"
            "`/porto size BBCA 9500 9200 10000000 2`\n"
            "_(modal 10jt, risk 2%, SL di 9200)_\n\n"
            "Risk% default = 2%")
        return
    try:
        kode       = args[0].upper()
        # ── Patch 15-5: Decimal untuk presisi finansial ──────
        harga_beli = Decimal(str(args[1]))
        harga_sl   = Decimal(str(args[2]))
        modal      = Decimal(str(args[3]))
        risk_pct   = Decimal(str(args[4])) if len(args) >= 5 else Decimal("2.0")
    except:
        dest_kirim_teks(dest, "⚠️ Cek format angka kamu."); return

    if harga_sl >= harga_beli:
        dest_kirim_teks(dest, "⚠️ Stop Loss harus lebih rendah dari harga beli."); return

    _100         = Decimal("100")
    risk_rp      = (modal * risk_pct / _100).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
    risk_lembar  = (harga_beli - harga_sl).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
    max_lembar   = (risk_rp / risk_lembar).quantize(Decimal("1"), rounding=ROUND_DOWN) if risk_lembar > 0 else Decimal(0)
    max_lot      = int(max_lembar / 100)          # 1 lot = 100 lembar
    modal_dipakai = Decimal(max_lot * 100) * harga_beli
    pct_modal    = float(modal_dipakai / modal * _100) if modal > 0 else 0.0
    sl_pct       = float(risk_lembar / harga_beli * _100)
    emj_rr       = "✅" if risk_pct <= 2 else ("⚠️" if risk_pct <= 3 else "❌")

    dest_kirim_teks(dest,
        f"📐 *Position Sizing — {kode}*\n"
        f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
        f"💰 Modal        : Rp {int(modal):,}\n"
        f"⚠️ Risk         : {float(risk_pct):.1f}% = Rp {int(risk_rp):,}\n"
        f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
        f"📌 Harga Beli   : Rp {int(harga_beli):,}\n"
        f"🛑 Stop Loss    : Rp {int(harga_sl):,} (-{sl_pct:.1f}%)\n"
        f"📉 Risk/lembar  : Rp {int(risk_lembar):,}\n"
        f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
        f"📦 Max Lot      : *{max_lot} lot* ({max_lot*100:,} lembar)\n"
        f"💵 Modal Dipakai: Rp {int(modal_dipakai):,} ({pct_modal:.1f}%)\n"
        f"{emj_rr} _Risk {float(risk_pct):.1f}% per trade {'— sudah sesuai manajemen risiko' if risk_pct <= 2 else '— pertimbangkan kurangi risiko'}_")

# ── 10. SIGNAL TRACK RECORD / WIN RATE ──────────────────────
def proses_cmd_winrate(dest):
    """
    /winrate — Tampilkan statistik akurasi sinyal bot.
    Bot cek harga sinyal 3 hari kemudian — jika naik > 2% = profit.
    """
    stats, total, pending = db_winrate_stats()
    if total == 0:
        dest_kirim_teks(dest,
            "📊 *Win Rate Bot*\n"
            "Belum ada data sinyal yang dicek.\n"
            "Data akan terkumpul setelah beberapa sesi trading."); return

    profit    = stats.get("profit", 0)
    loss      = stats.get("loss", 0)
    be        = stats.get("break_even", 0)
    checked   = total - pending
    wr_pct    = (profit / checked * 100) if checked > 0 else 0
    emj_wr    = "★" if wr_pct >= 60 else ("✅" if wr_pct >= 50 else "⚠️")

    bar_profit = int(wr_pct / 10)
    bar_loss   = 10 - bar_profit
    bar_visual = "🟩" * bar_profit + "🟥" * bar_loss

    dest_kirim_teks(dest,
        f"📊 *WIN RATE BOT RADAR*\n"
        f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
        f"📈 Total sinyal : *{total}*\n"
        f"✅ Sudah dicek  : *{checked}*\n"
        f"⏳ Pending cek  : *{pending}*\n"
        f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
        f"🟢 Profit  : *{profit}* sinyal\n"
        f"🔴 Loss    : *{loss}* sinyal\n"
        f"⚪ BE/Skip  : *{be}* sinyal\n"
        f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
        f"{emj_wr} *Win Rate : {wr_pct:.1f}%*\n"
        f"{bar_visual}\n"
        f"_Kriteria: Naik >2% dalam 3 hari = profit_\n"
        f"⏰ {now_wib().strftime('%H:%M')} WIB")

def loop_signal_checker():
    """Cek outcome sinyal 3 hari setelah sinyal terdeteksi."""
    while True:
        try:
            batas = time.time() - 3 * 86400   # 3 hari lalu
            with _db_lock:
                conn = _db_conn(); c = conn.cursor()
                c.execute("""SELECT id,kode,harga_sinyal FROM signal_history
                             WHERE result IS NULL AND ts_signal < ?
                             LIMIT 20""", (batas,))
                rows = c.fetchall(); conn.close()
            for (sid, kode, h_sinyal) in rows:
                try:
                    info = ambil_info_saham(kode + ".JK")
                    if not info: continue
                    h_now = info["harga"]
                    gain  = (h_now - h_sinyal) / h_sinyal * 100
                    if   gain >=  2.0: result = "WIN"
                    elif gain <= -2.0: result = "LOSS"
                    else:              result = "BE"
                    db_signal_update_result(kode, h_now, result, time.time())
                    logger.info("Signal check %s: %s (%.1f%%)", kode, result, gain)
                    time.sleep(0.5)
                except: pass
        except Exception as e:
            logger.error("loop_signal_checker: %s", e)
        time.sleep(3600)  # cek tiap 1 jam

# ── 11. PERSONAL WATCHLIST + MY RADAR ───────────────────────
def proses_cmd_mywl(user_id, args, dest):
    """Handler /mywl."""
    if not args:
        daftar = db_mywl_list(user_id)
        if not daftar:
            dest_kirim_teks(dest,
                "📋 *Watchlist Pribadiku Kosong*\n\n"
                "`/mywl add BBCA` — Tambah saham\n"
                "`/mywl del BBCA` — Hapus saham\n"
                "`/mywl list` — Lihat daftar\n"
                "`/mywl clear` — Kosongkan\n"
                "`/myradar` — Scan & radar watchlist pribadimu")
            return
        pesan = (f"📋 *Watchlist Pribadimu* ({len(daftar)} saham)\n"
                 f"━━━━━━━━━━━━━━━━━━━━━━\n"
                 + ", ".join(f"*{k}*" for k in daftar) + "\n\n"
                 f"Ketik `/myradar` untuk scan dan radar saham ini.")
        dest_kirim_teks(dest, pesan)
        return

    cmd  = args[0].lower()
    if cmd in ("add", "tambah") and len(args) >= 2:
        kode = args[1].upper()
        db_mywl_add(user_id, kode)
        dest_kirim_teks(dest, f"✅ *{kode}* ditambahkan ke watchlist pribadimu.")
        return
    if cmd in ("del", "hapus") and len(args) >= 2:
        kode = args[1].upper()
        db_mywl_del(user_id, kode)
        dest_kirim_teks(dest, f"✅ *{kode}* dihapus dari watchlist pribadimu.")
        return
    if cmd in ("list", "lihat"):
        daftar = db_mywl_list(user_id)
        if not daftar:
            dest_kirim_teks(dest, "📋 Watchlist pribadimu kosong."); return
        pesan = (f"📋 *Watchlist Pribadimu* ({len(daftar)} saham)\n"
                 + ", ".join(f"*{k}*" for k in daftar))
        dest_kirim_teks(dest, pesan)
        return
    if cmd == "clear":
        db_mywl_clear(user_id)
        dest_kirim_teks(dest, "🗑️ Watchlist pribadi dikosongkan."); return

    dest_kirim_teks(dest, "⚠️ Perintah tidak dikenal. Ketik `/mywl` untuk bantuan.")

def proses_cmd_myradar(user_id, args, dest):
    """Radar V3 hanya untuk saham di watchlist pribadi user."""
    daftar = db_mywl_list(user_id)
    if not daftar:
        dest_kirim_teks(dest,
            "📋 Watchlist pribadimu kosong.\n"
            "Tambah dulu: `/mywl add BBCA`"); return

    top_n     = int(args[0]) if args and args[0].isdigit() else min(len(daftar), 10)
    min_score = int(args[1]) if len(args) >= 2 and args[1].isdigit() else 0

    tickers = [k + ".JK" for k in daftar]
    dest_kirim_teks(dest,
        f"⚡ *My Radar — {len(tickers)} saham pribadimu*\n"
        f"⏳ Scanning...")

    hasil = []
    with ThreadPoolExecutor(max_workers=10) as ex:
        futs = {ex.submit(_scan_satu_radar_v3, t): t for t in tickers}
        for f in as_completed(futs):
            try:
                r = f.result(timeout=15)
                if r and r["score"] >= min_score:
                    hasil.append(r)
            except: pass

    hasil_sorted = sorted(hasil, key=lambda x: x["score"], reverse=True)
    top = hasil_sorted[:top_n]

    if not top:
        dest_kirim_teks(dest,
            f"📊 *My Radar Selesai*\n"
            f"Tidak ada saham yang lolos filter saat ini.\n"
            f"⏰ {now_wib().strftime('%H:%M')} WIB"); return

    medal = ["🥇","🥈","🥉","4️⃣","5️⃣","6️⃣","7️⃣","8️⃣","9️⃣","🔟"]
    pesan = (f"*▸ MY RADAR — Top {len(top)}*\n"
             f"📅 {now_wib().strftime('%d-%m-%Y %H:%M')} WIB\n"
             f"━━━━━━━━━━━━━━━━━━━━━━\n")
    for i, s in enumerate(top):
        prev = db_radar_get_prev(s["kode"])
        delta_str = ""
        if prev:
            delta = s["score"] - prev[0]
            delta_str = f" (▲{delta:+d})" if delta > 0 else (f" (▼{delta:+d})" if delta < 0 else " (=)")
        alasan_str = " | ".join(s["alasan"][:2]) if s["alasan"] else "-"
        label = "▲▲" if s["score"] >= 80 else ("▲" if s["score"] >= 65 else ("·" if s["score"] >= 50 else "📊"))
        gain_a = "📈" if s["gain"] >= 0 else "📉"
        pesan += (f"{medal[i]} *{s['kode']}* Score:`{s['score']}`{delta_str} {label}\n"
                  f"   Rp{int(s['harga']):,}  {gain_a}`{s['gain']:+.2f}%`  Vol `{s['vol_x']}×`\n"
                  f"   _{alasan_str}_\n"
                  f"   ─────────────────\n")
    pesan += "⚠️ _Bukan rekomendasi. DYOR._"
    dest_kirim_teks(dest, pesan)

# ── 12. MARKET BREADTH DASHBOARD ─────────────────────────────
def proses_cmd_breadth(dest):
    """
    /breadth — Market breadth: advance/decline, fear/greed proxy,
               top gainer/loser hari ini.
    """
    dest_kirim_teks(dest, "📊 Menghitung market breadth IHSG... ⏳")

    sample_tickers = [
        "BBCA","BBRI","BMRI","BBNI","TLKM","ASII","ICBP","UNVR","PGAS","ANTM",
        "ADRO","PTBA","TPIA","INDF","CPIN","SMGR","JSMR","KLBF","MIKA","EXCL",
        "BREN","AMMN","MDKA","GOTO","BUKA","ARTO","EMTK","SIDO","KAEF","UNTR",
        "SMRA","BSDE","CTRA","LPKR","PWON","MAPI","ACES","LPPF","AMRT","TBIG",
    ]
    advance = 0; decline = 0; unchanged = 0
    total_vol = 0; gainers = []; losers = []

    def _cek(kode):
        info = ambil_info_saham(kode+".JK")
        if not info: return None
        return {"kode": kode, "gain": info.get("gain",0), "vol": info.get("volume",0)}

    with ThreadPoolExecutor(max_workers=15) as ex:
        futs = {ex.submit(_cek, k): k for k in sample_tickers}
        for f in as_completed(futs):
            try:
                r = f.result(timeout=10)
                if not r: continue
                g = r["gain"]
                total_vol += r.get("vol", 0)
                if   g >  0.5: advance += 1; gainers.append(r)
                elif g < -0.5: decline += 1; losers.append(r)
                else:          unchanged += 1
            except: pass

    total = advance + decline + unchanged
    if total == 0:
        dest_kirim_teks(dest, "❌ Data market breadth tidak tersedia saat ini."); return

    # Advance/Decline Ratio
    adr = advance / decline if decline > 0 else float("inf")

    # Fear & Greed Proxy (0–100)
    # Formula sederhana: (advance/total)*100 dikombinasi momentum
    fg_score = int((advance / total) * 100)
    if   fg_score >= 75: fg_label = "🟢 EXTREME GREED"
    elif fg_score >= 60: fg_label = "💚 GREED"
    elif fg_score >= 40: fg_label = "🟡 NEUTRAL"
    elif fg_score >= 25: fg_label = "🟠 FEAR"
    else:                fg_label = "🔴 EXTREME FEAR"

    # Bar visual
    bar_a = int(advance / total * 10)
    bar_d = 10 - bar_a
    bar   = "🟢" * bar_a + "🔴" * bar_d

    # Top 3 gainer & loser
    gainers.sort(key=lambda x: x["gain"], reverse=True)
    losers.sort(key=lambda x: x["gain"])
    top3g = gainers[:3]
    top3l = losers[:3]

    pesan  = f"📊 *MARKET BREADTH IHSG*\n"
    pesan += f"📅 {now_wib().strftime('%d/%m/%Y %H:%M')} WIB\n"
    pesan += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
    pesan += f"📈 Naik    : *{advance}* saham\n"
    pesan += f"📉 Turun   : *{decline}* saham\n"
    pesan += f"➖ Stagnan : *{unchanged}* saham\n"
    pesan += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
    pesan += f"📊 A/D Ratio : *{adr:.2f}*\n"
    pesan += f"{bar}\n"
    pesan += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
    pesan += f"  Fear & Greed : *{fg_score}* — {fg_label}\n"
    pesan += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
    pesan += "  *Top Gainer:*\n"
    for r in top3g:
        pesan += f"  📈 *{r['kode']}* +{r['gain']:.2f}%\n"
    pesan += "💀 *Top Loser:*\n"
    for r in top3l:
        pesan += f"  📉 *{r['kode']}* {r['gain']:.2f}%\n"
    pesan += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
    pesan += f"_Sample: {total} saham likuid IHSG_"
    dest_kirim_teks(dest, pesan)

# ── 13. RADAR V3 SCORE HISTORY (upgrade jalankan_radar_v3) ──
def _radar_v3_dengan_history(dest, top_n=5, min_score=70):
    """
    Versi radar V3 yang menyimpan history skor ke DB
    dan menampilkan delta skor dibanding kemarin.
    Override fungsi asli jalankan_radar_v3.
    """
    watchlist_lokal = watchlist.copy()
    total_saham     = len(watchlist_lokal)
    jam_str         = now_wib().strftime("%H:%M:%S")
    tgl_str         = now_wib().strftime("%d-%m-%Y")

    mulai_msg = (
        f"⚡ *RADAR V3 — QUANT ENGINE*\n"
        f"📅 {tgl_str}  ⏰ {jam_str} WIB\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"🔍 Scanning *{total_saham}* saham IHSG...\n"
        f"🧵 Parallel 20 threads  •  🔄 History tracking ON\n"
        f"⏳ Estimasi: *< 15 detik*"
    )
    dest_kirim_teks(dest, mulai_msg)
    logger.info("RADAR V3 dimulai: %d saham", total_saham)

    t_mulai = time.time()
    hasil   = []

    with ThreadPoolExecutor(max_workers=20) as executor:
        futures = {executor.submit(_scan_satu_radar_v3, t): t
                   for t in watchlist_lokal}
        for future in as_completed(futures):
            try:
                r = future.result(timeout=15)
                if r and r["score"] >= min_score:
                    hasil.append(r)
                    # Simpan ke history DB
                    db_radar_save(r["kode"], r["score"], r["rsi"],
                                  r["vol_x"], r["harga"], r["gain"], r["alasan"])
            except: pass

    durasi = round(time.time() - t_mulai, 1)
    hasil_sorted = sorted(hasil, key=lambda x: x["score"], reverse=True)
    top10 = hasil_sorted[:top_n]

    logger.info("RADAR V3 selesai: %ds, %d kandidat, Top%d tampil",
                durasi, len(hasil), len(top10))

    if not top10:
        dest_kirim_teks(dest,
            f"📊 *Radar V3 Selesai*\n"
            f"⏱ {durasi}s — Tidak ada saham lolos filter\n"
            f"⏰ {now_wib().strftime('%H:%M:%S')} WIB")
        return

    medal = ["🥇","🥈","🥉","4️⃣","5️⃣","6️⃣","7️⃣","8️⃣","9️⃣","🔟"]
    pesan  = f"*▸ RADAR IHSG — TOP {len(top10)}*\n"
    pesan += f"📅 {tgl_str}  ⏰ {now_wib().strftime('%H:%M:%S')} WIB\n"
    pesan += f"⚡ {total_saham} saham  •  {durasi}s  •  {len(hasil)} kandidat\n"
    pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"

    for i, s in enumerate(top10):
        # Delta skor vs kemarin
        prev  = db_radar_get_prev(s["kode"], hari=1)
        delta_str = ""
        if prev:
            delta = s["score"] - prev[0]
            if   delta > 0:  delta_str = f" ▲`+{delta}`"
            elif delta < 0:  delta_str = f" ▼`{delta}`"
            else:            delta_str = " ➡`±0`"

        gain_arrow = "📈" if s["gain"] >= 0 else "📉"
        alasan_str = " | ".join(s["alasan"][:2]) if s["alasan"] else "-"
        if   s["score"] >= 80: label = "🚀 SUPER BULLISH"
        elif s["score"] >= 65: label = "🔥 STRONG BUY"
        elif s["score"] >= 50: label = "· BULLISH"
        else:                   label = "📊 KANDIDAT"

        pesan += (
            f"{medal[i]} *{s['kode']}*  Score:`{s['score']}`{delta_str}  {label}\n"
            f"   Rp{int(s['harga']):,}  {gain_arrow}`{s['gain']:+.2f}%`\n"
            f"   RSI`{s['rsi']}`  Vol`{s['vol_x']}×`  Vola`{s['vol5']}%`\n"
            f"   🧠 _{alasan_str}_\n"
            f"   ─────────────────────\n"
        )

    pesan += (
        f"80+▲▲  65+▲  50+·  30+📊\n"
        f"▲▼ = Delta skor vs kemarin\n"
        f"⚠️ _Bukan rekomendasi. DYOR._"
    )
    dest_kirim_teks(dest, pesan)

    for s in top10[:3]:
        time.sleep(1)
        buf = buat_chart_buffer(s["ticker"])
