# ── 14. VOLUME SPIKE REAL-TIME ALERT ────────────────────────
VOL_SPIKE_THREAD_ID  =  5762  # kirim ke topic radar
VOL_SPIKE_MULTIPLIER = 5.0               # spike jika vol > 5× rata-rata
VOL_SPIKE_HARGA_MIN  = 100               # filter saham < Rp100
VOL_SPIKE_COOLDOWN   = 90                # menit cooldown per saham

def _cek_vol_spike_satu(ticker):
    """Cek apakah satu saham mengalami volume spike hari ini."""
    try:
        cached = cache_get(f"vs_{ticker}")
        if cached: return cached

        url = (f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}"
               f"?range=1mo&interval=1d")
        r    = _http.get(url, headers={"User-Agent": "Mozilla/5.0"}, timeout=8)
        data = r.json()
        res  = data["chart"]["result"][0]
        meta = res.get("meta", {})
        q    = res["indicators"]["quote"][0]
        vols = [v for v in q["volume"] if v is not None]
        if len(vols) < 10: return None
        harga = meta.get("regularMarketPrice") or q["close"][-1]
        if not harga or harga < VOL_SPIKE_HARGA_MIN: return None
        avg20 = sum(vols[-21:-1]) / 20 if len(vols) >= 21 else sum(vols[:-1]) / max(1, len(vols)-1)
        last  = vols[-1]
        ratio = last / avg20 if avg20 > 0 else 0
        result = {"kode": ticker.replace(".JK",""), "harga": harga,
                  "vol_x": round(ratio,1), "vol_now": last, "vol_avg": avg20}
        cache_set(f"vs_{ticker}", result)
        return result
    except:
        return None

def jam_trading_aktif():
    """Alias publik — cek jam trading IDX (09:00-16:00 WIB, Senin-Jumat)."""
    now = now_wib()
    if now.weekday() >= 5:
        return False
    jam = now.hour * 60 + now.minute
    return (9 * 60) <= jam <= (16 * 60)

def loop_vol_spike():
    """Scan volume spike real-time tiap 10 menit saat jam trading."""
    time.sleep(120)
    while True:
        try:
            if not jam_trading_aktif():
                time.sleep(120); continue

            wl_sample = watchlist.copy()
            spike_list = []

            # Patch 15-5: pakai _IO_POOL persistent, bukan buat pool baru tiap scan
            futs = {_IO_POOL.submit(_cek_vol_spike_satu, t): t for t in wl_sample}
            for f in as_completed(futs):
                try:
                    r = f.result(timeout=12)
                    if r and r["vol_x"] >= VOL_SPIKE_MULTIPLIER:
                        spike_list.append(r)
                except: pass

            spike_list.sort(key=lambda x: x["vol_x"], reverse=True)
            now_str = now_wib().strftime("%H:%M")
            tgl_str = now_wib().strftime("%d-%m-%Y")

            for s in spike_list[:8]:  # Maksimal 8 alert per round
                kode = s["kode"]
                if not db_vol_spike_check(kode, VOL_SPIKE_COOLDOWN):
                    continue
                db_vol_spike_mark(kode)
                icon   = "🐳" if s["vol_x"] >= 10 else "🔥"
                entry  = int(s["harga"])
                tp_vs  = int(entry * 1.03)   # TP +3%
                sl_vs  = int(entry * 0.985)  # SL -1.5%
                pesan  = (
                    f"{icon} *VOLUME SPIKE ALERT V8*\n"
                    f"📅 {tgl_str}  ⏰ {now_str} WIB\n"
                    f"━━━━━━━━━━━━━━━━━━━━━━\n"
                    f"📌 *{kode}*  •  Rp {entry:,}\n"
                    f"⚡ Volume   : *{s['vol_x']:.1f}× rata-rata*\n"
                    f"📊 Vol hari ini : {int(s['vol_now']):,}\n"
                    f"📊 Vol avg 20hr : {int(s['vol_avg']):,}\n"
                    f"━━━━━━━━━━━━━━━━━━━━━━\n"
                    f"✅ TP: Rp {tp_vs:,} *(+3%)*   🛑 SL: Rp {sl_vs:,} *(-1.5%)*\n"
                    f"⚠️ _Tap tombol di bawah untuk konfirmasi_"
                )
                keyboard = _build_intraday_keyboard(kode, entry, tp_vs, sl_vs, "volspike")
                _send_with_inline(CHAT_ID, pesan, keyboard, thread_id=VOL_SPIKE_THREAD_ID)
                logger.info("Vol spike alert: %s %.1fx", kode, s["vol_x"])
                time.sleep(2)
        except Exception as e:
            logger.error("loop_vol_spike: %s", e)
        time.sleep(600)  # scan tiap 10 menit

# ── Fix 7: INTRADAY MOMENTUM SCANNER ─────────────────────────
def _scan_intraday_satu(ticker):
    """Scan satu saham untuk momentum intraday 15m."""
    try:
        url = (f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}"
               f"?range=1d&interval=15m")
        r = _http.get(url, headers={"User-Agent": "Mozilla/5.0"}, timeout=10)
        data = r.json()["chart"]["result"][0]
        q    = data["indicators"]["quote"][0]
        ts   = data["timestamp"]

        closes  = [c for c in q["close"]  if c is not None]
        volumes = [v for v in q["volume"] if v is not None]
        if len(closes) < 6 or len(volumes) < 6:
            return None

        close_now  = closes[-1]
        close_30m  = closes[-3]   # ~30 menit lalu
        vol_now    = volumes[-1]
        vol_avg    = sum(volumes[-8:-1]) / 7 if len(volumes) >= 8 else sum(volumes[:-1]) / max(len(volumes)-1, 1)

        if close_30m <= 0:
            return None

        gain_30m = (close_now - close_30m) / close_30m * 100
        vol_x    = vol_now / vol_avg if vol_avg > 0 else 0

        kode = ticker.replace(".JK", "")

        # BUY: naik > 1.5% dalam 30m + volume spike > 3x (V9.1)
        if gain_30m >= 1.5 and vol_x >= 3.0 and close_now >= 100:
            return {"kode": kode, "ticker": ticker,
                    "harga": close_now, "gain_30m": round(gain_30m, 2),
                    "vol_x": round(vol_x, 1), "direction": "buy"}

        # SELL: turun > 1.5% dalam 30m + volume spike > 3x (BARU V9.1 — SELL alert)
        if gain_30m <= -1.5 and vol_x >= 3.0 and close_now >= 100:
            return {"kode": kode, "ticker": ticker,
                    "harga": close_now, "gain_30m": round(gain_30m, 2),
                    "vol_x": round(vol_x, 1), "direction": "sell"}

    except Exception:
        pass
    return None

def _jam_trading_aktif_intraday():
    """Cek apakah sekarang jam trading IDX (09:00–16:00 WIB Senin-Jumat)."""
    now = now_wib()
    if now.weekday() >= 5:      # Sabtu/Minggu
        return False
    jam = now.hour * 60 + now.minute
    return (9 * 60) <= jam <= (16 * 60)

def loop_intraday_scanner():
    """
    Fix 7: Scan 150 saham likuid tiap 15 menit saat jam trading.
    Deteksi breakout/momentum intraday yang tidak tertangkap daily scanner.
    """
    time.sleep(180)  # delay awal 3 menit setelah bot start
    _alerted_intraday = {}   # {kode: timestamp} — cooldown 30 menit per saham

    while True:
        try:
            if not _jam_trading_aktif_intraday():
                time.sleep(120)
                continue

            # IDEA #2: Adaptive Universe — cull saham volume rendah
            _adap_base = list(LIKUID_150)
            try:
                _adap_filtered = get_adaptive_universe(_adap_base)
            except Exception:
                _adap_filtered = _adap_base
            universe = [k + ".JK" for k in _adap_filtered]
            hasil    = []
            now_ts   = time.time()

            # Patch 15-5: _IO_POOL persistent
            futs = {_IO_POOL.submit(_scan_intraday_satu, t): t for t in universe}
            for f in as_completed(futs):
                try:
                    r = f.result(timeout=12)
                    if r:
                        # Cooldown 30 menit per saham
                        last_alert = _alerted_intraday.get(r["kode"], 0)
                        if now_ts - last_alert >= 1800:
                            hasil.append(r)
                except Exception:
                    pass

            # Pisahkan BUY dan SELL
            hasil_buy  = [s for s in hasil if s.get("direction", "buy") == "buy"]
            hasil_sell = [s for s in hasil if s.get("direction") == "sell"]
            hasil_buy.sort(key=lambda x: x["gain_30m"], reverse=True)
            hasil_sell.sort(key=lambda x: x["gain_30m"])  # paling negatif duluan

            now_str = now_wib().strftime("%H:%M")
            tgl_str = now_wib().strftime("%d-%m-%Y")
            dest_rv3_intr = _get_radar_dest()

            # ── BUY alerts (max 3) ──────────────────────────
            for s in hasil_buy[:3]:
                kode   = s["kode"]
                _alerted_intraday[kode] = now_ts
                entry  = int(s["harga"])
                tp_intr= int(entry * 1.025)  # TP +2.5%
                sl_intr= int(entry * 0.985)  # SL -1.5%
                pesan  = (
                    f"⚡ *INTRADAY SCALP ALERT V9 — BUY*\n"
                    f"📅 {tgl_str}  ⏰ {now_str} WIB\n"
                    f"━━━━━━━━━━━━━━━━━━━━━━\n"
                    f"📌 *{kode}*  •  Entry: Rp {entry:,}\n"
                    f"🚀 Naik 30m  : *+{s['gain_30m']}%*\n"
                    f"⚡ Volume    : *{s['vol_x']}× rata-rata*\n"
                    f"━━━━━━━━━━━━━━━━━━━━━━\n"
                    f"✅ TP: Rp {tp_intr:,} *(+2.5%)*   🛑 SL: Rp {sl_intr:,} *(-1.5%)*\n"
                    f"⚖️ R/R: 1:1.7  |  _Scalp 15–30 menit_"
                )
                keyboard = _build_intraday_keyboard(kode, entry, tp_intr, sl_intr, "intraday")
                _send_with_inline(
                    dest_rv3_intr.get("chat_id", CHAT_ID) if "chat_id" in dest_rv3_intr else CHAT_ID,
                    pesan, keyboard,
                    thread_id=dest_rv3_intr.get("thread_id", THREAD_ID_RADAR)
                )
                logger.info("Intraday BUY alert: %s +%.1f%% vol %.1fx",
                            kode, s["gain_30m"], s["vol_x"])
                time.sleep(1)

            # ── SELL alerts (max 3) — BARU V9.1 ─────────────
            for s in hasil_sell[:3]:
                kode  = s["kode"]
                _alerted_intraday[kode] = now_ts
                harga = int(s["harga"])
                pesan = (
                    f"🔴 *INTRADAY SELL ALERT V9 — EXIT*\n"
                    f"📅 {tgl_str}  ⏰ {now_str} WIB\n"
                    f"━━━━━━━━━━━━━━━━━━━━━━\n"
                    f"📌 *{kode}*  •  Harga: Rp {harga:,}\n"
                    f"📉 Turun 30m : *{s['gain_30m']:.1f}%*\n"
                    f"⚡ Volume    : *{s['vol_x']}× rata-rata*\n"
                    f"━━━━━━━━━━━━━━━━━━━━━━\n"
                    f"⚠️ *Distribusi/panic sell terdeteksi!*\n"
                    f"💡 _Jika hold posisi ini → pertimbangkan CUT LOSS_\n"
                    f"🚫 Jangan beli dulu — tunggu stabil"
                )
                _tg_send_text_raw(
                    dest_rv3_intr.get("chat_id", CHAT_ID) if "chat_id" in dest_rv3_intr else CHAT_ID,
                    pesan,
                    thread_id=dest_rv3_intr.get("thread_id", THREAD_ID_RADAR)
                )
                logger.info("Intraday SELL alert: %s %.1f%% vol %.1fx",
                            kode, s["gain_30m"], s["vol_x"])
                time.sleep(1)

        except Exception as e:
            logger.error("loop_intraday_scanner: %s", e)

        time.sleep(900)  # scan tiap 15 menit

