# ============================================================
# --- AUTO DELETE PESAN LAMA (1 minggu) ---
# ============================================================
MSG_LOG_FILE   = os.path.join(DATA_DIR, "msg_log_radar.json")
DELETE_DETIK   = 7 * 24 * 3600  # 1 minggu

def _load_log():
    if _os.path.exists(MSG_LOG_FILE):
        try: return json.load(open(MSG_LOG_FILE))
        except: pass
    return []

def _save_log(log):
    try: json.dump(log, open(MSG_LOG_FILE, "w"))
    except: pass

def _catat(msg_id):
    log = _load_log()
    log.append({"id": msg_id, "ts": time.time()})
    _save_log(log)

def hapus_pesan_lama():
    log = _load_log(); sekarang = time.time(); sisa = []
    for item in log:
        if sekarang - item["ts"] >= DELETE_DETIK:
            try:
                _http.post(
                    f"https://api.telegram.org/bot{BOT_TOKEN}/deleteMessage",
                    data={"chat_id": CHAT_ID, "message_id": item["id"]}, timeout=10)
                print(f"🗑️  Pesan {item['id']} dihapus (1 minggu)")
            except: pass
        else:
            sisa.append(item)
    _save_log(sisa)

def send_telegram_message(message):
    """Kirim pesan teks ke Telegram."""
    url = f"https://api.telegram.org/bot{BOT_TOKEN}/sendMessage"
    payload = {'chat_id': CHAT_ID, 'text': message, 'parse_mode': 'Markdown', 'message_thread_id': THREAD_ID_RADAR}
    try:
        r = _http.post(url, data=payload, timeout=10)
        resp = r.json()
        if resp.get("ok"):
            _catat(resp["result"]["message_id"])
        print("   ✅ Pesan berhasil dikirim!")
    except Exception as e:
        print(f"   ❌ Gagal kirim pesan: {e}")


def kirim_foto_telegram(photo_buffer, caption):
    """Kirim gambar chart ke Telegram dengan retry otomatis."""
    url = f"https://api.telegram.org/bot{BOT_TOKEN}/sendPhoto"
    for percobaan in range(1, 4):  # Maksimal 3x percobaan
        try:
            photo_buffer.seek(0)
            files = {'photo': ('chart.png', photo_buffer, 'image/png')}
            data  = {'chat_id': CHAT_ID, 'caption': caption, 'parse_mode': 'Markdown', 'message_thread_id': THREAD_ID_RADAR}
            r2   = _http.post(url, files=files, data=data, timeout=60)
            resp2 = r2.json()
            if resp2.get("ok"):
                _catat(resp2["result"]["message_id"])
            print("   ✅ Chart berhasil dikirim ke Telegram!")
            return
        except Exception as e:
            print(f"   ⚠️ Percobaan {percobaan}/3 gagal kirim chart: {e}")
            time.sleep(3)
    print("   ❌ Chart gagal dikirim setelah 3x percobaan.")


