@functools.lru_cache(maxsize=512)
def format_nilai(nilai):
    """Format angka ke satuan Jt / M / T."""
    if abs(nilai) >= 1_000_000_000_000:
        return f"{nilai / 1_000_000_000_000:.2f}T"
    elif abs(nilai) >= 1_000_000_000:
        return f"{nilai / 1_000_000_000:.2f}M"
    elif abs(nilai) >= 1_000_000:
        return f"{nilai / 1_000_000:.1f}Jt"
    else:
        return f"{nilai:,.0f}"



