def buat_dan_kirim_chart(ticker):
    """Unduh data saham, buat chart lengkap dengan indikator, dan kirim ke Telegram."""
    print(f"   📊 Membuat chart untuk {ticker}...")
    url = f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}?range=3mo&interval=1d"
    headers = {'User-Agent': 'Mozilla/5.0'}
    try:
        response = _http.get(url, headers=headers, timeout=10)
        data = response.json()
        timestamps = data['chart']['result'][0]['timestamp']
        quote      = data['chart']['result'][0]['indicators']['quote'][0]

        df = pd.DataFrame({
            'Open':   quote['open'],
            'High':   quote['high'],
            'Low':    quote['low'],
            'Close':  quote['close'],
            'Volume': quote['volume']
        })
        df.index = pd.to_datetime(timestamps, unit='s')
        df.dropna(inplace=True)

        if df.empty or len(df) < 20:
            print("   ⚠️ Data chart tidak cukup, dilewati.")
            return

        # Hitung semua indikator
        df = hitung_indikator(df)
        n  = len(df)

        def safe_plot(series, **kwargs):
            """Buat addplot hanya jika series punya nilai valid."""
            s = series.copy()
            if s.notna().sum() < 2:
                return None
            return mpf.make_addplot(s, **kwargs)

        # ── SUSUN ADDPLOT ────────────────────────────────────
        ap = []

        # Bollinger Bands (panel harga)
        for col, clr in [('BB_upper','#FF6B6B'),('BB_mid','#FFD93D'),('BB_lower','#6BCB77')]:
            p = safe_plot(df[col], panel=0, color=clr, linestyle='--', width=0.8)
            if p: ap.append(p)

        # VWAP
        p = safe_plot(df['VWAP'], panel=0, color='#C77DFF', width=1.5)
        if p: ap.append(p)

        # EMA 50 & 200
        p = safe_plot(df['EMA50'],  panel=0, color='#FFD700', width=1.2, linestyle='--')
        if p: ap.append(p)
        p = safe_plot(df['EMA200'], panel=0, color='#FF69B4', width=1.5, linestyle='--')
        if p: ap.append(p)

        # Ichimoku
        for col, clr, lw in [('Tenkan','#E040FB',1.0),('Kijun','#00E5FF',1.0),
                               ('SpanA','#00C957',0.8),('SpanB','#FF4500',0.8),
                               ('Chikou','#FFFFFF',0.8)]:
            ls = '--' if col in ('SpanA','SpanB') else 'solid'
            p  = safe_plot(df[col], panel=0, color=clr, width=lw, linestyle=ls)
            if p: ap.append(p)

        # Alligator
        for col, clr in [('Jaw','#0096FF'),('Teeth','#FF4500'),('Lips','#00C957')]:
            p = safe_plot(df[col], panel=0, color=clr, width=1.2)
            if p: ap.append(p)

        # RSI
        p = safe_plot(df['RSI'], panel=2, color='#FFA500', width=1.2, ylabel='RSI')
        if p: ap.append(p)
        ap.append(mpf.make_addplot([70]*n, panel=2, color='red',  linestyle='--', width=0.6))
        ap.append(mpf.make_addplot([30]*n, panel=2, color='lime', linestyle='--', width=0.6))

        # MACD
        p = safe_plot(df['MACD'],   panel=3, color='#00BFFF', width=1.0, ylabel='MACD')
        if p: ap.append(p)
        p = safe_plot(df['Signal'], panel=3, color='#FF6347', width=1.0)
        if p: ap.append(p)
        if df['MACDhist'].notna().sum() >= 2:
            mc2 = ['#00C957' if v >= 0 else '#FF4500' for v in df['MACDhist'].fillna(0)]
            ap.append(mpf.make_addplot(df['MACDhist'], panel=3, type='bar', color=mc2))

        # Stochastic
        p = safe_plot(df['StochK'], panel=4, color='#00BFFF', width=1.0, ylabel='Stoch')
        if p: ap.append(p)
        p = safe_plot(df['StochD'], panel=4, color='#FF6347', width=1.0)
        if p: ap.append(p)
        ap.append(mpf.make_addplot([80]*n, panel=4, color='red',  linestyle='--', width=0.6))
        ap.append(mpf.make_addplot([20]*n, panel=4, color='lime', linestyle='--', width=0.6))

        # ── STYLE ────────────────────────────────────────────
        mc = mpf.make_marketcolors(
            up='#00AA44', down='#FF2222',
            edge='inherit', wick='inherit',
            volume={'up': '#00AA44', 'down': '#FF2222'}
        )
        s = mpf.make_mpf_style(
            marketcolors=mc,
            gridstyle=':',
            gridcolor='#2A2D3A',
            facecolor='#0D1117',
            figcolor='#0D1117',
            y_on_right=True,
            rc={
                'text.color':      THEME['txt'],
                'axes.labelcolor': THEME['txt'],
                'xtick.color':     THEME['sub'],
                'ytick.color':     THEME['sub'],
                'axes.titlecolor': THEME['txt'],
            }
        )
        _apply_dark_rc()   # [FIX] force text putih sebelum mpf render

        nama = ticker.replace('.JK', '')
        buf  = io.BytesIO()

        mpf.plot(
            df, type='candle', style=s,
            addplot=ap,
            volume=True,
            panel_ratios=(4, 1, 1.2, 1.2, 1.2),
            title=f"\n{nama} — BB | VWAP | Ichi | EMA | Alligator | RSI | MACD | Stoch",
             figsize=(10, 9),
            savefig=dict(fname=buf, dpi=80, bbox_inches='tight')
        )
        buf.seek(0)

        caption_teks = (
            f"📊 *Chart Pro {nama}*\n"
            f"🟡 BB  •  🟣 VWAP  •  🟡 EMA50  •  🩷 EMA200\n"
            f"🟣 Tenkan  •  🔵 Kijun  •  Ichi Cloud\n"
            f"🔵 Jaw  •  🔴 Teeth  •  🟢 Lips _(Alligator)_\n"
            f"📉 RSI(14)  •  📈 MACD  •  📊 Stoch(14,3,3)"
        )
        kirim_foto_telegram(buf, caption_teks)

    except Exception as e:
        print(f"   ❌ Gagal membuat chart: {e}")


def buat_chart_buffer(ticker):
    """Sama seperti buat_dan_kirim_chart tapi return buffer (untuk kirim ke DM)."""
    url = f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}?range=3mo&interval=1d"
    headers = {'User-Agent': 'Mozilla/5.0'}
    try:
        response = _http.get(url, headers=headers, timeout=10)
        data = response.json()
        timestamps = data['chart']['result'][0]['timestamp']
        quote      = data['chart']['result'][0]['indicators']['quote'][0]
        df = pd.DataFrame({'Open': quote['open'], 'High': quote['high'],
                           'Low': quote['low'], 'Close': quote['close'], 'Volume': quote['volume']})
        df.index = pd.to_datetime(timestamps, unit='s')
        df.dropna(inplace=True)
        if df.empty or len(df) < 20:
            return None
        df = hitung_indikator(df)
        n  = len(df)
        def sp(series, **kwargs):
            s = series.copy()
            if s.notna().sum() < 2: return None
            return mpf.make_addplot(s, **kwargs)
        ap = []
        for col, clr in [('BB_upper','#FF6B6B'),('BB_mid','#FFD93D'),('BB_lower','#6BCB77')]:
            p = sp(df[col], panel=0, color=clr, linestyle='--', width=0.8)
            if p: ap.append(p)
        for col, clr, lw in [('VWAP','#C77DFF',1.5),('EMA50','#FFD700',1.2),('EMA200','#FF69B4',1.5)]:
            p = sp(df[col], panel=0, color=clr, width=lw)
            if p: ap.append(p)
        for col, clr, lw in [('Tenkan','#E040FB',1.0),('Kijun','#00E5FF',1.0),
                              ('SpanA','#00C957',0.8),('SpanB','#FF4500',0.8)]:
            p = sp(df[col], panel=0, color=clr, width=lw)
            if p: ap.append(p)
        for col, clr in [('Jaw','#0096FF'),('Teeth','#FF4500'),('Lips','#00C957')]:
            p = sp(df[col], panel=0, color=clr, width=1.2)
            if p: ap.append(p)
        p = sp(df['RSI'], panel=2, color='#FFA500', width=1.2, ylabel='RSI')
        if p: ap.append(p)
        ap.append(mpf.make_addplot([70]*n, panel=2, color='red', linestyle='--', width=0.6))
        ap.append(mpf.make_addplot([30]*n, panel=2, color='lime', linestyle='--', width=0.6))
        p = sp(df['MACD'], panel=3, color='#00BFFF', width=1.0, ylabel='MACD')
        if p: ap.append(p)
        p = sp(df['Signal'], panel=3, color='#FF6347', width=1.0)
        if p: ap.append(p)
        if df['MACDhist'].notna().sum() >= 2:
            mc2 = ['#00C957' if v >= 0 else '#FF4500' for v in df['MACDhist'].fillna(0)]
            ap.append(mpf.make_addplot(df['MACDhist'], panel=3, type='bar', color=mc2))
        p = sp(df['StochK'], panel=4, color='#00BFFF', width=1.0, ylabel='Stoch')
        if p: ap.append(p)
        p = sp(df['StochD'], panel=4, color='#FF6347', width=1.0)
        if p: ap.append(p)
        ap.append(mpf.make_addplot([80]*n, panel=4, color='red', linestyle='--', width=0.6))
        ap.append(mpf.make_addplot([20]*n, panel=4, color='lime', linestyle='--', width=0.6))
        mc  = mpf.make_marketcolors(up='#00AA44', down='#FF2222', edge='inherit', wick='inherit',
                                     volume={'up':'#00AA44','down':'#FF2222'})
        s   = mpf.make_mpf_style(marketcolors=mc, gridstyle=':', gridcolor='#2A2D3A',
                                  facecolor='#0D1117', figcolor='#0D1117', y_on_right=True,
                                  rc={
                                      'text.color':       THEME['txt'],
                                      'axes.labelcolor':  THEME['txt'],
                                      'xtick.color':      THEME['sub'],
                                      'ytick.color':      THEME['sub'],
                                      'axes.titlecolor':  THEME['txt'],
                                  })
        _apply_dark_rc()   # [FIX] force text putih sebelum mpf.plot render
        buf = io.BytesIO()
        fig, axlist = mpf.plot(df, type='candle', style=s, addplot=ap, volume=True,
                 panel_ratios=(4,1,1.2,1.2,1.2),
                 title=f"\n{ticker.replace('.JK','')} — BB|VWAP|Ichi|EMA|Alligator|RSI|MACD|Stoch",
                 figsize=(10,9),
                 returnfig=True)
        # Annotation + watermark on price panel
        try:
            ax_price = axlist[0]
            _annotate_candle_patterns(ax_price, df, n)
            _add_watermark(ax_price)
        except Exception:
            pass
        fig.savefig(buf, dpi=80, bbox_inches='tight', facecolor=THEME["bg"])
        plt.close(fig)
        buf.seek(0)
        return buf
    except:
        return None

_CK = {
    "bg"     : "#0A0A0F",
    "card"   : "#0E1420",
    "card2"  : "#111926",
    "grid"   : "#141E2E",
    "border" : "#1A2840",
    "txt"    : "#D1D4DC",
    "sub"    : "#5E7A93",
    "up"     : "#00C853",
    "dn"     : "#E53935",
    "entry"  : "#00E676",
    "tp1"    : "#40C4FF",
    "tp2"    : "#FFD740",
    "tp3"    : "#FF9100",
    "sl"     : "#FF5252",
    "vwap"   : "#CE93D8",
    "ema50"  : "#FFD700",
    "ema200" : "#FF69B4",
    "bb"     : "#2979FF",
    "macd"   : "#00B0FF",
    "sig"    : "#FF6090",
    "rsi"    : "#FFA726",
    "sto"    : "#00E5FF",
}


def _ck_rcset():
    plt.rcParams.update({
        "text.color"        : _CK["txt"],
        "axes.labelcolor"   : _CK["txt"],
        "xtick.color"       : _CK["sub"],
        "ytick.color"       : _CK["sub"],
        "legend.labelcolor" : _CK["txt"],
        "legend.facecolor"  : _CK["card"],
        "legend.edgecolor"  : _CK["border"],
        "figure.facecolor"  : _CK["bg"],
        "axes.facecolor"    : _CK["card"],
        "axes.edgecolor"    : _CK["border"],
        "grid.color"        : _CK["grid"],
        "savefig.facecolor" : _CK["bg"],
        "savefig.edgecolor" : _CK["bg"],
        "font.family"       : "monospace",
    })


def _ck_draw_level(ax, price, color, label, pct_str, lw=1.1, ls="--"):
    ax.axhline(price, color=color, linewidth=lw, linestyle=ls, alpha=0.85, zorder=4)
    ax.annotate(
        f" {label} {pct_str} ",
        xy=(1.0, price), xycoords=("axes fraction", "data"),
        xytext=(3, 0), textcoords="offset points",
        ha="left", va="center",
        fontsize=6.5, fontweight="bold", color=color,
        bbox=dict(boxstyle="round,pad=0.2", fc=_CK["card2"], ec=color, lw=0.6, alpha=0.9),
        zorder=6, clip_on=False,
    )


def _ck_score_bar(ax, score, x0=0.0, y=0.5, width=0.35, height=0.32):
    import matplotlib.patches as _mp
    bar_bg = _mp.FancyBboxPatch(
        (x0, y - height/2), width, height, boxstyle="round,pad=0.01",
        fc=_CK["card2"], ec=_CK["border"], lw=0.5,
        transform=ax.transAxes, zorder=3)
    ax.add_patch(bar_bg)
    fill_color = _CK["up"] if score >= 80 else (_CK["tp2"] if score >= 60 else _CK["tp3"])
    bar_fill = _mp.FancyBboxPatch(
        (x0, y - height/2), width * (score/100), height, boxstyle="round,pad=0.01",
        fc=fill_color, ec="none", alpha=0.85,
        transform=ax.transAxes, zorder=4)
    ax.add_patch(bar_fill)
    ax.text(x0 + width + 0.01, y, f"{score}/100",
            transform=ax.transAxes, ha="left", va="center",
            fontsize=7, fontweight="bold", color=fill_color, zorder=5)


def buat_chart_konfirm_v2(ticker: str, signal_info: dict = None, n_candles: int = 60):
    """
    Chart Konfirm V3 — Swing Edition.
    Layout: Candlestick + EMA9/21 cloud + EMA50 + VWAP + S/R | Volume+MA5 | RSI
    Entry/TP1/TP2/TP3/SL levels + header banner + signal badge.
    """
    si          = signal_info or {}
    pola_str    = si.get("pola",   "")
    sinyal_type = si.get("sinyal", "BUY").upper()
    entry_p     = float(si.get("entry", 0.0))
    sl_p        = float(si.get("sl",    0.0))
    score       = int(si.get("score",   0))
    regime      = si.get("regime", "")
    nama        = ticker.replace(".JK", "")

    # 1. FETCH & CLEAN
    try:
        url  = (f"https://query1.finance.yahoo.com/v8/finance/chart/"
                f"{ticker}?range=4mo&interval=1d")
        resp = _http.get(url, headers={"User-Agent": "Mozilla/5.0"}, timeout=12)
        data = resp.json()
        result     = data["chart"]["result"][0]
        timestamps = result["timestamp"]
        quote      = result["indicators"]["quote"][0]
        df = pd.DataFrame({
            "Open":   quote["open"],  "High":  quote["high"],
            "Low":    quote["low"],   "Close": quote["close"],
            "Volume": quote["volume"],
        })
        df.index = pd.to_datetime(timestamps, unit="s")
        df.dropna(inplace=True)
        if len(df) < 20:
            return None
        df = df.iloc[-n_candles:].copy()
    except Exception as ex:
        print(f"[chart_konfirm_v3] fetch gagal: {ex}")
        return None

    # 2. INDIKATOR
    close  = df["Close"]
    high   = df["High"]
    low    = df["Low"]
    volume = df["Volume"]
    n2     = len(df)

    ema9   = close.ewm(span=9,  adjust=False).mean()
    ema21  = close.ewm(span=21, adjust=False).mean()
    ema50  = close.ewm(span=50, adjust=False).mean()
    tp_    = (high + low + close) / 3
    vwap   = (tp_ * volume).cumsum() / volume.cumsum()
    rsi    = hitung_rsi_wilder(close)
    vol_ma5= volume.rolling(5).mean()

    # 3. AUTO LEVELS
    last_close = float(close.iloc[-1])
    if entry_p <= 0: entry_p = last_close
    if sl_p    <= 0: sl_p    = entry_p * 0.975
    risk    = max(entry_p - sl_p, 1)
    tp1_p   = entry_p + risk * 1.2
    tp2_p   = entry_p + risk * 2.2
    tp3_p   = entry_p + risk * 3.5
    def _pct(t, b): return f"{(t/b-1)*100:+.1f}%"
    sl_pct  = _pct(sl_p,  entry_p)
    tp1_pct = _pct(tp1_p, entry_p)
    tp2_pct = _pct(tp2_p, entry_p)
    tp3_pct = _pct(tp3_p, entry_p)
    rr      = (tp2_p - entry_p) / risk

    # 4. AUTO S/R
    def _auto_sr(hi, lo, n_piv=3, tol=0.015):
        levels = []
        hv = hi.values; lv = lo.values; nn = len(hv)
        for i in range(n_piv, nn - n_piv):
            if all(hv[i] >= hv[i-j] and hv[i] >= hv[i+j] for j in range(1, n_piv+1)):
                levels.append(("R", float(hv[i])))
            if all(lv[i] <= lv[i-j] and lv[i] <= lv[i+j] for j in range(1, n_piv+1)):
                levels.append(("S", float(lv[i])))
        merged = []
        for sr_t, pr in sorted(levels, key=lambda x: x[1]):
            if not any(abs(pr - p) / p < tol for _, p in merged):
                merged.append((sr_t, pr))
        return [(t, p) for t, p in merged
                if last_close * 0.70 <= p <= last_close * 1.30]

    sr_levels = _auto_sr(high, low)

    # 5. STYLE
    _ck_rcset()
    UP = "#00D4A0"; DN = "#FF4560"
    E9 = "#00D4A0"; E21 = "#FF7A7A"; E50 = "#F0A030"; VWAP_C = "#B07FFF"
    SR_S = "#00D4A0"; SR_R = "#FF4560"
    ENTRY_C = "#F0C040"; SL_C = "#FF4560"; TP_C = "#00D4A0"
    BG = "#080C12"; CARD = "#0C1220"; GRID = "#141E28"; BORDER = "#1A2438"
    TXT = "#DCE8F5"; SUB = "#4A6080"

    mc = mpf.make_marketcolors(
        up=UP, down=DN, edge="inherit", wick="inherit",
        volume={"up": UP, "down": DN}
    )
    style = mpf.make_mpf_style(
        marketcolors=mc, gridstyle=":", gridcolor=GRID,
        facecolor=CARD, figcolor=BG, y_on_right=True,
        rc={
            "axes.labelcolor": TXT, "xtick.color": SUB,
            "ytick.color": SUB, "text.color": TXT,
            "axes.facecolor": CARD, "figure.facecolor": BG,
            "axes.edgecolor": BORDER, "grid.color": GRID,
            "font.family": "monospace",
        }
    )

    # 6. ADDPLOTS
    def sp(series, **kw):
        s = series.copy()
        return mpf.make_addplot(s, **kw) if s.notna().sum() >= 2 else None

    ap = []
    for ser, col, lw, ls in [
        (ema9,    E9,     1.4, "-"),
        (ema21,   E21,    1.1, "-"),
        (ema50,   E50,    1.2, "--"),
        (vwap,    VWAP_C, 1.0, "--"),
    ]:
        p = sp(ser, panel=0, color=col, width=lw, linestyle=ls)
        if p: ap.append(p)
    p = sp(vol_ma5, panel=1, color=E50, width=1.0, secondary_y=False)
    if p: ap.append(p)
    p = sp(rsi, panel=2, color=_CK["rsi"], width=1.1, ylabel="RSI")
    if p: ap.append(p)
    for lvl, col_r in [(70, DN), (50, SUB), (30, UP)]:
        ap.append(mpf.make_addplot(
            [lvl]*n2, panel=2, color=col_r,
            linestyle="--" if lvl != 50 else ":", width=0.5))

    # 7. PLOT
    try:
        fig, axlist = mpf.plot(
            df, type="candle", style=style, addplot=ap,
            volume=True, panel_ratios=(5, 1, 1.6),
            figsize=(10, 8), returnfig=True, tight_layout=False
        )
    except Exception as ex:
        print(f"[chart_konfirm_v3] mpf.plot gagal: {ex}")
        return None

    ax_p = axlist[0]
    ax_r = axlist[4]

    # 8. EMA CLOUD FILL
    try:
        xs = list(range(n2))
        e9v = ema9.values; e21v = ema21.values
        ax_p.fill_between(xs, e9v, e21v, where=e9v >= e21v,
                          color=UP, alpha=0.10, zorder=2)
        ax_p.fill_between(xs, e9v, e21v, where=e9v <  e21v,
                          color=DN, alpha=0.10, zorder=2)
    except Exception:
        pass

    # 9. S/R LINES
    for sr_type, sr_price in sr_levels:
        col_sr = SR_S if sr_type == "S" else SR_R
        ax_p.axhline(sr_price, color=col_sr, linewidth=0.7,
                     linestyle="--", alpha=0.55, zorder=3)
        ax_p.annotate(
            f" {sr_type} {int(sr_price):,} ",
            xy=(1.0, sr_price), xycoords=("axes fraction", "data"),
            xytext=(3, 0), textcoords="offset points",
            ha="left", va="center", fontsize=6, color=col_sr,
            bbox=dict(boxstyle="round,pad=0.15", fc=CARD, ec=col_sr, lw=0.5, alpha=0.85),
            clip_on=False, zorder=6
        )

    # 10. LEVEL LINES
    ax_p.axhspan(sl_p,    entry_p, color=SL_C,    alpha=0.04, zorder=1)
    ax_p.axhspan(entry_p, tp2_p,   color=ENTRY_C, alpha=0.03, zorder=1)
    for price, color, label, pct_s, lw, ls in [
        (tp3_p,   TP_C,    f"TP3 {int(tp3_p):,}", tp3_pct, 0.9, "--"),
        (tp2_p,   TP_C,    f"TP2 {int(tp2_p):,}", tp2_pct, 0.9, "--"),
        (tp1_p,   TP_C,    f"TP1 {int(tp1_p):,}", tp1_pct, 0.9, "--"),
        (entry_p, ENTRY_C, f"ENTRY {int(entry_p):,}", "",   1.5, "-"),
        (sl_p,    SL_C,    f"SL {int(sl_p):,}",  sl_pct,  0.9, "--"),
    ]:
        ax_p.axhline(price, color=color, linewidth=lw, linestyle=ls, alpha=0.88, zorder=4)
        ax_p.annotate(
            f" {label} {pct_s} ",
            xy=(1.0, price), xycoords=("axes fraction", "data"),
            xytext=(3, 0), textcoords="offset points",
            ha="left", va="center", fontsize=6.5, fontweight="bold", color=color,
            bbox=dict(boxstyle="round,pad=0.2", fc=CARD, ec=color, lw=0.6, alpha=0.92),
            zorder=6, clip_on=False
        )

    # 11. SIGNAL BADGE
    try:
        pola_short = (pola_str.replace("🌅 ","").replace("⚔️ ",""))[:16] or sinyal_type
        last_low   = float(df["Low"].iloc[-1])
        if sinyal_type == "BUY":
            ax_p.annotate(
                f"▲ {pola_short}",
                xy=(n2-1, last_low * 0.993), xytext=(n2-1, last_low * 0.993),
                ha="center", va="top", fontsize=7, fontweight="bold", color="#000",
                bbox=dict(boxstyle="round,pad=0.35", fc=UP, ec="none", alpha=0.95),
                zorder=9
            )
    except Exception:
        pass

    # 12. RSI LABEL
    try:
        rv = float(rsi.iloc[-1])
        rc = DN if rv >= 70 else (UP if rv <= 30 else _CK["rsi"])
        zone = "OVERBOUGHT" if rv >= 70 else ("OVERSOLD" if rv <= 30 else "NEUTRAL")
        ax_r.text(0.01, 0.88, f"RSI(14)  {rv:.1f}  {zone}",
                  transform=ax_r.transAxes, ha="left", va="top",
                  fontsize=6.5, fontweight="bold", color=rc)
    except Exception:
        pass

    # 13. LEGEND
    try:
        import matplotlib.patches as _mp3
        proxies = [
            _mp3.Patch(color=E9,     label="EMA9"),
            _mp3.Patch(color=E21,    label="EMA21"),
            _mp3.Patch(color=E50,    label="EMA50"),
            _mp3.Patch(color=VWAP_C, label="VWAP"),
            _mp3.Patch(color=SR_S,   label="Support"),
            _mp3.Patch(color=SR_R,   label="Resist"),
        ]
        ax_p.legend(handles=proxies, loc="upper left", fontsize=5.5, ncol=6,
                    framealpha=0.65, facecolor=CARD, edgecolor=BORDER,
                    handlelength=1.0, borderpad=0.4, columnspacing=0.6)
    except Exception:
        pass

    # 14. HEADER BANNER
    import matplotlib.patches as _mp2
    fig.subplots_adjust(top=0.90, bottom=0.05, left=0.01, right=0.86)
    ax_hdr = fig.add_axes([0.0, 0.905, 1.0, 0.095])
    ax_hdr.set_xlim(0, 1); ax_hdr.set_ylim(0, 1); ax_hdr.axis("off")
    ax_hdr.set_facecolor(BG)
    ax_hdr.add_patch(_mp2.FancyBboxPatch(
        (0, 0), 1, 1, boxstyle="square,pad=0",
        fc=CARD, ec="none", transform=ax_hdr.transAxes, zorder=0))
    stripe_col = UP if sinyal_type == "BUY" else DN
    ax_hdr.add_patch(_mp2.FancyBboxPatch(
        (0, 0), 0.006, 1, boxstyle="square,pad=0",
        fc=stripe_col, ec="none", transform=ax_hdr.transAxes, zorder=1))
    ax_hdr.text(0.013, 0.82,
                "● BUY SIGNAL" if sinyal_type == "BUY" else "● SELL SIGNAL",
                transform=ax_hdr.transAxes, ha="left", va="top",
                fontsize=7.5, fontweight="bold", color=stripe_col)
    ax_hdr.text(0.013, 0.28, nama,
                transform=ax_hdr.transAxes, ha="left", va="bottom",
                fontsize=17, fontweight="bold", color=TXT)
    if pola_str:
        ax_hdr.text(0.22, 0.54, pola_str[:22],
                    transform=ax_hdr.transAxes, ha="left", va="center",
                    fontsize=8, color=SUB,
                    bbox=dict(boxstyle="round,pad=0.3", fc=CARD, ec=BORDER, lw=0.6))
    info_parts = []
    if entry_p > 0: info_parts.append(f"ENTRY Rp{int(entry_p):,}")
    if sl_p    > 0: info_parts.append(f"SL {sl_pct}")
    if rr      > 0: info_parts.append(f"R:R 1:{rr:.1f}")
    if info_parts:
        ax_hdr.text(0.22, 0.18, "  ·  ".join(info_parts),
                    transform=ax_hdr.transAxes, ha="left", va="bottom",
                    fontsize=6.5, color=SUB)
    if score > 0:
        ax_hdr.text(0.62, 0.82, "SCORE", transform=ax_hdr.transAxes,
                    ha="left", va="top", fontsize=6, color=SUB)
        _ck_score_bar(ax_hdr, score, x0=0.62, y=0.40, width=0.22, height=0.30)
    if regime:
        reg_col = (UP if "GREEN" in regime.upper() or "BULL" in regime.upper()
                   else DN if "RED" in regime.upper() or "BEAR" in regime.upper()
                   else _CK["tp2"])
        ax_hdr.text(0.98, 0.54, f"IHSG: {regime.upper()}",
                    transform=ax_hdr.transAxes, ha="right", va="center",
                    fontsize=7, fontweight="bold", color=reg_col,
                    bbox=dict(boxstyle="round,pad=0.3", fc=CARD, ec=reg_col, lw=0.7))
    import datetime as _dt3
    try:
        _tz3 = _dt3.timezone(_dt3.timedelta(hours=7))
        ts3  = _dt3.datetime.now(_tz3).strftime("%H:%M WIB · 1D · IDX · Swing")
    except Exception:
        ts3 = "1D · IDX · Swing"
    ax_hdr.text(0.98, 0.12, ts3, transform=ax_hdr.transAxes,
                ha="right", va="bottom", fontsize=6, color=SUB)
    ax_p.text(0.995, 0.01, "@RadarSaham", transform=ax_p.transAxes,
              ha="right", va="bottom", fontsize=6, color=TXT,
              alpha=0.10, style="italic", zorder=99)

    # 15. SAVE
    buf2 = io.BytesIO()
    try:
        fig.savefig(buf2, dpi=100, bbox_inches="tight",
                    facecolor=BG, edgecolor="none")
        plt.close(fig)
        buf2.seek(0)
        return buf2
    except Exception as ex:
        print(f"[chart_konfirm_v3] savefig gagal: {ex}")
        plt.close(fig)
        return None


