# --- FUNGSI DETEKSI SINYAL ---
# ============================================================

def cek_semua_sinyal(ticker):
    """Deteksi pola candlestick dan sinyal teknikal pada saham."""
    url = f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}?range=2mo&interval=1d"
    headers = {'User-Agent': 'Mozilla/5.0'}
    try:
        response = _http.get(url, headers=headers, timeout=10)
        data = response.json()
        indicators = data['chart']['result'][0]['indicators']['quote'][0]

        data_bersih = [
            (o, c, h, l)
            for o, c, h, l in zip(
                indicators['open'], indicators['close'],
                indicators['high'], indicators['low']
            )
            if None not in (o, c, h, l)
        ]

        if len(data_bersih) >= 21:
            o_hari_ini, c_hari_ini, h_hari_ini, l_hari_ini = data_bersih[-1]
            o_kemarin,  c_kemarin,  h_kemarin,  l_kemarin  = data_bersih[-2]
            o_lusa,     c_lusa,     h_lusa,     l_lusa     = data_bersih[-3]

            harga_tutup = [d[1] for d in data_bersih]
            sinyal_list = []

            # ── FILTER HARGA ─────────────────────────────────
            # Ganti angka di bawah sesuai kebutuhan:
            # HARGA_MIN = 0    → semua harga
            # HARGA_MAX = 1000 → hanya saham di bawah Rp 1.000
            HARGA_MIN = 50     # abaikan saham terlalu murah (gorengan ekstrem)
            HARGA_MAX = 50000  # batas harga maksimum (semua saham IDX)
            if not (HARGA_MIN <= c_hari_ini <= HARGA_MAX):
                return None, None  # FIX: return tuple agar unpack tidak crash
            # ─────────────────────────────────────────────────

            # GAP UP
            if o_hari_ini > h_kemarin:
                sinyal_list.append("🚀 GAP UP")

            # Variabel bantu pola lain (PIERCING LINE, MORNING STAR, dll)
            kemarin_merah  = c_kemarin  < o_kemarin
            hari_ini_hijau = c_hari_ini > o_hari_ini

            # HAMMER
            body_size  = abs(c_hari_ini - o_hari_ini)
            lower_wick = min(o_hari_ini, c_hari_ini) - l_hari_ini
            upper_wick = h_hari_ini - max(o_hari_ini, c_hari_ini)
            if body_size > 0 and (lower_wick >= 2 * body_size) and (upper_wick <= 0.5 * body_size):
                sinyal_list.append("🔨 HAMMER")

            # PIERCING LINE
            midpoint_kemarin = (o_kemarin + c_kemarin) / 2
            if (kemarin_merah and hari_ini_hijau
                    and (o_hari_ini < c_kemarin)
                    and (c_hari_ini > midpoint_kemarin)
                    and (c_hari_ini < o_kemarin)):
                sinyal_list.append("🗡️ PIERCING LINE")

            # MORNING STAR
            lusa_merah    = c_lusa < o_lusa
            midpoint_lusa = (o_lusa + c_lusa) / 2
            kemarin_bawah = max(o_kemarin, c_kemarin) < c_lusa
            if lusa_merah and kemarin_bawah and hari_ini_hijau and (c_hari_ini > midpoint_lusa):
                sinyal_list.append("🌅 MORNING STAR")

            # ── POLA BARU ──────────────────────────────────────────

            # THREE INSIDE UP (Swing)
            # Hari ke-3: lusa merah besar → kemarin harami hijau kecil → hari ini konfirmasi hijau di atas kemarin
            lusa_merah_besar  = c_lusa < o_lusa
            kemarin_hijau_kecil = (c_kemarin > o_kemarin) and (o_kemarin >= c_lusa) and (c_kemarin <= o_lusa)
            konfirmasi_naik   = hari_ini_hijau and (c_hari_ini > c_kemarin)
            if lusa_merah_besar and kemarin_hijau_kecil and konfirmasi_naik:
                sinyal_list.append("🌊 THREE INSIDE UP")

            # DRAGONFLY DOJI
            body_df     = abs(c_hari_ini - o_hari_ini)
            range_df    = h_hari_ini - l_hari_ini
            sumbu_bawah = min(o_hari_ini, c_hari_ini) - l_hari_ini
            sumbu_atas  = h_hari_ini - max(o_hari_ini, c_hari_ini)
            if (range_df > 0 and
                body_df <= range_df * 0.1 and
                sumbu_bawah >= range_df * 0.6 and
                sumbu_atas  <= range_df * 0.1 and
                c_kemarin < o_kemarin):
                sinyal_list.append("🐉 DRAGONFLY DOJI")

            # THREE WHITE SOLDIERS — 3 candle hijau berturut, tiap close lebih tinggi
            if (c_lusa > o_lusa and c_kemarin > o_kemarin and hari_ini_hijau
                    and c_kemarin > c_lusa and c_hari_ini > c_kemarin
                    and o_kemarin > o_lusa and o_hari_ini > o_kemarin):
                sinyal_list.append("⚔️ THREE WHITE SOLDIERS")

            # TWEEZER BOTTOM — dua candle berurutan dengan low hampir sama
            low_diff = abs(l_hari_ini - l_kemarin)
            avg_range = ((h_kemarin - l_kemarin) + (h_hari_ini - l_hari_ini)) / 2
            if (kemarin_merah and hari_ini_hijau
                    and avg_range > 0 and low_diff <= avg_range * 0.1):
                sinyal_list.append("🦋 TWEEZER BOTTOM")

            # BULLISH ENGULFING — hari ini hijau menelan seluruh body kemarin merah
            if (kemarin_merah and hari_ini_hijau
                    and o_hari_ini <= c_kemarin
                    and c_hari_ini >= o_kemarin):
                sinyal_list.append("🟢 BULLISH ENGULFING")

            # ── BEARISH PATTERNS (untuk exit signal) ──────────────

            # BEARISH ENGULFING
            kemarin_hijau = c_kemarin > o_kemarin
            hari_ini_merah = c_hari_ini < o_hari_ini
            if (kemarin_hijau and hari_ini_merah
                    and o_hari_ini >= c_kemarin
                    and c_hari_ini <= o_kemarin):
                sinyal_list.append("🔴 BEARISH ENGULFING ⚠️")

            # EVENING STAR — kebalikan Morning Star
            lusa_hijau_besar = c_lusa > o_lusa
            kemarin_kecil    = abs(c_kemarin - o_kemarin) < abs(c_lusa - o_lusa) * 0.3
            midpoint_lusa_up = (o_lusa + c_lusa) / 2
            if (lusa_hijau_besar and kemarin_kecil and hari_ini_merah
                    and c_hari_ini < midpoint_lusa_up):
                sinyal_list.append("🌆 EVENING STAR ⚠️")

            # SHOOTING STAR — body kecil di bawah, sumbu atas panjang
            sumbu_atas_ss = h_hari_ini - max(o_hari_ini, c_hari_ini)
            body_ss       = abs(c_hari_ini - o_hari_ini)
            sumbu_bawah_ss = min(o_hari_ini, c_hari_ini) - l_hari_ini
            if (range_df > 0 and body_ss <= range_df * 0.25
                    and sumbu_atas_ss >= range_df * 0.6
                    and sumbu_bawah_ss <= range_df * 0.1
                    and c_kemarin > o_kemarin):  # setelah uptrend
                sinyal_list.append("💫 SHOOTING STAR ⚠️")

            # THREE BLACK CROWS — 3 candle merah berturut turun
            lusa_merah = c_lusa < o_lusa
            if (lusa_merah and kemarin_merah and hari_ini_merah
                    and c_kemarin < c_lusa and c_hari_ini < c_kemarin):
                sinyal_list.append("🐦‍⬛ THREE BLACK CROWS ⚠️")

            # ABANDONED BABY BEARISH — gap up doji lalu gap down
            body_kemarin_kecil = abs(c_kemarin - o_kemarin) < abs(c_lusa - o_lusa) * 0.1
            gap_up_ke_kemarin  = l_kemarin > h_lusa
            gap_down_ke_hari   = h_hari_ini < l_kemarin
            if (c_lusa > o_lusa and body_kemarin_kecil
                    and gap_up_ke_kemarin and gap_down_ke_hari and hari_ini_merah):
                sinyal_list.append("👶 ABANDONED BABY ⚠️")

            # ───────────────────────────────────────────────────────
            # FILTER: hanya Morning Star & Three White Soldiers untuk swing
            POLA_VALID_SWING = {"🌅 MORNING STAR", "⚔️ THREE WHITE SOLDIERS"}
            sinyal_list = [s for s in sinyal_list if s in POLA_VALID_SWING]

            if sinyal_list:
                gabungan_sinyal = " + ".join(sinyal_list)
                batas_sl = int(min(l_lusa, l_kemarin, l_hari_ini))
                if batas_sl == int(c_hari_ini):
                    batas_sl -= 2

                nama = ticker.replace('.JK', '')
                is_sell = False
                laporan  = f"🟢 *BUY SIGNAL — {nama}* 🟢\n"
                laporan += f"Pola : {gabungan_sinyal}\n"
                laporan += f"🏷️ Harga Saat Ini : *Rp {int(c_hari_ini)}*\n"
                laporan += f"🎯 Area Entry      : *Rp {int(c_hari_ini)}*\n"
                laporan += f"🛑 Stop Loss       : < *Rp {batas_sl}*"
                try:
                    _regime_ck = _get_market_regime_ihsg()
                except Exception:
                    _regime_ck = ""
                _signal_info = {
                    "pola"   : gabungan_sinyal,
                    "sinyal" : "BUY",
                    "entry"  : float(c_hari_ini),
                    "sl"     : float(batas_sl),
                    "score"  : 0,
                    "regime" : _regime_ck,
                }
                return laporan, _signal_info


    except Exception:
        pass
    return None, None



