def ambil_saham_idx():
    """
    Ambil daftar saham dari file Excel IDX atau file TXT.
    Path otomatis mengikuti lokasi script ini.
    """
    import os

    # Folder tempat script ini berada
    script_dir = os.path.dirname(os.path.abspath(__file__))

    # ── SUMBER 1: File Excel dari IDX ────────────────────────
    nama_file_excel = ['saham_idx.xlsx', 'saham_idx.xls', 'ListedCompanies.xlsx']
    for nama in nama_file_excel:
        # Cek di folder script
        path = os.path.join(script_dir, nama)
        # Cek juga di /storage/emulated/0/
        path_sd = os.path.join('/storage/emulated/0', nama)

        for p in [path, path_sd]:
            if os.path.exists(p):
                try:
                    print(f"📂 Membaca Excel: {p}")
                    df_excel = pd.read_excel(p, header=0)
                    print(f"   Kolom: {list(df_excel.columns[:5])}")

                    # Cari kolom kode saham
                    kode_col = None
                    for col in df_excel.columns:
                        col_str = str(col).lower()
                        if any(k in col_str for k in ['kode', 'code', 'stock', 'symbol', 'ticker']):
                            kode_col = col
                            break
                    if kode_col is None:
                        kode_col = df_excel.columns[0]

                    print(f"   Kolom kode: {kode_col}")
                    kode_list = (
                        df_excel[kode_col]
                        .dropna()
                        .astype(str)
                        .str.strip()
                        .str.upper()
                        .tolist()
                    )
                    kode_list = [k for k in kode_list if k.isalpha() and 2 <= len(k) <= 6]
                    kode_unik = list(dict.fromkeys(kode_list))

                    if len(kode_unik) > 50:
                        print(f"✅ Excel berhasil! {len(kode_unik)} saham dimuat dari {p}")
                        return [k + ".JK" for k in kode_unik]
                    else:
                        print(f"   ⚠️ Hanya {len(kode_unik)} kode valid, coba kolom lain...")
                        # Coba semua kolom
                        for col in df_excel.columns:
                            kode_try = (
                                df_excel[col]
                                .dropna()
                                .astype(str)
                                .str.strip()
                                .str.upper()
                                .tolist()
                            )
                            kode_try = [k for k in kode_try if k.isalpha() and 2 <= len(k) <= 6]
                            if len(kode_try) > 50:
                                kode_unik = list(dict.fromkeys(kode_try))
                                print(f"✅ Kolom [{col}]: {len(kode_unik)} saham!")
                                return [k + ".JK" for k in kode_unik]
                except Exception as e:
                    print(f"   ❌ Gagal baca {p}: {e}")

    # ── SUMBER 2: File saham.txt ──────────────────────────────
    for p in [os.path.join(script_dir, 'saham.txt'), '/storage/emulated/0/saham.txt']:
        if os.path.exists(p):
            try:
                print(f"📄 Membaca: {p}")
                with open(p, 'r') as f:
                    kode_list = [s.strip().upper() for s in f.readlines() if s.strip()]
                kode_unik = list(dict.fromkeys(kode_list))
                if len(kode_unik) > 10:
                    print(f"✅ saham.txt: {len(kode_unik)} saham!")
                    return [k + ".JK" for k in kode_unik]
            except Exception as e:
                print(f"   ❌ Gagal baca {p}: {e}")

    # ── FALLBACK ──────────────────────────────────────────────
    print(f"⚠️ File tidak ditemukan. Pakai {len(SAHAM_CADANGAN)} saham cadangan.")
    print(f"💡 Pastikan 'saham_idx.xlsx' ada di: {script_dir}")
    return [s + ".JK" for s in list(dict.fromkeys(SAHAM_CADANGAN))]


def refresh_watchlist():
    return ambil_saham_idx()



