offset_update = 0
sedang_scan   = False
sudah_kirim   = {}

def get_updates():
    global offset_update
    try:
        url  = f"https://api.telegram.org/bot{BOT_TOKEN}/getUpdates"
        resp = _http.get(url, params={"offset": offset_update, "timeout": 10}, timeout=15)
        data = resp.json()
        if data.get("ok"):
            return data.get("result", [])
    except:
        pass
    return []

def kirim_dm(user_id, pesan):
    """Kirim pesan ke DM pribadi user. Fallback ke plain text jika Markdown gagal."""
    url = f"https://api.telegram.org/bot{BOT_TOKEN}/sendMessage"
    for parse_mode in ["Markdown", ""]:
        try:
            payload = {"chat_id": user_id, "text": pesan}
            if parse_mode:
                payload["parse_mode"] = parse_mode
            r    = _http.post(url, data=payload, timeout=10)
            resp = r.json()
            if resp.get("ok"):
                _catat(resp["result"]["message_id"])
                return True
            else:
                logger.warning("kirim_dm FAIL uid=%s parse=%s err=%s",
                               user_id, parse_mode or "plain", resp.get("description","?"))
        except Exception as _e:
            logger.warning("kirim_dm EXCEPTION uid=%s: %s", user_id, _e)
    return False

def _kirim_algo_bot(pesan, chat_id=None):
    """Kirim DM via ALGO_BOT_TOKEN (@wordly_algo_bot)."""
    if not ALGO_BOT_TOKEN:
        return False
    try:
        url = f"https://api.telegram.org/bot{ALGO_BOT_TOKEN}/sendMessage"
        r   = _http.post(url, data={
            "chat_id"   : chat_id or ALGO_CHAT_ID,
            "text"      : pesan,
            "parse_mode": "Markdown",
        }, timeout=10)
        return r.json().get("ok", False)
    except:
        return False


# ═══════════════════════════════════════════════════════════
#   INTRADAY INLINE BUTTON SYSTEM V8
#   Opsi A: Alert → tombol [✅ BELI] [❌ SKIP] [📊 DETAIL]
#           Tap BELI → Order Card dikirim ke DM admin
# ═══════════════════════════════════════════════════════════

# Storage sementara sinyal intraday yg sedang pending konfirmasi
# {callback_data: signal_dict}
_pending_intraday = {}
_pending_lock     = threading.Lock()

def _build_intraday_keyboard(kode, entry, tp, sl, sumber="intraday"):
    """
    Buat inline keyboard JSON untuk alert intraday.
    callback_data: "beli|KODE|entry|tp|sl|sumber"
    """
    import json as _json
    cb_beli   = f"beli|{kode}|{entry}|{tp}|{sl}|{sumber}"
    cb_skip   = f"skip|{kode}"
    cb_detail = f"detail|{kode}"
    keyboard  = {
        "inline_keyboard": [[
            {"text": "✅ SIAP BELI",  "callback_data": cb_beli},
            {"text": "❌ SKIP",       "callback_data": cb_skip},
            {"text": "📊 DETAIL",     "callback_data": cb_detail},
        ]]
    }
    return _json.dumps(keyboard)


def _send_with_inline(chat_id, text, keyboard_json, thread_id=None, token=None):
    """Kirim pesan Telegram dengan inline keyboard."""
    tok = token or BOT_TOKEN
    url = f"https://api.telegram.org/bot{tok}/sendMessage"
    data = {
        "chat_id"      : chat_id,
        "text"         : text,
        "parse_mode"   : "Markdown",
        "reply_markup" : keyboard_json,
    }
    if thread_id:
        data["message_thread_id"] = thread_id
    try:
        r = _http.post(url, data=data, timeout=10)
        resp = r.json()
        if resp.get("ok"):
            mid = resp["result"]["message_id"]
            db_catat_msg(mid, "radar")
            return mid
        logger.warning("_send_with_inline error: %s", resp.get("description",""))
    except Exception as e:
        logger.error("_send_with_inline: %s", e)
    return None


def _answer_callback(callback_query_id, text="✅", token=None):
    """Jawab callback query agar loading spinner hilang di Telegram."""
    tok = token or BOT_TOKEN
    try:
        _http.post(
            f"https://api.telegram.org/bot{tok}/answerCallbackQuery",
            data={"callback_query_id": callback_query_id, "text": text},
            timeout=5)
    except:
        pass


def _kirim_order_card(user_id, kode, entry, tp, sl, sumber, modal_default=5_000_000):
    """
    Kirim Order Card ke DM admin saat tap ✅ SIAP BELI.
    Berisi semua info yang dibutuhkan untuk eksekusi di Stockbit.
    """
    entry  = float(entry)
    tp     = float(tp)
    sl     = float(sl)
    pct_tp = round((tp - entry) / entry * 100, 1)
    pct_sl = round((entry - sl) / entry * 100, 1)
    rr     = round(pct_tp / pct_sl, 1) if pct_sl > 0 else 0

    # Lot suggestion: modal default dibagi harga × 100 (1 lot = 100 lembar)
    modal = modal_default
    lot_suggest = max(1, int(modal / (entry * 100)))
    nilai_beli  = lot_suggest * 100 * entry
    potensi_tp  = lot_suggest * 100 * (tp - entry)
    potensi_sl  = lot_suggest * 100 * (entry - sl)

    now_str = now_wib().strftime("%H:%M WIB")
    sumber_label = "📡 Vol Spike" if sumber == "volspike" else "⚡ Intraday"

    card = (
        f"📋 *ORDER CARD — {kode}*\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"⏰ {now_str}  |  {sumber_label}\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"📌 *Saham    :* `{kode}`\n"
        f"💰 *Entry    :* Rp `{int(entry):,}`\n"
        f"✅ *TP       :* Rp `{int(tp):,}`  *(+{pct_tp}%)*\n"
        f"🛑 *SL       :* Rp `{int(sl):,}`  *(-{pct_sl}%)*\n"
        f"⚖️ *R/R      :* `1:{rr}`\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"📦 *Lot saran:* `{lot_suggest} lot`\n"
        f"   _(modal ~Rp{int(nilai_beli):,})_\n"
        f"   Potensi profit : Rp `{int(potensi_tp):,}`\n"
        f"   Potensi loss   : Rp `{int(potensi_sl):,}`\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"📱 *Langkah di Stockbit:*\n"
        f"1️⃣ Buka Stockbit → Search `{kode}`\n"
        f"2️⃣ Tap *Beli* → Harga: `{int(entry)}`\n"
        f"3️⃣ Lot: `{lot_suggest}` → Konfirmasi\n"
        f"4️⃣ Set price alert TP: `{int(tp)}` & SL: `{int(sl)}`\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"⚠️ _Cek harga terkini sebelum order!\n"
        f"Jika harga sudah > Rp{int(entry*1.02):,} → SKIP_"
    )

    # Kirim ke semua admin via DM
    for adm_id in get_admin_ids():
        try:
            _tg_send_text_raw(adm_id, card)
        except Exception as e:
            logger.error("order card DM %s: %s", adm_id, e)

    logger.info("Order card dikirim: %s entry=%.0f lot=%d", kode, entry, lot_suggest)


def proses_callback_intraday(callback_query):
    """
    Handler callback dari tombol inline alert intraday.
    callback_data format: "action|kode|entry|tp|sl|sumber"
    """
    try:
        cq_id   = callback_query.get("id")
        data_cb = callback_query.get("data", "")
        user    = callback_query.get("from", {})
        user_id = user.get("id")
        nama    = user.get("first_name", "User")

        parts = data_cb.split("|")
        action = parts[0] if parts else ""

        if action == "beli" and len(parts) >= 6:
            _, kode, entry, tp, sl, sumber = parts[:6]
            _answer_callback(cq_id, f"✅ Order Card {kode} dikirim ke DM kamu!")
            threading.Thread(
                target=_kirim_order_card,
                args=(user_id, kode, entry, tp, sl, sumber),
                daemon=True
            ).start()
            logger.info("BELI callback: %s oleh %s (%s)", kode, nama, user_id)

        elif action == "skip":
            kode = parts[1] if len(parts) > 1 else "?"
            _answer_callback(cq_id, f"❌ {kode} di-skip")
            logger.info("SKIP callback: %s oleh %s", kode, nama)

        elif action == "detail" and len(parts) >= 2:
            kode = parts[1]
            _answer_callback(cq_id, f"📊 Loading detail {kode}...")
            dest_dm = {"type": "dm", "user_id": user_id}
            threading.Thread(
                target=generate_pinescript,
                args=(kode, dest_dm),
                daemon=True
            ).start()

        # ── SMC: tap tombol sinyal (smc_d|KODE|signal) ──────────
        elif action == "smc_d" and len(parts) >= 3:
            kode_cb   = parts[1]
            signal_cb = parts[2]
            dest_dm   = {"type": "dm", "user_id": user_id}

            if signal_cb == "refresh":
                _answer_callback(cq_id, f"🔄 Refresh SMC {kode_cb}...")
                threading.Thread(
                    target=cmd_smc_analysis,
                    args=(kode_cb, dest_dm),
                    daemon=True
                ).start()
            elif signal_cb == "rencana":
                _answer_callback(cq_id, f"📈 Loading rencana {kode_cb}...")
                threading.Thread(
                    target=cmd_rencana,
                    args=(user_id, [kode_cb], dest_dm),
                    daemon=True
                ).start()
            else:
                # Detail per sinyal
                def _smc_cb_detail(kode_cb=kode_cb, signal_cb=signal_cb,
                                   dest_dm=dest_dm):
                    try:
                        result = get_candles_tf(kode_cb + ".JK", "1d", "1y")
                        if result is None:
                            dest_kirim_teks(dest_dm, f"❌ Data {kode_cb} tidak tersedia")
                            return
                        df_cb, _, _ = result
                        if df_cb is None or len(df_cb) < 20:
                            dest_kirim_teks(dest_dm, f"❌ Data {kode_cb} kurang")
                            return
                        rsi_cb = float(hitung_rsi_wilder(df_cb["Close"]).iloc[-1])
                        sc, al, det = _smc_score(df_cb, rsi_cb)
                        txt = _smc_detail_text(signal_cb, kode_cb, det, rsi_cb, sc)
                        dest_kirim_teks(dest_dm, txt)
                    except Exception as ex:
                        dest_kirim_teks(dest_dm, f"⚠️ Error detail SMC: {ex}")

                _answer_callback(cq_id, f"📊 Detail {signal_cb.upper()} {kode_cb}...")
                threading.Thread(target=_smc_cb_detail, daemon=True).start()

    except Exception as e:
        logger.error("proses_callback_intraday: %s", e)



def kirim_foto_dm(user_id, photo_buffer, caption):
    """Kirim chart ke DM pribadi user."""
    url = f"https://api.telegram.org/bot{BOT_TOKEN}/sendPhoto"
    for attempt in range(3):
        try:
            photo_buffer.seek(0)
            r = _http.post(url, files={"photo": ("chart.png", photo_buffer, "image/png")},
                data={"chat_id": user_id, "caption": caption, "parse_mode": "Markdown"}, timeout=60)
            resp = r.json()
            if resp.get("ok"):
                _catat(resp["result"]["message_id"])
                return
            err_code = resp.get("error_code", "?")
            err_desc = resp.get("description", "?")
            logger.error("kirim_foto_dm uid=%s ERR %s: %s", user_id, err_code, err_desc)
            # FIX v4-6: caption terlalu panjang → potong & kirim ulang
            if err_code == 400:
                photo_buffer.seek(0)
                _http.post(url, files={"photo": ("chart.png", photo_buffer, "image/png")},
                    data={"chat_id": user_id, "caption": caption[:1000] + "…",
                          "parse_mode": "Markdown"}, timeout=60)
            return
        except Exception as _fe:
            logger.warning("kirim_foto_dm attempt %d: %s", attempt + 1, _fe)
            time.sleep(3)

def kirim_ke_topic(thread_id, pesan):
    """Kirim pesan teks ke topic tertentu di grup."""
    try:
        url = f"https://api.telegram.org/bot{BOT_TOKEN}/sendMessage"
        r   = _http.post(url, data={
            "chat_id"           : CHAT_ID,
            "text"              : pesan,
            "parse_mode"        : "Markdown",
            "message_thread_id" : thread_id,
        }, timeout=10)
        resp = r.json()
        if resp.get("ok"):
            _catat(resp["result"]["message_id"])
        return resp.get("ok", False)
    except:
        return False

def kirim_foto_ke_topic(thread_id, photo_buffer, caption):
    """Kirim chart ke topic tertentu di grup."""
    url = f"https://api.telegram.org/bot{BOT_TOKEN}/sendPhoto"
    for attempt in range(3):
        try:
            photo_buffer.seek(0)
            r = _http.post(url,
                files={"photo": ("chart.png", photo_buffer, "image/png")},
                data={"chat_id": CHAT_ID, "caption": caption,
                      "parse_mode": "Markdown", "message_thread_id": thread_id},
                timeout=60)
            resp = r.json()
            if resp.get("ok"):
                _catat(resp["result"]["message_id"])
                return
            else:
                # Log Telegram API error — ini yang biasanya hilang
                err_code = resp.get("error_code","?")
                err_desc = resp.get("description","?")
                logger.error("kirim_foto_ke_topic TID=%s ERR %s: %s", thread_id, err_code, err_desc)
                if err_code == 400:   # Bad Request — topic salah, jangan retry
                    return
        except Exception as _fe:
            logger.warning("kirim_foto_ke_topic attempt %d: %s", attempt+1, _fe)
            time.sleep(3)

def dest_kirim_teks(dest, pesan):
    """Kirim teks ke tujuan: DM, topic, atau general grup."""
    t = dest.get("type") if dest else None
    logger.info("dest_kirim_teks: type=%s uid=%s len=%d", t, dest.get("user_id","?") if dest else "?", len(pesan))
    if t == "dm":
        result = kirim_dm(dest["user_id"], pesan)
        if not result:
            logger.warning("dest_kirim_teks DM GAGAL: uid=%s preview=%s", dest.get("user_id"), pesan[:80])
    elif t == "group":
        # General chat (tanpa thread/topic)
        try:
            url = f"https://api.telegram.org/bot{BOT_TOKEN}/sendMessage"
            r   = _http.post(url, data={
                "chat_id"   : dest.get("chat_id", CHAT_ID),
                "text"      : pesan,
                "parse_mode": "Markdown",
            }, timeout=10)
            resp = r.json()
            if resp.get("ok"):
                _catat(resp["result"]["message_id"])
        except Exception as _e:
            logger.warning("dest_kirim_teks group error: %s", _e)
    else:
        kirim_ke_topic(dest["thread_id"], pesan)


# ── IDEA #4: INLINE KEYBOARD HELPER ──────────────────────────
def kirim_inline_keyboard(dest, pesan: str, kode: str):
    """
    Kirim pesan teks + tombol inline: Chart | Physics | Rekap | Rencana | MTF | Narrative.
    user tap langsung tanpa perlu ketik ulang.
    """
    import json as _json
    keyboard = {
        "inline_keyboard": [
            [
                {"text": "📊 Chart",   "callback_data": f"chart:{kode}"},
                {"text": "⚛ Physics", "callback_data": f"physics:{kode}"},
                {"text": "📋 Rekap",   "callback_data": f"rekap:{kode}"},
            ],
            [
                {"text": "🎯 Rencana",   "callback_data": f"rencana:{kode}"},
                {"text": "📡 MTF",       "callback_data": f"mtf:{kode}"},
                {"text": "📝 Narasi",    "callback_data": f"narrative:{kode}"},
            ],
        ]
    }
    t = dest.get("type") if dest else None
    try:
        if t == "dm":
            chat_id = dest["user_id"]
        elif t == "group":
            chat_id = dest.get("chat_id", CHAT_ID)
        else:
            chat_id = CHAT_ID

        url = f"https://api.telegram.org/bot{BOT_TOKEN}/sendMessage"
        r = _http.post(url, json={
            "chat_id"      : chat_id,
            "text"         : pesan,
            "parse_mode"   : "Markdown",
            "reply_markup" : keyboard,
        }, timeout=12)
        resp = r.json()
        if resp.get("ok"):
            try:
                _catat(resp["result"]["message_id"])
            except Exception:
                pass
    except Exception as e:
        logger.warning("kirim_inline_keyboard error: %s", e)
        dest_kirim_teks(dest, pesan)   # fallback ke teks biasa


def proses_callback_query(callback_data: str, user_id: int, dest):
    """
    Handle tombol inline keyboard.
    callback_data format: "action:KODE"
    """
    try:
        parts = callback_data.split(":", 1)
        if len(parts) != 2:
            return
        action, kode = parts[0], parts[1].upper()
        if action == "chart":
            dest_kirim_foto(dest, kode + ".JK")
        elif action == "physics":
            threading.Thread(target=analisa_fisika_saham,
                             args=(kode, dest), daemon=True).start()
        elif action == "rekap":
            threading.Thread(target=proses_rekap,
                             args=(user_id, [kode], dest), daemon=True).start()
        elif action == "rencana":
            threading.Thread(target=cmd_rencana,
                             args=(user_id, [kode, "1d"], dest), daemon=True).start()
        elif action == "mtf":
            def _cb_mtf(k, d):
                mtf_r = get_mtf_confluence(k)
                agree = mtf_r.get("agreement", 0)
                comp  = mtf_r.get("composite", 50)
                agree_lbl = "🟢 3/3 KUAT" if agree==3 else "🟡 2/3 MODERAT" if agree==2 else "🔴 LEMAH"
                dest_kirim_teks(d,
                    f"📡 *MTF {k}*\n"
                    f"D={mtf_r.get('score_d',0):.0f}  W={mtf_r.get('score_w',0):.0f}  4H={mtf_r.get('score_4h',0):.0f}\n"
                    f"Composite {comp:.1f}/100 · {agree_lbl}")
            threading.Thread(target=_cb_mtf, args=(kode, dest), daemon=True).start()
        elif action == "narrative":
            def _cb_narr(k, d):
                try:
                    df_n, harga_n, _ = get_candles_tf(k+".JK", "1d", "3mo", None)
                    ind_n = hitung_indikator(df_n)
                    ema20_n = df_n["Close"].ewm(span=20,adjust=False).mean().iloc[-1]
                    x20_n = (harga_n - ema20_n) / ema20_n * 100 if ema20_n > 0 else 0
                    mtf_n = get_mtf_confluence(k)
                    sa_n  = detect_silent_accumulation(df_n)
                    narr  = generate_narrative(k, harga_n,
                                ind_n.get("rsi",50), ind_n.get("vol_ratio",1.0),
                                x20_n, ind_n.get("macd",0), ind_n.get("score",50),
                                "—", mtf_n.get("agreement"), sa_n.get("detected",False))
                    dest_kirim_teks(d, f"📝 *Narasi {k}*\n{narr}")
                except Exception as err:
                    dest_kirim_teks(d, f"❌ Narrative error: {err}")
            threading.Thread(target=_cb_narr, args=(kode, dest), daemon=True).start()
    except Exception as e:
        logger.warning("proses_callback_query error: %s", e)

def dest_kirim_foto(dest, ticker, signal_info=None):
    """Kirim Chart Konfirm V2 ke tujuan.
    signal_info opsional — kalau ada, tampilkan level ENTRY/TP/SL + header sinyal.
    Kalau None, tetap Chart Konfirm V2 tapi tanpa level (chart analisa biasa).
    Fallback ke buat_chart_buffer hanya jika V2 gagal.
    """
    kode = ticker.replace(".JK", "")

    # ── Selalu coba Chart Konfirm V2 dulu ───────────────────────────────
    buf = buat_chart_konfirm_v2(ticker, signal_info)
    if not buf:
        buf = buat_chart_buffer(ticker)   # fallback darurat

    # ── Caption ─────────────────────────────────────────────────────────
    si       = signal_info or {}
    pola     = si.get("pola", "")
    entry    = si.get("entry", 0)
    sl       = si.get("sl", 0)
    sinyal_t = si.get("sinyal", "").upper()

    if sinyal_t == "SELL":
        caption = (f"📊 *Chart Konfirm — {kode}*\n"
                   f"🔴 *SELL SIGNAL*  |  {pola}\n"
                   f"💡 Pertimbangkan exit jika hold posisi")
    elif sinyal_t == "BUY" and entry:
        tp1 = int(entry * 1.040)
        tp2 = int(entry * 1.080)
        caption = (f"📊 *Chart Konfirm — {kode}*\n"
                   f"🟢 *BUY*  ·  {pola}\n"
                   f"🎯 Entry : Rp {int(entry):,}  "
                   f"·  TP1 Rp {tp1:,}  ·  TP2 Rp {tp2:,}\n"
                   f"🛑 SL : Rp {int(sl):,}")
    else:
        caption = (f"📊 *Chart Konfirm — {kode}*\n"
                   f"BB  ·  VWAP  ·  EMA50/200  ·  Ichimoku  ·  Alligator\n"
                   f"RSI(14)  ·  MACD  ·  Stoch(14,3,3)")

    if not buf:
        dest_kirim_teks(dest, f"⚠️ Chart {kode} tidak tersedia")
        return
    dest_kirim_foto_buf(dest, buf, caption)

def dest_kirim_foto_buf(dest, buf, caption=""):
    t = dest.get("type")
