def _ambil_data_harian_radar(ticker, periode="3mo"):
    """
    Download data harian OHLCV dari Yahoo Finance.
    Return DataFrame bersih atau None jika gagal / data kurang.
    """
    url     = f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}?range={periode}&interval=1d"
    headers = {"User-Agent": "Mozilla/5.0"}
    try:
        r    = _http.get(url, headers=headers, timeout=8)
        data = r.json()
        res  = data["chart"]["result"][0]
        ts   = res["timestamp"]
        q    = res["indicators"]["quote"][0]
        meta = res.get("meta", {})
        df   = pd.DataFrame({
            "Open"  : q["open"],
            "High"  : q["high"],
            "Low"   : q["low"],
            "Close" : q["close"],
            "Volume": q["volume"],
        })
        df.index = pd.to_datetime(ts, unit="s")
        df.dropna(inplace=True)
        if len(df) < 25:
            return None, meta
        return df, meta
    except:
        return None, {}


# ── 1. BANDAR ACCUMULATION SCORE ────────────────────────────
def _bandar_accumulation_score(df):
    """
    Deteksi akumulasi Smart Money (bandar) berdasarkan:
    • Volume MA5 > Volume MA20  → volume mulai naik tapi diam-diam
    • Range (H-L)/C kecil       → harga sideways / tidak volatile
    • Candle hijau dominan      → tekanan beli bertahap
    Skor maksimum: 40
    """
    score    = 0
    alasan   = []

    vol_ma5  = df["Volume"].rolling(5).mean()
    vol_ma20 = df["Volume"].rolling(20).mean()

    # Volume MA5 melampaui MA20 (smart money mulai masuk)
    if vol_ma5.iloc[-1] > vol_ma20.iloc[-1]:
        score  += 20
        alasan.append("📦 Vol MA5>MA20")

    # Range kecil — harga sideways (fase akumulasi)
    recent    = df.tail(5)
    avg_range = ((recent["High"] - recent["Low"]) / recent["Close"]).mean()
    if avg_range < 0.06:            # range < 6% = sideways
        score  += 10
        alasan.append("📐 Range sempit")
    elif avg_range < 0.08:
        score  += 5
        alasan.append("📐 Range moderat")

    # Dominasi candle hijau dalam 5 hari terakhir
    hijau = (df["Close"].tail(5) > df["Open"].tail(5)).sum()
    if hijau >= 4:
        score  += 10
        alasan.append("🟢 Candle hijau dominan")
    elif hijau >= 3:
        score  += 5
        alasan.append("🟢 Candle mix cenderung hijau")

    return score, alasan


# ── 2. LIMIT UP / BREAKOUT SCORE ───────────────────────────
def _limit_up_score(df):
    """
    Prediksi potensi parabolic / limit up:
    • Close > High 20 hari (breakout resistance)
    • Volume > 2× rata-rata 20 hari
    • RSI > 65 (momentum kuat)
    • MACD Histogram positif & naik
    Skor maksimum: 40
    """
    score  = 0
    alasan = []

    close  = df["Close"]
    volume = df["Volume"]

    # Breakout resistance 20 hari
    high20 = df["High"].rolling(20).max().iloc[-2]   # kemarin punya high20
    if close.iloc[-1] > high20:
        score  += 15
        alasan.append("🚀 Breakout High-20")

    # Volume spike 2× rata-rata
    vol_avg20 = volume.rolling(20).mean().iloc[-1]
    vol_last  = volume.iloc[-1]
    if vol_avg20 > 0:
        vol_ratio = vol_last / vol_avg20
        if vol_ratio >= 3:
            score  += 15
            alasan.append(f"🔥 Vol {vol_ratio:.1f}× avg")
        elif vol_ratio >= 2:
            score  += 10
            alasan.append(f"🔥 Vol {vol_ratio:.1f}× avg")
        elif vol_ratio >= 1.5:
            score  += 5
            alasan.append(f"⚡ Vol {vol_ratio:.1f}× avg")

    # RSI momentum
    rsi    = float(hitung_rsi_wilder(close).iloc[-1])
    if rsi >= 70:
        score  += 10
        alasan.append(f"💥 RSI {rsi:.0f}")
    elif rsi >= 65:
        score  += 7
        alasan.append(f"⚡ RSI {rsi:.0f}")
    elif rsi >= 55:
        score  += 3
        alasan.append(f"📈 RSI {rsi:.0f}")

    # MACD Histogram positif & naik
    ema12  = close.ewm(span=12, adjust=False).mean()
    ema26  = close.ewm(span=26, adjust=False).mean()
    macd   = ema12 - ema26
    signal = macd.ewm(span=9, adjust=False).mean()
    hist   = macd - signal
    if hist.iloc[-1] > 0 and hist.iloc[-1] > hist.iloc[-2]:
        score  += 5
        alasan.append("📊 MACD hist naik")

    return score, alasan, round(rsi, 1)


# ── 3. VOLUME ANOMALY SCORE ─────────────────────────────────
def _volume_anomaly_score(df):
    """
    Deteksi anomali volume — pump sebelum breakout.
    Volume > 5× rata-rata = whale activity.
    Skor maksimum: 20
    """
    score    = 0
    alasan   = []
    vol      = df["Volume"]
    avg      = vol.rolling(20).mean().iloc[-1]
    last_vol = vol.iloc[-1]
    if avg > 0:
        ratio = last_vol / avg
        if ratio >= 10:
            score  += 20
            alasan.append(f"🐳 Whale! {ratio:.0f}× vol")
        elif ratio >= 5:
            score  += 15
            alasan.append(f"🔥 Pump {ratio:.0f}× vol")
        elif ratio >= 3:
            score  += 8
            alasan.append(f"⚡ Spike {ratio:.1f}× vol")
    return score, alasan


# ── 4. FALSE BREAKOUT FILTER ─────────────────────────────────
def _false_breakout_penalty(df):
    """
    Hukuman untuk false breakout:
    Jika 3 hari terakhir ada wick panjang di atas (>8% range)
    dan harga close kembali ke bawah high kemarin → penalty.
    """
    penalty  = 0
    candles  = df.tail(3)
    for _, row in candles.iterrows():
        rng = row["High"] - row["Low"]
        if rng <= 0:
            continue
        upper_wick = row["High"] - max(row["Open"], row["Close"])
        if upper_wick / rng > 0.5:        # wick atas > 50% range
            penalty -= 8
    return penalty


# ── 5. GORENGAN FILTER ──────────────────────────────────────
def _gorengan_filter(df, harga_terakhir):
    """
    ── SCALPING FILTER V7 ──────────────────────────────────────
    Filter ketat untuk scalping/daytrade 80% winrate:
    • Harga: Rp100 – Rp20.000 (likuid, bukan penny & bukan terlalu mahal)
    • Volatilitas 5 hari: MAX 10% (stop noise/gorengan liar)
    • Volume harian: MIN 500.000 lot (likuiditas wajib untuk scalping)
    • Upper wick rejection: wick atas > 45% range → tolak (rejection candle)
    • Lower wick ekstrem + vol tinggi: tolak
    Return: (lolos: bool, alasan_reject: str)
    """
    # ── Filter harga (scalping: butuh spread efisien) ──────────
    if harga_terakhir < 100:
        return False, f"Harga < Rp100 (penny, spread besar)"
    if harga_terakhir > 20_000:
        return False, f"Harga > Rp20.000 (kapital besar, sulit scalp)"

    # ── Volatilitas 5 hari MAX 10% ────────────────────────────
    ret5 = df["Close"].pct_change().tail(5)
    vol5 = ret5.std() * 100
    if vol5 > 10:
        return False, f"Volatilitas {vol5:.1f}% > 10% (terlalu berisiko scalp)"

    # ── Likuiditas wajib: volume harian >= 500rb lot ──────────
    vol_last = df["Volume"].iloc[-1]
    if vol_last < 500_000:
        return False, f"Volume {int(vol_last):,} lot < 500.000 (tidak likuid)"

    # ── Rata-rata volume 20hr >= 300rb lot ────────────────────
    vol_avg20 = df["Volume"].rolling(20).mean().iloc[-1]
    if vol_avg20 < 300_000:
        return False, f"Vol avg20 {int(vol_avg20):,} lot < 300.000 (tidak konsisten)"

    last = df.iloc[-1]
    rng  = last["High"] - last["Low"]

    # ── Upper wick rejection candle (seller overwhelm) ────────
    if rng > 0:
        upper_wick = last["High"] - max(last["Open"], last["Close"])
        if upper_wick / rng > 0.45:
            return False, f"Upper wick {upper_wick/rng*100:.0f}% range (rejection candle)"

    # ── Lower wick ekstrem + volatilitas tinggi ───────────────
    if rng > 0:
        lo_wick = (min(last["Open"], last["Close"]) - last["Low"])
        if (lo_wick / rng) > 0.7 and vol5 > 7:
            return False, "Wick bawah ekstrem + volatilitas tinggi"

    return True, ""


