# ── P1. HOOKE'S LAW — F = -kx (Spring Bounce / Mantul) ──────
def _hooke_bounce_score(df):
    """
    Hooke's Law: F = -k·x
    Ketika harga turun jauh di bawah EMA20/EMA50, ada restoring force
    yang mendorong harga kembali ke equilibrium (mantul).

    x = deviasi harga dari EMA (spring displacement)
    k = spring constant (diproxy dari ATR — semakin volatile, semakin elastis)
    F = restoring force (potensi bounce)

    Sweet spot mantul: harga 5–25% di bawah EMA20
    Skor maks: 30
    """
    import numpy as _np
    score  = 0
    alasan = []

    close  = df["Close"].astype(float)
    high   = df["High"].astype(float)
    low    = df["Low"].astype(float)

    ema20 = close.ewm(span=20, adjust=False).mean()
    ema50 = close.ewm(span=50, adjust=False).mean()

    c_now   = close.iloc[-1]
    e20_now = ema20.iloc[-1]
    e50_now = ema50.iloc[-1]

    if e20_now <= 0 or e50_now <= 0:
        return score, alasan, 0.0

    x20 = (c_now - e20_now) / e20_now * 100
    x50 = (c_now - e50_now) / e50_now * 100

    # ATR sebagai proxy spring constant k (True Range: max H-L, |H-PrevC|, |L-PrevC|)
    prev_close = close.shift(1)
    tr          = (high - low).combine(abs(high - prev_close), max).combine(abs(low - prev_close), max)
    atr         = tr.rolling(14).mean().iloc[-1]
    atr_pct = (atr / c_now * 100) if c_now > 0 else 0

    # === Hooke bounce zone EMA20 ===
    if -25 <= x20 <= -5:
        if x20 <= -15:
            score  += 25
            alasan.append(f"🪝 Hooke MAX: {x20:.1f}% bawah EMA20 (spring tegang)")
        elif x20 <= -10:
            score  += 20
            alasan.append(f"🪝 Hooke KUAT: {x20:.1f}% bawah EMA20")
        elif x20 <= -5:
            score  += 12
            alasan.append(f"🪝 Hooke: {x20:.1f}% bawah EMA20")
    elif -3 <= x20 <= 0:
        score  += 5
        alasan.append(f"⚖️ Near EMA20 support ({x20:.1f}%)")

    # Bonus jika EMA50 juga support ganda
    if -20 <= x50 <= -3:
        score  += 5
        alasan.append(f"🔩 EMA50 support ganda ({x50:.1f}%)")

    # Penalty: spring mungkin patah (terlalu jauh di bawah)
    if x20 < -30:
        score = max(0, score - 10)
        alasan.append(f"⚠️ Terlalu jauh EMA20 ({x20:.1f}%)")

    return score, alasan, round(x20, 1)


# ── P2. NEWTON F=ma — Gaya Bandar ───────────────────────────
def _newton_force_score(df):
    """
    Newton's 2nd Law: F = m·a
    Gaya bandar = Volume (massa) × Price Acceleration (percepatan harga)

    velocity     = pct_change harga
    acceleration = diff(velocity)
    force        = Volume × |acceleration|

    F_now / F_avg >> 1 dan arah naik → bandar mendorong keras ke atas
    Skor maks: 25
    """
    score  = 0
    alasan = []

    close  = df["Close"].astype(float)
    volume = df["Volume"].astype(float)

    velocity     = close.pct_change()
    acceleration = velocity.diff()

    force       = volume * acceleration.abs()
    force_avg20 = force.rolling(20).mean()

    f_now = force.iloc[-1]
    f_avg = force_avg20.iloc[-1]
    a_now = acceleration.iloc[-1]

    if f_avg <= 0 or _pd_isnan(f_now) or _pd_isnan(f_avg):
        return score, alasan

    force_ratio = f_now / f_avg

    if force_ratio >= 5 and a_now > 0:
        score  += 25
        alasan.append(f"⚡ Newton F={force_ratio:.1f}× avg (akselerasi naik kuat)")
    elif force_ratio >= 3 and a_now > 0:
        score  += 18
        alasan.append(f"⚡ Newton F={force_ratio:.1f}× avg ↑")
    elif force_ratio >= 2 and a_now > 0:
        score  += 12
        alasan.append(f"⚡ Newton F={force_ratio:.1f}× avg ↑")
    elif force_ratio >= 2 and a_now < 0:
        score  -= 5
        alasan.append(f"🔻 Newton F={force_ratio:.1f}× tapi turun (distribusi?)")

    # Deteksi akselerasi membalik dari negatif ke positif = reversal signal
    accel_vals = acceleration.tail(3).values
    if len(accel_vals) == 3:
        try:
            if accel_vals[0] < 0 and accel_vals[1] < 0 and accel_vals[2] > 0:
                score  += 8
                alasan.append("🔄 Akselerasi membalik (reversal signal)")
        except Exception:
            pass

    return score, alasan


# ── P3. KINETIC ENERGY — KE = ½mv² ─────────────────────────
def _kinetic_energy_score(df):
    """
    Kinetic Energy: KE = ½ · m · v²
    m = Volume (massa market)
    v = return rata-rata 3 hari terakhir (velocity harga)

    KE tinggi + arah naik  = momentum breakout kuat
    KE tinggi + arah turun = distribusi / jual kuat (penalty)
    Skor maks: 20
    """
    score  = 0
    alasan = []

    close  = df["Close"].astype(float)
    volume = df["Volume"].astype(float)

    v_3d  = close.pct_change().tail(3).mean()
    m     = volume.iloc[-1]
    m_avg = volume.rolling(20).mean().iloc[-1]

    if m_avg <= 0 or _pd_isnan(m_avg):
        return score, alasan

    vol_ratio = m / m_avg
    ke        = 0.5 * vol_ratio * (v_3d ** 2) * 10000

    vol_ratio_hist = volume / (volume.rolling(20).mean() + 1e-9)
    v_hist         = close.pct_change().rolling(3).mean()
    ke_hist        = 0.5 * vol_ratio_hist * (v_hist ** 2) * 10000
    ke_avg         = ke_hist.rolling(20).mean().iloc[-1]

    if ke_avg <= 0 or _pd_isnan(ke_avg):
        return score, alasan

    ke_ratio = ke / ke_avg

    if ke_ratio >= 5 and v_3d > 0:
        score  += 20
        alasan.append(f"🔋 KE={ke_ratio:.1f}× (energi breakout sangat tinggi)")
    elif ke_ratio >= 3 and v_3d > 0:
        score  += 15
        alasan.append(f"🔋 KE={ke_ratio:.1f}× (energi naik tinggi)")
    elif ke_ratio >= 2 and v_3d > 0:
        score  += 8
        alasan.append(f"🔋 KE={ke_ratio:.1f}× (energi naik moderat)")
    elif ke_ratio >= 2 and v_3d < 0:
        score  -= 5
        alasan.append(f"📉 KE tinggi tapi turun — jual kuat")

    return score, alasan


# ── P4. MOMENTUM p = mv — OBV & Volume-Weighted ─────────────
def _momentum_score(df):
    """
    Linear Momentum: p = m · v
    Deteksi bandar sedang membangun momentum secara tersembunyi.

    OBV (On-Balance Volume) = akumulasi volume berbobot arah harga
    OBV naik tapi harga datar = bandar diam-diam beli (stealth accumulation)
    Skor maks: 20
    """
    score  = 0
    alasan = []

    close  = df["Close"].astype(float)
    volume = df["Volume"].astype(float)

    # Hitung OBV
    obv = [0.0]
    ret = close.diff()
    for i in range(1, len(df)):
        try:
            r = float(ret.iloc[i])
            v = float(volume.iloc[i])
            if r > 0:
                obv.append(obv[-1] + v)
            elif r < 0:
                obv.append(obv[-1] - v)
            else:
                obv.append(obv[-1])
        except Exception:
            obv.append(obv[-1])
    obv_s = pd.Series(obv, index=df.index, dtype=float)

    obv_ema5  = obv_s.ewm(span=5,  adjust=False).mean()
    obv_ema20 = obv_s.ewm(span=20, adjust=False).mean()

    # OBV Golden Cross = bandar akumulasi
    if obv_ema5.iloc[-1] > obv_ema20.iloc[-1] and obv_ema5.iloc[-2] <= obv_ema20.iloc[-2]:
        score  += 15
        alasan.append("📦 OBV Golden Cross (momentum akumulasi)")
    elif obv_ema5.iloc[-1] > obv_ema20.iloc[-1]:
        score  += 8
        alasan.append("📦 OBV bullish (p=mv naik)")

    # Volume-Weighted Momentum
    vw_momentum = (volume * close.pct_change()).rolling(5).sum()
    vw_m_now    = vw_momentum.iloc[-1]
    vw_m_avg    = vw_momentum.abs().rolling(20).mean().iloc[-1]

    if vw_m_avg > 0 and not _pd_isnan(vw_m_now):
        vw_ratio = vw_m_now / vw_m_avg
        if vw_ratio >= 2:
            score  += 5
            alasan.append(f"💫 VW-Momentum {vw_ratio:.1f}× avg")

    # Divergence: price flat/turun, OBV naik = bullish divergence
    if len(df) >= 6:
        price_5d_gain = (float(close.iloc[-1]) - float(close.iloc[-5])) / (float(close.iloc[-5]) + 1e-9) * 100
        obv_prev      = float(obv_s.iloc[-5])
        obv_now_val   = float(obv_s.iloc[-1])
        obv_5d_gain   = (obv_now_val - obv_prev) / (abs(obv_prev) + 1e-9) * 100

        if obv_5d_gain > 10 and price_5d_gain < 2:
            score  += 10
            alasan.append("🔍 OBV-Price Divergence (akumulasi tersembunyi!)")
        elif obv_5d_gain > 5 and price_5d_gain < 1:
            score  += 5
            alasan.append("🔍 OBV naik > harga (stealth buy)")

    return score, alasan


# ── P5. WAVE RESONANCE — Constructive Interference ──────────
def _resonance_score(df, rsi, vol_x):
    """
    Wave Resonance: Amplitude ∝ N² saat N gelombang sefase.

    Berbeda dari additive biasa:
      Additive    : 7 sinyal = 7 × 1pt = 7pt (linear)
      Resonance   : 7 sinyal = (7/7)² × 25 = 25pt (eksponensial)
      Partial (4) : (4/7)² × 25 = 8.2pt

    Efek: Bot hanya alert tinggi saat SEMUA sinyal benar-benar align.
    False positive drastis berkurang.

    7 sinyal yang dicek:
    1. RSI zona bullish (40–70)
    2. Volume spike ≥ 2×
    3. MACD golden cross
    4. EMA9 cross di atas EMA21
    5. Stochastic oversold recovery
    6. Candle bullish (close > open)
    7. Harga di atas VWAP
    Skor maks: 25
    """
    score     = 0
    alasan    = []
    confirmed = 0.0
    total     = 7

    close  = df["Close"].astype(float)
    high   = df["High"].astype(float)
    low    = df["Low"].astype(float)
    volume = df["Volume"].astype(float)

    try:
        # 1. RSI bullish zone
        if 40 <= rsi <= 70:
            confirmed += 1

        # 2. Volume spike
        if vol_x >= 2.0:
            confirmed += 1

        # 3. MACD golden cross
        ema12 = close.ewm(span=12, adjust=False).mean()
        ema26 = close.ewm(span=26, adjust=False).mean()
        macd  = ema12 - ema26
        sig   = macd.ewm(span=9, adjust=False).mean()
        if macd.iloc[-1] > sig.iloc[-1] and macd.iloc[-2] <= sig.iloc[-2]:
            confirmed += 1
        elif macd.iloc[-1] > sig.iloc[-1]:
            confirmed += 0.5

        # 4. EMA9 > EMA21 crossup
        ema9  = close.ewm(span=9,  adjust=False).mean()
        ema21 = close.ewm(span=21, adjust=False).mean()
        if ema9.iloc[-1] > ema21.iloc[-1] and ema9.iloc[-2] <= ema21.iloc[-2]:
            confirmed += 1
        elif ema9.iloc[-1] > ema21.iloc[-1]:
            confirmed += 0.5

        # 5. Stochastic oversold recovery
        low14   = low.rolling(14).min()
        high14  = high.rolling(14).max()
        stoch_k = (close - low14) / (high14 - low14 + 1e-9) * 100
        if stoch_k.iloc[-1] < 30 and stoch_k.iloc[-1] > stoch_k.iloc[-2]:
            confirmed += 1
        elif stoch_k.iloc[-1] < 50 and stoch_k.iloc[-1] > stoch_k.iloc[-2]:
            confirmed += 0.3

        # 6. Candle bullish
        open_s = df["Open"].astype(float)
        if close.iloc[-1] > open_s.iloc[-1]:
            confirmed += 1

        # 7. Harga di atas VWAP
        typical  = (high + low + close) / 3
        vwap     = (typical * volume).cumsum() / (volume.cumsum() + 1e-9)
        if close.iloc[-1] > vwap.iloc[-1]:
            confirmed += 1
        elif close.iloc[-1] > vwap.iloc[-1] * 0.98:
            confirmed += 0.5

    except Exception:
        pass

    # RESONANCE FORMULA: skor ∝ (confirmed/total)²
    ratio         = confirmed / total
    resonance_raw = (ratio ** 2) * 25
    score         = int(resonance_raw)

    if score >= 20:
        alasan.append(f"🌊 RESONANCE {confirmed:.1f}/{total} — Full Convergence!")
    elif score >= 12:
        alasan.append(f"🌊 Resonance {confirmed:.1f}/{total} — Multi-signal aligned")
    elif score >= 6:
        alasan.append(f"〰️ Resonance {confirmed:.1f}/{total} — Partial convergence")

    return score, alasan, round(confirmed, 1), total


# ── P6. ENTROPY — Keteraturan Harga (Shannon) ───────────────
def _entropy_score(df):
    """
    Shannon Entropy: H = -Σ p_i · log2(p_i)

    Entropi RENDAH = pergerakan harga teratur (bandar mengontrol supply)
    Entropi TINGGI = kacau / noise (tidak ada pattern)

    H_min = 0 (semua candle searah, deterministik)
    H_max = log2(3) ≈ 1.585 (random sempurna)

    Akumulasi bandar = banyak candle hijau kecil → H rendah → prediktabel
    Skor maks: 10
    """
    import numpy as _np_ent
    score  = 0
    alasan = []

    close  = df["Close"].astype(float)
    ret10  = close.pct_change().tail(10)

    pos   = int((ret10 >  0.005).sum())
    neg   = int((ret10 < -0.005).sum())
    flat  = 10 - pos - neg

    counts = _np_ent.array([pos, neg, flat], dtype=float)
    total  = counts.sum()
    if total == 0:
        return score, alasan, 1.0

    probs = counts / total
    probs = probs[probs > 0]
    H     = float(-_np_ent.sum(probs * _np_ent.log2(probs)))
    H_max = float(_np_ent.log2(3))
    H_norm = H / H_max if H_max > 0 else 1.0

    if H_norm < 0.5 and pos > neg:
        score  += 10
        alasan.append(f"📐 Entropi rendah H={H_norm:.2f} (harga teratur naik)")
    elif H_norm < 0.65 and pos >= neg:
        score  += 5
        alasan.append(f"📐 Entropi moderat H={H_norm:.2f}")
    elif H_norm > 0.9:
        score  -= 3
        alasan.append(f"🔀 Entropi tinggi H={H_norm:.2f} (noise)")

    return score, alasan, round(H_norm, 3)


# Helper: NaN check aman untuk float/numpy
def _pd_isnan(val):
    try:
        import math
        return math.isnan(float(val))
    except Exception:
        return True


# ── P7. EEG — ElectroEncephaloGram Bandar ───────────────────
def _eeg_bandar_score(df):
    """
    EEG Physics: Deteksi 'gelombang otak' (brain-wave) aktivitas bandar.

    Analogi neurosains → pasar:
      Alpha wave  → bandar tenang, akumulasi teratur (range sempit, CLR konsisten)
      Beta wave   → bandar aktif mendorong (body besar, volume terkompresi)
      Gamma burst → breakout imminent (body dominan + volume spike)

    Metrik:
    1. CLR (Close Location Ratio): (Close-Low)/(High-Low)
       CLR > 0.6 konsisten = bandar selalu push close ke atas = fingerprint akumulasi
    2. Volume Compression Ratio:
       Volume naik tapi range candle menyempit = bandar mengontrol supply (stealth)
    3. Candle Body Dominance:
       Body/Range > 0.6 + arah hijau = gerakan terkontrol (bukan noise)

    Skor maks: 30
    """
    score  = 0
    alasan = []

    close  = df["Close"].astype(float)
    high   = df["High"].astype(float)
    low    = df["Low"].astype(float)
    open_  = df["Open"].astype(float)
    volume = df["Volume"].astype(float)

    rng   = (high - low).replace(0, float("nan"))

    # ── 1. CLR — Close Location Ratio (bandar fingerprint) ────
    clr    = (close - low) / rng
    clr_5d = float(clr.tail(5).mean())

    if not _pd_isnan(clr_5d):
        if clr_5d >= 0.75:
            score  += 14
            alasan.append(f"🧠 EEG Alpha: CLR={clr_5d:.2f} (bandar push close ke atas — akumulasi kuat)")
        elif clr_5d >= 0.60:
            score  += 8
            alasan.append(f"🧠 EEG: CLR={clr_5d:.2f} (tekanan beli konsisten)")
        elif clr_5d < 0.35:
            score  -= 6
            alasan.append(f"🔻 EEG: CLR={clr_5d:.2f} (close di bawah — tekanan jual dominan)")
    else:
        clr_5d = 0.0

    # ── 2. Volume Compression (stealth accumulation signal) ───
    vol_mean5  = float(volume.tail(5).mean())
    vol_mean20 = float(volume.tail(20).mean())
    rng_mean5  = float(rng.tail(5).mean()) if not _pd_isnan(float(rng.tail(5).mean())) else 0
    rng_mean20 = float(rng.tail(20).mean()) if not _pd_isnan(float(rng.tail(20).mean())) else 1

    if vol_mean20 > 0 and rng_mean20 > 0:
        vol_ratio_5_20   = vol_mean5 / (vol_mean20 + 1e-9)
        range_compression = rng_mean5 / (rng_mean20 + 1e-9)

        # Volume naik TAPI range menyempit = bandar absorb supply diam-diam
        if vol_ratio_5_20 >= 1.2 and range_compression < 0.75:
            score  += 12
            alasan.append(f"🧠 EEG Beta: Vol↑{vol_ratio_5_20:.1f}× Range↓{range_compression:.2f} (stealth accumulation)")
        elif vol_ratio_5_20 >= 1.0 and range_compression < 0.65:
            score  += 6
            alasan.append(f"🧠 EEG: Vol stabil + range kompres ({range_compression:.2f})")

    # ── 3. Body Dominance — Controlled Movement ───────────────
    body        = (close - open_).abs()
    body_ratio  = body / (rng.fillna(0) + 1e-9)
    bullish_dom = ((close > open_) & (body_ratio > 0.55)).tail(5).sum()

    if bullish_dom >= 4:
        score  += 4
        alasan.append(f"🧠 EEG Gamma: {bullish_dom}/5 candle body besar bullish (gerakan terkontrol)")
    elif bullish_dom >= 3:
        score  += 2
        alasan.append(f"🧠 EEG: {bullish_dom}/5 controlled bullish body")

    return score, alasan, round(clr_5d, 3)


# ── P8. EOG — ElectroOculoGram Bandar ───────────────────────
def _eog_bandar_score(df):
    """
    EOG Physics: Deteksi 'arah pandang' (gaze direction) bandar melalui money flow.

    Analogi neurosains → pasar:
      Saccade  (rapid eye movement) → bandar tiba-tiba agresif beli/jual (CMF flip)
      Fixation (mata diam)          → bandar fokus absorb di zona harga tertentu
      Nystagmus                     → bandar ciptakan volatilitas palsu (distribusi)

    Metrik:
    1. CMF (Chaikin Money Flow, 20p):
       CMF > 0.10  = net inflow — bandar beli
       CMF < -0.10 = net outflow — distribusi / jual
       CMF balik positif mendadak = Saccade (bandar masuk agresif)
    2. MFI (Money Flow Index, 14p):
       RSI berbasis typical price × volume
       MFI > 60 = strong money inflow
    3. A/D Line Slope (Accumulation/Distribution):
       Slope positif = long-term akumulasi trend

    Skor maks: 30
    """
    score  = 0
    alasan = []

    close  = df["Close"].astype(float)
    high   = df["High"].astype(float)
    low    = df["Low"].astype(float)
    volume = df["Volume"].astype(float)

    # ── 1. CMF — Chaikin Money Flow ────────────────────────────
    mfm     = ((close - low) - (high - close)) / (high - low + 1e-9)
    mfv     = mfm * volume
    vol_sum = volume.rolling(20).sum()
    cmf     = mfv.rolling(20).sum() / (vol_sum + 1e-9)
    cmf_now = float(cmf.iloc[-1]) if not _pd_isnan(float(cmf.iloc[-1])) else 0.0

    if cmf_now >= 0.25:
        score  += 15
        alasan.append(f"👁️ EOG Fixation: CMF={cmf_now:.3f} (bandar akumulasi sangat kuat)")
    elif cmf_now >= 0.15:
        score  += 10
        alasan.append(f"👁️ EOG: CMF={cmf_now:.3f} (net inflow kuat — bandar beli)")
    elif cmf_now >= 0.08:
        score  += 5
        alasan.append(f"👁️ EOG: CMF={cmf_now:.3f} (inflow positif moderat)")
    elif cmf_now <= -0.15:
        score  -= 10
        alasan.append(f"🔻 EOG: CMF={cmf_now:.3f} (distribusi kuat — bandar jual!)")
    elif cmf_now <= -0.05:
        score  -= 4
        alasan.append(f"⚠️ EOG: CMF={cmf_now:.3f} (tekanan jual ringan)")

    # Saccade: CMF flip dari negatif ke positif (bandar masuk mendadak)
    if len(cmf) >= 6:
        cmf_prev = float(cmf.iloc[-5]) if not _pd_isnan(float(cmf.iloc[-5])) else 0.0
        if cmf_now >= 0.10 and cmf_prev <= 0:
            score  += 7
            alasan.append(f"👁️ EOG Saccade: CMF flip ↑ (bandar masuk agresif!)")

    # ── 2. MFI — Money Flow Index ──────────────────────────────
    typical = (high + low + close) / 3
    mf_raw  = typical * volume
    tp_diff = typical.diff()

    pos_mf  = mf_raw.where(tp_diff > 0, 0.0)
    neg_mf  = mf_raw.where(tp_diff < 0, 0.0)
    pos_sum = pos_mf.rolling(14).sum()
    neg_sum = neg_mf.rolling(14).sum().abs()
    mfr     = pos_sum / (neg_sum + 1e-9)
    mfi     = (100 - (100 / (1 + mfr)))
    mfi_now = float(mfi.iloc[-1]) if not _pd_isnan(float(mfi.iloc[-1])) else 50.0

    if mfi_now >= 70:
        score  += 8
        alasan.append(f"👁️ EOG: MFI={mfi_now:.0f} (strong money inflow)")
    elif mfi_now >= 55:
        score  += 4
        alasan.append(f"👁️ EOG: MFI={mfi_now:.0f} (inflow moderat)")
    elif mfi_now <= 30:
        score  -= 5
        alasan.append(f"⚠️ EOG Nystagmus: MFI={mfi_now:.0f} (outflow — distribusi terdeteksi)")

    # ── 3. A/D Line Slope ──────────────────────────────────────
    ad_line = ((2*close - low - high) / (high - low + 1e-9) * volume).cumsum()
    if len(ad_line) >= 10:
        ad_slope  = float(ad_line.diff(5).iloc[-1])
        ad_absavg = float(ad_line.abs().tail(20).mean())
        if ad_absavg > 0:
            ad_norm = ad_slope / (ad_absavg + 1e-9)
            if ad_norm > 0.25:
                score  += 7
                alasan.append(f"👁️ EOG A/D: Akumulasi kuat (norm={ad_norm:.2f})")
            elif ad_norm > 0.08:
                score  += 3
                alasan.append(f"👁️ EOG A/D: Akumulasi moderat")
            elif ad_norm < -0.25:
                score  -= 5
                alasan.append(f"⚠️ EOG A/D: Distribusi long-term terdeteksi")

    return score, alasan, round(cmf_now, 3)


# ── BANDAR VERDICT — Sintesis EEG + EOG + Newton + Momentum ──
def _bandar_role_verdict(eeg_score, eog_score, p2_score, p4_score, cmf, clr):
    """
    Sintesis 4 komponen bandar detection → verdict akhir.

    Skoring bandar:
      EEG + EOG + Newton (P2) + Momentum (P4) → total bandar score

    Verdict:
      ≥ 65: BANDAR AKTIF AKUMULASI   → sinyal valid, ikut
      ≥ 45: BANDAR TERDETEKSI         → sinyal cukup kuat
      ≥ 25: BANDAR MUNGKIN HADIR      → perlu konfirmasi
      < 25: BANDAR TIDAK TERDETEKSI   → hati-hati, noise
      Negatif EOG/EEG: DISTRIBUSI     → waspadai jebakan
    """
    bandar_raw = eeg_score + eog_score + p2_score * 0.5 + p4_score * 0.5
    bandar_max = 30 + 30 + 12.5 + 10  # = 82.5

    # Deteksi distribusi — EOG negatif overrides semua
    is_distribusi = (cmf < -0.10) and (clr < 0.35)

    if is_distribusi:
        return "🔴 BANDAR DISTRIBUSI — Waspada Jebakan!", bandar_raw

    pct = (bandar_raw / bandar_max) * 100 if bandar_max > 0 else 0

    if pct >= 65:
        verdict = "✅ BANDAR AKTIF AKUMULASI — Sinyal Valid"
    elif pct >= 45:
        verdict = "🟡 BANDAR TERDETEKSI — Cukup Kuat"
    elif pct >= 25:
        verdict = "🟠 BANDAR MUNGKIN HADIR — Perlu Konfirmasi"
    else:
        verdict = "⚪ BANDAR TIDAK TERDETEKSI — Hati-hati Noise"

    return verdict, bandar_raw


