def _get_ihsg_gain_5d():
    """Fix 2: Fetch IHSG 5-day gain — cached 10 menit agar tidak flood."""
    cached = cache_get("ihsg_gain_5d")
    if cached is not None:
        return cached
    try:
        url = ("https://query1.finance.yahoo.com/v8/finance/chart/%5EJKSE"
               "?range=10d&interval=1d")
        r = _http.get(url, headers={"User-Agent": "Mozilla/5.0"}, timeout=8)
        data = r.json()["chart"]["result"][0]
        closes = [c for c in data["indicators"]["quote"][0]["close"] if c is not None]
        if len(closes) >= 6:
            gain = (closes[-1] - closes[-6]) / closes[-6] * 100
            cache_set("ihsg_gain_5d", gain, ttl=600)
            return gain
    except Exception:
        pass
    return 0.0

def _get_ihsg_live_price():
    """
    Ambil harga IHSG real-time via 3-endpoint failover chain.
    PHYSICS: N-modular redundancy — system tidak gagal jika 1 node down.
    Return float > 1000 jika berhasil, else 0.0.
    """
    crumb, cookie = get_yahoo_crumb()
    endpoints = [
        f"https://query1.finance.yahoo.com/v8/finance/chart/%5EJKSE?range=1d&interval=1m{'&crumb='+crumb if crumb else ''}",
        f"https://query2.finance.yahoo.com/v8/finance/chart/%5EJKSE?range=1d&interval=1m{'&crumb='+crumb if crumb else ''}",
        "https://query1.finance.yahoo.com/v8/finance/chart/%5EJKSE?range=5d&interval=1d",
    ]
    headers = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
               "AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"}
    for url in endpoints:
        try:
            r = _http.get(url, headers=headers, cookies=cookie or {}, timeout=8)
            if r.status_code != 200: continue
            meta = r.json()["chart"]["result"][0]["meta"]
            live = float(meta.get("regularMarketPrice") or 0)
            if live > 1000:
                return live
        except Exception:
            continue
    return 0.0


