# ── IDEA #3: SIGNAL COOLDOWN ─────────────────────────────
# ═══════════════════════════════════════════════════════════
_COOLDOWN_HOURS = 4   # skip sinyal yang sama < 4 jam

def signal_in_cooldown(kode: str) -> bool:
    """Return True kalau sinyal kode ini baru dikirim < _COOLDOWN_HOURS lalu."""
    try:
        conn = _db_conn_read()
        row  = conn.execute(
            "SELECT last_sent FROM signal_cooldown WHERE kode=?", (kode,)
        ).fetchone()
        conn.close()
        if row is None:
            return False
        elapsed = time.time() - row["last_sent"]
        return elapsed < _COOLDOWN_HOURS * 3600
    except Exception:
        return False

def signal_set_cooldown(kode: str):
    """Catat timestamp sinyal terakhir untuk kode ini."""
    try:
        with _db_lock:
            conn = _db_conn()
            conn.execute(
                "INSERT OR REPLACE INTO signal_cooldown(kode, last_sent) VALUES(?,?)",
                (kode, time.time())
            )
            conn.commit(); conn.close()
    except Exception as e:
        logger.warning("signal_set_cooldown %s: %s", kode, e)


