# ── IDEA #2: ADAPTIVE UNIVERSE FILTER ────────────────────
# ═══════════════════════════════════════════════════════════
_ADAPTIVE_VOL_THRESHOLD = 500_000   # min avg volume 5d (shares)
_adaptive_universe_cache: list = []
_adaptive_universe_ts: float = 0.0
_ADAPTIVE_CACHE_TTL = 6 * 3600      # refresh tiap 6 jam

def get_adaptive_universe(base_universe: list) -> list:
    """
    Cull saham dengan avg volume 5d < threshold dari base_universe.
    Cache 6 jam. Return subset yang liquid aktif.
    """
    global _adaptive_universe_cache, _adaptive_universe_ts
    now = time.time()
    if _adaptive_universe_cache and (now - _adaptive_universe_ts) < _ADAPTIVE_CACHE_TTL:
        return _adaptive_universe_cache

    liquid = []
    hdr    = {"User-Agent": "Mozilla/5.0"}
    for kode in base_universe:
        try:
            url = (f"https://query1.finance.yahoo.com/v8/finance/chart/"
                   f"{kode}.JK?range=5d&interval=1d")
            r   = _http.get(url, headers=hdr, timeout=6)
            q   = r.json()["chart"]["result"][0]["indicators"]["quote"][0]
            vols = [v for v in q.get("volume", []) if v]
            if vols and (sum(vols) / len(vols)) >= _ADAPTIVE_VOL_THRESHOLD:
                liquid.append(kode)
        except Exception:
            liquid.append(kode)   # keep kalau error (safe default)
        time.sleep(0.05)

    _adaptive_universe_cache = liquid if len(liquid) > 20 else base_universe
    _adaptive_universe_ts    = now
    logger.info("Adaptive universe: %d/%d saham lolos filter volume",
                len(_adaptive_universe_cache), len(base_universe))
    return _adaptive_universe_cache


