# ── IDEA #13: ANOMALY DETECTION — Silent Accumulation ────
# ═══════════════════════════════════════════════════════════
def detect_silent_accumulation(df, window: int = 20) -> dict:
    """
    Flag 'silent accumulation' bandar:
    Volume hari ini > mean + 2.5σ (rolling 20d) DAN perubahan harga ≤ 0.8%.
    Return dict: {detected: bool, vol_z: float, price_chg_pct: float, label: str}
    """
    result = {"detected": False, "vol_z": 0.0, "price_chg_pct": 0.0, "label": ""}
    try:
        import numpy as _np
        if len(df) < window + 2:
            return result
        vols    = df["Volume"].values
        closes  = df["Close"].values
        roll_v  = vols[-(window+1):-1]
        mean_v  = _np.mean(roll_v)
        std_v   = _np.std(roll_v)
        if std_v == 0:
            return result
        today_v  = vols[-1]
        z        = (today_v - mean_v) / std_v
        price_ch = abs(closes[-1] - closes[-2]) / closes[-2] * 100

        result["vol_z"]         = round(z, 2)
        result["price_chg_pct"] = round(price_ch, 2)

        if z >= 2.5 and price_ch <= 0.8:
            result["detected"] = True
            if z >= 4.0:
                result["label"] = "🐋 AKUMULASI MASIF (Vol Z>" + f"{z:.1f}σ, Δharga {price_ch:.1f}%)"
            else:
                result["label"] = f"🔇 Silent Accumulation (Vol Z={z:.1f}σ, Δharga {price_ch:.1f}%)"
    except Exception:
        pass
    return result


