# ── IDEA #1: MTF CONFLUENCE ENGINE ───────────────────────
# ═══════════════════════════════════════════════════════════
_MTF_CACHE_TTL = 30 * 60   # 30 menit

def _mtf_quick_score(df) -> float:
    """
    Hitung quick confluence score 0–100 dari df candle satu TF.
    Pakai RSI + EMA trend + MACD cross + volume ratio.
    """
    try:
        import numpy as _np
        cl  = df["Close"].values
        vol = df["Volume"].values
        if len(cl) < 26:
            return 50.0
        # RSI 14
        delta  = _np.diff(cl)
        gain   = _np.where(delta > 0, delta, 0)
        loss   = _np.where(delta < 0, -delta, 0)
        ag     = _np.convolve(gain, _np.ones(14)/14, mode="valid")[-1]
        al     = _np.convolve(loss, _np.ones(14)/14, mode="valid")[-1]
        rsi    = 100 - 100/(1 + ag/al) if al > 0 else 100.0
        # EMA trend
        ema20  = pd.Series(cl).ewm(span=20, adjust=False).mean().values[-1]
        ema50  = pd.Series(cl).ewm(span=50, adjust=False).mean().values[-1]
        # MACD
        m_fast = pd.Series(cl).ewm(span=12, adjust=False).mean().values
        m_slow = pd.Series(cl).ewm(span=26, adjust=False).mean().values
        macd   = m_fast[-1] - m_slow[-1]
        # Volume ratio
        v_avg  = _np.mean(vol[-20:]) if len(vol) >= 20 else _np.mean(vol)
        v_rat  = vol[-1] / v_avg if v_avg > 0 else 1.0

        score  = 50.0
        # RSI bullish zone
        if 45 <= rsi <= 70:   score += 15
        elif rsi < 35:        score += 10    # oversold bounce potential
        elif rsi > 80:        score -= 10
        # EMA trend
        if cl[-1] > ema20 > ema50:  score += 20
        elif cl[-1] < ema20 < ema50: score -= 20
        # MACD
        if macd > 0:  score += 10
        else:          score -= 10
        # Volume
        if v_rat > 1.5:  score += 5
        return max(0.0, min(100.0, score))
    except Exception:
        return 50.0

def get_mtf_confluence(kode: str) -> dict:
    """
    Pull data D/W/4H, hitung quick score tiap TF,
    return agreement + composite score.
    Cache 30 menit di SQLite.
    """
    import math
    try:
        conn = _db_conn_read()
        row  = conn.execute(
            "SELECT score_d,score_w,score_4h,agreement,ts FROM mtf_cache WHERE kode=?",
            (kode,)).fetchone()
        conn.close()
        if row and (time.time() - row["ts"]) < _MTF_CACHE_TTL:
            return {"score_d": row["score_d"], "score_w": row["score_w"],
                    "score_4h": row["score_4h"], "agreement": row["agreement"],
                    "composite": round((row["score_d"]+row["score_w"]+row["score_4h"])/3, 1)}
    except Exception:
        pass

    hdr     = {"User-Agent": "Mozilla/5.0"}
    configs = [("1d","3mo","score_d"), ("1wk","1y","score_w"), ("60m","2mo","score_4h")]
    scores  = {}
    for interval, rng, key in configs:
        try:
            url = (f"https://query1.finance.yahoo.com/v8/finance/chart/"
                   f"{kode}.JK?range={rng}&interval={interval}")
            r   = _http.get(url, headers=hdr, timeout=10)
            res = r.json()["chart"]["result"][0]
            q   = res["indicators"]["quote"][0]
            ts  = res["timestamp"]
            rows = [(o,h,l,c,v)
                    for o,h,l,c,v in zip(q["open"],q["high"],q["low"],q["close"],q["volume"])
                    if None not in (o,h,l,c)]
            if len(rows) < 10:
                scores[key] = 50.0; continue
            opens  = [r[0] for r in rows]; highs=[r[1] for r in rows]
            lows   = [r[2] for r in rows]; closes=[r[3] for r in rows]
            vols   = [r[4] if r[4] else 0 for r in rows]
            df_tmp = pd.DataFrame({
                "Open":opens,"High":highs,"Low":lows,"Close":closes,"Volume":vols
            })
            scores[key] = _mtf_quick_score(df_tmp)
        except Exception:
            scores[key] = 50.0
        time.sleep(0.1)

    sd  = scores.get("score_d",  50.0)
    sw  = scores.get("score_w",  50.0)
    s4h = scores.get("score_4h", 50.0)
    # Agreement: berapa TF yang bullish (score >= 60)?
    agree = sum(1 for s in [sd, sw, s4h] if s >= 60)
    composite = round((sd + sw + s4h) / 3, 1)

    try:
        with _db_lock:
            conn = _db_conn()
            conn.execute(
                "INSERT OR REPLACE INTO mtf_cache VALUES(?,?,?,?,?,?)",
                (kode, sd, sw, s4h, agree, time.time()))
            conn.commit(); conn.close()
    except Exception:
        pass

    return {"score_d": sd, "score_w": sw, "score_4h": s4h,
            "agreement": agree, "composite": composite}


