# ── IDEA #15: AUTO-NARRATIVE GENERATOR ───────────────────
# ═══════════════════════════════════════════════════════════
def generate_narrative(kode, harga, rsi, vol_x, x20_ema, macd_val,
                       score, regime, mtf_agree=None, silent_acc=False) -> str:
    """
    Generate narasi analis 2-3 kalimat otomatis dari kondisi indikator.
    Template-based, tidak butuh LLM.
    """
    parts = []

    # Fase harga
    if x20_ema <= -10:
        parts.append(f"*{kode}* berada jauh di bawah EMA20 ({x20_ema:+.1f}%), "
                     f"membentuk spring compression — potensi mantul tinggi.")
    elif x20_ema <= -3:
        parts.append(f"*{kode}* sedikit di bawah EMA20 ({x20_ema:+.1f}%), "
                     f"fase konsolidasi dekat support dinamis.")
    elif x20_ema <= 5:
        parts.append(f"*{kode}* bergerak di sekitar EMA20 ({x20_ema:+.1f}%), "
                     f"dalam equilibrium — tunggu konfirmasi arah.")
    else:
        parts.append(f"*{kode}* extended di atas EMA20 ({x20_ema:+.1f}%), "
                     f"hati-hati pullback jangka pendek.")

    # RSI + Volume
    rsi_keterangan = (
        "oversold (RSI {:.0f}) — potensi reversal".format(rsi) if rsi < 35 else
        "momentum bullish kuat (RSI {:.0f})".format(rsi) if rsi < 60 else
        "RSI {:.0f} mulai jenuh beli — waspadai distribusi".format(rsi) if rsi >= 75 else
        "RSI {:.0f} zona netral".format(rsi)
    )
    vol_keterangan = (
        f"volume {vol_x:.1f}× rata-rata (konfirmasi kuat)" if vol_x >= 2.0 else
        f"volume {vol_x:.1f}× rata-rata (normal)" if vol_x >= 0.8 else
        f"volume rendah {vol_x:.1f}× (likuiditas tipis, hati-hati)"
    )
    parts.append(f"Momentum {rsi_keterangan}, dengan {vol_keterangan}.")

    # MACD
    if macd_val > 0:
        parts.append("MACD positif mengkonfirmasi tekanan beli masih dominan.")
    else:
        parts.append("MACD masih negatif — tunggu golden cross sebelum entry agresif.")

    # Silent accumulation
    if silent_acc:
        parts.append("⚠️ Terdeteksi *silent accumulation* — volume anomali "
                     "tanpa pergerakan harga signifikan, indikasi bandar masuk diam-diam.")

    # MTF
    if mtf_agree is not None:
        if mtf_agree >= 3:
            parts.append("✅ *Konfluens 3/3 TF bullish* (D/W/4H) — setup multi-timeframe solid.")
        elif mtf_agree == 2:
            parts.append("🔶 2/3 TF bullish — setup cukup kuat, masih ada risiko countertrend.")
        else:
            parts.append("⛔ Multi-timeframe belum align — hindari entry terburu-buru.")

    # Score verdict
    if score >= 70:
        parts.append(f"Score keseluruhan *{score}/100* — peluang entry layak dipertimbangkan.")
    elif score >= 50:
        parts.append(f"Score *{score}/100* — setup moderat, sizing kecil dulu.")
    else:
        parts.append(f"Score *{score}/100* — setup belum matang, masuk watchlist dulu.")

    return "\n".join(f"  {p}" for p in parts)


