# ── IDEA #14: CORRELATION MATRIX ─────────────────────────
# ═══════════════════════════════════════════════════════════
def hitung_correlation_matrix(kode_list: list, period: str = "3mo") -> dict:
    """
    Hitung matrix korelasi return harian antar saham dalam kode_list.
    Return dict: {matrix: ndarray, labels: list, pairs: list[tuple]}
    pairs = top 3 paling berkorelasi & top 3 paling divergen.
    """
    import numpy as _np
    hdr    = {"User-Agent": "Mozilla/5.0"}
    series = {}
    for kode in kode_list[:8]:   # max 8 saham
        try:
            url = (f"https://query1.finance.yahoo.com/v8/finance/chart/"
                   f"{kode}.JK?range={period}&interval=1d")
            r   = _http.get(url, headers=hdr, timeout=10)
            res = r.json()["chart"]["result"][0]
            cl  = res["indicators"]["quote"][0]["close"]
            ts  = res["timestamp"]
            s   = pd.Series({t: c for t, c in zip(ts, cl) if c is not None})
            if len(s) >= 20:
                series[kode] = s.pct_change().dropna()
        except Exception:
            pass
        time.sleep(0.05)

    if len(series) < 2:
        return {}

    # Align index
    df_all = pd.DataFrame(series).dropna()
    labels = list(df_all.columns)
    mat    = _np.corrcoef(df_all.T.values)

    # Top correlated pairs
    pairs_corr = []
    n = len(labels)
    for i in range(n):
        for j in range(i+1, n):
            pairs_corr.append((labels[i], labels[j], round(mat[i, j], 3)))
    pairs_corr.sort(key=lambda x: abs(x[2]), reverse=True)

    return {"matrix": mat, "labels": labels,
            "top_similar": pairs_corr[:3],
            "top_divergen": sorted(pairs_corr, key=lambda x: x[2])[:3]}


def _get_market_regime_ihsg():
    """
    Market Regime IHSG — Physics-Enhanced Multi-Layer:

    Layer 1 — Position (Newton statics):
      GREEN  = IHSG live > EMA20 & EMA50
      RED    = IHSG live < EMA20 & EMA50
      NEUTRAL= di antara EMA

    Layer 2 — Velocity + Acceleration (F=ma, d²x/dt²):
      Jika posisi=RED tapi velocity 5-hari POSITIF dan akselerasi naik
      → downgrade ke NEUTRAL (mencegah false RED saat reversal intraday)
      Jika posisi=GREEN tapi velocity 5-hari NEGATIF dan akselerasi turun
      → downgrade ke NEUTRAL

    Layer 3 — Live price via 3-endpoint failover:
      Tidak pakai candle kemarin. regularMarketPrice = harga sekarang.

    Cache: 5 menit jam bursa (09:00–16:15), 30 menit luar bursa.
    """
    cached = cache_get("ihsg_regime")
    if cached is not None:
        return cached
    try:
        # Ambil data historis untuk EMA calculation
        crumb, cookie = get_yahoo_crumb()
        url_hist = "https://query1.finance.yahoo.com/v8/finance/chart/%5EJKSE?range=6mo&interval=1d"
        if crumb:
            url_hist += f"&crumb={crumb}"
        r = _http.get(url_hist,
            headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
                     "AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36"},
            cookies=cookie or {}, timeout=10)
        if r.status_code != 200:
            raise ValueError(f"HTTP {r.status_code}")
        data = r.json()["chart"]["result"][0]
        meta = data.get("meta", {})

        closes_raw = data["indicators"]["quote"][0]["close"]
        closes = [c for c in closes_raw if c is not None]
        if len(closes) < 50:
            cache_set("ihsg_regime", "UNKNOWN", ttl=300)
            return "UNKNOWN"

        import pandas as _pd_reg
        s   = _pd_reg.Series(closes, dtype=float)
        e20 = float(s.ewm(span=20, adjust=False).mean().iloc[-1])
        e50 = float(s.ewm(span=50, adjust=False).mean().iloc[-1])

        # ── Layer 3: Live price failover ─────────────────────────────────
        meta_live = float(meta.get("regularMarketPrice") or 0)
        if meta_live > 1000:
            c = meta_live
        else:
            c = _get_ihsg_live_price()
            if c <= 0:
                c = float(s.iloc[-1])  # last resort: candle kemarin

        # ── Layer 1: Position regime ──────────────────────────────────────
        if c > e20 and c > e50:
            regime_pos = "GREEN"
        elif c < e20 and c < e50:
            regime_pos = "RED"
        else:
            regime_pos = "NEUTRAL"

        # ── Layer 2: Velocity + Acceleration (F=Δp/Δt, d²x/dt²) ─────────
        velocity_5d = 0.0; accel = 0.0
        if len(closes) >= 6:
            velocity_5d = (closes[-1] - closes[-6]) / max(closes[-6], 1) * 100
        if len(closes) >= 11:
            v_now  = (closes[-1] - closes[-6]) / max(closes[-6], 1) * 100
            v_prev = (closes[-6] - closes[-11]) / max(closes[-11], 1) * 100
            accel  = v_now - v_prev

        # Koreksi regime berdasarkan momentum
        if regime_pos == "RED" and velocity_5d > 1.5 and accel > 0:
            regime = "NEUTRAL"
            logger.info("Regime RED→NEUTRAL (momentum+): v5d=%.2f%% a=%.2f", velocity_5d, accel)
        elif regime_pos == "GREEN" and velocity_5d < -2.0 and accel < 0:
            regime = "NEUTRAL"
            logger.info("Regime GREEN→NEUTRAL (momentum-): v5d=%.2f%% a=%.2f", velocity_5d, accel)
        else:
            regime = regime_pos

        now_h = now_wib().hour; now_m = now_wib().minute
        jam_bursa = (9 <= now_h < 16) or (now_h == 16 and now_m <= 15)
        ttl = 300 if jam_bursa else 1800

        cache_set("ihsg_regime", regime, ttl=ttl)
        logger.info("IHSG Regime: %s | Live=%.2f EMA20=%.2f EMA50=%.2f v5d=%.1f%% a=%.2f TTL=%ds",
                    regime, c, e20, e50, velocity_5d, accel, ttl)
        return regime
    except Exception as ex:
        logger.warning("_get_market_regime_ihsg: %s", ex)
        cache_set("ihsg_regime", "UNKNOWN", ttl=300)
        return "UNKNOWN"


def _binary_score_7(h):
    """
    Hitung binary score 0-7 (setiap sinyal = 1 poin):
      1. RSI 50-70 (bullish zone, bukan overbought)
      2. VR20 ≥ 2x
      3. CrossUp EMA
      4. MACD Golden Cross
      5. Stoch Golden Cross
      6. Breakout resistance
      7. Candle bullish (engulf / hammer / morningstar)
    """
    checks = [
        50.0 <= h.get("rsi", 0) <= 70.0,
        h.get("vol_x", 0) >= 2.0,
        bool(h.get("crossup", False)),
        bool(h.get("macd_gc", False)),
        bool(h.get("stoch_gc", False)),
        bool(h.get("breakout", False)),
        bool(h.get("engulf", False) or h.get("hammer", False) or h.get("morningstar", False)),
    ]
    return sum(1 for c in checks if c), 7


def _rsi_zone_label(rsi):
    """Label zona RSI untuk output sinyal."""
    if rsi < 30:  return "OVERSOLD"
    if rsi < 50:  return "NEUTRAL-"
    if rsi < 70:  return "NEUTRAL"
    return "OVERBOUGHT"


def _rs_ihsg_score(df):
    """
    Fix 2: Relative Strength vs IHSG — saham yang outperform IHSG dapat bonus skor.
    Return (skor 0-10, alasan_list)
    """
    try:
        closes = df["Close"].astype(float)
        if len(closes) < 6:
            return 0, []
        saham_gain_5d = (float(closes.iloc[-1]) - float(closes.iloc[-6])) / float(closes.iloc[-6]) * 100
        ihsg_gain_5d  = _get_ihsg_gain_5d()
        rs = saham_gain_5d - ihsg_gain_5d   # RS positif = outperform IHSG

        if rs >= 5:
            return 10, [f"  RS vs IHSG +{rs:.1f}% (sangat kuat)"]
        elif rs >= 2:
            return 7,  [f"📈 RS vs IHSG +{rs:.1f}% (outperform)"]
        elif rs >= 0:
            return 4,  [f"➡️ RS vs IHSG +{rs:.1f}% (setara)"]
        elif rs >= -3:
            return 0,  [f"⚠️ RS vs IHSG {rs:.1f}% (underperform)"]
        else:
            return -5, [f"🔻 RS vs IHSG {rs:.1f}% (sangat lemah)"]
    except Exception:
        return 0, []


# ── MANDATORY SCALPING GATE V7 ───────────────────────────────
def _mandatory_scalping_gate(df, rsi, vol_x):
    """
    ── HARD GATE: Semua kondisi WAJIB terpenuhi ─────────────────
    Berbeda dari skor additive biasa — ini adalah BINARY GATE.
    Jika SATU SAJA gagal → sinyal DIBLOKIR (bukan dikurangi skor).

    Target: Winrate 80%+ untuk scalping/daytrade IDX.

    7 Kondisi WAJIB:
    1. RSI 48–78 (momentum positif, belum overbought ekstrem)
    2. Volume ≥ 2.0× rata-rata (ada partisipasi nyata)
    3. EMA9 > EMA21 (trend jangka pendek bullish)
    4. MACD histogram positif (momentum positif)
    5. Close >= Open (candle hijau — konfirmasi bullish hari ini)
    6. Close > VWAP (harga di atas rata-rata tertimbang hari ini)
    7. Tidak ada 2+ candle merah berturut-turut dalam 3 hari terakhir
       (mencegah masuk di trend turun)

    Return: (lolos: bool, list_gagal: list[str])
    """
    close  = df["Close"].astype(float)
    high   = df["High"].astype(float)
    low    = df["Low"].astype(float)
    open_  = df["Open"].astype(float)
    volume = df["Volume"].astype(float)
    gagal  = []

    # 1. RSI 48–78
    if not (48 <= rsi <= 78):
        gagal.append(f"RSI {rsi:.0f} di luar 48–78")

    # 2. Volume ≥ 2.0×
    if vol_x < 2.0:
        gagal.append(f"Vol {vol_x:.1f}× < 2.0× (partisipasi lemah)")

    # 3. EMA9 > EMA21
    ema9  = close.ewm(span=9,  adjust=False).mean()
    ema21 = close.ewm(span=21, adjust=False).mean()
    if ema9.iloc[-1] <= ema21.iloc[-1]:
        gagal.append("EMA9 ≤ EMA21 (trend pendek bearish)")

    # 4. MACD histogram positif
    ema12 = close.ewm(span=12, adjust=False).mean()
    ema26 = close.ewm(span=26, adjust=False).mean()
    macd  = ema12 - ema26
    sig   = macd.ewm(span=9, adjust=False).mean()
    hist  = macd - sig
    if hist.iloc[-1] <= 0:
        gagal.append("MACD histogram negatif")

    # 5. Candle hijau (close >= open)
    if close.iloc[-1] < open_.iloc[-1]:
        gagal.append("Candle merah (close < open)")

    # 6. Close > VWAP
    typical = (high + low + close) / 3
    vwap    = (typical * volume).cumsum() / (volume.cumsum() + 1e-9)
    if close.iloc[-1] < vwap.iloc[-1] * 0.995:
        gagal.append(f"Harga di bawah VWAP")

    # 7. Tidak ada 2+ candle merah berturut-turut dalam 3 hari terakhir
    candles3 = df.tail(3)
    merah_berturut = 0
    max_merah = 0
    for _, row in candles3.iterrows():
        if float(row["Close"]) < float(row["Open"]):
            merah_berturut += 1
            max_merah = max(max_merah, merah_berturut)
        else:
            merah_berturut = 0
    if max_merah >= 2:
        gagal.append("2+ candle merah berturut (downtrend)")

    return (len(gagal) == 0), gagal


def radar_total_score(df, harga_terakhir):
    """
    PHYSICS ENGINE V7 SCALPING — Skor total 13 komponen + Mandatory Gate.

    ── MANDATORY GATE (NEW V7) ───────────────────────────────────
    Jika hard conditions tidak terpenuhi → return -1 (diblokir total).

    Komponen klasik: s1 maks 40, s2 maks 40, s3 maks 20, s4 maks 10
    Komponen fisika: P1-P8 total maks ~190
    Normalisasi: raw/150 × 100 → skala 0–100
    Market Regime: GREEN×1.0 | NEUTRAL×0.88 | RED×0.72
    """
    lolos, _ = _gorengan_filter(df, harga_terakhir)
    if not lolos:
        return -1, [], 0

    # ── Komponen klasik ───────────────────────────────────────
    s1, a1         = _bandar_accumulation_score(df)
    s2, a2, rsi    = _limit_up_score(df)
    s3, a3         = _volume_anomaly_score(df)
    s4, a4         = _rs_ihsg_score(df)
    penalty        = _false_breakout_penalty(df)

    # ── Komponen fisika ───────────────────────────────────────
    try:
        vol_avg = df["Volume"].rolling(20).mean().iloc[-1]
        vol_now = df["Volume"].iloc[-1]
        vol_x   = vol_now / vol_avg if vol_avg > 0 else 0

        p1, ap1, x20          = _hooke_bounce_score(df)
        p2, ap2               = _newton_force_score(df)
        p3, ap3               = _kinetic_energy_score(df)
        p4, ap4               = _momentum_score(df)
        p5, ap5, n_res, _tot  = _resonance_score(df, rsi, vol_x)
        p6, ap6, H            = _entropy_score(df)
        p7, ap7, clr          = _eeg_bandar_score(df)
        p8, ap8, cmf          = _eog_bandar_score(df)
    except Exception as _phys_err:
        logger.debug("physics score error: %s", _phys_err)
        p1=p2=p3=p4=p5=p6=p7=p8=0
        ap1=ap2=ap3=ap4=ap5=ap6=ap7=ap8=[]
        vol_x = 0

    # ── MANDATORY SCALPING GATE V7 ────────────────────────────
    gate_lolos, gate_gagal = _mandatory_scalping_gate(df, rsi, vol_x)
    if not gate_lolos:
        logger.debug("Mandatory gate BLOCK: %s", " | ".join(gate_gagal))
        return -1, [], rsi

    # ── Raw total ─────────────────────────────────────────────
    raw_klasik = s1 * 0.75 + s2 + s3 + s4 + penalty
    raw_fisika = p1 + p2 + p3 + p4 + p5 + p6 + p7 + p8
    raw_total  = raw_klasik + raw_fisika

    # ── Normalisasi → 0–100 (NORMALIZER naik 120→150 utk P7+P8) ─
    NORMALIZER  = 150.0
    score_norm  = (raw_total / NORMALIZER) * 100

    # ── Market Regime Multiplier ──────────────────────────────
    regime = _get_market_regime_ihsg()
    mult   = {"GREEN": 1.00, "NEUTRAL": 0.88, "RED": 0.72}.get(regime, 0.80)

    final = int(score_norm * mult)
    final = max(0, min(100, final))

    alasan = a1 + a2 + a3 + a4 + ap1 + ap2 + ap3 + ap4 + ap5 + ap6 + ap7 + ap8
    return final, alasan, rsi


# ── 7. SCAN SATU SAHAM (untuk parallel) ─────────────────────
def _scan_satu_radar_v3(ticker):
    """
    Download data + hitung skor untuk satu ticker.
    V8: Tambah gap-up filter — saham yang sudah terbang >3% DIBLOKIR.
    Ini mencegah sinyal terlambat seperti kasus SMMT (+11% saat sinyal dikirim).
    Entry zone = prev_close s/d prev_close × 1.02 (max beli +2% dari prev close).
    Return dict hasil atau None.
    """
    try:
        df, meta = _ambil_data_harian_radar(ticker)
        if df is None:
            return None

        harga = meta.get("regularMarketPrice") or df["Close"].iloc[-1]
        if not harga or harga <= 0:
            return None

        # ── Prev close untuk gap-up filter & entry zone ───────
        prev = meta.get("previousClose") or (float(df["Close"].iloc[-2]) if len(df) >= 2 else None)
        if not prev or prev <= 0:
            return None

        # ── GAP-UP FILTER V8: BLOKIR jika sudah naik > 3% ────
        # Ini adalah fix utama problem "sinyal telat" (SMMT case)
        gain_live = (harga - prev) / prev * 100
        if gain_live > 3.0:
            logger.debug("Gap-up filter BLOCK %s: sudah naik %.1f%% dari prev close",
                         ticker.replace(".JK",""), gain_live)
            return None

        # ── Jika scan pre-market (08:00–08:59): gunakan prev close sebagai harga ──
        # Karena pasar belum buka, regularMarketPrice = prev close
        now_h = now_wib().hour
        harga_scan = prev if (8 <= now_h < 9) else harga

        # Gorengan filter
        lolos, alasan_reject = _gorengan_filter(df, harga_scan)
        if not lolos:
            return None

        score, alasan, rsi = radar_total_score(df, harga_scan)
        if score < 0:
            return None

        # Volume ratio
        vol_avg = df["Volume"].rolling(20).mean().iloc[-1]
        vol_now = df["Volume"].iloc[-1]
        vol_x   = round(vol_now / vol_avg, 1) if vol_avg > 0 else 0

        # Volatilitas 5 hari
        vol5 = round(df["Close"].pct_change().tail(5).std() * 100, 1)

        # ── Entry Zone V8: prev_close s/d +2% ─────────────────
        # Jika harga sudah lewat +2% → entry tidak valid
        entry_low  = int(prev)
        entry_high = int(prev * 1.020)
        entry_valid = (gain_live <= 2.0)  # masih dalam entry zone

        # Physics metadata (untuk output Telegram)
        try:
            _, _, x20_p           = _hooke_bounce_score(df)
            _, _, H_p             = _entropy_score(df)
            _, _, n_res_p, _totp  = _resonance_score(df, rsi, vol_x)
            regime_p              = _get_market_regime_ihsg()
        except Exception:
            x20_p = 0.0; H_p = 1.0; n_res_p = 0.0; regime_p = "UNKNOWN"

        # ── CANDLESTICK PATTERN DETECTION (scalp) ───────────
        candle_pola = []
        candle_valid = False
        try:
            _o = df["Open"].values; _h = df["High"].values
            _l = df["Low"].values; _c = df["Close"].values
            _n = len(_c)
            def _bd(i): return abs(_c[i]-_o[i])
            def _fl(i): return _h[i]-_l[i] if _h[i]>_l[i] else 1
            _avg_bd = sum(_bd(i) for i in range(max(0,_n-10),_n)) / 10 + 1e-9
            for _i in range(max(2,_n-4), _n):
                _body=_bd(_i); _full=_fl(_i)
                _up=_h[_i]-max(_o[_i],_c[_i]); _lo=min(_o[_i],_c[_i])-_l[_i]
                _bull=_c[_i]>_o[_i]; _bear=_c[_i]<_o[_i]
                # Hammer
                if _lo>=_body*2 and _up<=_body*0.3 and _bull:
                    candle_pola.append("🔨Hammer"); candle_valid=True
                # Shooting Star
                if _up>=_body*2 and _lo<=_body*0.3 and _bear:
                    candle_pola.append("⭐ShootingStar")
                # Marubozu Bull
                if _up<_body*0.05 and _lo<_body*0.05 and _body>_avg_bd*1.5 and _bull:
                    candle_pola.append("🟩Marubozu"); candle_valid=True
                # Doji
                if _body/_full<0.1:
                    candle_pola.append("◆Doji")
                # Engulfing (2-bar)
                if _i>=1:
                    _po,_pc=_o[_i-1],_c[_i-1]
                    if _pc<_po and _bull and _c[_i]>_po and _o[_i]<_pc and _body>_bd(_i-1):
                        candle_pola.append("🟢BullEngulfing"); candle_valid=True
                    elif _pc>_po and _bear and _c[_i]<_po and _o[_i]>_pc and _body>_bd(_i-1):
                        candle_pola.append("🔴BearEngulfing")
                # Morning Star (3-bar)
                if _i>=2:
                    if (_c[_i-2]<_o[_i-2] and _bd(_i-2)>_avg_bd
                            and _bd(_i-1)<_bd(_i-2)*0.3
                            and _bull and _c[_i]>(_o[_i-2]+_c[_i-2])/2):
                        candle_pola.append("🌟MorningStar"); candle_valid=True
                    if (_c[_i-2]>_o[_i-2] and _bd(_i-2)>_avg_bd
                            and _bd(_i-1)<_bd(_i-2)*0.3
                            and _bear and _c[_i]<(_o[_i-2]+_c[_i-2])/2):
                        candle_pola.append("🌆EveningStar")
            # Deduplicate
            seen=set(); candle_pola=[p for p in candle_pola if not (p in seen or seen.add(p))]
        except Exception:
            pass

        # ── RBS / SBR proximity (informational, non-blocking) ─────
        try:
            _scan_rbs, _scan_sbr = _detect_rbs_sbr(df, harga_scan)
        except Exception:
            _scan_rbs, _scan_sbr = [], []

        kode = ticker.replace(".JK", "")
        return {
            "kode"        : kode,
            "ticker"      : ticker,
            "score"       : score,
            "harga"       : harga_scan,
            "prev_close"  : prev,
            "gain"        : round(gain_live, 2),
            "entry_low"   : entry_low,
            "entry_high"  : entry_high,
            "entry_valid" : entry_valid,
            "rsi"         : rsi,
            "vol_x"       : vol_x,
            "vol5"        : vol5,
            "alasan"      : alasan,
            "x20"         : x20_p,
            "entropy"     : H_p,
            "resonance"   : round(n_res_p, 1),
            "regime"      : regime_p,
            "candle_pola" : candle_pola,
            "candle_valid": candle_valid,
            "near_rbs"    : bool(_scan_rbs),
            "near_sbr"    : bool(_scan_sbr),
            "rbs_levels"  : _scan_rbs,
            "sbr_levels"  : _scan_sbr,
        }
    except:
        return None


# ── 8. RADAR V3 — MAIN FUNCTION ─────────────────────────────
def jalankan_radar_v3(dest, top_n=5, min_score=70):
    """
    Scan seluruh watchlist secara PARALEL dengan ThreadPoolExecutor.
    V7 SCALPING: min_score=70, top_n=5, mandatory gate aktif.
    Filter gorengan → mandatory gate → hitung skor → ranking Top N → kirim Telegram.
    """
    watchlist_lokal = watchlist.copy()
    total_saham     = len(watchlist_lokal)
    jam_str         = now_wib().strftime("%H:%M:%S")
    tgl_str         = now_wib().strftime("%d-%m-%Y")

    # ── Notif mulai ───────────────────────────────────────────
    mulai_msg = (
        f"⚡ *RADAR V3 — QUANT ENGINE*\n"
        f"📅 {tgl_str}  ⏰ {jam_str} WIB\n"
        f"━━━━━━━━━━━━━━━━━━━━━━\n"
        f"🔍 Scanning *{total_saham}* saham IHSG...\n"
        f"🧵 Parallel • 20 threads\n"
        f"⏳ Estimasi: *< 15 detik*"
    )
    dest_kirim_teks(dest, mulai_msg)
    print(f"\n🚀 RADAR V3 — Scan {total_saham} saham [parallel 20 threads]")

    t_mulai  = time.time()
    hasil    = []

    # ── PARALLEL SCAN ─────────────────────────────────────────
    with ThreadPoolExecutor(max_workers=20) as executor:
        futures = {
            executor.submit(_scan_satu_radar_v3, ticker): ticker
            for ticker in watchlist_lokal
        }
        for future in as_completed(futures):
            try:
                result = future.result(timeout=15)
                if result and result["score"] >= min_score:
                    hasil.append(result)
            except:
                pass

    t_selesai = time.time()
    durasi    = round(t_selesai - t_mulai, 1)

    # ── RANKING ───────────────────────────────────────────────
    hasil_sorted = sorted(hasil, key=lambda x: x["score"], reverse=True)
    top10        = hasil_sorted[:top_n]

    print(f"   ✅ Selesai {durasi}s — {len(hasil)} kandidat — Top {len(top10)} tampil")

    if not top10:
        dest_kirim_teks(dest,
            f"📊 *Radar V3 Selesai*\n"
            f"⏱ Durasi : {durasi} detik\n"
            f"😴 Tidak ada saham yang lolos filter saat ini\n"
            f"⏰ {now_wib().strftime('%H:%M:%S')} WIB")
        return

    # ── BUAT PESAN RANKING ───────────────────────────────────
    medal   = ["🥇","🥈","🥉","4️⃣","5️⃣","6️⃣","7️⃣","8️⃣","9️⃣","🔟"]
    now_h_out = now_wib().hour
    sesi_label = "🌅 PRE-MARKET" if now_h_out < 9 else ("☀️ SIANG" if now_h_out < 14 else "🌆 SORE")
    pesan   = f"*▸ RADAR {sesi_label} — TOP {len(top10)}*\n"
    pesan  += f"📅 {tgl_str}  ⏰ {now_wib().strftime('%H:%M:%S')} WIB\n"
    pesan  += f"⚡ Scan {total_saham} saham selesai dalam *{durasi}s*\n"
    pesan  += f"🚫 Gap-up >3% otomatis diblokir\n"
    pesan  += f"━━━━━━━━━━━━━━━━━━━━━━\n"

    for i, s in enumerate(top10):
        alasan_str  = " | ".join(s["alasan"][:2]) if s["alasan"] else "-"

        # Label skor
        if s["score"] >= 85:   label = "🚀 SUPER BULLISH"
        elif s["score"] >= 75: label = "🔥 STRONG BUY"
        elif s["score"] >= 70: label = "· SCALP VALID"
        else:                  label = "📊 KANDIDAT"

        # Entry zone V8
        entry_low   = s.get("entry_low",  int(s["harga"]))
        entry_high  = s.get("entry_high", int(s["harga"] * 1.02))
        entry_valid = s.get("entry_valid", True)
        gain_now    = s.get("gain", 0)
        entry_label = f"Rp{entry_low:,}–{entry_high:,}"
        entry_warn  = "" if entry_valid else " ⚠️ batas atas"
        gain_str    = f"  `({gain_now:+.1f}% vs prev)`" if gain_now != 0 else ""

        # TP/SL dari entry_low
        vol5      = s.get("vol5", 3.0)
        rsi_val   = s.get("rsi", 60)
        vol_x_val = s.get("vol_x", 2.0)
        if vol_x_val >= 5 and rsi_val >= 65: tp_pct = 5.0
        elif vol_x_val >= 3 or rsi_val >= 60: tp_pct = 3.0
        else: tp_pct = 2.0
        sl_pct   = max(min(vol5 * 0.4, 2.5), 1.5)
        tp_harga = int(entry_low * (1 + tp_pct / 100))
        sl_harga = int(entry_low * (1 - sl_pct / 100))
        rr       = round(tp_pct / sl_pct, 1)

        # Physics labels
        x20        = s.get("x20", 0)
        hooke_str  = f"🪝{x20:.0f}%" if x20 <= -5 else ""
        res        = s.get("resonance", 0)
        res_str    = f"🌊{res:.0f}/7" if res >= 4 else f"〰️{res:.0f}/7"
        H          = s.get("entropy", 1.0)
        ent_str    = f" 📐H={H:.2f}" if H < 0.65 else ""
        regime     = s.get("regime", "")
        regime_icon= {"GREEN": "🟢", "NEUTRAL": "🟡", "RED": "🔴"}.get(regime, "⚪")
        phys_line  = f"   {res_str}{ent_str}  {hooke_str}  {regime_icon}IHSG\n" if (res_str or hooke_str) else ""

        # Candle pattern line
        _cp      = s.get("candle_pola", [])
        _cp_str  = "  ".join(_cp[:2]) if _cp else "—"
        _cv_icon = "✅" if s.get("candle_valid") else "⚠️"

        # RBS / SBR proximity tag
        _zone_tag = ""
        if s.get("near_rbs"):
            _rbs_l = s.get("rbs_levels", [])
            _rbs_str = f"Rp{int(_rbs_l[0]):,}" if _rbs_l else ""
            _zone_tag = f"   🎯 *Near RBS* {_rbs_str} — ex-resistance jadi support\n"
        elif s.get("near_sbr"):
            _sbr_l = s.get("sbr_levels", [])
            _sbr_str = f"Rp{int(_sbr_l[0]):,}" if _sbr_l else ""
            _zone_tag = f"   ⚠️ *Near SBR* {_sbr_str} — ex-support jadi resistance\n"

        pesan += (
            f"{medal[i]} *{s['kode']}*  Score:`{s['score']}`  {label}\n"
            f"   🎯 Entry Zone: *{entry_label}*{entry_warn}{gain_str}\n"
            f"   ✅ TP: Rp{tp_harga:,} `(+{tp_pct:.0f}%)`   🛑 SL: Rp{sl_harga:,} `(-{sl_pct:.1f}%)`\n"
            f"   ⚖️ R/R: `1:{rr}`  Vol `{s['vol_x']}×`  RSI `{s['rsi']}`\n"
            f"   🕯️ {_cv_icon} {_cp_str}\n"
            f"{_zone_tag}"
            f"{phys_line}"
            f"   🧠 _{alasan_str}_\n"
            f"   ─────────────────────\n"
        )

    pesan += (
        f"📌 *Scalp Rules V8:*\n"
        f"⏰ Sinyal pre-market — order sebelum jam 09:00 WIB\n"
        f"🎯 Beli *dalam entry zone saja* — jangan kejar harga\n"
        f"🚫 Jika buka > entry_high → LEWATI, tunggu sinyal lain\n"
        f"🛑 Patuhi SL ketat — no average down\n"
        f"🎯 Max 3–5 posisi sehari — kualitas > kuantitas\n"
        f"85+▲▲ Prio 1  •  75+▲ Prio 2  •  70+· Prio 3\n"
        f"⚠️ _Bukan rekomendasi. DYOR & manajemen risiko._"
    )

    dest_kirim_teks(dest, pesan)

    # ── CHART TOP 3 ──────────────────────────────────────────
    for s in top10[:3]:
        time.sleep(1)
        buf = buat_chart_buffer(s["ticker"])
        if buf:
            # [FIX v2] Tambah candlestick patterns ke caption scalp radar
            _cpola = s.get("candle_pola", [])
            _pola_str = "  ".join(_cpola[:3]) if _cpola else "—"
            _cv_mark = "✅" if s.get("candle_valid") else "⚠️"
            caption = (
                f"📊 *Chart Pro {s['kode']}*  —  Rank #{top10.index(s)+1}\n"
                f"🎯 Score: `{s['score']}`  •  RSI: `{s['rsi']}`\n"
                f"🕯️ Candle: {_cv_mark} {_pola_str}\n"
                f"🧠 {' | '.join(s['alasan'][:2]) if s['alasan'] else '-'}\n"
                f"🟡 BB  •  🟣 VWAP  •  🟡 EMA50  •  🩷 EMA200\n"
                f"📉 RSI(14)  •  📈 MACD  •  📊 Stoch(14,3,3)"
            )
            dest_kirim_foto_buf(dest, buf, caption)


# ── 9. COMMAND: /radar ───────────────────────────────────────
def proses_cmd_radar_v3(args, dest):
    """
    Handler untuk command /radar.
    V7 SCALPING: default top_n=5, min_score=70
    Argumen opsional: /radar [top_n] [min_score]
    Contoh: /radar 5 70
    """
    top_n     = 5
    min_score = 70

    if len(args) >= 1 and args[0].isdigit():
        top_n = min(int(args[0]), 10)
    if len(args) >= 2 and args[1].isdigit():
        min_score = max(int(args[1]), 65)  # floor 65 — tidak boleh kurang

    jalankan_radar_v3(dest, top_n=top_n, min_score=min_score)

