# ═══════════════════════════════════════════════════════════
# CHART UTILITIES — Annotation & Watermark
# ═══════════════════════════════════════════════════════════

def _annotate_candle_patterns(ax, df_plot, n):
    """
    IDEA #10: Detect & annotate candlestick patterns langsung di chart.
    Tambah label kecil di atas/bawah candle yang terdeteksi.
    """
    try:
        opens  = df_plot["Open"].values
        highs  = df_plot["High"].values
        lows   = df_plot["Low"].values
        closes = df_plot["Close"].values
        for i in range(2, n):
            o, h, l, c = opens[i], highs[i], lows[i], closes[i]
            body  = abs(c - o)
            range_ = h - l if h > l else 1
            # Hammer / Shooting Star
            lower_wick = min(o, c) - l
            upper_wick = h - max(o, c)
            if lower_wick > 2 * body and upper_wick < body * 0.3 and range_ > 0:
                ax.annotate("🔨", xy=(i, l), xytext=(i, l - range_*0.06),
                            fontsize=7, ha="center", color=THEME["grn"], zorder=8)
            elif upper_wick > 2 * body and lower_wick < body * 0.3 and c < o:
                ax.annotate("⭐", xy=(i, h), xytext=(i, h + range_*0.04),
                            fontsize=7, ha="center", color=THEME["red"], zorder=8)
            # Doji
            if body <= range_ * 0.08 and range_ > 0:
                ax.annotate("◆", xy=(i, (h+l)/2), fontsize=6,
                            ha="center", color=THEME["gold"], zorder=8)
            # Engulfing (bullish)
            if i >= 1:
                po, pc = opens[i-1], closes[i-1]
                if pc < po and c > o and c > po and o < pc:  # bull engulfing
                    ax.annotate("▲ ENG", xy=(i, l), xytext=(i, l - range_*0.08),
                                fontsize=6.5, ha="center", color=THEME["grn"],
                                fontweight="bold", zorder=8)
    except Exception:
        pass


# ═══════════════════════════════════════════════════════════
# IDEA #11: DM SIGNAL CARD — PNG per sinyal
# ═══════════════════════════════════════════════════════════
def buat_signal_card(kode, harga, pola, skor, tp1, sl,
                     rsi, vol_x, regime, df=None) -> "io.BytesIO | None":
    """
    Generate PNG card sinyal untuk DM.
    Layout: nama besar | score gauge | TP/SL table | mini sparkline.
    """
    try:
        fig = plt.figure(figsize=(9, 5), facecolor=THEME["bg"])
        gs  = gridspec.GridSpec(2, 3, figure=fig,
                                left=0.04, right=0.97,
                                top=0.88, bottom=0.08,
                                wspace=0.35, hspace=0.45)
        ax_gauge = fig.add_subplot(gs[0, 0])
        ax_info  = fig.add_subplot(gs[0, 1:])
        ax_spark = fig.add_subplot(gs[1, :2])
        ax_tp    = fig.add_subplot(gs[1, 2])

        for ax in [ax_gauge, ax_info, ax_spark, ax_tp]:
            ax.set_facecolor(THEME["card"])
            ax.spines[:].set_visible(False)

        # ── Score Gauge (half donut) ──────────────────────────
        score_clr = THEME["grn"] if skor >= 65 else THEME["ylw"] if skor >= 40 else THEME["red"]
        filled = skor / 100
        ax_gauge.pie([filled, 1 - filled],
                     colors=[score_clr, THEME["card2"]],
                     startangle=180, counterclock=False,
                     wedgeprops=dict(width=0.38, edgecolor=THEME["bg"]))
        ax_gauge.text(0, -0.15, f"{skor}", ha="center", va="center",
                      fontsize=22, color=score_clr, fontweight="bold")
        ax_gauge.text(0, -0.55, "/100", ha="center", va="center",
                      fontsize=9, color=THEME["sub"])
        ax_gauge.set_title("SCORE", fontsize=7.5, color=THEME["sub"], pad=2)

        # ── Info Panel ────────────────────────────────────────
        ax_info.axis("off")
        pola_clr = THEME["grn"] if "Long" in pola or "BUY" in pola.upper() else THEME["red"]
        ax_info.text(0.0, 0.92, kode, fontsize=20, color=THEME["txt"],
                     fontweight="bold", transform=ax_info.transAxes)
        ax_info.text(0.0, 0.70, f"Rp {int(harga):,}".replace(",","."),
                     fontsize=13, color=THEME["acc"], transform=ax_info.transAxes)
        ax_info.text(0.0, 0.52, pola, fontsize=10, color=pola_clr,
                     fontweight="bold", transform=ax_info.transAxes)
        ax_info.text(0.0, 0.34,
                     f"RSI {rsi:.0f}  ·  Vol {vol_x:.1f}×",
                     fontsize=8.5, color=THEME["sub"], transform=ax_info.transAxes)
        regime_clr = THEME["grn"] if "BULL" in str(regime).upper() else THEME["red"]
        ax_info.text(0.0, 0.16, f"Regime: {regime}",
                     fontsize=8, color=regime_clr, transform=ax_info.transAxes)

        # ── TP / SL table ─────────────────────────────────────
        ax_tp.axis("off")
        tp2 = round(harga * 1.04, 0) if tp1 else 0
        tp3 = round(harga * 1.07, 0) if tp1 else 0
        rows_tp = [
            ("TP1", f"Rp{int(tp1):,}".replace(",",".") if tp1 else "-", THEME["grn"]),
            ("TP2", f"Rp{int(tp2):,}".replace(",",".")  if tp2 else "-", THEME["grn"]),
            ("TP3", f"Rp{int(tp3):,}".replace(",",".")  if tp3 else "-", THEME["grn"]),
            ("SL",  f"Rp{int(sl):,}".replace(",",".")   if sl  else "-", THEME["red"]),
        ]
        for idx, (lbl, val, clr_r) in enumerate(rows_tp):
            y = 0.85 - idx * 0.22
            ax_tp.text(0.05, y, lbl, fontsize=8, color=THEME["sub"],
                       transform=ax_tp.transAxes, va="top")
            ax_tp.text(0.95, y, val, fontsize=8, color=clr_r,
                       transform=ax_tp.transAxes, va="top", ha="right", fontweight="bold")
        ax_tp.set_title("TARGET", fontsize=7.5, color=THEME["sub"], pad=2)

        # ── Sparkline 20 candle ───────────────────────────────
        ax_spark.set_facecolor(THEME["card"])
        if df is not None and len(df) >= 5:
            df_sp = df.tail(25).copy()
            sp_n  = len(df_sp)
            sp_o  = df_sp["Open"].values
            sp_h  = df_sp["High"].values
            sp_l  = df_sp["Low"].values
            sp_c  = df_sp["Close"].values
            for i in range(sp_n):
                clr_s = THEME["up"] if sp_c[i] >= sp_o[i] else THEME["dn"]
                ax_spark.plot([i,i],[sp_l[i],sp_h[i]], color=clr_s, lw=0.7)
                ax_spark.add_patch(mpatches.Rectangle(
                    (i-0.35, min(sp_o[i],sp_c[i])), 0.7, abs(sp_c[i]-sp_o[i])+1e-9,
                    color=clr_s, zorder=3))
            # EMA9 overlay
            ema9_sp = pd.Series(sp_c).ewm(span=9, adjust=False).mean().values
            ax_spark.plot(range(sp_n), ema9_sp, color=THEME["gold"], lw=1.0)
        ax_spark.set_xticks([]); ax_spark.set_yticks([])
        ax_spark.set_title("25D CANDLE + EMA9", fontsize=7.5, color=THEME["sub"], pad=2)

        # ── Watermark ─────────────────────────────────────────
        _add_watermark(ax_spark)

        # ── Supertitle ────────────────────────────────────────
        ts_str = now_wib().strftime("%d/%m/%Y %H:%M WIB")
        fig.text(0.5, 0.955, f"📡  SIGNAL ALERT — {ts_str}",
                 ha="center", fontsize=9.5, color=THEME["sub"])

        buf = io.BytesIO()
        fig.savefig(buf, format="png", dpi=130,
                    bbox_inches="tight", facecolor=THEME["bg"])
        plt.close(fig)
        buf.seek(0)
        return buf
    except Exception as e:
        logger.error("buat_signal_card error: %s", e)
        return None


