def jalankan_scan_satu(kode, dest):
    """Scan 1 saham — kirim hasil ke dest (DM atau topic asal perintah)."""
    ticker  = kode + ".JK"
    jam_str = now_wib().strftime("%H:%M:%S")

    laporan_sinyal, signal_info = cek_semua_sinyal(ticker)
    if laporan_sinyal:
        # Kirim dengan inline keyboard
        kirim_inline_keyboard(dest, laporan_sinyal, kode)
    else:
        dest_kirim_teks(dest, f"📋 *{kode}* — Tidak ada sinyal candlestick saat ini\n⏰ {jam_str} WIB")
    time.sleep(1)

    dest_kirim_foto(dest, ticker, signal_info)

def jalankan_scan(from_name="Auto", dest=None):
    global sedang_scan, sudah_kirim
    sedang_scan = True
    sudah_kirim.clear()

    now     = now_wib()
    jam_str = now.strftime("%H:%M:%S")
    print(f"\n🔍 SCAN MANUAL [{jam_str}] oleh {from_name} — {len(watchlist)} saham")

    sinyal_ke = 0
    for saham in watchlist:
        if bot_stop:
            dest_kirim_teks(dest, f"⛔ *Scan Dihentikan!*\n📊 {sinyal_ke} sinyal sebelum stop\n⏰ {now_wib().strftime('%H:%M:%S')} WIB")
            sedang_scan = False
            return

        kode = saham.replace(".JK", "")

        # ── IDEA #3: Signal Cooldown ──────────────────────────
        if signal_in_cooldown(kode):
            time.sleep(0.1); continue

        laporan_sinyal, signal_info_scan = cek_semua_sinyal(saham)
        if laporan_sinyal:
            sinyal_ke += 1
            pola_sinyal = laporan_sinyal.split("\n")[0]
            print(f"   🎯 Sinyal #{sinyal_ke}: {kode}!")
            catat_sinyal_ringkasan(kode, pola_sinyal, sumber="SCAN")
            signal_set_cooldown(kode)   # set cooldown setelah kirim

            dest_kirim_teks(dest, laporan_sinyal)
            time.sleep(1)
            dest_kirim_foto(dest, saham, signal_info_scan)
            time.sleep(1)
        time.sleep(0.3)

    msg = (f"✅ *Scan Selesai!*\n📊 {sinyal_ke} sinyal dari {len(watchlist)} saham\n⏰ {now_wib().strftime('%H:%M:%S')} WIB"
           if sinyal_ke > 0 else
           f"✅ *Scan Selesai!*\n😴 Tidak ada sinyal saat ini\n⏰ {now_wib().strftime('%H:%M:%S')} WIB")
    dest_kirim_teks(dest, msg)
    print(f"✅ Scan selesai — {sinyal_ke} sinyal.\n")
    sedang_scan = False



def hapus_log_file(log_file, nama_topic, umur_detik):
    """Hapus pesan dari log file berdasarkan umur."""
    import json as _json, os as _os2
    if not _os2.path.exists(log_file):
        return 0
    try:
        log = _json.load(open(log_file))
    except:
        return 0
    sekarang = time.time()
    sisa  = []
    hapus = 0
    for item in log:
        if umur_detik == 0 or (sekarang - item["ts"]) >= umur_detik:
            try:
                r = _http.post(
                    f"https://api.telegram.org/bot{BOT_TOKEN}/deleteMessage",
                    data={"chat_id": CHAT_ID, "message_id": item["id"]}, timeout=10)
                if r.json().get("ok"):
                    hapus += 1
            except:
                sisa.append(item)
        else:
            sisa.append(item)
    _json.dump(sisa, open(log_file, "w"))
    return hapus

def hapus_by_umur(log_file, nama_topic, umur_detik):
    """Hapus pesan bot dari log berdasarkan umur. Aman — hanya hapus yang tercatat."""
    total = hapus_log_file(log_file, nama_topic, umur_detik)
    print(f"   ✅ {nama_topic}: {total} dihapus")
    return total



def _hitung_accum_mf_intraday(ticker):
    """
    [FIX v4-15 Opsi B] AccumMF mode intraday — pakai candle 5m range 1d.
    Dipanggil saat hari=1 supaya SM/BM hari ini valid (1 candle harian = tidak valid).
    Output dict sama dengan hitung_accum_mf + flag is_intraday=True.
    """
    url     = (f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}"
               f"?range=1d&interval=5m")
    headers = {"User-Agent": "Mozilla/5.0"}
    try:
        r    = _http.get(url, headers=headers, timeout=10)
        data = r.json()
        res  = data["chart"]["result"][0]
        meta = res.get("meta", {})
        q    = res["indicators"]["quote"][0]

        candles = [
            (o, c, h, l, v)
            for o, c, h, l, v in zip(
                q.get("open", []), q.get("close", []),
                q.get("high", []),  q.get("low", []),
                q.get("volume", []))
            if None not in (o, c, h, l, v) and v > 0
        ]

        if len(candles) < 2:
            return None

        total_cm   = 0.0
        total_sm   = 0.0
        total_bm   = 0.0
        bar_plus   = 0
        bar_minus  = 0
        cm_per_bar = []

        prev_c = candles[0][0]  # seed: open bar 5m pertama

        for o, c, h, l, v in candles:
            tp        = (h + l + c) / 3
            mf        = tp * v
            tick_size = get_idx_tick_size(max(prev_c, 1.0))
            delta     = c - prev_c

            if delta >= tick_size:
                sm = mf; bm = 0
            elif delta <= -tick_size:
                sm = 0;  bm = mf
            else:
                if   c > o: sm = mf; bm = 0
                elif c < o: sm = 0;  bm = mf
                else:       sm = 0;  bm = 0   # doji — netral

            cm         = sm - bm
            total_sm  += sm
            total_bm  += bm
            total_cm  += cm
            if cm >= 0: bar_plus  += 1
            else:       bar_minus += 1
            cm_per_bar.append(cm)
            prev_c = c

        harga = (meta.get("regularMarketPrice")
                 or meta.get("previousClose")
                 or candles[-1][1])
        nama  = ticker.replace(".JK", "")

        return {
            "kode"        : nama,
            "harga"       : harga,
            "hari"        : 1,
            "total_cm"    : total_cm,
            "total_sm"    : total_sm,
            "total_bm"    : total_bm,
            "hari_plus"   : bar_plus,    # = jumlah bar 5m SM (bukan hari)
            "hari_minus"  : bar_minus,   # = jumlah bar 5m BM
            "cm_per_hari" : cm_per_bar,
            "is_intraday" : True,        # flag untuk caller — ubah label display
            "n_bar"       : len(candles),
        }
    except Exception as e:
        print(f"   ⚠️ accum_mf_intraday error {ticker}: {e}")
        return None


def hitung_accum_mf(ticker, hari):
    """
    Hitung akumulasi CM (Clean Money) selama N hari terakhir.
    Pakai data harian (1d interval), tiap candle dihitung typical price × volume.
    CM per hari = Smart Money - Bad Money.

    [FIX v4-15]
    - hari < 1  → raise ValueError (invalid input)
    - hari == 1 → delegate ke _hitung_accum_mf_intraday() (5m bars, valid)
    - hari >= 2 → logika harian biasa
    """
    # [FIX Opsi A] Validasi minimum
    if hari < 1:
        raise ValueError(f"hitung_accum_mf: hari minimum 1 (input: {hari})")

    # [FIX Opsi B] hari=1 → intraday 5m supaya SM/BM hari ini akurat
    if hari == 1:
        return _hitung_accum_mf_intraday(ticker)

    # Tentukan range berdasarkan jumlah hari
    if hari <= 5:
        rng = "5d"
    elif hari <= 30:
        rng = "1mo"
    elif hari <= 90:
        rng = "3mo"
    elif hari <= 180:
        rng = "6mo"
    else:
        rng = "1y"

    url     = f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}?range={rng}&interval=1d"
    headers = {"User-Agent": "Mozilla/5.0"}
    try:
        r    = _http.get(url, headers=headers, timeout=10)
        data = r.json()
        res  = data["chart"]["result"][0]
        meta = res.get("meta", {})
        q    = res["indicators"]["quote"][0]

        candles = [
            (o, c, h, l, v)
            for o, c, h, l, v in zip(
                q["open"], q["close"], q["high"], q["low"], q["volume"])
            if None not in (o, c, h, l, v) and v > 0
        ]

        if len(candles) < 1:
            return None

        # Ambil N hari terakhir
        candles = candles[-hari:]
        hari_aktual = len(candles)

        total_cm     = 0.0
        total_sm     = 0.0
        total_bm     = 0.0
        total_val    = 0.0
        hari_plus    = 0
        hari_minus   = 0
        cm_per_hari  = []

        # Tick-based v4-15: bandingkan close vs prev_close (inter-candle)
        # Naik ≥ 1 tick IDX = SM; turun ≥ 1 tick = BM; ±1 tick = tiebreak body
        prev_c = candles[0][0]  # seed: open candle pertama

        for o, c, h, l, v in candles:
            tp        = (h + l + c) / 3
            mf        = tp * v
            total_val += mf
            tick_size = get_idx_tick_size(max(prev_c, 1.0))
            delta     = c - prev_c

            if delta >= tick_size:       # naik ≥ 1 tick → Smart Money
                sm = mf; bm = 0
            elif delta <= -tick_size:    # turun ≥ 1 tick → Bad Money
                sm = 0;  bm = mf
            else:                        # ±1 tick → tiebreak body
                if   c > o: sm = mf; bm = 0
                elif c < o: sm = 0;  bm = mf
                else:       sm = 0;  bm = 0   # doji — netral

            cm = sm - bm
            total_sm  += sm
            total_bm  += bm
            total_cm  += cm
            if cm >= 0: hari_plus  += 1
            else:       hari_minus += 1
            cm_per_hari.append(cm)
            prev_c = c   # update rolling

        harga = meta.get("regularMarketPrice") or candles[-1][1]
        nama  = ticker.replace(".JK", "")

        return {
            "kode"       : nama,
            "harga"      : harga,
            "hari"       : hari_aktual,
            "total_cm"   : total_cm,
            "total_sm"   : total_sm,
            "total_bm"   : total_bm,
            "hari_plus"  : hari_plus,
            "hari_minus" : hari_minus,
            "cm_per_hari": cm_per_hari,   # list CM tiap hari (untuk cek tren terbaru)
        }
    except Exception as e:
        print(f"   ⚠️ accum_mf error {ticker}: {e}")
        return None

def fmt_rupiah(nilai):
    """Format nilai rupiah ke Jt/M/T."""
    abs_v  = abs(nilai)
    prefix = "+" if nilai >= 0 else "-"
    if abs_v >= 1_000_000_000_000:
        return f"{prefix}{abs_v/1_000_000_000_000:.2f}T"
    elif abs_v >= 1_000_000_000:
        return f"{prefix}{abs_v/1_000_000_000:.2f}M"
    elif abs_v >= 1_000_000:
        return f"{prefix}{abs_v/1_000_000:.1f}Jt"
    else:
        return f"{prefix}{abs_v/1_000:.0f}Rb"



