BROKER_ASING = {"DB","CS","JP","MS","ML","UB","BK","RX","YO","BN",
                "KI","DU","EM","OD","SQ","CI","EP","XL","GR","AK"}

def fmt_lot(v):
    try:
        v = float(v)
        if   abs(v) >= 1_000_000_000: return f"{v/1_000_000_000:.2f}M"
        elif abs(v) >= 1_000_000:     return f"{v/1_000_000:.2f}Jt"
        elif abs(v) >= 1_000:         return f"{v/1_000:.1f}rb"
        else:                          return f"{int(v):,}".replace(",",".")
    except: return str(v)


def buat_chart_dsl(ticker, tf_key=None):
    """DSL chart — ambil data sesuai tf_key jika diberikan, fallback ke daily."""
    try:
        if tf_key and tf_key in TF_MAP:
            interval, rng, tf_lbl, resample = TF_MAP[tf_key]
        else:
            interval, rng, tf_lbl, resample = "1d", "4mo", "Daily", None

        df, harga, prev = get_candles_tf(ticker, interval, rng, resample)
        if len(df) < 10:
            # kalau intraday gagal, fallback ke daily
            df, harga, prev = get_candles_tf(ticker, "1d", "4mo", None)
            tf_lbl = "Daily (fallback)"
        if len(df) < 5: return None

        df["Res_Step"] = df["High"].rolling(20).max().shift(1)
        df["Sup_Step"] = df["Low"].rolling(20).min().shift(1)
        delta = df["Close"].diff()
        df["RSI"] = hitung_rsi_wilder(df["Close"])
        min_rsi = df["RSI"].rolling(14).min()
        max_rsi = df["RSI"].rolling(14).max()
        df["StochRSI_K"] = (df["RSI"] - min_rsi) / (max_rsi - min_rsi).replace(0, float("nan")) * 100
        df["StochRSI_D"] = df["StochRSI_K"].rolling(3).mean()
        ema12 = df["Close"].ewm(span=12, adjust=False).mean()
        ema26 = df["Close"].ewm(span=26, adjust=False).mean()
        df["Value_Detector"] = (ema12 - ema26) - (ema12 - ema26).ewm(span=9, adjust=False).mean()
        n = len(df)
        def sp(s, **kw):
            if s.notna().sum() < 2: return None
            return mpf.make_addplot(s, **kw)
        ap = []
        p = sp(df["Res_Step"], panel=0, color="#1565C0", width=1.4, linestyle="--")
        if p: ap.append(p)
        p = sp(df["Sup_Step"], panel=0, color="#C62828", width=1.4, linestyle="--")
        if p: ap.append(p)
        if df["Value_Detector"].notna().sum() >= 2:
            vc = ["#00AA44" if v >= 0 else "#FF2222" for v in df["Value_Detector"].fillna(0)]
            ap.append(mpf.make_addplot(df["Value_Detector"], panel=2, type="bar", color=vc, ylabel="Val Det"))
        p = sp(df["StochRSI_K"], panel=3, color="#00AA44", width=1.2, ylabel="StochRSI")
        if p: ap.append(p)
        p = sp(df["StochRSI_D"], panel=3, color="#FF2222", width=1.2)
        if p: ap.append(p)
        ap.append(mpf.make_addplot([80]*n, panel=3, color="red",   linestyle="--", width=0.6))
        ap.append(mpf.make_addplot([20]*n, panel=3, color="green", linestyle="--", width=0.6))
        mc = mpf.make_marketcolors(
            up="#00AA44", down="#FF2222",
            edge="inherit", wick="inherit",
            volume={"up":"#00AA44","down":"#FF2222"})
        s  = mpf.make_mpf_style(marketcolors=mc, gridstyle=":", gridcolor="#2A2D3A",
                                 facecolor="#0D1117", figcolor="#0D1117", y_on_right=True)
        kode = ticker.replace(".JK","")
        buf  = io.BytesIO()
        mpf.plot(df, type="candle", style=s, addplot=ap, volume=True,
                 panel_ratios=(4,1,1,1.2), figsize=(12,9),
                 title=f"\n{kode}  |  {tf_lbl}  |  S/R Step · Value Detector · StochRSI(14,3)",
 savefig=dict(fname=buf, dpi=100, bbox_inches="tight"))
        buf.seek(0); return buf
    except Exception as e:
        print(f"   buat_chart_dsl error: {e}"); return None


def buat_chart_pivot(ticker, levels):
    """Chart candle 1 bulan dengan garis Pivot R3–S3."""
    import matplotlib; matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    _apply_dark_rc()   # [FIX v4-15]
    try:
        url = f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}?range=1mo&interval=1d"
        r   = _http.get(url, headers={"User-Agent":"Mozilla/5.0"}, timeout=10)
        res = r.json()["chart"]["result"][0]
        q   = res["indicators"]["quote"][0]; ts = res["timestamp"]
        rows = [(pd.Timestamp(t, unit="s"), o, h, l, c)
                for t,o,h,l,c in zip(ts, q["open"], q["high"], q["low"], q["close"])
                if None not in (o,h,l,c)]
        if len(rows) < 5: return None
        dates  = [r[0] for r in rows]; opens  = [r[1] for r in rows]
        highs  = [r[2] for r in rows]; lows   = [r[3] for r in rows]
        closes = [r[4] for r in rows]; n = len(rows)
        fig, ax = plt.subplots(figsize=(12,6), facecolor="#0D1117")
        ax.set_facecolor("#0D1117")
        for i,(o,h,l,c) in enumerate(zip(opens,highs,lows,closes)):
            clr = "#00AA44" if c >= o else "#FF2222"
            ax.plot([i,i],[l,h], color=clr, linewidth=0.8)
            ax.add_patch(plt.Rectangle((i-0.35,min(o,c)),0.7,abs(c-o),color=clr,zorder=3))
        def fh(v): return f"{int(v):,}".replace(",",".")
        for key,clr,ls,lw in [("R3","#C62828","--",0.8),("R2","#E53935","--",1.0),
                               ("R1","#FF7043","-",1.4), ("PP","#64B5F6","-",1.8),
                               ("S1","#2E7D32","-",1.4), ("S2","#66BB6A","--",1.0),
                               ("S3","#A5D6A7","--",0.8)]:
            val = levels.get(key)
            if val:
                ax.axhline(y=val,color=clr,linestyle=ls,linewidth=lw,alpha=0.9)
                ax.text(n+0.1,val,f" {key} {fh(val)}",va="center",ha="left",
                        fontsize=7.5,color=clr,fontweight="bold")
        harga = levels.get("harga")
        if harga:
            ax.axhline(y=harga,color="#CE93D8",linestyle=":",linewidth=1.5,alpha=0.9)
            ax.text(n+0.1,harga,f" Now {fh(harga)}",va="center",ha="left",
                    fontsize=7.5,color="#CE93D8",fontweight="bold")
        step = max(1,n//7)
        ax.set_xticks(range(0,n,step))
        ax.set_xticklabels([dates[i].strftime("%d/%m") for i in range(0,n,step)],fontsize=7.5,color="#9E9E9E")
        ax.tick_params(axis="y",labelsize=7.5,colors="#9E9E9E")
        ax.set_xlim(-0.5,n+5); ax.grid(axis="y",color="#2A2D3A",linewidth=0.5,zorder=0)
        ax.spines[["top","right","left","bottom"]].set_visible(False)
        kode = ticker.replace(".JK","")
        ax.set_title(f"Pivot Point — {kode}  |  1 Bulan",fontsize=11,fontweight="bold",color="#D1D4DC",pad=8)
        buf = io.BytesIO(); plt.tight_layout()
        plt.savefig(buf,format="png",dpi=130,bbox_inches="tight",facecolor="#0D1117"); plt.close()
        buf.seek(0); return buf
    except Exception as e:
        print(f"   chart_pivot error: {e}"); return None


def buat_chart_entry(ticker, df, sr_levels, harga, tf_label, engulfing_info=None):
    """Dark-theme entry chart: candle + EMA20/50 + S/R + volume panel."""
    import matplotlib; matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    import pandas as pd
    _apply_dark_rc()   # [FIX v4-15]
    try:
        df_plot = df.tail(60).copy(); n = len(df_plot)
        if n < 5: return None
        opens  = df_plot["Open"].values;  highs  = df_plot["High"].values
        lows   = df_plot["Low"].values;   closes = df_plot["Close"].values
        dates  = df_plot.index.tolist()
        fig, (ax, ax_vol) = plt.subplots(2, 1, figsize=(13,7),
            gridspec_kw={"height_ratios":[4,1]}, facecolor="#0D1117")
        ax.set_facecolor("#0D1117"); ax_vol.set_facecolor("#0D1117")
        for i,(o,h,l,c) in enumerate(zip(opens,highs,lows,closes)):
            clr = "#00AA44" if c >= o else "#FF2222"
            ax.plot([i,i],[l,h],color=clr,linewidth=0.7)
            ax.add_patch(plt.Rectangle((i-0.38,min(o,c)),0.76,abs(c-o)+1e-9,color=clr,zorder=3))
        for i,(o,c,v) in enumerate(zip(opens,closes,df_plot["Volume"].values)):
            ax_vol.bar(i,v,color="#00AA44" if c>=o else "#FF2222",alpha=0.6,width=0.7)
        # EMA lines
        try:
            close_s = pd.Series(closes)
            ema20_v = close_s.ewm(span=20,adjust=False).mean().values
            ema50_v = close_s.ewm(span=50,adjust=False).mean().values
            ax.plot(range(n),ema20_v,color="#FFD700", linewidth=1.0,alpha=0.85,label="EMA20",zorder=2)
            ax.plot(range(n),ema50_v,color="#FF69B4",linewidth=1.0,alpha=0.85,label="EMA50",zorder=2)
            ax.legend(fontsize=6.5,loc="upper left",facecolor="#161B22",labelcolor="#AAA",framealpha=0.6,ncol=2)
        except: pass
        # S/R lines
        def fh(v): return f"{int(v):,}".replace(",",".")
        sr_below = sorted([x for x in sr_levels if x[1]<=harga],key=lambda x:x[1],reverse=True)[:3]
        sr_above = sorted([x for x in sr_levels if x[1]>harga], key=lambda x:x[1])[:3]
        for _,val,strength in sr_below:
            ax.axhline(y=val,color="#1B5E20",linestyle="--",linewidth=1.0+min(strength,3)*0.3,alpha=0.8)
            ax.text(n-0.3,val,f"  S {fh(val)}",va="bottom",ha="left",fontsize=7,color="#4CAF50",fontweight="bold")
        for _,val,strength in sr_above:
            ax.axhline(y=val,color="#B71C1C",linestyle="--",linewidth=1.0+min(strength,3)*0.3,alpha=0.8)
            ax.text(n-0.3,val,f"  R {fh(val)}",va="bottom",ha="left",fontsize=7,color="#EF5350",fontweight="bold")
        ax.axhline(y=harga,color="#BB86FC",linestyle=":",linewidth=1.4,alpha=0.9)
        ax.text(n-0.3,harga,f"  {fh(harga)}",va="bottom",ha="left",fontsize=7,color="#BB86FC",fontweight="bold")
        if engulfing_info:
            ax.annotate("🐂 ENTRY",xy=(n-1,highs[-1]),xytext=(n-1,highs[-1]*1.005),
                fontsize=8,color="#FF6F00",fontweight="bold",ha="center",
                arrowprops=dict(arrowstyle="->",color="#FF6F00",lw=1.2))
            for offset in [0,1]:
                idx = n-2+offset
                ax.add_patch(plt.Rectangle((idx-0.42,lows[idx]),0.84,highs[idx]-lows[idx],
                    fill=False,edgecolor="#FF6F00",linewidth=1.5,zorder=5))
        fmt_x = "%d/%m %H:%M" if tf_label.lower() not in ("1 hari","1 minggu","daily","weekly") else "%d/%m"
        step = max(1,n//8)
        ax.set_xticks(range(0,n,step))
        ax.set_xticklabels([dates[i].strftime(fmt_x) for i in range(0,n,step)],
                           fontsize=6.5,color="#8B949E",rotation=15)
        ax_vol.set_xticks([]); ax_vol.set_yticks([])
        ax.set_xlim(-0.5,n+4.5)
        for sp in ax.spines.values(): sp.set_visible(False)
        for sp in ax_vol.spines.values(): sp.set_visible(False)
        ax.tick_params(axis="y",colors="#8B949E",labelsize=7)
        sinyal_str = "🐂 ENGULFING!" if engulfing_info else "📊 S/R + Trend"
        kode = ticker.replace(".JK","")
        ax.set_title(f"{kode}  |  TF {tf_label}  |  {sinyal_str}",
                     fontsize=10.5,fontweight="bold",color="#E6EDF3",pad=8)
        buf = io.BytesIO(); plt.subplots_adjust(hspace=0.05)
        plt.tight_layout()
        plt.savefig(buf,format="png",dpi=130,bbox_inches="tight",facecolor="#0D1117")
        plt.close(); buf.seek(0); return buf
    except Exception as e:
        print(f"   chart_entry error: {e}"); return None




