# --- FUNGSI UNTUK WATCHLIST & TARGET (YANG BELUM ADA) ---
# ============================================================

def proses_watchlist(user_id, args, dest):
    data = _load_json(WATCHLIST_FILE)
    uid  = str(user_id)
    if uid not in data:
        data[uid] = []

    if not args or args[0] == "list":
        wl = data[uid]
        if not wl:
            dest_kirim_teks(dest, "📋 Watchlist kamu kosong.\n/wl add BBCA untuk tambah saham.")
        else:
            pesan = f"📋 *Watchlist kamu ({len(wl)} saham)*\n"
            pesan += " • ".join(wl)
            dest_kirim_teks(dest, pesan)

    elif args[0] == "add" and len(args) > 1:
        kode = args[1].upper()
        if kode not in data[uid]:
            data[uid].append(kode)
            _save_json(WATCHLIST_FILE, data)
            dest_kirim_teks(dest, f"✅ *{kode}* ditambahkan ke watchlist!")
        else:
            dest_kirim_teks(dest, f"⚠️ *{kode}* sudah ada di watchlist.")

    elif args[0] in ["del","remove","hapus"] and len(args) > 1:
        kode = args[1].upper()
        if kode in data[uid]:
            data[uid].remove(kode)
            _save_json(WATCHLIST_FILE, data)
            dest_kirim_teks(dest, f"🗑️ *{kode}* dihapus dari watchlist.")
        else:
            dest_kirim_teks(dest, f"⚠️ *{kode}* tidak ada di watchlist.")

    elif args[0] == "scan":
        wl = data[uid]
        if not wl:
            dest_kirim_teks(dest, "📋 Watchlist kosong. Tambah dulu dengan /wl add BBCA")
        else:
            dest_kirim_teks(dest, f"🔍 Scan watchlist *{len(wl)} saham*...\n" + " • ".join(wl))
            def _scan_wl():
                sinyal_ke = 0
                for kode in wl:
                    ticker = kode + ".JK"
                    lap, lap_info = cek_semua_sinyal(ticker)
                    if lap:
                        sinyal_ke += 1
                        dest_kirim_teks(dest, lap)
                        time.sleep(1)
                        dest_kirim_foto(dest, ticker, lap_info)
                        time.sleep(1)
                    else:
                        dest_kirim_teks(dest, f"📋 *{kode}* — Tidak ada sinyal saat ini")
                    time.sleep(0.5)
                dest_kirim_teks(dest, f"✅ Scan watchlist selesai — {sinyal_ke} sinyal ditemukan.")
            threading.Thread(target=_scan_wl, daemon=True).start()
    else:
        dest_kirim_teks(dest, "⚠️ Format salah.\n`/wl` • `/wl add BBCA` • `/wl del BBCA` • `/wl scan`")

def proses_target(user_id, args, dest):
    data = _load_json(TARGETS_FILE)
    uid  = str(user_id)
    if uid not in data:
        data[uid] = {}

    if not args:
        dest_kirim_teks(dest, "⚠️ Format: `/target BBCA 9500`")
        return

    if args[0] == "list":
        tgt = data[uid]
        if not tgt:
            dest_kirim_teks(dest, "🎯 Belum ada target. Tambah: /target BBCA 9500")
        else:
            pesan = "🎯 *Target Harga Kamu*\n━━━━━━━━━━━━━━━━\n"
            for kode, info in tgt.items():
                pesan += f"📌 *{kode}* → Rp {int(info['target']):,}  ({info['arah']})\n"
            dest_kirim_teks(dest, pesan)
        return

    if args[0] in ["del","hapus"] and len(args) > 1:
        kode = args[1].upper()
        if kode in data[uid]:
            del data[uid][kode]
            _save_json(TARGETS_FILE, data)
            dest_kirim_teks(dest, f"🗑️ Target *{kode}* dihapus.")
        else:
            dest_kirim_teks(dest, f"⚠️ Tidak ada target untuk *{kode}*.")
        return

    if len(args) >= 2:
        kode = args[0].upper()
        try:
            target_harga = float(args[1].replace(",","."))
        except:
            dest_kirim_teks(dest, "⚠️ Harga target tidak valid. Contoh: /target BBCA 9500")
            return
        # Ambil harga sekarang untuk tahu arah
        try:
            r = _http.get(
                f"https://query1.finance.yahoo.com/v8/finance/chart/{kode}.JK?range=1d&interval=1d",
                headers={"User-Agent":"Mozilla/5.0"}, timeout=10)
            harga_skrg = r.json()["chart"]["result"][0]["meta"].get("regularMarketPrice", 0)
        except:
            harga_skrg = 0

        arah = "🎯 Target Naik" if target_harga > harga_skrg else "⚠️ Target Turun/SL"
        data[uid][kode] = {
            "target"    : target_harga,
            "arah"      : arah,
            "user_id"   : user_id,
            "notified"  : False,
        }
        _save_json(TARGETS_FILE, data)
        harga_str = f"{int(harga_skrg):,}".replace(",",".") if harga_skrg else "?"
        dest_kirim_teks(dest,
            f"🎯 *Target set!*\n"
            f"📌 {kode}  •  Harga skrg: Rp {harga_str}\n"
            f"🏁 Target: Rp {int(target_harga):,}  {arah}\n"
            f"Bot akan notif otomatis saat harga kena target!")
    else:
        dest_kirim_teks(dest, "⚠️ Format: `/target BBCA 9500`")


