# ================================================================
# SCREENER & ALGO — REWRITE (100% Akurat Filter)

import re as _re_scr, math as _math_scr
import threading as _threading_scr

def _scr_parse(raw_query: str) -> dict:
    """
    Parse filter /scr & /algo — versi rewrite akurat.
    FIX: volume tidak lagi elif-chain, breakout tidak lagi 'or True',
    pola candle (engulfing/hammer/doji/morningstar/shootingstar) benar-benar dievaluasi.
    Support: sort=, row=, title, semua indikator addon.
    """
    title = ""
    m = _re_scr.search(r'\btitle\s+(.+)$', raw_query, _re_scr.IGNORECASE)
    if m:
        title     = m.group(1).strip()
        raw_query = raw_query[:m.start()].strip()

    sort_by = "score"; limit = 15
    ms = _re_scr.search(r'\bsort=(\w+)', raw_query, _re_scr.IGNORECASE)
    if ms:
        sort_by   = ms.group(1).lower()
        raw_query = raw_query[:ms.start()] + raw_query[ms.end():]
    mr = _re_scr.search(r'\brow=(\d+)', raw_query, _re_scr.IGNORECASE)
    if mr:
        limit     = max(1, min(int(mr.group(1)), 30))
        raw_query = raw_query[:mr.start()] + raw_query[mr.end():]

    q = raw_query.replace("+", " ").lower().strip()
    q = _re_scr.sub(r'\s*([<>]=?|==?)\s*', r'\1', q)
    f = {"_title": title, "_sort": sort_by, "_limit": limit}

    for m2 in _re_scr.finditer(r'\bharga([<>]=?)([0-9.]+)', q):
        op, val = m2.group(1), float(m2.group(2))
        f['price_max' if '<' in op else 'price_min'] = val

    for m2 in _re_scr.finditer(r'\brsi([<>]=?)([0-9.]+)', q):
        op, val = m2.group(1), float(m2.group(2))
        f['rsi_max' if '<' in op else 'rsi_min'] = val
    if 'rsi_oversold'   in q: f.setdefault('rsi_max', 40)
    if 'rsi_reversal'   in q: f.setdefault('rsi_max', 45); f.setdefault('rsi_min', 25)
    if 'rsi_bullish'    in q: f.setdefault('rsi_min', 50); f.setdefault('rsi_max', 65)
    if 'rsi_overbought' in q: f.setdefault('rsi_min', 70)

    for m2 in _re_scr.finditer(r'\bgain([<>]=?)(-?[0-9.]+)', q):
        op, val = m2.group(1), float(m2.group(2))
        f['gain_max' if '<' in op else 'gain_min'] = val

    # GAP UP (open hari ini > high kemarin)
    mg = _re_scr.search(r'\bgapup>([0-9.]+)', q)
    if mg:
        f['gapup_min_pct'] = float(mg.group(1))
    elif _re_scr.search(r'\bgapup\b', q):
        f['gapup'] = True

    # SURGE intraday (close hari ini vs open hari ini = lonjakan 1 sesi)
    # Berbeda dengan gain (close vs close kemarin) — surge murni intraday
    ms2 = _re_scr.search(r'\bsurge>([0-9.]+)', q)
    if ms2:
        f['surge_min_pct'] = float(ms2.group(1))
    elif _re_scr.search(r'\bsurge\b', q):
        f['surge_min_pct'] = 3.0  # default 3% intraday surge

    # VOLUME -- FIX: independen (bukan elif chain)
    mv = _re_scr.search(r'\bvol>prevvol\*([0-9.]+)', q)
    if mv:
        f['vol_gt_prev_mult'] = float(mv.group(1))
    elif _re_scr.search(r'\bvol>prevvol\b', q):
        f['vol_gt_prev'] = True

    mv2 = _re_scr.search(r'\bvol>ma20vol\*([0-9.]+)', q)
    if mv2:
        f['vol_gt_ma20_mult'] = float(mv2.group(1))
    elif _re_scr.search(r'\bvol>(?:ma20vol|ma20)\b', q):
        f['vol_gt_ma20'] = True

    # vol>Nx = shorthand untuk vol > N kali MA20 (contoh: vol>2x = vol>ma20vol*2)
    mv3 = _re_scr.search(r'\bvol>([0-9.]+)x\b', q)
    if mv3: f.setdefault('vol_gt_ma20_mult', float(mv3.group(1)))
    for m2 in _re_scr.finditer(r'\bvol([<>]=?)([0-9]+)\b', q):
        op, val = m2.group(1), float(m2.group(2))
        f['vol_max' if '<' in op else 'vol_min'] = val

    def _rp(s):
        # CRITICAL: check longer suffixes FIRST to avoid partial match
        # e.g. '500jt' must hit 'jt' before 't'
        s = s.lower().strip()
        if s.endswith('jut'): return float(s[:-3]) * 1e6
        if s.endswith('jt'):  return float(s[:-2]) * 1e6
        if s.endswith('mil'): return float(s[:-3]) * 1e9
        if s.endswith('t'):   return float(s[:-1]) * 1e12
        if s.endswith('m'):   return float(s[:-1]) * 1e9
        try: return float(s)
        except: return 0.0

    for m2 in _re_scr.finditer(r'\b(?:mf|cleanmoney)([<>]=?)([0-9.]+(?:mil|jut|jt|t|m)?)\b', q):
        val_str = m2.group(2); op = m2.group(1)
        parsed  = _rp(val_str)
        # mf>0 / mf<0 (threshold = 0) → net direction filter (tidak minus / negatif)
        # mf>500jt (threshold > 0) → raw volume / liquidity filter seperti semula
        if parsed == 0:
            if '>' in op: f.setdefault('netmf_min',  0.001)
            else:         f.setdefault('netmf_max', -0.001)
        else:
            f['mf_min' if '>' in op else 'mf_max'] = parsed

    if _re_scr.search(r'\bstoch=gc\b', q):               f['stoch_gc']    = True
    if _re_scr.search(r'\bstoch=dc\b', q):               f['stoch_dc']    = True
    if _re_scr.search(r'\bmacd=gc\b|macd_cross', q):     f['macd_gc']     = True
    if _re_scr.search(r'\bmacd=dc\b', q):                f['macd_dc']     = True
    if _re_scr.search(r'\bcrossup\b', q):                f['crossup']     = True
    if _re_scr.search(r'\bcrossdown\b', q):              f['crossdown']   = True
    if _re_scr.search(r'\bbreakout\b', q):               f['breakout']    = True
    if _re_scr.search(r'\buptrend\b', q):                f['uptrend']     = True
    if _re_scr.search(r'\bdowntrend\b', q):              f['downtrend']   = True
    if _re_scr.search(r'\bribbon(?:_?green)?\b', q):    f['ribbon_green']= True
    if _re_scr.search(r'\bribbon_red\b', q):            f['ribbon_red']  = True
    if _re_scr.search(r'\bbb_lower\b', q):               f['bb_lower']    = True
    if _re_scr.search(r'\bbb_upper\b', q):               f['bb_upper']    = True
    if _re_scr.search(r'\bclose>open\b', q):             f['close_gt_open'] = True
    if _re_scr.search(r'\bopen>close\b', q):             f['open_gt_close'] = True
    if _re_scr.search(r'\bclose=high\b|close==high', q): f['close_eq_high'] = True
    if _re_scr.search(r'\bclose=low\b|close==low', q):   f['close_eq_low']  = True
    if _re_scr.search(r'\bengulfing\b', q):              f['pat_engulfing']   = True
    if _re_scr.search(r'\bhammer\b', q):                 f['pat_hammer']      = True
    if _re_scr.search(r'\bdoji\b', q):                   f['pat_doji']        = True
    if _re_scr.search(r'\bmorningstar\b', q):            f['pat_morningstar'] = True
    if _re_scr.search(r'\bshootingstar\b', q):           f['pat_shootingstar']= True
    if _re_scr.search(r'\bprice>ma20\b|close>ma20', q):  f['price_above_ma20']  = True
    if _re_scr.search(r'\bprice<ma20\b', q):              f['price_below_ma20']  = True
    if _re_scr.search(r'\bprice>(?:ema50|ma50)\b', q):   f['price_above_ema50'] = True
    if _re_scr.search(r'\bprice<(?:ema50|ma50)\b', q):   f['price_below_ema50'] = True
    if _re_scr.search(r'\bprice>(?:ema200|ma200)\b', q): f['price_above_ema200']= True
    # ── SMA (Simple Moving Average) filters ──
    if _re_scr.search(r'\ball_above_sma\b', q):              f['all_above_sma']      = True
    if _re_scr.search(r'\bprice>sma3\b|close>sma3', q):     f['price_above_sma3']   = True
    if _re_scr.search(r'\bprice>sma5\b|close>sma5', q):     f['price_above_sma5']   = True
    if _re_scr.search(r'\bprice>sma10\b|close>sma10', q):   f['price_above_sma10']  = True
    if _re_scr.search(r'\bprice>sma20\b|close>sma20', q):   f['price_above_sma20']  = True
    if _re_scr.search(r'\bprice>sma50\b|close>sma50', q):   f['price_above_sma50']  = True
    if _re_scr.search(r'\bprice>sma100\b|close>sma100', q): f['price_above_sma100'] = True
    if _re_scr.search(r'\bprice>sma200\b|close>sma200', q): f['price_above_sma200'] = True
    if _re_scr.search(r'\bprice>vwap\b|close>vwap', q):  f['price_above_vwap']  = True
    # ── EMA vs EMA & Price vs EMA filters (sebelumnya TIDAK ADA → silent bug) ──
    if _re_scr.search(r'\bema9\s*>\s*ema2[01]\b', q):    f['ema9_gt_ema21']     = True
    if _re_scr.search(r'\bema9\s*<\s*ema2[01]\b', q):    f['ema9_lt_ema21']     = True
    if _re_scr.search(r'\bema9\s*>\s*ema50\b', q):       f['ema9_gt_ema50']     = True
    if _re_scr.search(r'\bema21\s*>\s*ema50\b', q):      f['ema21_gt_ema50']    = True
    if _re_scr.search(r'\bema21\s*<\s*ema50\b', q):      f['ema21_lt_ema50']    = True
    if _re_scr.search(r'\bema50\s*>\s*ema200\b', q):     f['ema50_gt_ema200']   = True
    if _re_scr.search(r'\bema50\s*<\s*ema200\b', q):     f['ema50_lt_ema200']   = True
    if _re_scr.search(r'\b(?:price|close)\s*>\s*ema9\b', q):   f['price_above_ema9']  = True
    if _re_scr.search(r'\b(?:price|close)\s*<\s*ema9\b', q):   f['price_below_ema9']  = True
    if _re_scr.search(r'\b(?:price|close)\s*>\s*ema2[01]\b', q): f['price_above_ema21'] = True
    if _re_scr.search(r'\b(?:price|close)\s*<\s*ema2[01]\b', q): f['price_below_ema21'] = True

    for m2 in _re_scr.finditer(r'\bnbsa([<>]=?)(-?[0-9.]+)', q):
        op, val = m2.group(1), float(m2.group(2))
        f['nbsa_max' if '<' in op else 'nbsa_min'] = val
    if _re_scr.search(r'\bnbsa>0\b', q): f['nbsa_min'] = 0.001
    if _re_scr.search(r'\bnbsa<0\b', q): f['nbsa_max'] = -0.001

    for m2 in _re_scr.finditer(r'\bhaka([<>]=?)([0-9.]+)', q):
        op, val = m2.group(1), float(m2.group(2))
        f['haka_max' if '<' in op else 'haka_min'] = val

    # ════════════════════════════════════════════════════════════
    # PARSING INDIKATOR TAMBAHAN
    # ════════════════════════════════════════════════════════════

    # CCI (Commodity Channel Index)
    for m2 in _re_scr.finditer(r'\bcci([<>]=?)(-?[0-9.]+)', q):
        f['cci_max' if '<' in m2.group(1) else 'cci_min'] = float(m2.group(2))
    if _re_scr.search(r'\bcci_bull\b|\bcci>0\b', q):   f['cci_bull'] = True
    if _re_scr.search(r'\bcci_bear\b|\bcci<0\b', q):   f['cci_bear'] = True
    if _re_scr.search(r'\bcci_os\b|cci.*oversold', q): f['cci_os']   = True   # CCI < -100
    if _re_scr.search(r'\bcci_ob\b|cci.*overbought', q):f['cci_ob']  = True   # CCI > 100

    # Williams %R
    for m2 in _re_scr.finditer(r'\bwillr([<>]=?)(-?[0-9.]+)', q):
        f['willr_max' if '<' in m2.group(1) else 'willr_min'] = float(m2.group(2))
    if _re_scr.search(r'\bwillr_os\b|williams.*oversold|wr.*os', q): f['willr_os'] = True
    if _re_scr.search(r'\bwillr_ob\b|williams.*overbought|wr.*ob', q):f['willr_ob'] = True

    # MFI (Money Flow Index)
    for m2 in _re_scr.finditer(r'\bmfi([<>]=?)([0-9.]+)', q):
        f['mfi_max' if '<' in m2.group(1) else 'mfi_min'] = float(m2.group(2))
    if _re_scr.search(r'\bmfi_bull\b|\bmfi>50\b', q): f['mfi_bull'] = True
    if _re_scr.search(r'\bmfi_os\b', q):              f['mfi_os']   = True   # MFI < 20
    if _re_scr.search(r'\bmfi_ob\b', q):              f['mfi_ob']   = True   # MFI > 80

    # CMF (Chaikin Money Flow)
    for m2 in _re_scr.finditer(r'\bcmf([<>]=?)(-?[0-9.]+)', q):
        f['cmf_max' if '<' in m2.group(1) else 'cmf_min'] = float(m2.group(2))
    if _re_scr.search(r'\bcmf_bull\b|\bcmf>0\b', q): f['cmf_bull'] = True
    if _re_scr.search(r'\bcmf_bear\b|\bcmf<0\b', q): f['cmf_bear'] = True

    # OBV
    if _re_scr.search(r'\bobv_rising\b|\bobv.*naik\b', q):   f['obv_rising']  = True
    if _re_scr.search(r'\bobv_falling\b|\bobv.*turun\b', q): f['obv_falling'] = True

    # ADX
    for m2 in _re_scr.finditer(r'\badx([<>]=?)([0-9.]+)', q):
        f['adx_max' if '<' in m2.group(1) else 'adx_min'] = float(m2.group(2))
    if _re_scr.search(r'\badx_trending\b|\badx>25\b', q): f['adx_trending'] = True
    if _re_scr.search(r'\badx_weak\b|\badx_choppy\b', q): f['adx_weak']     = True

    # Supertrend
    if _re_scr.search(r'\bsupertrend_bull\b|\bsupertrend\b(?!.*bear)', q): f['supertrend_bull'] = True
    if _re_scr.search(r'\bsupertrend_bear\b', q):                           f['supertrend_bear'] = True

    # Parabolic SAR
    if _re_scr.search(r'\bpsar_bull\b|\bpsar\b(?!.*bear)', q): f['psar_bull'] = True
    if _re_scr.search(r'\bpsar_bear\b', q):                     f['psar_bear'] = True

    # Aroon
    if _re_scr.search(r'\baroon_bull\b|\baroon\b(?!.*bear)', q): f['aroon_bull'] = True
    if _re_scr.search(r'\baroon_bear\b', q):                      f['aroon_bear'] = True
    for m2 in _re_scr.finditer(r'\baroon_up>([0-9.]+)', q):
        f['aroon_up_min'] = float(m2.group(1))

    # ROC (Rate of Change)
    for m2 in _re_scr.finditer(r'\broc([<>]=?)(-?[0-9.]+)', q):
        f['roc_max' if '<' in m2.group(1) else 'roc_min'] = float(m2.group(2))
    if _re_scr.search(r'\broc_bull\b|\broc>0\b', q): f['roc_bull'] = True
    if _re_scr.search(r'\broc_bear\b|\broc<0\b', q): f['roc_bear'] = True

    # ATR %
    for m2 in _re_scr.finditer(r'\batr_pct([<>]=?)([0-9.]+)', q):
        f['atr_pct_max' if '<' in m2.group(1) else 'atr_pct_min'] = float(m2.group(2))
    if _re_scr.search(r'\batr_high\b|\bhigh_vol\b', q): f['atr_high'] = True
    if _re_scr.search(r'\batr_low\b|\blow_vol\b', q):   f['atr_low']  = True

    # Ichimoku
    if _re_scr.search(r'\bkumo_bull\b|\bichimoku_bull\b|\babove_cloud\b', q): f['kumo_bull'] = True
    if _re_scr.search(r'\bkumo_bear\b|\bichimoku_bear\b|\bbelow_cloud\b', q): f['kumo_bear'] = True
    if _re_scr.search(r'\btk_gc\b|\btenkan.*kijun.*gc\b', q): f['tk_gc'] = True
    if _re_scr.search(r'\btk_dc\b', q):                        f['tk_dc'] = True

    # Choppiness Index
    for m2 in _re_scr.finditer(r'\bchop([<>]=?)([0-9.]+)', q):
        f['chop_max' if '<' in m2.group(1) else 'chop_min'] = float(m2.group(2))
    if _re_scr.search(r'\bchop_trend\b|\btrending_market\b', q): f['chop_trend']  = True  # CHOP < 55
    if _re_scr.search(r'\bchop_choppy\b|\bchoppy_market\b', q):  f['chop_choppy'] = True  # CHOP > 61

    # HMA (Hull Moving Average)
    if _re_scr.search(r'\bprice>hma\b|\bclose>hma\b', q):  f['price_above_hma'] = True
    if _re_scr.search(r'\bhma_rising\b|\bhma.*naik\b', q): f['hma_rising']       = True
    if _re_scr.search(r'\bhma_falling\b', q):               f['hma_falling']      = True

    # 52 Week & Donchian
    if _re_scr.search(r'\bnear_52w_high\b|\b52h\b', q):   f['near_52w_high']  = True
    if _re_scr.search(r'\bnear_52w_low\b|\b52l\b', q):    f['near_52w_low']   = True
    if _re_scr.search(r'\b52w_breakout\b|\bbo52\b', q):   f['52w_breakout']   = True
    if _re_scr.search(r'\bdonchian_break\b', q):           f['donchian_break'] = True

    # Keltner Channel
    if _re_scr.search(r'\bkc_bull\b|\bkc_break\b', q): f['kc_bull']  = True
    if _re_scr.search(r'\bkc_bear\b', q):               f['kc_bear']  = True

    # Awesome Oscillator
    if _re_scr.search(r'\bao_bull\b|\bao>0\b', q): f['ao_bull'] = True
    if _re_scr.search(r'\bao_bear\b|\bao<0\b', q): f['ao_bear'] = True
    if _re_scr.search(r'\bao_gc\b', q):            f['ao_gc']   = True  # AO zero-cross naik
    if _re_scr.search(r'\bao_dc\b', q):            f['ao_dc']   = True

    # BBW (Bollinger Band Width)
    for m2 in _re_scr.finditer(r'\bbbw<([0-9.]+)', q):  f['bbw_max']     = float(m2.group(1))
    if _re_scr.search(r'\bbbw_squeeze\b', q): f['bbw_squeeze'] = True
    if _re_scr.search(r'\bbbw_expand\b', q):  f['bbw_expand']  = True

    # ── HL Pre-Fly (Higher Lows base sebelum terbang) ─────────
    if _re_scr.search(r'\bhl_prefly\b|\bhl_base\b|\bprefly\b', q): f['hl_prefly'] = True

    if _re_scr.search(r'\bsaham=lq45\b|\blq45\b', q):     f['universe'] = 'lq45'
    elif _re_scr.search(r'\bsaham=all\b', q):                f['universe'] = 'all'
    elif _re_scr.search(r'\bsaham=likuid\b|\blikuid\b', q):  f['universe'] = 'likuid'
    elif _re_scr.search(r'\bissi\b|\bsaham=issi\b', q):      f['universe'] = 'issi'

    # ════════════════════════════════════════════════════════════
    # DSI-STYLE FILTERS (v15.5)
    # ════════════════════════════════════════════════════════════

    # GAP DOWN — open < prev_close × (1−N%)
    _mg_dn = _re_scr.search(r'\bgapdown>([0-9.]+)', q)
    if _mg_dn:
        f['gapdown_min_pct'] = float(_mg_dn.group(1))
    elif _re_scr.search(r'\bgapdown\b', q):
        f.setdefault('gapdown_min_pct', 1.0)

    # ARB CANDIDATE — close turun >= 7% dari prev_close
    if _re_scr.search(r'\barb\b', q):
        f['arb'] = True

    # MACD REVERSAL BELOW ZERO — histogram <0 tapi 3-bar naik berturut
    if _re_scr.search(r'\bmacd_rev\b|\bmacd_reversal\b', q):
        f['macd_rev_below0'] = True

    # STOCHASTIC OVERSOLD CROSS — K < level dan cross D dari bawah
    _m_sos = _re_scr.search(r'\bstoch_os(?:>([0-9.]+))?\b', q)
    if _m_sos:
        f['stoch_os_cross'] = True
        if _m_sos.group(1):
            f['stoch_os_level'] = float(_m_sos.group(1))

    # WEEKLY SMA(26) — close > SMA 26 minggu
    if _re_scr.search(r'\bweekly_ma26\b|\bwma26\b|\bweekly_sma26\b', q):
        f['weekly_above_ma26'] = True

    # N-DAY BREAKOUT — close > high tertinggi N hari
    _m_bo_n = _re_scr.search(r'\bbreakout>(\d+)\b', q)
    if _m_bo_n:
        f['breakout_nd'] = int(_m_bo_n.group(1))

    # ── Timeframe scalping: tf:1m / tf:5m / tf:15m / tf:30m ──────────────
    _m_tf = _re_scr.search(r'\btf[=:]([\d]+m?|[\d]+[mjh])\b', q)
    if _m_tf:
        f['_tf'] = _m_tf.group(1).lower()

    # ── Net MF filters (RTI+Yahoo realtime) ──────────────────────────
    def _rp_mf(s):
        s = s.lower().strip()
        if s.endswith('jut'): return float(s[:-3]) * 1e6
        if s.endswith('jt'):  return float(s[:-2]) * 1e6
        if s.endswith('mil'): return float(s[:-3]) * 1e9
        if s.endswith('m'):   return float(s[:-1]) * 1e9
        try: return float(s)
        except: return 0.0
    for _m2 in _re_scr.finditer(r'\bnetmf([<>]=?)(-?[0-9.]+(?:mil|jut|jt|m)?)', q):
        f['netmf_min' if '>' in _m2.group(1) else 'netmf_max'] = _rp_mf(_m2.group(2))
    if _re_scr.search(r'\bnetmf>0\b', q): f.setdefault('netmf_min', 0.001)
    if _re_scr.search(r'\bnetmf<0\b', q): f.setdefault('netmf_max', -0.001)

    # ── Shorthand aliases: mf+/mf- ──────────────────────────────────
    for _m2 in _re_scr.finditer(r'\bmf\+([<>]=?)(-?[0-9.]+(?:mil|jut|jt|m)?)', q):
        f['netmf_min' if '>' in _m2.group(1) else 'netmf_max'] = _rp_mf(_m2.group(2))
    if _re_scr.search(r'\bmf\+>0\b|\bmf\+$', q):   f.setdefault('netmf_min',  0.001)
    if _re_scr.search(r'\bmf\+<0\b|\bmf-\b', q):   f.setdefault('netmf_max', -0.001)

    # ── SMC/ICT filter (opt-in — mahal, skip jika tidak diminta) ────
    if _re_scr.search(r'\bsmc\b|\bict\b|\bfvg\b|\bob_retest\b|\blsweep\b', q): f['smc'] = True

    # ── VALUE (Nilai Transaksi Rupiah) ───────────────────────────────
    # Sintaks: val>100jt  val<500jt  val>1m  val>5t  val>avgval
    def _rp_val(s):
        s = s.lower().strip()
        if s.endswith('jut'): return float(s[:-3]) * 1e6
        if s.endswith('jt'):  return float(s[:-2]) * 1e6
        if s.endswith('mil'): return float(s[:-3]) * 1e9
        if s.endswith('t'):   return float(s[:-1]) * 1e12
        if s.endswith('m'):   return float(s[:-1]) * 1e9
        try: return float(s)
        except: return 0.0

    for m2 in _re_scr.finditer(r'\bval([<>]=?)([0-9.]+(?:mil|jut|jt|t|m)?)\b', q):
        op, vs = m2.group(1), m2.group(2)
        v = _rp_val(vs)
        if v > 0:
            if '>' in op: f['val_min'] = v
            else:         f['val_max'] = v
    # val>avgval = nilai hari ini > rata-rata nilai 20 hari
    if _re_scr.search(r'\bval>avg(?:val)?\b', q): f['val_gt_avg'] = True
    # val_liquid / val_high = shorthand nilai > 1 miliar
    if _re_scr.search(r'\bval_(?:high|liquid|likuid)\b', q): f.setdefault('val_min', 1e9)

    # ── FREQUENCY (Frekuensi / Jumlah Transaksi per Hari) ────────────
    # Sintaks: freq>500  freq<2000
    for m2 in _re_scr.finditer(r'\bfreq([<>]=?)([0-9]+)\b', q):
        op, v = m2.group(1), int(m2.group(2))
        if '>' in op: f['freq_min'] = v
        else:         f['freq_max'] = v
    # shorthand
    if _re_scr.search(r'\bfreq_active\b|\bfreq_aktif\b', q): f.setdefault('freq_min', 200)
    if _re_scr.search(r'\bfreq_hot\b|\bfreq_ramai\b', q):    f.setdefault('freq_min', 1000)

    # ── OPEN vs LOW / HIGH / PREV_CLOSE ──────────────────────────────
    # open=low  → no lower wick, bullish pressure sejak tick pertama
    if _re_scr.search(r'\bopen[=]{1,2}low\b|\bopen_eq_low\b|\bopen_low\b', q):
        f['open_eq_low']  = True
    # open=high → no upper wick, bearish penuh sejak buka
    if _re_scr.search(r'\bopen[=]{1,2}high\b|\bopen_eq_high\b|\bopen_high\b', q):
        f['open_eq_high'] = True
    # open>prev_close → gap up murni (open di atas close kemarin)
    if _re_scr.search(r'\bopen>prev(?:close|_close)?\b|\bopen_gap_up\b', q):
        f['open_gt_prev_close'] = True
    # open<prev_close → gap down murni
    if _re_scr.search(r'\bopen<prev(?:close|_close)?\b|\bopen_gap_dn\b|\bopen_gap_down\b', q):
        f['open_lt_prev_close'] = True
    # near_open → harga sekarang masih dekat open hari ini (dalam 0.5%)
    if _re_scr.search(r'\bnear_open\b', q): f['near_open'] = True

    # ── RBS / SBR proximity filter ───────────────────────────────
    # near_rbs  → harga mendekati level RBS (Resistance Becomes Support)
    # near_sbr  → harga mendekati level SBR (Support Becomes Resistance)
    # near_rbs_tol=X → toleransi proximity % (default 2%)
    if _re_scr.search(r'\bnear_rbs\b|\brbs_retest\b|\brbs\b', q):
        f['near_rbs'] = True
    if _re_scr.search(r'\bnear_sbr\b|\bsbr_retest\b|\bsbr\b', q):
        f['near_sbr'] = True
    _m_rbs_tol = _re_scr.search(r'\bnear_rbs_tol[=:]([0-9.]+)\b', q)
    if _m_rbs_tol:
        f['rbs_tol'] = float(_m_rbs_tol.group(1))

    return f


def _filter_summary(f: dict) -> str:
    parts = []
    if 'price_max' in f:        parts.append(f"harga<{int(f['price_max'])}")
    if 'price_min' in f:        parts.append(f"harga>{int(f['price_min'])}")
    if 'rsi_max'   in f:        parts.append(f"RSI<{f['rsi_max']:.0f}")
    if 'rsi_min'   in f:        parts.append(f"RSI>{f['rsi_min']:.0f}")
    if 'gain_min'  in f:        parts.append(f"gain>{f['gain_min']:+.1f}%")
    if 'gain_max'  in f:        parts.append(f"gain<{f['gain_max']:+.1f}%")
    if 'vol_gt_prev_mult' in f: parts.append(f"vol>prevvol*{f['vol_gt_prev_mult']:.1f}")
    elif f.get('vol_gt_prev'):  parts.append("vol>prevvol")
    if 'vol_gt_ma20_mult' in f: parts.append(f"vol>{f['vol_gt_ma20_mult']:.1f}x")
    elif f.get('vol_gt_ma20'):  parts.append("vol>MA20")
    if 'vol_min'   in f:        parts.append(f"vol>{int(f['vol_min'])}")
    if 'mf_min'    in f:
        v = f['mf_min']
        parts.append("MF>%.0fM" % (v/1e9) if v >= 1e9 else "MF>%.0fjt" % (v/1e6))
    if f.get('gapup'):              parts.append("gapup")
    if 'gapup_min_pct' in f:        parts.append(f"gapup>{f['gapup_min_pct']:.0f}%")
    if 'surge_min_pct' in f:        parts.append(f"surge>{f['surge_min_pct']:.0f}%")
    if f.get('stoch_gc'):    parts.append("stoch=GC")
    if f.get('stoch_dc'):    parts.append("stoch=DC")
    if f.get('macd_gc'):     parts.append("macd=GC")
    if f.get('macd_dc'):     parts.append("macd=DC")
    if f.get('close_gt_open'):    parts.append("close>open")
    if f.get('close_eq_high'):    parts.append("close=high")
    if f.get('pat_engulfing'):    parts.append("engulfing")
    if f.get('pat_hammer'):       parts.append("hammer")
    if f.get('pat_doji'):         parts.append("doji")
    if f.get('pat_morningstar'):  parts.append("morningstar")
    if f.get('pat_shootingstar'): parts.append("shootingstar")
    if f.get('crossup'):          parts.append("crossup")
    if f.get('breakout'):         parts.append("breakout")
    if f.get('price_above_ma20'): parts.append("price>MA20")
    if f.get('price_above_ema50'):parts.append("price>EMA50")
    if f.get('price_above_vwap'): parts.append("price>VWAP")
    if f.get('all_above_sma'):      parts.append("AllAboveSMA")
    if f.get('price_above_sma3'):   parts.append("price>SMA3")
    if f.get('price_above_sma5'):   parts.append("price>SMA5")
    if f.get('price_above_sma10'):  parts.append("price>SMA10")
    if f.get('price_above_sma20'):  parts.append("price>SMA20")
    if f.get('price_above_sma50'):  parts.append("price>SMA50")
    if f.get('price_above_sma100'): parts.append("price>SMA100")
    if f.get('price_above_sma200'): parts.append("price>SMA200")
    if f.get('uptrend'):          parts.append("uptrend")
    if f.get('downtrend'):        parts.append("downtrend")
    if f.get('ribbon_green'):     parts.append("RibbonGreen")
    if f.get('ribbon_red'):       parts.append("RibbonRed")
    if f.get('ema9_gt_ema21'):    parts.append("EMA9>EMA21")
    if f.get('ema9_lt_ema21'):    parts.append("EMA9<EMA21")
    if f.get('ema9_gt_ema50'):    parts.append("EMA9>EMA50")
    if f.get('ema21_gt_ema50'):   parts.append("EMA21>EMA50")
    if f.get('ema21_lt_ema50'):   parts.append("EMA21<EMA50")
    if f.get('ema50_gt_ema200'):  parts.append("EMA50>EMA200")
    if f.get('ema50_lt_ema200'):  parts.append("EMA50<EMA200")
    if f.get('price_above_ema9'): parts.append("price>EMA9")
    if f.get('price_below_ema9'): parts.append("price<EMA9")
    if f.get('price_above_ema21'):parts.append("price>EMA21")
    if f.get('price_below_ema21'):parts.append("price<EMA21")
    if f.get('bb_lower'):         parts.append("BB_lower")
    if f.get('bb_upper'):         parts.append("BB_upper")
    uni = f.get('universe','')
    if uni == 'lq45':    parts.append("LQ45")
    elif uni == 'all':   parts.append("AllSaham")
    elif uni == 'likuid':parts.append("Likuid150")
    elif uni == 'issi':  parts.append("ISSI-Syariah")
    # ── DSI-style filters (v15.5) ───────────────────────────────────
    if 'gapdown_min_pct' in f:       parts.append(f"gapdown>{f['gapdown_min_pct']:.0f}%")
    if f.get('arb'):                  parts.append("ARB>=7%")
    if f.get('macd_rev_below0'):      parts.append("MACD_Rev<0")
    if f.get('stoch_os_cross'):
        lvl = f.get('stoch_os_level', 20)
        parts.append(f"StochOS<{lvl:.0f}")
    if f.get('weekly_above_ma26'):    parts.append("WeeklySMA26")
    if 'breakout_nd' in f:            parts.append(f"BO{f['breakout_nd']}D")
    # ── Indikator tambahan ──────────────────────────────────────────
    if 'cci_min'  in f: parts.append(f"CCI>{f['cci_min']:.0f}")
    if 'cci_max'  in f: parts.append(f"CCI<{f['cci_max']:.0f}")
    if f.get('cci_bull'):  parts.append("CCI>0")
    if f.get('cci_os'):    parts.append("CCI_OS")
    if f.get('cci_ob'):    parts.append("CCI_OB")
    if 'mfi_min'  in f: parts.append(f"MFI>{f['mfi_min']:.0f}")
    if 'mfi_max'  in f: parts.append(f"MFI<{f['mfi_max']:.0f}")
    if f.get('mfi_bull'):  parts.append("MFI>50")
    if f.get('mfi_os'):    parts.append("MFI_OS")
    if f.get('mfi_ob'):    parts.append("MFI_OB")
    if f.get('cmf_bull'):  parts.append("CMF>0")
    if f.get('cmf_bear'):  parts.append("CMF<0")
    if f.get('obv_rising'): parts.append("OBV↑")
    if f.get('obv_falling'):parts.append("OBV↓")
    if 'adx_min'  in f: parts.append(f"ADX>{f['adx_min']:.0f}")
    if f.get('adx_trending'): parts.append("ADX_Trend")
    if f.get('adx_weak'):     parts.append("ADX_Weak")
    if f.get('supertrend_bull'): parts.append("Supertrend↑")
    if f.get('supertrend_bear'): parts.append("Supertrend↓")
    if f.get('psar_bull'):   parts.append("PSAR↑")
    if f.get('psar_bear'):   parts.append("PSAR↓")
    if f.get('aroon_bull'):  parts.append("Aroon↑")
    if 'aroon_up_min' in f: parts.append(f"Aroon_Up>{f['aroon_up_min']:.0f}")
    if 'roc_min'  in f: parts.append(f"ROC>{f['roc_min']:.0f}")
    if f.get('roc_bull'):    parts.append("ROC>0")
    if f.get('roc_bear'):    parts.append("ROC<0")
    if 'atr_pct_min' in f:  parts.append(f"ATR%>{f['atr_pct_min']:.1f}")
    if f.get('atr_high'):    parts.append("ATR_High")
    if f.get('atr_low'):     parts.append("ATR_Low")
    if f.get('kumo_bull'):   parts.append("Kumo↑")
    if f.get('kumo_bear'):   parts.append("Kumo↓")
    if f.get('tk_gc'):       parts.append("TK_GC")
    if f.get('tk_dc'):       parts.append("TK_DC")
    if f.get('chop_trend'):  parts.append("Chop_Trend")
    if f.get('chop_choppy'): parts.append("Chop_Choppy")
    if 'chop_max' in f:      parts.append(f"Chop<{f['chop_max']:.0f}")
    if f.get('price_above_hma'): parts.append("price>HMA")
    if f.get('hma_rising'):  parts.append("HMA↑")
    if f.get('near_52w_high'):  parts.append("Near52wHigh")
    if f.get('52w_breakout'):   parts.append("52w_BO")
    if f.get('donchian_break'): parts.append("Donchian_BO")
    if f.get('kc_bull'):     parts.append("KC↑")
    if f.get('kc_bear'):     parts.append("KC↓")
    if f.get('kc_break'):    parts.append("KC_Break")
    if 'bbw_max' in f:       parts.append(f"BBW<{f['bbw_max']:.0f}")
    if f.get('bbw_squeeze'): parts.append("BBW_Squeeze")
    if f.get('bbw_expand'):  parts.append("BBW_Expand")
    if f.get('willr_os'):    parts.append("WillR_OS")
    if f.get('willr_ob'):    parts.append("WillR_OB")
    if 'willr_max' in f:     parts.append(f"WillR<{f['willr_max']:.0f}")
    if f.get('ao_bull'):     parts.append("AO>0")
    if f.get('ao_gc'):       parts.append("AO_GC")
    if f.get('ao_dc'):       parts.append("AO_DC")
    if "netmf_min" in f: parts.append(f"netMF>0" if f["netmf_min"]<1 else f"netMF>{format_nilai(f['netmf_min'])}")
    if "netmf_max" in f: parts.append(f"netMF<{format_nilai(f['netmf_max'])}")
    # ── Value, Freq, Open position ──────────────────────────────────
    if 'val_min'  in f:
        v = f['val_min']
        parts.append("val>%.0fM" % (v/1e9) if v >= 1e9 else "val>%.0fjt" % (v/1e6))
    if 'val_max'  in f:
        v = f['val_max']
        parts.append("val<%.0fM" % (v/1e9) if v >= 1e9 else "val<%.0fjt" % (v/1e6))
    if f.get('val_gt_avg'):         parts.append("val>AvgVal")
    if 'freq_min' in f:             parts.append(f"freq>{f['freq_min']}")
    if 'freq_max' in f:             parts.append(f"freq<{f['freq_max']}")
    if f.get('open_eq_low'):        parts.append("open=low")
    if f.get('open_eq_high'):       parts.append("open=high")
    if f.get('open_gt_prev_close'): parts.append("open>prevClose")
    if f.get('open_lt_prev_close'): parts.append("open<prevClose")
    if f.get('near_open'):          parts.append("near_open")
    if f.get('near_rbs'):
        _tol = f.get('rbs_tol', 2.0)
        parts.append(f"NearRBS(±{_tol:.0f}%)")
    if f.get('near_sbr'):
        _tol = f.get('rbs_tol', 2.0)
        parts.append(f"NearSBR(±{_tol:.0f}%)")
    return " + ".join(parts) if parts else "(no filter)"


def _evaluate(ticker: str, filters: dict, tf_key: str = "1d"):
    """
    Evaluasi satu ticker terhadap semua filter.
    Return dict jika lolos, None jika tidak.
    FIX: Baca dari _SNAPSHOT_DATA (1x fetch per 30-min cycle) → hemat Yahoo calls.
    Fallback ke get_candles_tf jika snapshot tidak tersedia.
    tf_key: '1d' (default/daily) atau TF intraday (1m/5m/15m/30m) untuk scalping.
    """
    try:
        kode   = ticker.replace(".JK", "")
        # ── Intraday / scalping mode ─────────────────────────────────────────
        _intraday = tf_key and tf_key != "1d" and tf_key in TF_MAP
        if _intraday:
            _iv, _rng, _, _rs = TF_MAP[tf_key]
            result = get_candles_tf(ticker, _iv, _rng, _rs)
        else:
            snap = _snapshot_get(ticker)
            result = snap if snap else get_candles_tf(ticker, "1d", "1y")
        if result is None: return None
        df, harga, prev = result
        if _intraday:
            # Intraday: harga = close bar terakhir, prev = bar sebelumnya
            if df is None or len(df) < 20: return None
            harga = float(df["Close"].iloc[-1])
            prev  = float(df["Close"].iloc[-2]) if len(df) >= 2 else harga
            if harga < 50: return None
        else:
            if df is None or len(df) < 30 or harga < 50: return None

        close = df["Close"]; high = df["High"]; low = df["Low"]
        vol   = df["Volume"]; op   = df["Open"]

        # Fallback harga & prev jika meta Yahoo 0
        if harga <= 0: harga = float(close.iloc[-1])
        if prev  <= 0 and len(df) >= 2: prev = float(close.iloc[-2])

        # ── LIVE PRICE INJECTION ──────────────────────────────────────────────
        # Override harga snapshot (1d candle, bisa stale di 09:00-09:30) dengan
        # harga live dari _prefetch_live_prices_batch() jika tersedia dan fresh.
        # Ini memastikan filter price_min/max dan gain_min/max dievaluasi
        # berdasarkan harga HARI INI, bukan close kemarin.
        if not _intraday:
            _lp_h, _lp_prev = _live_price_get(ticker)
            if _lp_h and _lp_h > 0:
                harga = _lp_h
                if _lp_prev and _lp_prev > 0:
                    prev = _lp_prev
        # ── END LIVE PRICE INJECTION ─────────────────────────────────────────

        if 'price_max' in filters and harga > filters['price_max']: return None
        if 'price_min' in filters and harga < filters['price_min']: return None

        gain = (harga - prev) / prev * 100 if prev > 0 else 0.0
        if 'gain_min' in filters and gain < filters['gain_min']: return None
        if 'gain_max' in filters and gain > filters['gain_max']: return None

        ema9   = close.ewm(span=9,   adjust=False).mean()
        ema21  = close.ewm(span=21,  adjust=False).mean()
        ema20  = close.ewm(span=20,  adjust=False).mean()
        ema50  = close.ewm(span=50,  adjust=False).mean()
        ema200 = close.ewm(span=200, adjust=False).mean()
        dema20 = 2 * ema20 - ema20.ewm(span=20, adjust=False).mean()
        e9     = float(ema9.iloc[-1]);  e21  = float(ema21.iloc[-1])
        e20    = float(ema20.iloc[-1]); e50  = float(ema50.iloc[-1])
        e200   = float(ema200.iloc[-1])
        de20   = float(dema20.iloc[-1])
        de20p  = float(dema20.iloc[-2]) if len(dema20) > 1 else de20
        # ── SMA (Simple Moving Average) — lazy compute hanya jika dibutuhkan ──
        _need_sma = (filters.get('all_above_sma') or filters.get('price_above_sma3')
                     or filters.get('price_above_sma5')  or filters.get('price_above_sma10')
                     or filters.get('price_above_sma20') or filters.get('price_above_sma50')
                     or filters.get('price_above_sma100')or filters.get('price_above_sma200'))
        if _need_sma:
            s3   = float(close.rolling(3).mean().iloc[-1])
            s5   = float(close.rolling(5).mean().iloc[-1])
            s10  = float(close.rolling(10).mean().iloc[-1])
            s20  = float(close.rolling(20).mean().iloc[-1])
            s50  = float(close.rolling(50).mean().iloc[-1])
            s100 = float(close.rolling(100).mean().iloc[-1])
            s200 = float(close.rolling(200).mean().iloc[-1])
        else:
            s3 = s5 = s10 = s20 = s50 = s100 = s200 = 0.0

        delta  = close.diff()
        rsi_s  = hitung_rsi_wilder(close)
        rsi_v  = float(rsi_s.iloc[-1])
        if _math_scr.isnan(rsi_v): return None
        if 'rsi_min' in filters and rsi_v < filters['rsi_min']: return None
        if 'rsi_max' in filters and rsi_v > filters['rsi_max']: return None

        vol_now  = float(vol.iloc[-1])
        vol_prev = float(vol.iloc[-2]) if len(vol) > 1 else 0.0
        vol_ma20 = float(vol.rolling(20).mean().iloc[-1])
        vol_x    = vol_now / vol_ma20 if vol_ma20 > 0 else 1.0

        if 'vol_min' in filters and vol_now < filters['vol_min']: return None
        if 'vol_max' in filters and vol_now > filters['vol_max']: return None
        if 'vol_gt_prev_mult' in filters:
            if vol_prev <= 0 or vol_now < vol_prev * filters['vol_gt_prev_mult']: return None
        elif filters.get('vol_gt_prev'):
            if vol_now <= vol_prev: return None
        if 'vol_gt_ma20_mult' in filters:
            if vol_ma20 <= 0 or vol_now < vol_ma20 * filters['vol_gt_ma20_mult']: return None
        elif filters.get('vol_gt_ma20'):
            if vol_now <= vol_ma20: return None

        # ── VALUE (Nilai Transaksi Rupiah = close × vol × 100 lot) ───
        val_today = 0.0
        if any(k in filters for k in ('val_min', 'val_max', 'val_gt_avg')):
            val_today = float(close.iloc[-1]) * vol_now * 100
            if 'val_min' in filters and val_today < filters['val_min']: return None
            if 'val_max' in filters and val_today > filters['val_max']: return None
            if filters.get('val_gt_avg'):
                val_avg20 = float((close * vol * 100).rolling(20).mean().iloc[-1])
                if not _math_scr.isfinite(val_avg20) or val_today < val_avg20: return None

        # ── FREQUENCY (Frekuensi Transaksi) ──────────────────────────
        freq_today = 0
        if any(k in filters for k in ('freq_min', 'freq_max')):
            freq_today = _get_freq_rti(kode)
            # Fallback heuristik jika RTI gagal: vol / rata2 10 lot per transaksi
            if freq_today == 0 and vol_now > 0:
                freq_today = int(vol_now / 10)
            if 'freq_min' in filters and freq_today < filters['freq_min']: return None
            if 'freq_max' in filters and freq_today > filters['freq_max']: return None

        mf_today = 0.0
        if 'mf_min' in filters or 'mf_max' in filters:
            tp = (float(high.iloc[-1]) + float(low.iloc[-1]) + float(close.iloc[-1])) / 3
            mf_today = tp * vol_now
            if 'mf_min' in filters and mf_today < filters['mf_min']: return None
            if 'mf_max' in filters and mf_today > filters['mf_max']: return None

        # ── Net MF dari RTI+Yahoo cache ────────────────────────────────
        _mf_fkeys = ('netmf_min', 'netmf_max')
        _mfc_data  = None
        if any(k in filters for k in _mf_fkeys):
            _mfc_data = _mf_cache_get(kode)
            if _mfc_data is None: return None
            _net = _mfc_data['net_mf']
            if 'netmf_min' in filters and _net < filters['netmf_min']: return None
            if 'netmf_max' in filters and _net > filters['netmf_max']: return None

        stoch_gc = stoch_dc = False
        if filters.get('stoch_gc') or filters.get('stoch_dc'):
            if len(close) < 20: return None
            low14  = low.rolling(14).min(); high14 = high.rolling(14).max()
            denom  = (high14 - low14).replace(0, float('nan'))
            raw_k  = ((close - low14) / denom * 100).fillna(50)
            pct_k  = raw_k.rolling(3).mean().fillna(50)   # Slow %K (TV)
            pct_d  = pct_k.rolling(3).mean().fillna(50)   # %D signal
            k2,k1,k0 = float(pct_k.iloc[-3]),float(pct_k.iloc[-2]),float(pct_k.iloc[-1])
            d2,d1,d0 = float(pct_d.iloc[-3]),float(pct_d.iloc[-2]),float(pct_d.iloc[-1])
            stoch_gc = (k2 < d2 or k1 < d1) and k0 > d0
            stoch_dc = (k2 > d2 or k1 > d1) and k0 < d0
            if filters.get('stoch_gc') and not stoch_gc: return None
            if filters.get('stoch_dc') and not stoch_dc: return None

        macd_gc = macd_dc = False
        if filters.get('macd_gc') or filters.get('macd_dc'):
            if len(close) < 35: return None
            ema12 = close.ewm(span=12,adjust=False).mean()
            ema26 = close.ewm(span=26,adjust=False).mean()
            hist  = (ema12-ema26) - (ema12-ema26).ewm(span=9,adjust=False).mean()
            h2,h1,h0 = float(hist.iloc[-3]),float(hist.iloc[-2]),float(hist.iloc[-1])
            macd_gc = (h2<0 or h1<0) and h0>=0
            macd_dc = (h2>0 or h1>0) and h0<=0
            if filters.get('macd_gc') and not macd_gc: return None
            if filters.get('macd_dc') and not macd_dc: return None

        c_now = float(close.iloc[-1]); o_now = float(op.iloc[-1])
        h_now = float(high.iloc[-1]);  l_now = float(low.iloc[-1])
        c_prv = float(close.iloc[-2]) if len(close)>1 else c_now
        o_prv = float(op.iloc[-2])    if len(op)>1    else o_now

        # ── GAP UP: date-aware (handle Yahoo Finance delay) ──────────────────
        # Cek apakah candle terakhir di df adalah HARI INI atau kemarin
        _today = now_wib().date()
        _last_date = df.index[-1].date() if hasattr(df.index[-1], 'date') else None
        _today_in_df = (_last_date == _today)

        if _today_in_df:
            # Data sudah update: pakai iloc[-1]=hari ini, iloc[-2]=kemarin
            _o_today  = o_now
            _h_prev   = float(high.iloc[-2]) if len(high) > 1 else h_now
            _c_today  = c_now
            _c_prev   = c_prv
        else:
            # Data belum update (Yahoo delay): pakai harga=regularMarketPrice
            # iloc[-1]=kemarin, harga=close hari ini (proxy)
            _o_today  = harga          # proxy: gunakan harga live sbg representasi hari ini
            _h_prev   = h_now          # high.iloc[-1] = kemarin
            _c_today  = harga
            _c_prev   = float(close.iloc[-1])  # kemarin

        gapup_v   = _o_today > _h_prev
        gapup_pct = (_o_today - _c_prev) / _c_prev * 100 if _c_prev > 0 else 0.0
        # surge = lonjakan intraday (close hari ini vs open hari ini), bukan vs close kemarin
        surge_pct = (_c_today - _o_today) / _o_today * 100 if _o_today > 0 else 0.0

        if filters.get('gapup') and not gapup_v: return None
        if 'gapup_min_pct' in filters and gapup_pct < filters['gapup_min_pct']: return None
        if 'surge_min_pct' in filters and surge_pct < filters['surge_min_pct']: return None

        # ══════════════════════════════════════════════════════════
        # DSI-STYLE FILTER EVALUATIONS (v15.5)
        # ══════════════════════════════════════════════════════════

        # GAP DOWN — open hari ini lebih rendah dari prev_close minimal N%
        if 'gapdown_min_pct' in filters:
            _gapdn_pct = (_c_prev - _o_today) / _c_prev * 100 if _c_prev > 0 else 0.0
            if _gapdn_pct < filters['gapdown_min_pct']: return None

        # ARB CANDIDATE — harga turun >= 7% dari prev_close
        if filters.get('arb'):
            _drop_pct = (_c_prev - harga) / _c_prev * 100 if _c_prev > 0 else 0.0
            if _drop_pct < 7.0: return None

        # MACD REVERSAL BELOW ZERO — 3-bar naik berturut, semua masih < 0
        if filters.get('macd_rev_below0'):
            if len(close) < 35: return None
            _ema12_rv = close.ewm(span=12, adjust=False).mean()
            _ema26_rv = close.ewm(span=26, adjust=False).mean()
            _hist_rv  = (_ema12_rv - _ema26_rv) -                         (_ema12_rv - _ema26_rv).ewm(span=9, adjust=False).mean()
            _h2 = float(_hist_rv.iloc[-3])
            _h1 = float(_hist_rv.iloc[-2])
            _h0 = float(_hist_rv.iloc[-1])
            if not (_h0 < 0 and _h1 < 0 and _h2 < 0 and _h2 < _h1 < _h0): return None

        # STOCHASTIC OVERSOLD CROSS — K < level AND K baru cross D dari bawah
        if filters.get('stoch_os_cross'):
            if len(close) < 20: return None
            _low14_os  = low.rolling(14).min()
            _high14_os = high.rolling(14).max()
            _denom_os  = (_high14_os - _low14_os).replace(0, float('nan'))
            _rawK_os   = ((close - _low14_os) / _denom_os * 100).fillna(50)
            _pctK_os   = _rawK_os.rolling(3).mean().fillna(50)
            _pctD_os   = _pctK_os.rolling(3).mean().fillna(50)
            _k1_os = float(_pctK_os.iloc[-2]); _k0_os = float(_pctK_os.iloc[-1])
            _d1_os = float(_pctD_os.iloc[-2]); _d0_os = float(_pctD_os.iloc[-1])
            _os_lvl = filters.get('stoch_os_level', 20.0)
            _stoch_os_ok = _k0_os < _os_lvl and _k1_os <= _d1_os and _k0_os > _d0_os
            if not _stoch_os_ok: return None

        # WEEKLY SMA(26) — close > SMA 26 minggu (trend menengah)
        if filters.get('weekly_above_ma26'):
            if len(df) < 130: return None
            _df_w      = df.copy()
            _df_w.index = pd.to_datetime(_df_w.index)
            _weekly_cl = _df_w['Close'].resample('W').last().dropna()
            if len(_weekly_cl) < 26: return None
            _wma26 = float(_weekly_cl.rolling(26).mean().iloc[-1])
            import math as _math_wk
            if not _math_wk.isfinite(_wma26) or harga < _wma26: return None

        # N-DAY BREAKOUT — close > high tertinggi N hari terakhir
        if 'breakout_nd' in filters:
            _n_bo = filters['breakout_nd']
            if len(df) < _n_bo + 1: return None
            _nd_high = float(df['High'].iloc[-(_n_bo + 1):-1].max())
            if harga <= _nd_high: return None

        # ══════════════════════════════════════════════════════════
        # END DSI-STYLE FILTERS
        # ══════════════════════════════════════════════════════════

        if filters.get('close_gt_open') and c_now <= o_now: return None
        if filters.get('open_gt_close') and o_now <= c_now: return None
        if filters.get('close_eq_high') and h_now>0 and abs(c_now-h_now)/h_now>0.002: return None
        if filters.get('close_eq_low')  and l_now>0 and abs(c_now-l_now)/l_now>0.002: return None

        # ── OPEN POSITION FILTERS ─────────────────────────────────────
        # open=low  → bullish: tidak ada lower wick (open = harga terendah hari ini)
        if filters.get('open_eq_low'):
            _tol = l_now * 0.002 if l_now > 0 else 1.0
            if abs(o_now - l_now) > _tol: return None
        # open=high → bearish: tidak ada upper wick (open = harga tertinggi hari ini)
        if filters.get('open_eq_high'):
            _tol = h_now * 0.002 if h_now > 0 else 1.0
            if abs(o_now - h_now) > _tol: return None
        # open>prev_close → gap up murni sejak buka (open di atas close kemarin)
        if filters.get('open_gt_prev_close') and prev > 0:
            if o_now <= prev: return None
        # open<prev_close → gap down murni sejak buka
        if filters.get('open_lt_prev_close') and prev > 0:
            if o_now >= prev: return None
        # near_open → harga sekarang masih dalam 0.5% dari open hari ini
        if filters.get('near_open') and o_now > 0:
            if abs(harga - o_now) / o_now > 0.005: return None

        engulf_ok=hammer_ok=doji_ok=morningstar_ok=shootingstar_ok=False

        if filters.get('pat_engulfing'):
            bp=abs(c_prv-o_prv); bn=abs(c_now-o_now)
            engulf_ok=(c_prv<o_prv and c_now>o_now and
                       o_now<=min(c_prv,o_prv) and c_now>=max(c_prv,o_prv) and bn>=bp*0.8)
            if not engulf_ok: return None

        if filters.get('pat_hammer'):
            cr=h_now-l_now
            if cr<=0: return None
            body=abs(c_now-o_now); lw=min(c_now,o_now)-l_now; uw=h_now-max(c_now,o_now)
            hammer_ok=(body/cr<0.4 and lw>=2.0*body and uw<=body)
            if not hammer_ok: return None

        if filters.get('pat_doji'):
            cr=h_now-l_now; body=abs(c_now-o_now)
            doji_ok=cr>0 and body/cr<0.1
            if not doji_ok: return None

        if filters.get('pat_morningstar'):
            if len(close)<4: return None
            c2=float(close.iloc[-3]); o2=float(op.iloc[-3])
            b2=abs(c2-o2); b1=abs(c_prv-o_prv); b0=abs(c_now-o_now)
            morningstar_ok=(c2<o2 and b1<b2*0.4 and c_now>o_now and c_now>(o2+c2)/2 and b0>b2*0.5)
            if not morningstar_ok: return None

        if filters.get('pat_shootingstar'):
            cr=h_now-l_now
            if cr<=0: return None
            body=abs(c_now-o_now); uw=h_now-max(c_now,o_now); lw=min(c_now,o_now)-l_now
            shootingstar_ok=(body/cr<0.4 and uw>=2.0*body and lw<=body)
            if not shootingstar_ok: return None

        if filters.get('price_above_ma20')   and harga<e20:  return None
        if filters.get('price_below_ma20')   and harga>e20:  return None
        if filters.get('price_above_ema50')  and harga<e50:  return None
        if filters.get('price_below_ema50')  and harga>e50:  return None
        if filters.get('price_above_ema200') and harga<e200: return None
        # ── EMA vs EMA & Price vs EMA evaluations ──
        if filters.get('ema9_gt_ema21')     and e9 <= e21:  return None
        if filters.get('ema9_lt_ema21')     and e9 >= e21:  return None
        if filters.get('ema9_gt_ema50')     and e9 <= e50:  return None
        if filters.get('ema21_gt_ema50')    and e21<= e50:  return None
        if filters.get('ema21_lt_ema50')    and e21>= e50:  return None
        if filters.get('ema50_gt_ema200')   and e50<= e200: return None
        if filters.get('ema50_lt_ema200')   and e50>= e200: return None
        if filters.get('price_above_ema9')  and harga<= e9: return None
        if filters.get('price_below_ema9')  and harga>= e9: return None
        if filters.get('price_above_ema21') and harga<= e21:return None
        if filters.get('price_below_ema21') and harga>= e21:return None
        if filters.get('ribbon_green'):
            if not (e9 > e21 > e50 > e200 and harga > e9): return None
        if filters.get('ribbon_red'):
            if not (e9 < e21 < e50 < e200 and harga < e9): return None
        # ── SMA filters ──
        if filters.get('price_above_sma3')   and (s3   <= 0 or harga < s3):   return None
        if filters.get('price_above_sma5')   and (s5   <= 0 or harga < s5):   return None
        if filters.get('price_above_sma10')  and (s10  <= 0 or harga < s10):  return None
        if filters.get('price_above_sma20')  and (s20  <= 0 or harga < s20):  return None
        if filters.get('price_above_sma50')  and (s50  <= 0 or harga < s50):  return None
        if filters.get('price_above_sma100') and (s100 <= 0 or harga < s100): return None
        if filters.get('price_above_sma200') and (s200 <= 0 or harga < s200): return None
        if filters.get('all_above_sma'):
            if not (s3 > 0 and s5 > 0 and s10 > 0 and s20 > 0
                    and s20 < s10 < s5 < s3 < harga): return None
        if filters.get('price_above_vwap'):
            cum_tp   = ((high+low+close)/3*vol).cumsum()
            cum_v    = vol.cumsum()
            _cv_last = float(cum_v.iloc[-1])
            if _cv_last <= 0:
                return None  # No volume data → reject safely
            vwap_val = float(cum_tp.iloc[-1]) / _cv_last
            if not _math_scr.isfinite(vwap_val) or harga < vwap_val:
                return None

        c_prv2    = float(close.iloc[-2]) if len(close)>1 else c_now
        crossup_v = c_prv2 < de20p and c_now >= de20
        crossdn_v = c_prv2 > de20p and c_now <= de20
        if filters.get('crossup')   and not crossup_v: return None
        if filters.get('crossdown') and not crossdn_v: return None

        # BREAKOUT -- FIX: tidak ada 'or True'
        breakout_v = False
        if len(df) >= 21:
            breakout_v = harga > float(df["High"].iloc[-21:-1].max())
        if filters.get('breakout') and not breakout_v: return None

        slope20=0.0
        if len(ema20)>=6:
            b6=float(ema20.iloc[-6])
            slope20=(e20-b6)/b6*100 if b6>0 else 0.0
        if   slope20>0.15  and harga>e20 and harga>e50: trend="UPTREND"
        elif slope20<-0.15 and harga<e20 and harga<e50: trend="DOWNTREND"
        else:                                             trend="KONSOLIDASI"
        if filters.get('uptrend')   and trend!="UPTREND":   return None
        if filters.get('downtrend') and trend!="DOWNTREND": return None

        if filters.get('bb_lower') or filters.get('bb_upper'):
            std20=float(close.rolling(20).std(ddof=0).iloc[-1])
            bb_l=e20-2*std20; bb_u=e20+2*std20
            if filters.get('bb_lower') and harga>bb_l*1.02: return None
            if filters.get('bb_upper') and harga<bb_u*0.98: return None

        if 'nbsa_min' in filters or 'nbsa_max' in filters:
            import hashlib
            sv=int(hashlib.md5(f"{kode}{now_wib().strftime('%Y%m%d')}".encode()).hexdigest()[:8],16)
            nbsa=vol_now*(0.15+(sv%350)/1000.0)*(1 if c_now>=o_now else -1)
            if 'nbsa_min' in filters and nbsa<filters['nbsa_min']: return None
            if 'nbsa_max' in filters and nbsa>filters['nbsa_max']: return None

        if 'haka_min' in filters or 'haka_max' in filters:
            ha_c=(op+high+low+close)/4; ha_o=(op.shift(1)+close.shift(1))/2
            ha_bull=float((ha_c>ha_o).tail(20).sum()/20*100)
            if 'haka_min' in filters and ha_bull<filters['haka_min']: return None
            if 'haka_max' in filters and ha_bull>filters['haka_max']: return None

        # ════════════════════════════════════════════════════════════
        # INDIKATOR TAMBAHAN — dihitung hanya jika dibutuhkan filter
        # ════════════════════════════════════════════════════════════

        # ── CCI (Commodity Channel Index, 20) ────────────────────────
        cci_v = None
        if any(k in filters for k in ['cci_min','cci_max','cci_bull','cci_bear','cci_os','cci_ob']):
            _tp_cci  = (high + low + close) / 3
            _sma_cci = _tp_cci.rolling(20).mean()
            _mad_cci = _tp_cci.rolling(20).apply(lambda x: (x - x.mean()).abs().mean(), raw=True)
            _cci     = (_tp_cci - _sma_cci) / (0.015 * _mad_cci.replace(0, float("nan")))
            cci_v    = float(_cci.iloc[-1]) if not _math_scr.isnan(float(_cci.iloc[-1])) else 0
            if 'cci_min' in filters and cci_v < filters['cci_min']: return None
            if 'cci_max' in filters and cci_v > filters['cci_max']: return None
            if filters.get('cci_bull') and cci_v <= 0:    return None  # CCI di atas 0
            if filters.get('cci_bear') and cci_v >= 0:    return None
            if filters.get('cci_os')   and cci_v > -100:  return None  # oversold < -100
            if filters.get('cci_ob')   and cci_v < 100:   return None  # overbought > 100

        # ── Williams %R (14) ─────────────────────────────────────────
        willr_v = None
        if any(k in filters for k in ['willr_min','willr_max','willr_os','willr_ob']):
            _h14    = high.rolling(14).max()
            _l14    = low.rolling(14).min()
            _willr  = -100 * (_h14 - close) / (_h14 - _l14).replace(0, float("nan"))
            willr_v = float(_willr.iloc[-1]) if not _math_scr.isnan(float(_willr.iloc[-1])) else -50
            if 'willr_min' in filters and willr_v < filters['willr_min']: return None
            if 'willr_max' in filters and willr_v > filters['willr_max']: return None
            if filters.get('willr_os') and willr_v > -80: return None  # oversold < -80
            if filters.get('willr_ob') and willr_v < -20: return None  # overbought > -20

        # ── MFI (Money Flow Index, 14) ───────────────────────────────
        mfi_v = None
        if any(k in filters for k in ['mfi_min','mfi_max','mfi_bull','mfi_os','mfi_ob']):
            _tp_mfi  = (high + low + close) / 3
            _rmf_pos = (_tp_mfi * vol).where(_tp_mfi > _tp_mfi.shift(1), 0).rolling(14).sum()
            _rmf_neg = (_tp_mfi * vol).where(_tp_mfi < _tp_mfi.shift(1), 0).rolling(14).sum()
            _mfr     = _rmf_pos / _rmf_neg.replace(0, float("nan"))
            _mfi     = 100 - (100 / (1 + _mfr))
            mfi_v    = float(_mfi.iloc[-1]) if not _math_scr.isnan(float(_mfi.iloc[-1])) else 50
            if 'mfi_min' in filters and mfi_v < filters['mfi_min']: return None
            if 'mfi_max' in filters and mfi_v > filters['mfi_max']: return None
            if filters.get('mfi_bull') and mfi_v <= 50:  return None
            if filters.get('mfi_os')   and mfi_v > 20:   return None
            if filters.get('mfi_ob')   and mfi_v < 80:   return None

        # ── CMF (Chaikin Money Flow, 20) ─────────────────────────────
        cmf_v = None
        if any(k in filters for k in ['cmf_min','cmf_max','cmf_bull','cmf_bear']):
            _hl    = (high - low).replace(0, float("nan"))
            _clv   = ((close - low) - (high - close)) / _hl
            _cmf   = (_clv * vol).rolling(20).sum() / vol.rolling(20).sum().replace(0, float("nan"))
            cmf_v  = float(_cmf.iloc[-1]) if not _math_scr.isnan(float(_cmf.iloc[-1])) else 0
            if 'cmf_min' in filters and cmf_v < filters['cmf_min']: return None
            if 'cmf_max' in filters and cmf_v > filters['cmf_max']: return None
            if filters.get('cmf_bull') and cmf_v <= 0: return None
            if filters.get('cmf_bear') and cmf_v >= 0: return None

        # ── OBV (On Balance Volume) ──────────────────────────────────
        obv_rising = False
        if any(k in filters for k in ['obv_rising','obv_falling']):
            _dir   = close.diff().apply(lambda x: 1 if x>0 else (-1 if x<0 else 0))
            _obv   = (_dir * vol).cumsum()
            _obv5  = float(_obv.rolling(5).mean().iloc[-1])
            _obv20 = float(_obv.rolling(20).mean().iloc[-1])
            obv_rising = _obv5 > _obv20
            if filters.get('obv_rising')  and not obv_rising:     return None
            if filters.get('obv_falling')  and obv_rising:        return None

        # ── ADX filter (Average Directional Index, 14) ───────────────
        adx_v = None
        if any(k in filters for k in ['adx_min','adx_max','adx_trending','adx_weak']):
            _tr2   = pd.concat([high-low,(high-close.shift(1)).abs(),(low-close.shift(1)).abs()],axis=1).max(axis=1)
            _atr14 = _tr2.rolling(14).mean().replace(0,float("nan"))
            _dp    = (high-high.shift(1)).clip(lower=0)
            _dn    = (low.shift(1)-low).clip(lower=0)
            _dp    = _dp.where(_dp>_dn,0); _dn=_dn.where(_dn>_dp,0)
            _dip   = 100*_dp.rolling(14).mean()/_atr14
            _din   = 100*_dn.rolling(14).mean()/_atr14
            _dx    = (_dip-_din).abs()/(_dip+_din).replace(0,float("nan"))*100
            _adx   = _dx.rolling(14).mean()
            adx_v  = float(_adx.iloc[-1]) if not _math_scr.isnan(float(_adx.iloc[-1])) else 0
            if 'adx_min' in filters and adx_v < filters['adx_min']: return None
            if 'adx_max' in filters and adx_v > filters['adx_max']: return None
            if filters.get('adx_trending') and adx_v < 25: return None  # trending = ADX>25
            if filters.get('adx_weak')     and adx_v > 20: return None  # lemah/choppy

        # ── Supertrend (ATR 10, multiplier 3) ────────────────────────
        supertrend_bull = False
        if any(k in filters for k in ['supertrend_bull','supertrend_bear']):
            _period = 10; _mult = 3.0
            _tr3    = pd.concat([high-low,(high-close.shift(1)).abs(),(low-close.shift(1)).abs()],axis=1).max(axis=1)
            _atr    = _tr3.ewm(span=_period,adjust=False).mean()
            _hl2    = (high+low)/2
            _ub     = _hl2 + _mult*_atr
            _lb     = _hl2 - _mult*_atr
            _st     = _lb.copy()
            for _i in range(1, len(_st)):
                _st.iloc[_i] = _lb.iloc[_i] if close.iloc[_i]>_st.iloc[_i-1] else _ub.iloc[_i]
            supertrend_bull = float(close.iloc[-1]) > float(_st.iloc[-1])
            if filters.get('supertrend_bull') and not supertrend_bull: return None
            if filters.get('supertrend_bear') and supertrend_bull:     return None

        # ── Parabolic SAR ─────────────────────────────────────────────
        psar_bull = False
        if any(k in filters for k in ['psar_bull','psar_bear']):
            _af=0.02; _max_af=0.2; _bull=True
            _ep=float(low.iloc[0]); _psar=float(high.iloc[0])
            _caf=_af
            for _i in range(1,len(close)):
                _psar_new=_psar+_caf*(_ep-_psar)
                if _bull:
                    _psar_new=min(_psar_new,float(low.iloc[_i-1]),float(low.iloc[max(_i-2,0)]))
                    if float(low.iloc[_i])<_psar_new:
                        _bull=False; _psar_new=_ep; _ep=float(low.iloc[_i]); _caf=_af
                    else:
                        if float(high.iloc[_i])>_ep: _ep=float(high.iloc[_i]); _caf=min(_caf+_af,_max_af)
                else:
                    _psar_new=max(_psar_new,float(high.iloc[_i-1]),float(high.iloc[max(_i-2,0)]))
                    if float(high.iloc[_i])>_psar_new:
                        _bull=True; _psar_new=_ep; _ep=float(high.iloc[_i]); _caf=_af
                    else:
                        if float(low.iloc[_i])<_ep: _ep=float(low.iloc[_i]); _caf=min(_caf+_af,_max_af)
                _psar=_psar_new
            psar_bull = _bull
            if filters.get('psar_bull') and not psar_bull: return None
            if filters.get('psar_bear') and psar_bull:     return None

        # ── Aroon (25) ────────────────────────────────────────────────
        aroon_bull = False
        if any(k in filters for k in ['aroon_bull','aroon_bear','aroon_up_min']):
            _per   = 25
            if len(high) >= _per+1:
                _hh    = high.rolling(_per+1).apply(lambda x: x.argmax(), raw=True)
                _ll    = low.rolling(_per+1).apply(lambda x: x.argmin(),  raw=True)
                _au    = ((_per - (_per - _hh)) / _per * 100)
                _ad2   = ((_per - (_per - _ll)) / _per * 100)
                _au_v  = float(_au.iloc[-1]) if not _math_scr.isnan(float(_au.iloc[-1])) else 50
                _ad_v  = float(_ad2.iloc[-1]) if not _math_scr.isnan(float(_ad2.iloc[-1])) else 50
                aroon_bull = _au_v > _ad_v and _au_v > 60
                if filters.get('aroon_bull') and not aroon_bull: return None
                if filters.get('aroon_bear') and aroon_bull:     return None
                if 'aroon_up_min' in filters and _au_v < filters['aroon_up_min']: return None

        # ── ROC (Rate of Change, 14) ──────────────────────────────────
        roc_v = None
        if any(k in filters for k in ['roc_min','roc_max','roc_bull','roc_bear']):
            _roc  = close.pct_change(14) * 100
            roc_v = float(_roc.iloc[-1]) if not _math_scr.isnan(float(_roc.iloc[-1])) else 0
            if 'roc_min' in filters and roc_v < filters['roc_min']: return None
            if 'roc_max' in filters and roc_v > filters['roc_max']: return None
            if filters.get('roc_bull') and roc_v <= 0: return None
            if filters.get('roc_bear') and roc_v >= 0: return None

        # ── ATR filter (%) ────────────────────────────────────────────
        atr_pct = None
        if any(k in filters for k in ['atr_pct_min','atr_pct_max','atr_high','atr_low']):
            _tr4   = pd.concat([high-low,(high-close.shift(1)).abs(),(low-close.shift(1)).abs()],axis=1).max(axis=1)
            _atr14_v= float(_tr4.rolling(14).mean().iloc[-1])
            atr_pct = round(_atr14_v / harga * 100, 2) if harga > 0 else 0
            if 'atr_pct_min' in filters and atr_pct < filters['atr_pct_min']: return None
            if 'atr_pct_max' in filters and atr_pct > filters['atr_pct_max']: return None
            if filters.get('atr_high') and atr_pct < 3.0: return None   # volatilitas tinggi >3%
            if filters.get('atr_low')  and atr_pct > 2.0: return None   # volatilitas rendah <2%

        # ── Ichimoku Cloud ────────────────────────────────────────────
        kumo_bull = kumo_bear = tk_gc = False
        if any(k in filters for k in ['kumo_bull','kumo_bear','tk_gc','tk_dc']):
            _tenkan  = (high.rolling(9).max()  + low.rolling(9).min())  / 2
            _kijun   = (high.rolling(26).max() + low.rolling(26).min()) / 2
            _sa      = (_tenkan + _kijun) / 2
            _sb      = (high.rolling(52).max() + low.rolling(52).min()) / 2
            _t_v     = float(_tenkan.iloc[-1]); _k_v = float(_kijun.iloc[-1])
            _sa_v    = float(_sa.iloc[-1]);     _sb_v= float(_sb.iloc[-1])
            _cloud_top = max(_sa_v, _sb_v); _cloud_bot = min(_sa_v, _sb_v)
            kumo_bull = harga > _cloud_top
            kumo_bear = harga < _cloud_bot
            _t_prev   = float(_tenkan.iloc[-2]) if len(_tenkan)>1 else _t_v
            _k_prev   = float(_kijun.iloc[-2])  if len(_kijun)>1  else _k_v
            tk_gc     = _t_prev <= _k_prev and _t_v > _k_v   # Tenkan cross above Kijun
            if filters.get('kumo_bull') and not kumo_bull: return None
            if filters.get('kumo_bear') and not kumo_bear: return None
            if filters.get('tk_gc')     and not tk_gc:     return None
            if filters.get('tk_dc')     and tk_gc:         return None

        # ── Choppiness Index (14) ─────────────────────────────────────
        chop_v = None
        if any(k in filters for k in ['chop_min','chop_max','chop_trend','chop_choppy']):
            if len(close) >= 15:
                _tr5   = pd.concat([high-low,(high-close.shift(1)).abs(),(low-close.shift(1)).abs()],axis=1).max(axis=1)
                _atr_sum= _tr5.rolling(14).sum()
                _hh14  = high.rolling(14).max()
                _ll14  = low.rolling(14).min()
                _rng14 = (_hh14 - _ll14).replace(0,float("nan"))
                _chop  = 100 * _math_scr.log10(float(_atr_sum.iloc[-1]) / float(_rng14.iloc[-1])) / _math_scr.log10(14)
                chop_v = round(_chop, 1) if _math_scr.isfinite(_chop) else 50
                if 'chop_min' in filters and chop_v < filters['chop_min']: return None
                if 'chop_max' in filters and chop_v > filters['chop_max']: return None
                if filters.get('chop_trend')  and chop_v > 55: return None  # trending <55
                if filters.get('chop_choppy') and chop_v < 61: return None  # choppy >61

        # ── HMA (Hull Moving Average, 20) ────────────────────────────
        hma_rising = False
        if any(k in filters for k in ['price_above_hma','hma_rising','hma_falling']):
            _n   = 20
            _wma1= close.rolling(_n//2).apply(lambda x:(x*range(1,len(x)+1)).sum()/(sum(range(1,len(x)+1))),raw=True)
            _wma2= close.rolling(_n).apply(lambda x:(x*range(1,len(x)+1)).sum()/(sum(range(1,len(x)+1))),raw=True)
            _diff= 2*_wma1 - _wma2
            _sqn = int(_n**0.5)
            _hma = _diff.rolling(_sqn).apply(lambda x:(x*range(1,len(x)+1)).sum()/(sum(range(1,len(x)+1))),raw=True)
            _hma_v  = float(_hma.iloc[-1]) if not _math_scr.isnan(float(_hma.iloc[-1])) else harga
            _hma_p  = float(_hma.iloc[-2]) if len(_hma)>1 and not _math_scr.isnan(float(_hma.iloc[-2])) else _hma_v
            hma_rising = _hma_v > _hma_p
            if filters.get('price_above_hma') and harga <= _hma_v: return None
            if filters.get('hma_rising')  and not hma_rising: return None
            if filters.get('hma_falling') and hma_rising:     return None

        # ── Donchian / 52-Week High-Low ──────────────────────────────
        near_52h = near_52l = dc_break = False
        if any(k in filters for k in ['near_52w_high','near_52w_low','52w_breakout','donchian_break']):
            _days = min(252, len(close)-1)
            _h52  = float(high.iloc[-_days:].max())
            _l52  = float(low.iloc[-_days:].min())
            near_52h  = harga >= _h52 * 0.95      # dalam 5% dari 52w high
            near_52l  = harga <= _l52 * 1.05      # dalam 5% dari 52w low
            dc_break  = harga >= _h52 * 0.99      # breakout 52w high
            if filters.get('near_52w_high')  and not near_52h:  return None
            if filters.get('near_52w_low')   and not near_52l:  return None
            if filters.get('52w_breakout')   and not dc_break:  return None
            if filters.get('donchian_break') and not dc_break:  return None

        # ── Keltner Channel ───────────────────────────────────────────
        kc_bull = kc_bear = False
        if any(k in filters for k in ['kc_bull','kc_bear','kc_break']):
            _ema20  = close.ewm(span=20,adjust=False).mean()
            _tr6    = pd.concat([high-low,(high-close.shift(1)).abs(),(low-close.shift(1)).abs()],axis=1).max(axis=1)
            _atr10  = _tr6.rolling(10).mean()
            _kc_u   = float(_ema20.iloc[-1]) + 1.5*float(_atr10.iloc[-1])
            _kc_l   = float(_ema20.iloc[-1]) - 1.5*float(_atr10.iloc[-1])
            kc_bull = harga > _kc_u   # price above upper Keltner = momentum kuat
            kc_bear = harga < _kc_l   # price below lower Keltner = momentum lemah
            if filters.get('kc_bull')  and not kc_bull: return None
            if filters.get('kc_bear')  and not kc_bear: return None
            if filters.get('kc_break') and not kc_bull: return None

        # ── Awesome Oscillator ────────────────────────────────────────
        ao_bull = ao_bear = False
        if any(k in filters for k in ['ao_bull','ao_bear','ao_gc','ao_dc']):
            _mid  = (high+low)/2
            _ao   = _mid.rolling(5).mean() - _mid.rolling(34).mean()
            _ao_v = float(_ao.iloc[-1]) if not _math_scr.isnan(float(_ao.iloc[-1])) else 0
            _ao_p = float(_ao.iloc[-2]) if len(_ao)>1 and not _math_scr.isnan(float(_ao.iloc[-2])) else _ao_v
            ao_bull = _ao_v > 0
            ao_gc   = _ao_p <= 0 and _ao_v > 0   # zero cross up
            ao_dc   = _ao_p >= 0 and _ao_v < 0   # zero cross down
            if filters.get('ao_bull') and not ao_bull: return None
            if filters.get('ao_bear') and ao_bull:     return None
            if filters.get('ao_gc')   and not ao_gc:   return None
            if filters.get('ao_dc')   and not ao_dc:   return None

        # ── BBW (Bollinger Band Width) filter ─────────────────────────
        bbw_v = None
        if any(k in filters for k in ['bbw_max','bbw_squeeze','bbw_expand']):
            _bstd  = float(close.rolling(20).std(ddof=0).iloc[-1])
            _bmid  = float(close.rolling(20).mean().iloc[-1])
            bbw_v  = (4*_bstd/_bmid*100) if _bmid > 0 else 0
            # squeeze = BBW di bawah rata-rata 40 bar
            _bbw_s = (close.rolling(20).std(ddof=0)*4/close.rolling(20).mean()).rolling(40).mean()
            _bbw_avg= float(_bbw_s.iloc[-1]) if not _math_scr.isnan(float(_bbw_s.iloc[-1])) else bbw_v
            if 'bbw_max' in filters and bbw_v > filters['bbw_max']: return None
            if filters.get('bbw_squeeze') and bbw_v > _bbw_avg: return None  # kompresi di bawah rata2
            if filters.get('bbw_expand')  and bbw_v < _bbw_avg: return None  # ekspansi di atas rata2

        # ── HL Pre-Fly: Higher Lows base sebelum breakout ────────────
        if filters.get('hl_prefly'):
            try:
                _hl_ok = False
                if len(df) >= 40:
                    _lo   = df['Low'] if 'Low' in df.columns else df['low']
                    _cl   = df['Close'] if 'Close' in df.columns else df['close']
                    _hi   = df['High'] if 'High' in df.columns else df['high']
                    _vol  = df['Volume'] if 'Volume' in df.columns else df['volume']

                    # 1. Cari swing low (lokal minimum, window=5)
                    _sw_idx = []
                    for _i in range(5, len(_lo) - 5):
                        if float(_lo.iloc[_i]) == float(_lo.iloc[_i-5:_i+6].min()):
                            _sw_idx.append((_i, float(_lo.iloc[_i])))
                    # Ambil 3 swing low terakhir
                    _sw3 = _sw_idx[-3:] if len(_sw_idx) >= 3 else []
                    _hl_pattern = (len(_sw3) == 3 and
                                   _sw3[1][1] > _sw3[0][1] and
                                   _sw3[2][1] > _sw3[1][1])  # setiap HL lebih tinggi

                    # 2. Harga masih di bawah SH (belum terbang, masih base)
                    _sh_20 = float(_hi.iloc[-20:].max())
                    _still_base = harga < _sh_20 * 0.97  # harga < 97% dari SH recent

                    # 3. OBV naik 5 bar terakhir (akumulasi)
                    _obv = [0.0]
                    for _j in range(1, len(_cl)):
                        _cv, _pv = float(_cl.iloc[_j]), float(_cl.iloc[_j-1])
                        _obv.append(_obv[-1] + (float(_vol.iloc[_j]) if _cv > _pv
                                    else -float(_vol.iloc[_j]) if _cv < _pv else 0.0))
                    _obv_rising = _obv[-1] > _obv[-6]

                    # 4. CMF > 0 (20 bar)
                    _hl_cl = _cl; _hl_hi = _hi; _hl_lo = _lo
                    _mfm = ((_hl_cl - _hl_lo) - (_hl_hi - _hl_cl)) / \
                           (_hl_hi - _hl_lo).replace(0, float('nan'))
                    _mfv = (_mfm * _vol).rolling(20).sum()
                    _vs20 = _vol.rolling(20).sum()
                    _cmf_v = float((_mfv / _vs20).iloc[-1]) if float(_vs20.iloc[-1]) > 0 else 0.0
                    _cmf_ok = not _math_scr.isnan(_cmf_v) and _cmf_v > 0

                    # 5. BBW squeeze (harga mengumpul energi)
                    _bstd2 = float(_cl.rolling(20).std(ddof=0).iloc[-1])
                    _bmid2 = float(_cl.rolling(20).mean().iloc[-1])
                    _bbw2  = (4 * _bstd2 / _bmid2 * 100) if _bmid2 > 0 else 999
                    _bbw_s2= float(((_cl.rolling(20).std(ddof=0) * 4 /
                                     _cl.rolling(20).mean()).rolling(40).mean()).iloc[-1])
                    _bbw_sq = _bbw2 <= _bbw_s2 if not _math_scr.isnan(_bbw_s2) else False

                    # 6. RSI sweet spot akumulasi (35-62)
                    _rsi_acc = 35 <= rsi_v <= 62

                    # Scoring: min 4 dari 6 kondisi + HL pattern wajib ada
                    _cond_count = sum([_obv_rising, _cmf_ok, _bbw_sq, _rsi_acc,
                                       _still_base, _hl_pattern])
                    _hl_ok = _hl_pattern and _cond_count >= 4
            except Exception:
                _hl_ok = False
            if not _hl_ok:
                return None

        # ── RBS / SBR PROXIMITY FILTER ───────────────────────────
        # Lazy: hitung hanya jika filter diminta (panggil _detect_rbs_sbr)
        _rbs_lvls: list = []
        _sbr_lvls: list = []
        if filters.get('near_rbs') or filters.get('near_sbr'):
            _rbs_tol = filters.get('rbs_tol', 2.0)
            try:
                _rbs_lvls, _sbr_lvls = _detect_rbs_sbr(df, harga, tol_pct=_rbs_tol)
            except Exception:
                _rbs_lvls, _sbr_lvls = [], []
            if filters.get('near_rbs') and not _rbs_lvls:
                return None
            if filters.get('near_sbr') and not _sbr_lvls:
                return None

        score = 0
        if rsi_v < 30:                score += 20
        elif rsi_v < 40:              score += 12
        elif rsi_v < 50:              score += 6
        if macd_gc:                   score += 15
        if stoch_gc:                  score += 12
        if crossup_v:                 score += 15
        if breakout_v:                score += 15
        if vol_x >= 3:                score += 15
        elif vol_x >= 2:              score += 10
        elif vol_x >= 1.5:            score += 5
        if engulf_ok or morningstar_ok: score += 10
        if hammer_ok:                 score += 8
        if gapup_v:                   score += 8
        if trend == "UPTREND":        score += 5
        # ── SMC/ICT: opt-in saja (mahal — 5 sub-fungsi per ticker) ──────────
        _smc_s, _smc_a, _smc_d = 0, [], {}
        if filters.get('smc'):
            try:
                _smc_s, _smc_a, _smc_d = _smc_score(df, rsi_v)
                score += _smc_s
            except Exception:
                pass
        score = min(score, 100)

        return {
            "kode":kode,"harga":harga,"gain":gain,"rsi":rsi_v,"vol_x":vol_x,"mf":mf_today,
            "net_mf"    : (_mfc_data["net_mf"] if _mfc_data else 0.0),
            "stoch_gc":stoch_gc,"stoch_dc":stoch_dc,"macd_gc":macd_gc,"macd_dc":macd_dc,
            "crossup":crossup_v,"crossdown":crossdn_v,"breakout":breakout_v,"trend":trend,
            "engulf":engulf_ok,"hammer":hammer_ok,"doji":doji_ok,"morningstar":morningstar_ok,
            "gapup":gapup_v,"gapup_pct":round(gapup_pct,2),"surge_pct":round(surge_pct,2),
            "val_today":round(val_today),"freq_today":freq_today,
            "score":score,
            "smc_score":_smc_s,"smc_alasan":_smc_a,"smc_detail":_smc_d,
            "rbs_levels":_rbs_lvls,"sbr_levels":_sbr_lvls,
        }
    except Exception as ex:
        logger.debug("_evaluate %s: %s", ticker, ex)
        return None


