# ── /scr Rate Limiter — cegah Yahoo Finance ban ──────────────
_SCR_LAST_CALL  = {}   # {user_id: timestamp}
_SCR_COOLDOWN   = 45   # detik minimum antar /scr manual

def _scr_check_cooldown(user_id):
    """Return (boleh, sisa_detik). Boleh=True jika cooldown sudah habis."""
    if user_id is None:
        return True, 0
    now = time.time()
    last = _SCR_LAST_CALL.get(str(user_id), 0)
    sisa = _SCR_COOLDOWN - (now - last)
    if sisa > 0:
        return False, int(sisa) + 1
    _SCR_LAST_CALL[str(user_id)] = now
    return True, 0

def _fetch_ohlcv_robust(ticker, period="6mo"):
    """
    Fetch OHLCV dengan 4-layer fallback + cache + rate limit.
    Layer 1: yf.download (paling stabil) — via rate limiter
    Layer 2: yf.Ticker.history — via rate limiter
    Layer 3: Yahoo Finance v8 API langsung
    Layer 4: Cache internal bot
    """
    import yfinance as yf
    import pandas as pd
    import requests as _req

    # ── Cache check ──
    _ck = _yf_cache_key("_fetch_ohlcv_robust", ticker, period)
    _cached, _hit = _yf_cache_get(_ck)
    if _hit and _cached is not None:
        return _cached

    min_rows = 50

    # Layer 1: yf.download via rate limiter
    try:
        raw = _silent_yf_download_safe(ticker, period=period, interval="1d",
                          auto_adjust=True, progress=False, timeout=15)
        if raw is not None and len(raw) >= min_rows:
            df = raw[["Open","High","Low","Close","Volume"]].copy()
            df.columns = ["Open","High","Low","Close","Volume"]
            df.dropna(inplace=True)
            if len(df) >= min_rows:
                _yf_cache_set(_ck, df, _YF_CACHE_TTL)
                return df
    except Exception:
        pass

    # Layer 2: Ticker.history via rate limiter
    try:
        raw = _safe_ticker_history(ticker, period=period, interval="1d",
                                   auto_adjust=True, timeout=15)
        if raw is not None and len(raw) >= min_rows:
            df = raw[["Open","High","Low","Close","Volume"]].copy()
            df.columns = ["Open","High","Low","Close","Volume"]
            df.dropna(inplace=True)
            if len(df) >= min_rows:
                _yf_cache_set(_ck, df, _YF_CACHE_TTL)
                return df
    except Exception:
        pass

    # Layer 3: Yahoo Finance v8 API langsung
    try:
        url  = (f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}"
                f"?range={period}&interval=1d&includePrePost=false")
        r = _req.get(url, headers={"User-Agent": "Mozilla/5.0"}, timeout=15)
        data = r.json()["chart"]["result"][0]
        ts   = data["timestamp"]
        q    = data["indicators"]["quote"][0]
        adj  = data["indicators"].get("adjclose", [{}])[0].get("adjclose", q["close"])
        rows = []
        for i in range(len(ts)):
            try:
                rows.append({
                    "Open"  : q["open"][i],
                    "High"  : q["high"][i],
                    "Low"   : q["low"][i],
                    "Close" : adj[i] if adj[i] else q["close"][i],
                    "Volume": q["volume"][i] or 0,
                })
            except Exception:
                pass
        if rows:
            idx = pd.to_datetime([_dt.datetime.fromtimestamp(t, tz=WIB) for t in ts[:len(rows)]])
            df  = pd.DataFrame(rows, index=idx)
            df.dropna(subset=["Open","High","Low","Close"], inplace=True)
            if len(df) >= min_rows:
                return df
    except Exception:
        pass

    # Layer 4: bot internal cache
    try:
        df_int, _ = _ambil_data_harian_radar(ticker)
        if df_int is not None and len(df_int) >= min_rows:
            return df_int[["Open","High","Low","Close","Volume"]].copy()
    except Exception:
        pass

    return None


# ════════════════════════════════════════════════════════════
# ██  SMC / ICT STRATEGY ENGINE  ████████████████████████████
# ════════════════════════════════════════════════════════════
# Diadaptasi dari XAUUSD/BTC ICT ke IDX
# 5 sinyal: FVG | Liquidity Sweep | Order Block | BOS/CHoCH | Volume Profile
# Integrasi: _evaluate() skor += smc_score(df, rsi_v)
# Command: /smc KODE
# ════════════════════════════════════════════════════════════

# ── 1. ORDER BLOCK (OB) ──────────────────────────────────────
def _smc_detect_ob(df, n=3):
    """Bullish OB: candle bearish terakhir sebelum bullish impulse (BOS)."""
    if len(df) < n + 15:
        return []
    obs = []
    for i in range(n + 1, len(df) - 1):
        if float(df['Close'].iloc[i]) < float(df['Open'].iloc[i]):
            window = df['High'].iloc[max(0, i - 14):i]
            if len(window) < 5:
                continue
            atr  = float(window.max() - window.min())
            move = float(df['Close'].iloc[i + 1]) - float(df['Open'].iloc[i + 1])
            if move > atr * 0.8:
                obs.append({
                    'index':   i,
                    'ob_high': float(df['Open'].iloc[i]),
                    'ob_low':  float(df['Close'].iloc[i]),
                })
    active = []
    for ob in obs[-5:]:
        if len(df) > ob['index'] + 2:
            recent_low = float(df['Low'].iloc[ob['index'] + 2:].min())
            if recent_low > ob['ob_low']:
                active.append(ob)
    return active

def _smc_ob_signal(df):
    """True jika harga sedang retest ke zona OB aktif."""
    obs = _smc_detect_ob(df)
    if not obs:
        return False, None
    last_ob = obs[-1]
    cur = float(df['Close'].iloc[-1])
    in_ob = last_ob['ob_low'] <= cur <= last_ob['ob_high'] * 1.005
    return in_ob, last_ob

# ── 2. FAIR VALUE GAP (FVG) ──────────────────────────────────
def _smc_detect_fvg(df, min_gap_pct=0.005):
    """
    Bullish FVG: low[i] > high[i-2] (gap di atas, belum diisi).
    min_gap_pct: minimum 0.5% untuk IDX.
    """
    if len(df) < 5:
        return []
    fvgs = []
    for i in range(2, len(df)):
        h_im2 = float(df['High'].iloc[i - 2])
        l_im2 = float(df['Low'].iloc[i - 2])
        h_i   = float(df['High'].iloc[i])
        l_i   = float(df['Low'].iloc[i])
        if l_i > h_im2:
            gap_pct = (l_i - h_im2) / h_im2 if h_im2 > 0 else 0
            if gap_pct >= min_gap_pct:
                fvgs.append({'type': 'bullish', 'top': l_i, 'bot': h_im2,
                             'mid': (l_i + h_im2) / 2, 'idx': i})
        elif h_i < l_im2:
            gap_pct = (l_im2 - h_i) / l_im2 if l_im2 > 0 else 0
            if gap_pct >= min_gap_pct:
                fvgs.append({'type': 'bearish', 'top': l_im2, 'bot': h_i,
                             'mid': (l_im2 + h_i) / 2, 'idx': i})
    active = []
    for fvg in fvgs[-8:]:
        later = df.iloc[fvg['idx'] + 1:]
        if len(later) == 0:
            active.append(fvg); continue
        if fvg['type'] == 'bullish':
            filled = bool((later['Low'] <= fvg['mid']).any())
        else:
            filled = bool((later['High'] >= fvg['mid']).any())
        if not filled:
            active.append(fvg)
    return active

def _smc_fvg_signal(df):
    """True jika harga sedang di dalam bullish FVG aktif."""
    fvgs = _smc_detect_fvg(df)
    cur  = float(df['Close'].iloc[-1])
    for fvg in fvgs:
        if fvg['type'] == 'bullish' and fvg['bot'] <= cur <= fvg['top']:
            return True, fvg
    return False, None

# ── 3. BOS / CHoCH (MARKET STRUCTURE) ───────────────────────
def _smc_detect_ms(df, swing_len=5):
    """
    BOS bullish: close > swing high terakhir.
    CHoCH bullish: Higher Low setelah serangkaian Lower Lows.
    """
    if len(df) < swing_len * 3:
        return {'bos': False, 'choch': False, 'type': None}
    highs, lows = [], []
    for i in range(swing_len, len(df) - swing_len):
        win_h = df['High'].iloc[i - swing_len: i + swing_len + 1]
        win_l = df['Low'].iloc[i - swing_len: i + swing_len + 1]
        if float(df['High'].iloc[i]) == float(win_h.max()):
            highs.append((i, float(df['High'].iloc[i])))
        if float(df['Low'].iloc[i]) == float(win_l.min()):
            lows.append((i, float(df['Low'].iloc[i])))
    result = {'bos': False, 'choch': False, 'type': None}
    cur_close = float(df['Close'].iloc[-1])
    if highs and cur_close > highs[-1][1]:
        result['bos'] = True; result['type'] = 'bullish'
    if len(lows) >= 3:
        sl = [l[1] for l in lows[-3:]]
        if sl[0] > sl[1] and sl[2] > sl[1]:  # V-shape = Higher Low
            result['choch'] = True; result['type'] = 'bullish_reversal'
    return result

# ── 4. VOLUME PROFILE (POC / VAH / VAL) ─────────────────────
def _smc_volume_profile(df, bins=20):
    """
    POC = price bin dengan volume terbesar.
    VAH/VAL = Value Area High/Low (70% volume).
    """
    if len(df) < 10 or float(df['Volume'].sum()) == 0:
        return None, None, None
    price_min = float(df['Low'].min())
    price_max = float(df['High'].max())
    if price_max <= price_min:
        return None, None, None
    bin_size = (price_max - price_min) / bins
    vbp = {}
    for _, row in df.iterrows():
        lo  = float(row['Low']); hi = float(row['High']); vol = float(row['Volume'])
        if hi <= lo or vol == 0: continue
        for b in range(bins):
            bp = price_min + b * bin_size; tp = bp + bin_size
            overlap = max(0.0, min(hi, tp) - max(lo, bp))
            if overlap > 0:
                vbp[b] = vbp.get(b, 0.0) + vol * overlap / (hi - lo)
    if not vbp: return None, None, None
    poc_bin  = max(vbp, key=vbp.get)
    poc      = price_min + poc_bin * bin_size + bin_size / 2
    total_v  = sum(vbp.values()); target = total_v * 0.70
    hi_b = lo_b = poc_bin; area_v = vbp.get(poc_bin, 0.0)
    while area_v < target:
        up = vbp.get(hi_b + 1, 0.0); dn = vbp.get(lo_b - 1, 0.0)
        if up >= dn and hi_b + 1 < bins: hi_b += 1; area_v += up
        elif lo_b - 1 >= 0:              lo_b -= 1; area_v += dn
        else: break
    return poc, price_min + hi_b * bin_size + bin_size, price_min + lo_b * bin_size

# ── 5. LIQUIDITY SWEEP ───────────────────────────────────────
def _smc_detect_lsweep(df, eq_tol=0.003, lookback=20):
    """
    Bullish sweep: Equal Lows → spike bawah EL → close balik di atas EL.
    Bearish sweep: Equal Highs → spike atas EH → close balik di bawah EH.
    """
    result = {'bullish_sweep': False, 'bearish_sweep': False, 'level': None}
    if len(df) < lookback + 2: return result
    lows_s  = df['Low'].iloc[-lookback - 1:-1].values
    highs_s = df['High'].iloc[-lookback - 1:-1].values
    last    = df.iloc[-1]
    for i in range(len(lows_s) - 1):
        for j in range(i + 1, len(lows_s)):
            li, lj = lows_s[i], lows_s[j]
            if li > 0 and abs(li - lj) / li < eq_tol:
                eq_low = min(li, lj)
                if float(last['Low']) < eq_low * 0.999 and float(last['Close']) > eq_low:
                    result['bullish_sweep'] = True; result['level'] = eq_low; break
        if result['bullish_sweep']: break
    for i in range(len(highs_s) - 1):
        for j in range(i + 1, len(highs_s)):
            hi, hj = highs_s[i], highs_s[j]
            if hi > 0 and abs(hi - hj) / hi < eq_tol:
                eq_high = max(hi, hj)
                if float(last['High']) > eq_high * 1.001 and float(last['Close']) < eq_high:
                    result['bearish_sweep'] = True; result['level'] = eq_high; break
        if result['bearish_sweep']: break
    return result

# ── UNIFIED SCORER ───────────────────────────────────────────
def _smc_score(df, rsi_val=None):
    """
    Hitung skor gabungan SMC/ICT.
    Return: (score: int, alasan: list[str], detail: dict)

    Scoring:
      FVG bullish aktif       → +3  (prioritas #1, win rate ~72%)
      Liquidity Sweep bullish → +3  (sinyal terkuat)
      Order Block retest      → +2  (win rate ~68%)
      CHoCH bullish reversal  → +2  (win rate ~65%)
      BOS bullish lanjut      → +1
      VP: harga < VAL         → +1  (mean-reversion setup)
    Max: +12 poin
    """
    score = 0; alasan = []
    detail = {'fvg': None, 'lsweep': None, 'ob': None, 'ms': None, 'vp': None}
    try:
        cur = float(df['Close'].iloc[-1])

        # FVG
        fvg_ok, fvg_d = _smc_fvg_signal(df)
        detail['fvg'] = fvg_d
        if fvg_ok and fvg_d:
            score += 3
            gap_pct = (fvg_d['top'] - fvg_d['bot']) / fvg_d['bot'] * 100
            alasan.append(f"🟪 FVG Bullish [{fvg_d['bot']:.0f}–{fvg_d['top']:.0f}] gap={gap_pct:.1f}%")

        # Liquidity Sweep
        sw = _smc_detect_lsweep(df)
        detail['lsweep'] = sw
        if sw['bullish_sweep']:
            score += 3
            alasan.append(f"💧 Liq.Sweep Bullish (stop hunt EL={sw['level']:.0f})")
        elif sw['bearish_sweep']:
            alasan.append(f"⚠️ Liq.Sweep Bearish EH={sw['level']:.0f}")

        # Order Block (hanya jika RSI tidak overbought)
        ob_ok, ob_d = _smc_ob_signal(df)
        detail['ob'] = ob_d
        rsi_ok = (rsi_val is None) or (rsi_val < 55)
        if ob_ok and ob_d and rsi_ok:
            score += 2
            alasan.append(f"🟧 OB retest [{ob_d['ob_low']:.0f}–{ob_d['ob_high']:.0f}]")

        # BOS / CHoCH
        ms = _smc_detect_ms(df)
        detail['ms'] = ms
        if ms['choch']:
            score += 2
            alasan.append("🟩 CHoCH Bullish Reversal (Higher Low)")
        elif ms['bos']:
            score += 1
            alasan.append("🟩 BOS Bullish (trend continuation)")

        # Volume Profile
        poc, vah, val = _smc_volume_profile(df)
        detail['vp'] = {'poc': poc, 'vah': vah, 'val': val}
        if val is not None and cur < val * 1.005:
            score += 1
            alasan.append(f"🟥 VP: harga < VAL={val:.0f} (mean-revert ke POC={poc:.0f})")

    except Exception:
        pass
    return score, alasan, detail

# ── COMMAND HANDLER: /smc KODE ───────────────────────────────
def _smc_build_chart(kode, df, detail, score, rsi_val):
    """
    Generate chart mplfinance + overlay SMC zones.
    Return: io.BytesIO buffer (PNG)
    """
    import matplotlib.patches as mpatches
    import matplotlib.lines  as mlines

    df_plot = df.tail(60).copy()
    n = len(df_plot)

    mc = mpf.make_marketcolors(
        up='#00CC55', down='#FF3333',
        edge='inherit', wick='inherit',
        volume={'up': '#00CC55', 'down': '#FF3333'}
    )
    style = mpf.make_mpf_style(
        marketcolors=mc,
        gridstyle=':',
        gridcolor='#2a2a3a',
        facecolor='#0d1117',
        figcolor='#0a0f1a',
        y_on_right=True,
        rc={'axes.labelcolor': '#94a3b8',
            'axes.edgecolor':  '#1e293b',
            'xtick.color':     '#64748b',
            'ytick.color':     '#94a3b8',
            'text.color':      '#e2e8f0'}
    )

    stars  = "⭐" * min(score // 2, 5)
    grade  = ("🔥 VERY STRONG" if score >= 9 else
              "✅ STRONG"      if score >= 6 else
              "📊 MODERATE"    if score >= 3 else
              "⚪ WEAK")
    cur    = float(df_plot['Close'].iloc[-1])
    title  = (f"{kode}  |  SMC Score +{score} {stars}  |  {grade}"
              f"  |  Harga {cur:,.0f}  |  RSI {rsi_val:.1f}")

    buf = io.BytesIO()
    fig, axes = mpf.plot(
        df_plot, type='candle', style=style,
        volume=True, panel_ratios=(4, 1),
        title=f"\n{title}",
        figsize=(12, 7),
        returnfig=True
    )
    ax = axes[0]  # price axis

    price_min = float(df_plot['Low'].min())
    price_max = float(df_plot['High'].max())
    price_range = price_max - price_min or 1

    def x_of(bar_idx_in_df_plot):
        """Convert bar index to matplotlib x coordinate."""
        return bar_idx_in_df_plot

    # ── FVG Zone (purple dashed rect) ──────────────────────────
    fvg = detail.get('fvg')
    if fvg:
        y_bot = fvg['bot']; y_top = fvg['top']
        # Hitung posisi x FVG berdasarkan idx bar saat FVG terbentuk
        _df_full_len = len(df)
        _tail_start  = _df_full_len - 60
        _fvg_plot_x  = max(0, fvg.get('idx', 0) - _tail_start)
        rect = mpatches.FancyBboxPatch(
            (_fvg_plot_x, y_bot), n - _fvg_plot_x, y_top - y_bot,
            boxstyle="square,pad=0",
            linewidth=1.5, linestyle='--',
            edgecolor='#8B5CF6', facecolor='#8B5CF6', alpha=0.12
        )
        ax.add_patch(rect)
        ax.axhline(fvg['mid'], color='#8B5CF6', linewidth=0.8,
                   linestyle=':', alpha=0.7)
        ax.text(_fvg_plot_x + 0.5, fvg['top'] + price_range * 0.005,
                f"FVG [{fvg['bot']:.0f}–{fvg['top']:.0f}]",
                color='#8B5CF6', fontsize=7, fontweight='bold',
                bbox=dict(facecolor='#0d1117', edgecolor='#8B5CF6',
                          alpha=0.8, pad=1, linewidth=0.8))

    # ── Order Block Zone (orange dashed rect) ───────────────────
    ob = detail.get('ob')
    if ob:
        ob_idx = ob.get('index', 0)
        # map to df_plot index
        df_full_len = len(df)
        tail_start  = df_full_len - 60
        plot_idx    = ob_idx - tail_start if ob_idx >= tail_start else 0
        plot_idx    = max(0, min(plot_idx, n - 1))
        rect_ob = mpatches.FancyBboxPatch(
            (plot_idx, ob['ob_low']), n - plot_idx,
            ob['ob_high'] - ob['ob_low'],
            boxstyle="square,pad=0",
            linewidth=1.5, linestyle='--',
            edgecolor='#F59E0B', facecolor='#F59E0B', alpha=0.12
        )
        ax.add_patch(rect_ob)
        ax.text(plot_idx + 0.5, ob['ob_high'] + price_range * 0.005,
                f"OB [{ob['ob_low']:.0f}–{ob['ob_high']:.0f}]",
                color='#F59E0B', fontsize=7, fontweight='bold',
                bbox=dict(facecolor='#0d1117', edgecolor='#F59E0B',
                          alpha=0.8, pad=1, linewidth=0.8))

    # ── Volume Profile POC/VAH/VAL lines ───────────────────────
    vp = detail.get('vp', {}) or {}
    poc = vp.get('poc'); vah = vp.get('vah'); val_v = vp.get('val')
    if poc:
        ax.axhline(poc,   color='#EF4444', linewidth=1.2,
                   linestyle='--', alpha=0.9, label=f'POC {poc:.0f}')
        ax.text(n - 1, poc + price_range * 0.003,
                f"POC {poc:.0f}", color='#EF4444',
                fontsize=7, ha='right', fontweight='bold')
    if vah:
        ax.axhline(vah,   color='#F87171', linewidth=0.7,
                   linestyle=':', alpha=0.6)
        ax.text(n - 1, vah + price_range * 0.003,
                f"VAH {vah:.0f}", color='#F87171', fontsize=6, ha='right')
    if val_v:
        ax.axhline(val_v, color='#F87171', linewidth=0.7,
                   linestyle=':', alpha=0.6)
        ax.text(n - 1, val_v - price_range * 0.008,
                f"VAL {val_v:.0f}", color='#F87171', fontsize=6, ha='right')

    # ── Liquidity Sweep marker (cyan arrow) ─────────────────────
    sw = detail.get('lsweep', {}) or {}
    if sw.get('bullish_sweep') and sw.get('level'):
        lvl = sw['level']
        # Annotate last bar
        ax.annotate(
            f"💧 SWEEP\n{lvl:.0f}",
            xy=(n - 1, float(df_plot['Low'].iloc[-1])),
            xytext=(n - 4, lvl - price_range * 0.05),
            arrowprops=dict(arrowstyle='->', color='#06B6D4', lw=1.5),
            color='#06B6D4', fontsize=7, fontweight='bold',
            bbox=dict(facecolor='#0d1117', edgecolor='#06B6D4',
                      alpha=0.85, pad=2, linewidth=0.8)
        )
    elif sw.get('bearish_sweep') and sw.get('level'):
        lvl = sw['level']
        ax.annotate(
            f"⚠️ SWEEP\n{lvl:.0f}",
            xy=(n - 1, float(df_plot['High'].iloc[-1])),
            xytext=(n - 4, lvl + price_range * 0.04),
            arrowprops=dict(arrowstyle='->', color='#F97316', lw=1.5),
            color='#F97316', fontsize=7, fontweight='bold',
            bbox=dict(facecolor='#0d1117', edgecolor='#F97316',
                      alpha=0.85, pad=2, linewidth=0.8)
        )

    # ── BOS / CHoCH marker ──────────────────────────────────────
    ms = detail.get('ms', {}) or {}
    if ms.get('choch'):
        ax.text(n // 2, price_max - price_range * 0.04,
                "▲ CHoCH Bullish Reversal",
                color='#10B981', fontsize=7, fontweight='bold',
                bbox=dict(facecolor='#0d1117', edgecolor='#10B981',
                          alpha=0.8, pad=2, linewidth=0.8))
    elif ms.get('bos'):
        ax.text(n // 2, price_max - price_range * 0.04,
                "▲ BOS Bullish",
                color='#10B981', fontsize=7,
                bbox=dict(facecolor='#0d1117', edgecolor='#10B981',
                          alpha=0.6, pad=1, linewidth=0.7))

    fig.savefig(buf, dpi=90, bbox_inches='tight',
                facecolor='#0a0f1a', edgecolor='none')
    plt.close(fig)
    buf.seek(0)
    return buf


def _smc_build_keyboard(kode, detail, score):
    """
    Buat inline keyboard untuk /smc.
    Row 1: 5 signal buttons (status icon langsung)
    Row 2: Refresh | Rencana
    """
    fvg = detail.get('fvg')
    sw  = detail.get('lsweep', {}) or {}
    ob  = detail.get('ob')
    ms  = detail.get('ms', {}) or {}
    vp  = detail.get('vp', {}) or {}
    cur_close = None  # tidak tersedia di sini, VP cukup POC

    def sig(ok): return "✅" if ok else "❌"

    fvg_ok   = bool(fvg)
    sw_ok    = sw.get('bullish_sweep', False)
    sw_warn  = sw.get('bearish_sweep', False)
    ob_ok    = bool(ob)
    ms_ok    = ms.get('choch', False) or ms.get('bos', False)
    vp_poc   = vp.get('poc')

    keyboard = {
        "inline_keyboard": [
            [
                {"text": f"FVG {sig(fvg_ok)}",
                 "callback_data": f"smc_d|{kode}|fvg"},
                {"text": f"Sweep {'✅' if sw_ok else ('⚠️' if sw_warn else '❌')}",
                 "callback_data": f"smc_d|{kode}|lsweep"},
                {"text": f"OB {sig(ob_ok)}",
                 "callback_data": f"smc_d|{kode}|ob"},
                {"text": f"BOS {sig(ms_ok)}",
                 "callback_data": f"smc_d|{kode}|ms"},
                {"text": f"VP {'='+str(int(vp_poc)) if vp_poc else '❌'}",
                 "callback_data": f"smc_d|{kode}|vp"},
            ],
            [
                {"text": "🔄 Refresh",
                 "callback_data": f"smc_d|{kode}|refresh"},
                {"text": f"📈 Rencana {kode}",
                 "callback_data": f"smc_d|{kode}|rencana"},
            ],
        ]
    }
    return json.dumps(keyboard)


def _smc_detail_text(signal, kode, detail, rsi_val, score):
    """Teks detail untuk tap tombol sinyal."""
    fvg = detail.get('fvg')
    sw  = detail.get('lsweep', {}) or {}
    ob  = detail.get('ob')
    ms  = detail.get('ms', {}) or {}
    vp  = detail.get('vp', {}) or {}

    if signal == 'fvg':
        if fvg:
            return (f"🟪 *Fair Value Gap — {kode}*\n\n"
                    f"Zona: `{fvg['bot']:.0f} – {fvg['top']:.0f}`\n"
                    f"Mid (50% fill): `{fvg['mid']:.0f}`\n"
                    f"Status: *AKTIF* (belum terisi)\n\n"
                    f"Entry: harga pullback ke zona FVG\n"
                    f"Konfirmasi: volume turun saat pullback\n"
                    f"Win Rate IDX: *~72%*")
        return f"🟪 *FVG — {kode}*\n\nTidak ada FVG aktif saat ini."

    elif signal == 'lsweep':
        if sw.get('bullish_sweep'):
            return (f"💧 *Liquidity Sweep — {kode}*\n\n"
                    f"Type: *BULLISH* (Stop Hunt)\n"
                    f"Equal Low yang di-sweep: `{sw['level']:.0f}`\n\n"
                    f"Sinyal: harga spike bawah EL lalu balik ✅\n"
                    f"Entry: close kembali di atas EL\n"
                    f"Win Rate IDX: *~63%*")
        elif sw.get('bearish_sweep'):
            return (f"💧 *Liquidity Sweep — {kode}*\n\n"
                    f"Type: *BEARISH* ⚠️\n"
                    f"Equal High yang di-sweep: `{sw['level']:.0f}`\n\n"
                    f"Warning: kemungkinan distribusi bandar!")
        return f"💧 *Liq.Sweep — {kode}*\n\nTidak terdeteksi dalam 20 bar terakhir."

    elif signal == 'ob':
        if ob:
            return (f"🟧 *Order Block — {kode}*\n\n"
                    f"Zona OB: `{ob['ob_low']:.0f} – {ob['ob_high']:.0f}`\n"
                    f"Status: *RETEST AKTIF* ✅\n\n"
                    f"Entry: harga di dalam zona OB\n"
                    f"Filter: RSI < 55 ({rsi_val:.1f})\n"
                    f"Win Rate IDX: *~68%*")
        return f"🟧 *Order Block — {kode}*\n\nTidak ada OB dalam zona retest."

    elif signal == 'ms':
        if ms.get('choch'):
            return (f"🟩 *CHoCH — {kode}*\n\n"
                    f"Type: *Bullish Reversal* ✅\n\n"
                    f"Higher Low terbentuk setelah serangkaian Lower Lows.\n"
                    f"IDX: early entry swing 1-5 hari\n"
                    f"Win Rate IDX: *~65%*")
        elif ms.get('bos'):
            return (f"🟩 *BOS — {kode}*\n\n"
                    f"Type: *Bullish Continuation*\n\n"
                    f"Close menembus Swing High terakhir.\n"
                    f"IDX: momentum trade / trend lanjut")
        return f"🟩 *BOS/CHoCH — {kode}*\n\nStruktur pasar tidak terkonfirmasi."

    elif signal == 'vp':
        poc = vp.get('poc'); vah = vp.get('vah'); val = vp.get('val')
        if poc:
            return (f"🟥 *Volume Profile — {kode}*\n\n"
                    f"POC (Point of Control): `{poc:.0f}`\n"
                    f"VAH (Value Area High):  `{vah:.0f}`\n"
                    f"VAL (Value Area Low):   `{val:.0f}`\n\n"
                    f"POC = level bandar paling aktif transaksi.\n"
                    f"Harga jauh dari POC → mean-reversion entry.\n"
                    f"Win Rate IDX: *~70%*")
        return f"🟥 *Vol Profile — {kode}*\n\nData tidak cukup untuk kalkulasi."

    return f"📡 *SMC — {kode}*\nSMC Score: *+{score}*"


def _smc_send_photo_with_kb(kode, df, rsi_val, score, alasan, detail, dest):
    """Kirim chart + inline keyboard ke dest."""
    import json as _json_smc

    # 1. Buat chart
    buf = _smc_build_chart(kode, df, detail, score, rsi_val)

    # 2. Caption ringkas
    stars = "⭐" * min(score // 2, 5)
    grade = ("🔥 VERY STRONG" if score >= 9 else
             "✅ STRONG"      if score >= 6 else
             "📊 MODERATE"    if score >= 3 else
             "⚪ WEAK")
    caption_lines = [
        f"📡 *SMC/ICT — {kode}*  |  Score *+{score}* {stars}",
        f"Verdict: *{grade}*  |  RSI: {rsi_val:.1f}",
        "━━━━━━━━━━━━━━━━━",
    ]
    if alasan:
        for a in alasan:
            caption_lines.append(f"  {a}")
    else:
        caption_lines.append("❌ Tidak ada sinyal SMC aktif")
    caption_lines.append("\n_Tap tombol di bawah untuk detail tiap sinyal_")
    caption = "\n".join(caption_lines)

    # 3. Keyboard
    kb_json = _smc_build_keyboard(kode, detail, score)

    # 4. Kirim foto dengan reply_markup
    tok = BOT_TOKEN
    if dest.get("type") == "dm":
        cid = dest["user_id"]; tid = None
    else:
        cid = CHAT_ID; tid = dest.get("thread_id")

    url = f"https://api.telegram.org/bot{tok}/sendPhoto"
    data_send = {
        "chat_id": cid,
        "caption": caption[:1024],
        "parse_mode": "Markdown",
        "reply_markup": kb_json,
    }
    if tid:
        data_send["message_thread_id"] = tid
    buf.seek(0)
    try:
        r = _http.post(url,
            files={"photo": ("smc_chart.png", buf, "image/png")},
            data=data_send, timeout=60)
        resp = r.json()
        if resp.get("ok"):
            db_catat_msg(resp["result"]["message_id"], "radar")
    except Exception as e:
        logger.error("_smc_send_photo_with_kb: %s", e)
        dest_kirim_teks(dest, caption)


def cmd_smc_analysis(kode, dest):
    """Analisa 5 sinyal SMC/ICT — chart annotated + inline keyboard."""
    try:
        ticker = kode + ".JK"
        dest_kirim_teks(dest, f"⏳ Generating SMC chart *{kode}*...")
        result = get_candles_tf(ticker, "1d", "1y")
        if result is None:
            dest_kirim_teks(dest, f"❌ Data tidak tersedia: *{kode}*"); return
        df, harga, prev = result
        if df is None or len(df) < 30:
            dest_kirim_teks(dest, f"❌ Data {kode} kurang dari 30 bar"); return
        rsi_val = float(hitung_rsi_wilder(df["Close"]).iloc[-1])
        score, alasan, detail = _smc_score(df, rsi_val)
        _smc_send_photo_with_kb(kode, df, rsi_val, score, alasan, detail, dest)
    except Exception as e:
        logger.error("cmd_smc_analysis %s: %s", kode, e)
        dest_kirim_teks(dest, f"⚠️ Error /smc {kode}: {e}")


def cmd_rencana(user_id, args, dest):
    """
    /rencana KODE [period]
    Sniper Chart TradingView-style — MERGED v3:
    - Candlestick dark (#131722)
    - EMA Ribbon 9/21/50/200 + fill
    - VWAP + Bollinger Bands
    - Long A (teal) · Long B (hijau) · Short A (merah) · Short B (oranye)
    - HOOK label (amber, terpisah) · DC label (merah gelap)
    - BUY / SELL label besar mirip TradingView
    - TP1-TP5 horizontal lines + SL + Entry
    - OS Bounce advisory (💊)
    - Volume + RSI(14) + MACD subplot
    - Score Panel 0-10 + ADX + HTF + VWAP + Status
    """
    if not args:
        dest_kirim_teks(dest,
            "📊 *Format:* `/rencana KODE [period] [budget]`\n"
            "Contoh:\n"
            "  `/rencana BBCA` — 6 bulan\n"
            "  `/rencana ESSA 1y` — 1 tahun\n"
            "  `/rencana KUAS 6mo 500k` — chart + kalkulasi lot & PnL modal 500k\n"
            "  `/rencana GSMF 1y 1jt` — chart + kalkulasi modal 1 juta\n"
            "Period: `3mo` `6mo` `1y` `2y` `5y`\n"
            "Budget: `500k` `1jt` `2jt` dll (opsional → tampil lot calc)\n\n"
            "📈 Output: Sniper Chart + Budget Lot Calculator\n"
            "🟢 Long A = GC+ADX+HTF+VWAP (Grade A BUY)\n"
            "🟩 Long B = Hammer/Hook (Grade B BUY)\n"
            "🪝 HOOK = EMA9 curl advisory\n"
            "🔴 Short A = Death Cross (DC)\n"
            "🟠 Short B = Support Break\n"
            "📐 TP1-TP5 + SL + Entry otomatis\n"
            "💰 Budget = kalkulasi lot + PnL net setelah komisi")
        return

    kode   = args[0].upper().replace(".JK", "")

    # v4-12: parse budget opsional — /rencana KODE [period] [budget]
    # Contoh: /rencana KUAS 6mo 500k  atau  /rencana GSMF 1y 1jt
    _budget_rencana = None
    _remaining_args = args[1:]
    _period_choices = {"1mo","3mo","6mo","1y","2y","5y","max"}
    period = "6mo"
    for _a in _remaining_args:
        _al = _a.lower().replace(",","")
        if _a in _period_choices:
            period = _a
        elif _al.endswith("jt") or _al.endswith("m"):
            try: _budget_rencana = float(_al.rstrip("jt").rstrip("m")) * 1_000_000
            except: pass
        elif _al.endswith("k"):
            try: _budget_rencana = float(_al[:-1]) * 1_000
            except: pass
        elif _al.isdigit() and len(_al) >= 5:
            try: _budget_rencana = float(_al)
            except: pass

    ticker = kode + ".JK"
    _budget_info = f" · Budget Rp{int(_budget_rencana):,}" if _budget_rencana else ""
    dest_kirim_teks(dest, f"📊 _Membuat Sniper Chart *{kode}* ({period}){_budget_info}..._")

    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        import matplotlib.gridspec as gridspec
        import matplotlib.patches as mpatches
        import numpy as np
        import io, warnings
        warnings.filterwarnings("ignore")

        df = _fetch_ohlcv_robust(ticker, period)
        if df is None or len(df) < 50:
            got = len(df) if df is not None else 0
            dest_kirim_teks(dest,
                f"❌ Data *{kode}* gagal ({got} baris).\n"
                f"Coba: `/rencana {kode} 1y`")
            return

        # ── OHLCV ─────────────────────────────────────────────────────
        close  = df["Close"].astype(float)
        open_  = df["Open"].astype(float)
        high   = df["High"].astype(float)
        low    = df["Low"].astype(float)
        volume = df["Volume"].astype(float)
        n      = len(df)

        # ── EMA Ribbon ────────────────────────────────────────────────
        ema9   = close.ewm(span=9,   adjust=False).mean()
        ema21  = close.ewm(span=21,  adjust=False).mean()
        ema50  = close.ewm(span=50,  adjust=False).mean()
        ema200 = close.ewm(span=200, adjust=False).mean()

        # ── Bollinger Bands ───────────────────────────────────────────
        bb_mid   = close.rolling(20).mean()
        bb_std   = close.rolling(20).std()
        bb_upper = bb_mid + 2*bb_std
        bb_lower = bb_mid - 2*bb_std

        # ── VWAP ──────────────────────────────────────────────────────
        typical  = (high + low + close) / 3
        vwap     = (typical * volume).cumsum() / volume.cumsum().replace(0, np.nan)

        # ── RSI(14) ───────────────────────────────────────────────────
        delta = close.diff()
        gain  = delta.clip(lower=0).rolling(14).mean()
        loss  = (-delta.clip(upper=0)).rolling(14).mean()
        rsi   = 100 - (100 / (1 + gain / loss.replace(0, np.nan)))

        # ── MACD(12,26,9) ─────────────────────────────────────────────
        ema12     = close.ewm(span=12, adjust=False).mean()
        ema26     = close.ewm(span=26, adjust=False).mean()
        macd_line = ema12 - ema26
        macd_sig  = macd_line.ewm(span=9, adjust=False).mean()
        macd_hist = macd_line - macd_sig

        # ── ATR(14) ───────────────────────────────────────────────────
        _tr1 = high - low
        _tr2 = (high - close.shift(1)).abs()
        _tr3 = (low  - close.shift(1)).abs()
        _true_range = pd.concat([_tr1, _tr2, _tr3], axis=1).max(axis=1)
        atr14 = _true_range.rolling(14).mean().replace(0, np.nan)

        # ── ADX(14) ───────────────────────────────────────────────────
        _atr14 = atr14.copy()
        _dm_pos = (high - high.shift(1)).clip(lower=0)
        _dm_neg = (low.shift(1) - low).clip(lower=0)
        _dm_pos = _dm_pos.where(_dm_pos > _dm_neg, 0)
        _dm_neg = _dm_neg.where(_dm_neg > _dm_pos, 0)
        _di_pos = 100 * _dm_pos.rolling(14).mean() / _atr14
        _di_neg = 100 * _dm_neg.rolling(14).mean() / _atr14
        _dx = (_di_pos - _di_neg).abs() / (_di_pos + _di_neg).replace(0, np.nan) * 100
        adx = _dx.rolling(14).mean()
        adx_trending = adx > 25  # v4-15: 20 → 25 (TV-aligned gate, filter sideways)

        # ── Candle body/wick ──────────────────────────────────────────
        body    = (close - open_).abs()
        crange  = (high - low).replace(0, np.nan)
        lo_wick = close.where(close < open_, open_) - low
        up_wick = high - close.where(close > open_, open_)

        vol_ma20 = volume.rolling(20).mean().replace(0, np.nan)

        # ── HTF Bias & VWAP Position ──────────────────────────────────
        htf_bull = ema50 > ema200
        htf_bear = ema50 < ema200
        price_above_vwap = close > vwap

        not_extended   = close < ema21 * 1.35
        not_overbought = rsi < 65

        # ════════════════════════════════════════════════════════════
        #  SIGNAL LOGIC — Merged & Enhanced (akurasi maksimum)
        # ════════════════════════════════════════════════════════════

        # ── LONG A (Grade A BUY) — Highest confidence ────────────────
        # Golden Cross + ADX trending + HTF Bull + Price above VWAP
        # + volume surge + not overbought/extended
        long_a = (
            (ema9 > ema21) & (ema9.shift(1) <= ema21.shift(1)) &  # GC terjadi
            htf_bull &                                              # EMA50 > EMA200
            adx_trending &                                          # ADX > 20 (ada trend)
            price_above_vwap &                                      # harga di atas VWAP
            not_overbought &                                        # RSI < 65
            not_extended &                                          # tidak terlalu jauh dari EMA21
            (volume > vol_ma20)                                     # volume di atas rata-rata
        )

        # ── HOOK Detection ────────────────────────────────────────────
        # EMA9 turun 1 bar lalu, sekarang mulai naik = hook/curl
        # FIX v4-5: kembali ke 1-bar (sensitif utk saham choppy)
        # + konfirmasi RSI slope naik agar tidak trigger saat momentum masih negatif
        _ema9_was_fall = ema9.shift(2) > ema9.shift(1)
        _ema9_now_rise = ema9 > ema9.shift(1)
        _hook = (
            _ema9_was_fall & _ema9_now_rise &
            (close > ema9) &
            (rsi < 60) &                       # bukan overbought
            (rsi > rsi.shift(1)) &             # FIX v4-5: RSI harus naik = momentum confirm
            (volume > vol_ma20 * 0.9)          # volume minimal 90% normal
        )

        # ── LONG B (Grade B BUY) — Hammer/Pinbar atau Hook ───────────
        _hammer = (
            (body/crange < 0.4) &         # body kecil
            (lo_wick >= body * 2) &       # ekor bawah panjang (pinbar)
            (close > ema21) &             # harga di atas EMA21
            not_overbought &
            not_extended
        )
        long_b = (_hammer | _hook) & ~long_a

        # ── HOOK ADVISORY (tampil terpisah dari Long B) ───────────────
        # Tampil di setiap bar _hook yang tidak sudah menjadi Long A
        # (termasuk bar Long B — supaya Hook advisory selalu visible)
        # BUG FIX: sebelumnya _hook & ~long_b selalu kosong karena
        # long_b = (_hammer|_hook) & ~long_a → _hook sudah termasuk long_b
        hook_advisory = _hook & ~long_a  # hook advisory: semua hook kecuali Long A

        # ── HOOK SELL: EMA9 curl DOWN = exit signal ───────────────────
        # Kebalikan hook buy: EMA9 tadinya naik, sekarang mulai turun
        _ema9_was_rise2 = ema9.shift(2) < ema9.shift(1)
        _ema9_now_fall2 = ema9 < ema9.shift(1)
        _hook_sell = (
            _ema9_was_rise2 & _ema9_now_fall2 &
            (close < ema9) &                       # harga sudah di bawah EMA9
            (rsi < rsi.shift(1)) &                 # RSI turun = momentum bearish
            (volume > vol_ma20 * 0.8)              # volume cukup
        )

        # ── OS Bounce advisory (💊) ───────────────────────────────────
        ob_signal = (
            (rsi < 30) &
            (close <= bb_lower * 1.03) &
            (close >= open_) &                           # candle hijau
            (macd_hist > macd_hist.shift(1)) &           # MACD mulai naik
            (volume > vol_ma20 * 0.8)
        )

        # ── SHORT A (Grade A SELL) — Death Cross (DC) ─────────────────
        death_cross = (ema9 < ema21) & (ema9.shift(1) >= ema21.shift(1))
        short_a = death_cross & (htf_bear | adx_trending)

        # ── SHORT B (Grade B SELL) — Support Break EMA21 ──────────────
        # FIX v4-4: tambah konfirmasi RSI < 50 + volume agar tidak false break
        supp_break = (
            (close < ema21) & (close.shift(1) >= ema21.shift(1)) &
            (rsi < 50) &                  # momentum bearish dikonfirmasi RSI
            (volume > vol_ma20 * 0.8)     # ada tekanan jual nyata
        )
        short_b = supp_break & ~short_a

        # ── OVERBOUGHT SELL ───────────────────────────────────────────
        ob_sell = (
            (rsi > 75) &
            (close >= bb_upper * 0.98) &
            (close < open_) &                            # candle merah
            (macd_hist < macd_hist.shift(1))             # MACD mulai turun
        )

        # ════════════════════════════════════════════════════════════
        #  SCORE Panel (0-10) — kondisi candle terakhir
        # ════════════════════════════════════════════════════════════
        def _last(s):
            v = s.iloc[-1]
            return float(v) if not (isinstance(v, float) and np.isnan(v)) else 0.0

        _score_conds = [
            _last(ema9)      > _last(ema21),           # 1. EMA9 > EMA21
            _last(ema21)     > _last(ema50),           # 2. EMA21 > EMA50
            _last(ema50)     > _last(ema200),          # 3. HTF bullish
            _last(close)     > _last(vwap),            # 4. Price above VWAP
            _last(macd_hist) > 0,                      # 5. MACD hist +
            _last(macd_line) > _last(macd_sig),        # 6. MACD > Signal
            50 < _last(rsi) <= 75,                    # 7. RSI bullish (bukan OB: >75 = extended risk)
            _last(adx)       > 25,                     # 8. ADX trending (≥25 = real trend)
            _last(volume)    > _last(vol_ma20),        # 9. Vol > MA20
            _last(close)     > _last(close.shift(1)),  # 10. Candle bullish
        ]
        score_val = sum(_score_conds)

        # ── v4-15: MTF Conflict Penalty ───────────────────────────────────
        # HTF Bearish (EMA50 < EMA200) tapi score bullish ≥ 6 → konflik regime
        # Penalti -2 poin: hindari long saat macro downtrend
        _htf_bearish    = _last(ema50) < _last(ema200)
        _short_bullish  = _last(ema9)  > _last(ema21)
        _mtf_conflict   = _htf_bearish and _short_bullish
        if _mtf_conflict:
            score_val = max(0, score_val - 2)  # -2 poin penalty
        _mtf_conflict_lbl = " ⚠️MTF" if _mtf_conflict else ""

        adx_val      = _last(adx)
        atr_val      = _last(atr14)
        htf_bias_lbl = "Bullish" if _last(ema50) > _last(ema200) else "Bearish"
        trend_lbl    = "Bullish" if _last(ema9)  > _last(ema21)  else "Bearish"
        vol_status   = "High"   if _last(volume) > _last(vol_ma20)*1.5 else \
                       "Normal" if _last(volume) > _last(vol_ma20)*0.8 else "Low"
        vwap_pos     = "Above"  if _last(close)  > _last(vwap)   else "Below"
        rsi_val      = _last(rsi)
        status_lbl   = "No Trade" if adx_val < 15 else \
                       ("Active" if score_val >= 6 else "Wait")

        # ════════════════════════════════════════════════════════════
        #  TP / SL / ENTRY — Sniper-style dari sinyal Long A/B terakhir
        # ════════════════════════════════════════════════════════════
        entry_price = None
        entry_idx   = None
        _cur_close  = float(close.iloc[-1])
        # FIX v4-4: cari Long A/B terakhir maks 20 bar (bukan 60 — hindari entry stale)
        for i in range(n-1, max(n-20, 0)-1, -1):
            if bool(long_a.iloc[i]) or bool(long_b.iloc[i]):
                _cand = float(close.iloc[i])
                # Abaikan entry yang harganya >15% lebih tinggi dari current (stale peak)
                if _cand <= _cur_close * 1.15:
                    entry_price = _cand
                    entry_idx   = i
                break

        # Fallback: harga sekarang jika tidak ada sinyal valid dalam 20 bar
        if entry_price is None:
            entry_price = _cur_close
            entry_idx   = n - 1

        # SL = entry - 1.5×ATR (minimal -3%, maksimal -12%)
        atr_entry  = float(atr14.iloc[entry_idx]) if not np.isnan(float(atr14.iloc[entry_idx])) else entry_price * 0.05
        sl_price   = entry_price - 1.5 * atr_entry
        sl_price   = max(sl_price, entry_price * 0.85)  # maks -15%
        sl_price   = min(sl_price, entry_price * 0.95)  # min  -5%
        risk_unit  = entry_price - sl_price

        # TP1-TP5 R:R = 1:1, 1:2, 1:3, 1:4, 1:5
        tp_prices  = [entry_price + r * risk_unit for r in [1, 2, 3, 4, 5]]
        tp_labels  = ["TP1", "TP2", "TP3", "TP4", "TP5"]
        tp_colors  = ["#26a69a", "#43a047", "#fbc02d", "#f57c00", "#e53935"]

        # SL% dan TP1% untuk caption
        sl_pct     = round((1 - sl_price / entry_price) * 100, 1)
        tp1_pct    = round((tp_prices[0] / entry_price - 1) * 100, 1)

        # ════════════════════════════════════════════════════════════
        #  FIGURE SETUP
        # ════════════════════════════════════════════════════════════
        BG   = "#131722"; GRID = "#1e222d"
        C_UP = "#26a69a"; C_DN = "#ef5350"

        fig = plt.figure(figsize=(20, 15), facecolor=BG)
        gs  = gridspec.GridSpec(4, 1, height_ratios=[5.5, 1.5, 1.2, 1.2],
                                hspace=0.04, figure=fig)
        ax_price = fig.add_subplot(gs[0])
        ax_vol   = fig.add_subplot(gs[1], sharex=ax_price)
        ax_rsi   = fig.add_subplot(gs[2], sharex=ax_price)
        ax_macd  = fig.add_subplot(gs[3], sharex=ax_price)

        for ax in [ax_price, ax_vol, ax_rsi, ax_macd]:
            ax.set_facecolor(BG)
            ax.grid(True, color=GRID, linewidth=0.5, linestyle="--", alpha=0.8)
            ax.tick_params(colors="#787b86", labelsize=7)
            for sp in ax.spines.values(): sp.set_edgecolor(GRID)

        # ── Candlestick ───────────────────────────────────────────────
        x = np.arange(n)
        for i in range(n):
            c=float(close.iloc[i]); o=float(open_.iloc[i])
            h=float(high.iloc[i]);  l=float(low.iloc[i])
            color = C_UP if c >= o else C_DN
            ax_price.add_patch(plt.Rectangle((i-0.3,min(o,c)),0.6,max(abs(c-o),0.1),
                               color=color, zorder=3))
            ax_price.plot([i,i],[l,min(o,c)],  color=color, lw=0.8, zorder=2)
            ax_price.plot([i,i],[max(o,c),h],  color=color, lw=0.8, zorder=2)

        # ── EMA Ribbon ────────────────────────────────────────────────
        ax_price.plot(x, ema9.values,   color="#f6c35a", lw=1.0, zorder=4, label="EMA9")
        ax_price.plot(x, ema21.values,  color="#e65100", lw=1.3, zorder=4, label="EMA21")
        ax_price.plot(x, ema50.values,  color="#1565c0", lw=1.8, zorder=4, label="EMA50")
        ax_price.plot(x, ema200.values, color="#b71c1c", lw=2.2, zorder=4, label="EMA200")
        ax_price.fill_between(x, ema9.values, ema21.values,
            where=(ema9.values>ema21.values),  color=C_UP, alpha=0.18, interpolate=True, zorder=1)
        ax_price.fill_between(x, ema9.values, ema21.values,
            where=(ema9.values<=ema21.values), color=C_DN, alpha=0.18, interpolate=True, zorder=1)

        # ── Bollinger Bands ───────────────────────────────────────────
        ax_price.plot(x, bb_upper.values, color="#9c27b0", lw=0.7, ls="--", alpha=0.7)
        ax_price.plot(x, bb_lower.values, color="#9c27b0", lw=0.7, ls="--", alpha=0.7)
        ax_price.fill_between(x, bb_upper.values, bb_lower.values, color="#9c27b0", alpha=0.04)

        # ── VWAP ──────────────────────────────────────────────────────
        ax_price.plot(x, vwap.values, color="#e040fb", lw=1.2, label="VWAP")

        # ════════════════════════════════════════════════════════════
        #  TP/SL/ENTRY HORIZONTAL LINES (Sniper-style, kanan chart)
        # ════════════════════════════════════════════════════════════
        x_start = max(0, entry_idx - 5)   # mulai dari sekitar entry

        # SL line
        ax_price.axhline(sl_price, color="#ef5350", lw=1.0, ls="-", alpha=0.85, zorder=5)
        ax_price.text(n + 0.5, sl_price, f"SL  {int(sl_price):,}",
                      color="#ef5350", fontsize=7, va="center", fontfamily="monospace")

        # Entry line
        ax_price.axhline(entry_price, color="#2979ff", lw=1.2, ls="--", alpha=0.90, zorder=5)
        ax_price.text(n + 0.5, entry_price, f"ENTRY: {int(entry_price):,}",
                      color="#2979ff", fontsize=7.5, fontweight="bold", va="center",
                      fontfamily="monospace",
                      bbox=dict(boxstyle="round,pad=0.2", facecolor="#1a237e", alpha=0.7, edgecolor="none"))

        # TP1-TP5 lines
        for tp_p, tp_l, tp_c in zip(tp_prices, tp_labels, tp_colors):
            ax_price.axhline(tp_p, color=tp_c, lw=0.9, ls="-", alpha=0.80, zorder=5)
            tp_pct_i = round((tp_p / entry_price - 1) * 100, 0)
            ax_price.text(n + 0.5, tp_p, f"{tp_l}: {int(tp_p):,}",
                          color=tp_c, fontsize=7, va="center", fontfamily="monospace")

        # ════════════════════════════════════════════════════════════
        #  SIGNAL LABELS — State Machine (prioritized)
        # ════════════════════════════════════════════════════════════
        # Color palette
        _C_LONG_A  = "#26a69a"   # teal
        _C_LONG_B  = "#4caf50"   # green
        _C_HOOK    = "#ff8f00"   # amber
        _C_SHORT_A = "#ef5350"   # red
        _C_SHORT_B = "#ff7043"   # deep-orange
        _C_OS_B    = "#7b2ff7"   # purple (OS bounce)
        _C_BUY_BIG = "#1b5e20"   # dark green (BUY box)
        _C_SELL_BIG= "#b71c1c"   # dark red   (SELL box)

        bbox_la   = dict(boxstyle="round,pad=0.3",  facecolor=_C_LONG_A,  edgecolor="none", alpha=0.93)
        bbox_lb   = dict(boxstyle="round,pad=0.3",  facecolor=_C_LONG_B,  edgecolor="none", alpha=0.88)
        bbox_hook = dict(boxstyle="round,pad=0.28", facecolor=_C_HOOK,    edgecolor="none", alpha=0.90)
        bbox_sa   = dict(boxstyle="round,pad=0.3",  facecolor=_C_SHORT_A, edgecolor="none", alpha=0.93)
        bbox_sb   = dict(boxstyle="round,pad=0.3",  facecolor=_C_SHORT_B, edgecolor="none", alpha=0.88)
        bbox_os   = dict(boxstyle="round,pad=0.25", facecolor=_C_OS_B,    edgecolor="none", alpha=0.85)
        bbox_buy  = dict(boxstyle="round,pad=0.35", facecolor=C_UP,       edgecolor="none", alpha=0.92)
        bbox_sell = dict(boxstyle="round,pad=0.35", facecolor=C_DN,       edgecolor="none", alpha=0.92)
        bbox_dc   = dict(boxstyle="round,pad=0.25", facecolor="#880e4f",   edgecolor="none", alpha=0.88)
        bbox_ob_s = dict(boxstyle="round,pad=0.25", facecolor="#4a0000",   edgecolor="none", alpha=0.88)

        in_position   = False
        ob_sell_shown = set()   # FIX Bug 4: pisahkan tracking OB SELL
        os_shown      = set()   # FIX Bug 4: pisahkan tracking OS Bounce
        hook_shown    = set()
        dc_shown      = set()   # FIX Bug 3: track DC sudah tampil

        for i in range(n):
            is_la  = bool(long_a.iloc[i])
            is_lb  = bool(long_b.iloc[i])
            is_sa  = bool(short_a.iloc[i])
            is_sb  = bool(short_b.iloc[i])
            is_os  = bool(ob_signal.iloc[i])
            is_obs = bool(ob_sell.iloc[i])
            is_hk  = bool(_hook.iloc[i])
            is_hk_adv = bool(hook_advisory.iloc[i])
            is_hks = bool(_hook_sell.iloc[i])

            lo = float(low.iloc[i]);  hi = float(high.iloc[i])
            y_buy   = lo  * 0.948
            y_sell  = hi  * 1.052
            y_buy2  = lo  * 0.965   # sub-label grade (Long A/Long B)
            y_buy3  = lo  * 0.982   # hook advisory di bawah grade (FIX Bug 5: offset lebih)
            y_sell2 = hi  * 1.035
            y_dc    = hi  * 1.020   # DC label khusus (FIX Bug 3)

            # ── LONG A — primary BUY ─────────────────────────────────
            if is_la and not in_position:
                ax_price.text(i, y_buy, "BUY",
                    color="white", fontsize=9, fontweight="bold",
                    ha="center", va="top", bbox=bbox_buy, zorder=11)
                ax_price.text(i, y_buy2, "Long A",
                    color="white", fontsize=6, fontweight="bold",
                    ha="center", va="top", bbox=bbox_la, zorder=10)
                in_position = True

            # ── LONG B — secondary BUY (termasuk hook re-entry saat in_position) ─
            elif is_lb and not in_position:
                ax_price.text(i, y_buy, "BUY",
                    color="white", fontsize=9, fontweight="bold",
                    ha="center", va="top", bbox=bbox_buy, zorder=11)
                ax_price.text(i, y_buy2, "Long B",
                    color="white", fontsize=6, fontweight="bold",
                    ha="center", va="top", bbox=bbox_lb, zorder=10)
                if is_hk:
                    ax_price.text(i, y_buy3, "🪝Hook",
                        color="white", fontsize=5.5, fontweight="bold",
                        ha="center", va="top", bbox=bbox_hook, zorder=9)
                    hook_shown.add(i)
                in_position = True

            # ── HOOK RE-ENTRY BUY — aktif walaupun in_position (re-entry on dip)
            # v4-14: Hook BUY selalu tampil — matching screenshot TradingView
            elif is_hk and i not in hook_shown and (i-1) not in hook_shown:
                ax_price.text(i, y_buy, "BUY",
                    color="white", fontsize=8, fontweight="bold",
                    ha="center", va="top", bbox=bbox_buy, zorder=11)
                ax_price.text(i, y_buy3, "🪝Hook",
                    color="white", fontsize=5.5, fontweight="bold",
                    ha="center", va="top", bbox=bbox_hook, zorder=9)
                hook_shown.add(i)
                in_position = True

            # ── SHORT A — Death Cross SELL ────────────────────────────
            if is_sa and i not in dc_shown:
                y_sa = y_sell if in_position else hi * 1.038
                ax_price.text(i, y_sa, "SELL" if in_position else "⚠️SELL",
                    color="white", fontsize=9 if in_position else 7.5, fontweight="bold",
                    ha="center", va="bottom", bbox=bbox_sell, zorder=11)
                ax_price.text(i, y_sell2, "DC",
                    color="white", fontsize=6, fontweight="bold",
                    ha="center", va="bottom", bbox=bbox_dc, zorder=10)
                dc_shown.add(i)
                in_position = False

            # ── SHORT B — Support Break SELL ─────────────────────────
            elif is_sb and in_position and i not in dc_shown:
                ax_price.text(i, y_sell, "SELL",
                    color="white", fontsize=9, fontweight="bold",
                    ha="center", va="bottom", bbox=bbox_sell, zorder=11)
                ax_price.text(i, y_sell2, "Short B",
                    color="white", fontsize=6, fontweight="bold",
                    ha="center", va="bottom", bbox=bbox_sb, zorder=10)
                in_position = False

            # ── HOOK SELL — EMA9 curl DOWN: exit signal (v4-14 baru) ──
            # Tampil SELL ketika EMA9 mulai turun + price < EMA9 + RSI turun
            # Tidak butuh in_position — advisory keluar saja, tapi juga tutup posisi
            elif is_hks and in_position and i not in dc_shown \
                    and (i-1) not in ob_sell_shown:
                ax_price.text(i, y_sell, "SELL",
                    color="white", fontsize=8, fontweight="bold",
                    ha="center", va="bottom", bbox=bbox_sell, zorder=10)
                ax_price.text(i, y_sell2, "🪝Exit",
                    color="white", fontsize=5.5, fontweight="bold",
                    ha="center", va="bottom", bbox=bbox_hook, zorder=9)
                ob_sell_shown.add(i)
                in_position = False

            # ── OB SELL advisory — reset in_position (v4-14: tutup posisi) ──
            if is_obs and (i-1) not in ob_sell_shown and i not in ob_sell_shown:
                ax_price.text(i, hi * 1.025, "SELL",
                    color="white", fontsize=7.5, fontweight="bold",
                    ha="center", va="bottom", bbox=bbox_ob_s, zorder=9)
                ob_sell_shown.add(i)
                in_position = False   # v4-14: OB SELL menutup posisi

            # ── HOOK ADVISORY — tampil jika belum BUY/hook_shown ──────
            if is_hk_adv and i not in hook_shown and (i-1) not in hook_shown:
                ax_price.text(i, lo * 0.960, "🪝Hook",
                    color="white", fontsize=5.5, fontweight="bold",
                    ha="center", va="top", bbox=bbox_hook, zorder=8)
                hook_shown.add(i)

            # ── OS Bounce advisory ────────────────────────────────────
            if is_os and i not in os_shown and (i-1) not in os_shown:
                ax_price.text(i, lo * 0.945, "💊OS",
                    color="white", fontsize=5.5, fontweight="bold",
                    ha="center", va="top", bbox=bbox_os, zorder=8)
                os_shown.add(i)

        # ════════════════════════════════════════════════════════════
        #  INFO PANEL (top-right, TradingView-style)
        # ════════════════════════════════════════════════════════════
        _score_color = "#26a69a" if score_val >= 7 else \
                       "#f59e0b" if score_val >= 4 else "#ef5350"
        _htf_color   = "#26a69a" if htf_bias_lbl == "Bullish" else "#ef5350"
        _trend_color = "#26a69a" if trend_lbl    == "Bullish" else "#ef5350"
        _stat_color  = "#26a69a" if status_lbl   == "Active"  else \
                       "#f59e0b" if status_lbl   == "Wait"    else "#787b86"
        _rsi_icon    = "🔴OB" if rsi_val > 70 else ("🟢OS" if rsi_val < 30 else "⚪")

        info_txt = (
            f"Score  : {score_val}/10\n"
            f"Trend  : {trend_lbl}\n"
            f"HTF    : {htf_bias_lbl}{_mtf_conflict_lbl}\n"
            f"ADX    : {adx_val:.1f}\n"
            f"RSI    : {rsi_val:.1f} {_rsi_icon}\n"
            f"VWAP   : {vwap_pos}\n"
            f"Vol    : {vol_status}\n"
            f"ATR14  : {atr_val:.1f}\n"
            f"Status : {status_lbl}"
        )
        ax_price.text(0.996, 0.985, info_txt,
            transform=ax_price.transAxes,
            color="#d1d4dc", fontsize=7, va="top", ha="right",
            fontfamily="monospace",
            bbox=dict(boxstyle="round,pad=0.45", facecolor="#1e222d",
                      edgecolor="#363a45", alpha=0.93),
            zorder=15)

        # ── Volume subplot ───────────────────────────────────────────
        vc = [C_UP if float(close.iloc[i])>=float(open_.iloc[i]) else C_DN for i in range(n)]
        ax_vol.bar(x, volume.values, color=vc, width=0.8, alpha=0.7)
        ax_vol.plot(x, volume.rolling(20).mean().values, color="#e65100", lw=0.8)
        ax_vol.set_ylabel("Vol", color="#787b86", fontsize=7)
        ax_vol.yaxis.set_major_formatter(
            plt.FuncFormatter(lambda v,_: f"{v/1e6:.1f}M" if v>=1e6 else f"{v/1e3:.0f}K"))

        # ── RSI subplot ──────────────────────────────────────────────
        rv = rsi.values
        ax_rsi.plot(x, rv, color="#ce93d8", lw=1.0)
        ax_rsi.axhline(70, color=C_DN, lw=0.7, ls="--", alpha=0.8)
        ax_rsi.axhline(30, color=C_UP, lw=0.7, ls="--", alpha=0.8)
        ax_rsi.axhline(50, color="#787b86", lw=0.5, ls=":", alpha=0.5)
        ax_rsi.fill_between(x, rv, 70, where=(rv>=70), color=C_DN, alpha=0.2, interpolate=True)
        ax_rsi.fill_between(x, rv, 30, where=(rv<=30), color=C_UP, alpha=0.2, interpolate=True)
        ax_rsi.set_ylim(0,100)
        ax_rsi.set_ylabel("RSI(14)", color="#787b86", fontsize=7)
        cur_rsi = float(rsi.iloc[-1]) if not np.isnan(float(rsi.iloc[-1])) else 0
        ax_rsi.text(n-1, cur_rsi, f" {cur_rsi:.0f}", color="#ce93d8", fontsize=7, va="center")

        # ── MACD subplot ─────────────────────────────────────────────
        hv = macd_hist.values; lv = macd_line.values; sv = macd_sig.values
        hc = [C_UP if v>=0 else C_DN for v in np.nan_to_num(hv)]
        ax_macd.bar(x, hv, color=hc, width=0.8, alpha=0.8)
        ax_macd.plot(x, lv, color="#2962ff", lw=1.0, label="MACD")
        ax_macd.plot(x, sv, color="#ff6d00", lw=1.0, label="Signal")
        ax_macd.axhline(0, color="#787b86", lw=0.5)
        ax_macd.set_ylabel("MACD", color="#787b86", fontsize=7)
        ax_macd.legend(loc="upper left", fontsize=6, labelcolor="white",
                       facecolor=BG, framealpha=0.4)

        # ── Title & Axis ─────────────────────────────────────────────
        last   = float(close.iloc[-1])
        e9v    = float(ema9.iloc[-1]); e21v = float(ema21.iloc[-1])
        e50v   = float(ema50.iloc[-1]); e200v= float(ema200.iloc[-1])
        gain_1d= round((last/float(close.iloc[-2])-1)*100,2) if n>=2 else 0
        macd_v = float(macd_hist.iloc[-1]) if not np.isnan(float(macd_hist.iloc[-1])) else 0
        ribbon_ok  = e9v>e21v>e50v>e200v and last>e9v
        ribbon_red = e9v<e21v<e50v<e200v and last<e9v
        ribbon_lbl = ("🟢 RIBBON GREEN" if ribbon_ok else
                      "🔴 RIBBON RED"   if ribbon_red else
                      "🟡 Transisi")

        ax_price.legend(loc="upper left", fontsize=7, labelcolor="white",
                        facecolor=BG, framealpha=0.35, ncol=4)
        ax_price.set_title(
            f"{kode}  ·  {period.upper()}  ·  Rp{int(last):,}  ({gain_1d:+.2f}%)  ·  "
            f"RSI:{cur_rsi:.0f}  ·  MACD:{macd_v:+.2f}  ·  {ribbon_lbl}",
            color="#d1d4dc", fontsize=9, pad=6, loc="left")

        plt.setp(ax_price.get_xticklabels(), visible=False)
        plt.setp(ax_vol.get_xticklabels(),   visible=False)
        plt.setp(ax_rsi.get_xticklabels(),   visible=False)
        step = max(1, n//12)
        ax_macd.set_xticks(x[::step])
        try:    labels=[str(df.index[i])[:10] for i in range(0,n,step)]
        except: labels=[str(i) for i in range(0,n,step)]
        ax_macd.set_xticklabels(labels, rotation=30, ha="right", fontsize=6, color="#787b86")

        pad = (float(high.max())-float(low.min()))*0.08
        # Extend x-axis kanan untuk label TP/SL
        ax_price.set_ylim(
            min(float(low.min())-pad, sl_price - pad*0.5),
            max(float(high.max())+pad*3.0, tp_prices[-1] + pad*0.5)
        )
        ax_price.set_xlim(-1, n + 14)   # ruang untuk label TP/SL di kanan
        fig.patch.set_facecolor(BG)
        plt.subplots_adjust(left=0.07, right=0.88, top=0.94, bottom=0.07, hspace=0.04)

        buf = io.BytesIO()
        fig.savefig(buf, format="png", dpi=150, facecolor=BG,
                    edgecolor="none", bbox_inches="tight")
        buf.seek(0); plt.close(fig)

        # ════════════════════════════════════════════════════════════
        #  CAPTION
        # ════════════════════════════════════════════════════════════
        n_long_a  = int(long_a.sum())
        n_long_b  = int(long_b.sum())
        n_hook    = int(_hook.sum())
        n_short_a = int(short_a.sum())
        n_short_b = int(short_b.sum())

        # Signal sekarang (candle terakhir)
        cur_sig = ""
        if bool(long_a.iloc[-1]):  cur_sig = "🟢 *LONG A aktif!* (Grade A BUY)"
        elif bool(long_b.iloc[-1]): cur_sig = "🟩 *LONG B aktif!* (Grade B BUY)"
        elif bool(_hook.iloc[-1]): cur_sig = "🪝 *HOOK aktif!* (EMA9 curl)"
        elif bool(short_a.iloc[-1]): cur_sig = "🔴 *SHORT A aktif!* (Death Cross)"
        elif bool(short_b.iloc[-1]): cur_sig = "🟠 *SHORT B aktif!* (Support Break)"
        else: cur_sig = f"⏳ Sinyal: `{status_lbl}`"

        caption = (
            f"📊 *{kode}* — WillyAlgo Sniper Chart  [{period.upper()}]\n"
            f"━━━━━━━━━━\n"
            f"  Harga   : Rp`{int(last):,}`  `({gain_1d:+.2f}%)`\n"
            f"〰 EMA9:{int(e9v):,}  EMA21:{int(e21v):,}  EMA50:{int(e50v):,}\n"
            f"📉 RSI(14): `{cur_rsi:.1f}`  ADX: `{adx_val:.1f}` {'✅' if adx_val>25 else '⚠️'}\n"
            f"📈 MACD hist: `{macd_v:+.2f}`\n"
            f"━━━━━━━━━━\n"
            f"{ribbon_lbl}\n"
            f"📊 Momentum : `{score_val}/10`\n"
            f"{'⚠️ RSI ' + f'{cur_rsi:.0f}' + ' — *Overbought*, risiko koreksi tinggi!' + chr(10) if cur_rsi > 75 else ''}"
            f"📈 HTF   : `{htf_bias_lbl}`{_mtf_conflict_lbl}\n"
            f"  VWAP   : `{vwap_pos}`\n"
            f"🔊 Vol   : `{vol_status}`\n"
            f"━━━━━━━━━━\n"
            f"🎯 *Sniper Entry/Exit*\n"
            f"📌 Entry : Rp`{int(entry_price):,}`\n"
            f"🛑 SL    : Rp`{int(sl_price):,}` `(-{sl_pct}%)`\n"
            f"✅ TP1   : Rp`{int(tp_prices[0]):,}` `(+{tp1_pct}%)`\n"
            f"✅ TP2   : Rp`{int(tp_prices[1]):,}`\n"
            f"✅ TP3   : Rp`{int(tp_prices[2]):,}`\n"
            f"✅ TP4   : Rp`{int(tp_prices[3]):,}`\n"
            f"✅ TP5   : Rp`{int(tp_prices[4]):,}`\n"
            f"━━━━━━━━━━\n"
            f"🟢 *Long A* : `{n_long_a}×`  (GC+ADX+HTF+VWAP)\n"
            f"🟩 *Long B* : `{n_long_b}×`  (Hammer/Hook)\n"
            f"🪝 *Hook*   : `{n_hook}×`  (EMA9 curl advisory)\n"
            f"🔴 *Short A*: `{n_short_a}×`  (Death Cross)\n"
            f"🟠 *Short B*: `{n_short_b}×`  (Support Break)\n"
            f"━━━━━━━━━━\n"
            f"{cur_sig}\n"
            f"_Kuning=EMA9 · Oranye=EMA21 · Biru=EMA50 · Merah=EMA200_\n"
            f"_Ungu=BB(20,2) · Pink=VWAP · 💊=OS Bounce_"
        )
        dest_kirim_foto_buf(dest, buf, caption=caption)

        # ── v4-12: Budget Lot Calculator ─────────────────────────────────
        if _budget_rencana and _budget_rencana > 0:
            _harga_entry = int(entry_price)
            _modal_1lot  = _harga_entry * 100
            if _modal_1lot > _budget_rencana:
                _lot_msg = (
                    f"*◈ Kalkulasi Modal Rp{int(_budget_rencana):,} — {kode}*\n"
                    f"━━━━━━━━━━━━━━━━━━━━━━\n"
                    f"📌 Entry: Rp`{_harga_entry:,}` | 1 lot = Rp`{_modal_1lot:,}`\n"
                    f"🔴 *TIDAK BISA BELI* — budget kurang untuk 1 lot\n"
                    f"   Butuh minimal Rp`{_modal_1lot:,}`\n"
                    f"   Kekurangan: Rp`{int(_modal_1lot - _budget_rencana):,}`\n"
                    f"━━━━━━━━━━━━━━━━━━━━━━\n"
                    f"💡 Cari saham ≤ Rp`{int(_budget_rencana/100):,}`/lembar"
                )
            else:
                _lot_allIn  = int(_budget_rencana / _modal_1lot)
                _lot_15pct  = max(1, int(_budget_rencana * 0.15 / _modal_1lot))
                _lot_1risk  = max(1, int(_budget_rencana * 0.01 / max((entry_price - sl_price) * 100, 1)))
                _lot_pakai  = min(_lot_1risk, _lot_15pct)

                # Rupiah PnL per TP level
                def _rp_pnl(tp, entry, lot):
                    gross = (tp - entry) * lot * 100
                    buy_c = entry * lot * 100 * 0.0015
                    sel_c = tp    * lot * 100 * 0.0025
                    return gross - buy_c - sel_c

                _pnl_tp1 = _rp_pnl(tp_prices[0], entry_price, _lot_pakai)
                _pnl_tp2 = _rp_pnl(tp_prices[1], entry_price, _lot_pakai)
                _pnl_tp3 = _rp_pnl(tp_prices[2], entry_price, _lot_pakai)
                _pnl_sl  = (sl_price - entry_price) * _lot_pakai * 100 - entry_price * _lot_pakai * 100 * 0.0015 - sl_price * _lot_pakai * 100 * 0.0025
                _invested = _lot_pakai * _modal_1lot
                _komisi_rt = _invested * 0.004  # round-trip

                _lot_msg = (
                    f"💰 *Kalkulasi Modal Rp{int(_budget_rencana):,} — {kode}*\n"
                    f"━━━━━━━━━━━━━━━━━━━━━━\n"
                    f"📌 Entry       : Rp`{_harga_entry:,}` / lembar\n"
                    f"📦 1 lot       : Rp`{_modal_1lot:,}` (100 lembar)\n"
                    f"━━━━━━━━━━\n"
                    f"📊 *Lot Rekomendasi (1% risk):* `{_lot_pakai}` lot\n"
                    f"   Modal terpakai : Rp`{int(_invested):,}` "
                    f"(`{_invested/_budget_rencana*100:.0f}%` dari budget)\n"
                    f"   Sisa kas       : Rp`{int(_budget_rencana - _invested):,}`\n"
                    f"   Komisi RT est. : Rp`{int(_komisi_rt * _lot_pakai):,}`\n"
                    f"━━━━━━━━━━\n"
                    f"🎯 *PnL Net (setelah komisi):*\n"
                    f"✅ TP1 +{tp1_pct}% → `+Rp{int(_pnl_tp1):,}` "
                    f"(`{_pnl_tp1/_budget_rencana*100:+.1f}%` modal)\n"
                    f"✅ TP2          → `+Rp{int(_pnl_tp2):,}` "
                    f"(`{_pnl_tp2/_budget_rencana*100:+.1f}%` modal)\n"
                    f"✅ TP3          → `+Rp{int(_pnl_tp3):,}` "
                    f"(`{_pnl_tp3/_budget_rencana*100:+.1f}%` modal)\n"
                    f"🛑 SL -{sl_pct}% → `{int(_pnl_sl):,}` "
                    f"(`{_pnl_sl/_budget_rencana*100:.1f}%` modal)\n"
                    f"━━━━━━━━━━\n"
                    f"📦 All-in maks : `{_lot_allIn}` lot "
                    f"(Rp`{int(_lot_allIn*_modal_1lot):,}` — *TIDAK disarankan*)\n"
                    f"━━━━━━━━━━\n"
                    f"_✅ v4-12: Komisi 0.15%+0.25% sudah dihitung_\n"
                    f"_⚠️ Bukan saran investasi. Selalu pasang SL._"
                )
            dest_kirim_teks(dest, _lot_msg)

        logger.info("cmd_rencana OK: %s period=%s rows=%d score=%d", kode, period, n, score_val)

    except Exception as exc:
        logger.exception("cmd_rencana error %s: %s", kode, exc)
        dest_kirim_teks(dest, f"❌ Gagal chart *{kode}*: `{exc}`")



# ════════════════════════════════════════════════════════════
