def proses_addmember(user_id, args, dest):
    """Admin tambah/hapus/list member langsung tanpa /daftar."""
    if not is_admin(user_id): dest_kirim_teks(dest,"🔒 Khusus Admin."); return
    if not args:
        dest_kirim_teks(dest,"👥 *Admin: Kelola Member*\n`/addmember USER_ID Nama` — Tambah\n`/addmember list` — Lihat\n`/addmember del USER_ID` — Hapus"); return
    cmd=args[0].lower()
    if cmd=="list":
        members=db_load_members(); aktif={u:v for u,v in members.items() if v.get("status")=="active"}
        p=f"👥 *MEMBER ({len(members)})* — Aktif: {len(aktif)}\n━━━━━━━━━━━━━━━━━━━━━━\n"
        for i,(u,v) in enumerate(list(aktif.items())[:30],1): p+=f"{i}. {v.get('nama','?')} — `{u}`\n"
        if len(members)>30: p+=f"\n_...+{len(members)-30} lainnya_"
        dest_kirim_teks(dest,p); return
    if cmd=="del" and len(args)>=2:
        try: tid=str(int(args[1]))
        except: dest_kirim_teks(dest,"⚠️ Format: `/addmember del USER_ID`"); return
        members=db_load_members()
        if tid not in members: dest_kirim_teks(dest,f"⚠️ `{tid}` tidak ditemukan."); return
        nm=members[tid].get("nama","?"); db_save_member(tid,nm,status="removed")
        dest_kirim_teks(dest,f"🗑️ Member dihapus: {nm} (`{tid}`)"); return
    try: tid=str(int(args[0]))
    except:
        dest_kirim_teks(dest,"⚠️ Format: `/addmember USER_ID Nama Member`"); return
    nm=" ".join(args[1:]).strip() or f"Member-{tid}"
    members=db_load_members(); sudah=tid in members and members[tid].get("status")=="active"
    db_save_member(tid,nm,status="active")
    dest_kirim_teks(dest,
        f"{'ℹ️ Diperbarui' if sudah else '✅ Ditambahkan'}!\n👤 {nm}\n🆔 `{tid}`\n📊 Total: {len(members)+(0 if sudah else 1)} member")
    try: kirim_dm(int(tid),f"👋 *Selamat datang, {nm}!*\nKamu didaftarkan admin.\nKetik /menu untuk lihat fitur.")
    except: pass


def proses_notice(user_id, args, dest):
    """Admin broadcast ke semua member aktif via DM.
    Mendukung: /notice <teks>  atau  /notice dengan foto (caption = /notice <teks>)
    """
    if not is_admin(user_id): dest_kirim_teks(dest,"🔒 Khusus Admin."); return
    if not args:
        dest_kirim_teks(dest,
            "📢 `/notice Pesan` — Broadcast teks ke member\n"
            "📷 Kirim foto + caption `/notice Pesan` — Broadcast gambar\n"
            "`/notice count` — Hitung member aktif"); return
    if args[0].lower()=="count":
        m=db_load_members(); ak=[v for v in m.values() if v.get("status")=="active"]
        dest_kirim_teks(dest,f"👥 Aktif: {len(ak)} | Total: {len(m)}"); return

    msg_text = " ".join(args).strip()
    if not msg_text: dest_kirim_teks(dest,"⚠️ Pesan kosong."); return

    members=db_load_members(); ids=[u for u,v in members.items() if v.get("status")=="active"]
    if not ids: dest_kirim_teks(dest,"⚠️ Tidak ada member aktif."); return

    # Ambil photo_file_id dari _pending_notice_photo jika ada
    photo_fid = _NOTICE_PHOTO_PENDING.pop(str(user_id), None)

    now_str = now_wib().strftime("%d/%m/%Y %H:%M")
    # Pesan bersih: hanya konten + timestamp, tanpa header "PENGUMUMAN ADMIN"
    isi_teks = f"{msg_text}\n\n⏰ {now_str} WIB"

    dest_kirim_teks(dest, f"📤 Mengirim ke {len(ids)} member...\n_{msg_text[:80]}_")

    def _blast():
        ok = gagal = 0
        for u in ids:
            try:
                if photo_fid:
                    # Kirim foto + caption ke tiap member
                    url_p = f"https://api.telegram.org/bot{BOT_TOKEN}/sendPhoto"
                    _http.post(url_p, data={
                        "chat_id"   : int(u),
                        "photo"     : photo_fid,
                        "caption"   : isi_teks,
                        "parse_mode": "Markdown",
                    }, timeout=20)
                else:
                    kirim_dm(int(u), isi_teks)
                ok += 1
                time.sleep(0.3)
            except: gagal += 1
        dest_kirim_teks(dest, f"✅ Broadcast selesai!\n📤 {ok} terkirim | ❌ {gagal} gagal")

    _threading_scr.Thread(target=_blast, daemon=True).start()



def analisa_ihsg_ai(tgl_str, dest):
    """
    Analisa makro/mikro IHSG via Anthropic Claude API.
    tgl_str: format DD-MM-YYYY
    """
    import datetime, json as _json
    try:
        dt = datetime.datetime.strptime(tgl_str, "%d-%m-%Y")
        tgl_fmt   = dt.strftime("%d %B %Y")
        hari_name = ["Senin","Selasa","Rabu","Kamis","Jumat","Sabtu","Minggu"][dt.weekday()]
        is_weekend= dt.weekday() >= 5
    except:
        dest_kirim_teks(dest,
            "⚠️ Format tanggal salah.\n"
            "Contoh: `/news IHSG 10-03-2026`"); return

    if is_weekend:
        dest_kirim_teks(dest,
            f"📅 *{tgl_fmt} ({hari_name})*\n"
            "Bursa tutup hari Sabtu & Minggu."); return

    today    = now_wib()
    is_future= dt.date() > today.date()
    dest_kirim_teks(dest,
        f"🔍 Menganalisa *IHSG {tgl_fmt}* dengan AI...\n_Mohon tunggu ~10 detik_")

    konteks = (
        f"Tanggal yang diminta ({tgl_fmt}) adalah MASA DEPAN. Berikan outlook/prediksi."
        if is_future else
        f"Berikan analisa kondisi IHSG pada {tgl_fmt} berdasarkan data historis/terkini."
    )
    icon_lbl = "🔮" if is_future else "📅"

    prompt = f"""Kamu adalah analis saham senior Indonesia.

Buat analisa IHSG untuk: **{tgl_fmt} ({hari_name})**
{konteks}

Format respons dalam bahasa Indonesia, struktur PERSIS berikut:

**KONDISI MAKRO**
- [3-4 poin: inflasi, suku bunga BI, kurs USD/IDR, komoditas, kondisi global]

**KONDISI MIKRO**
- [3-4 poin: sektor dominan, rotasi, asing vs domestik, aksi korporasi]

**SENTIMEN PASAR**
- [Bullish/Bearish/Mixed] + penjelasan singkat

**LEVEL KUNCI IHSG**
- Support utama: [angka]
- Resistance utama: [angka]
- Target jangka pendek: [angka]

**SEKTOR UNGGULAN**
- [2-3 sektor outperform/underperform]

**KESIMPULAN**
- [1-2 kalimat: akumulasi/wait&see/selektif beli]

Maksimal 400 kata, padat dan informatif."""

    try:
        if not ANTHROPIC_API_KEY or "GANTI_DENGAN" in ANTHROPIC_API_KEY:
            dest_kirim_teks(dest,
                "❌ *ANTHROPIC_API_KEY belum diisi.*\n"
                "Edit bot_radar_saham.py → isi `ANTHROPIC_API_KEY`"); return

        r = _http.post(
            "https://api.anthropic.com/v1/messages",
            headers={"Content-Type":"application/json",
                     "x-api-key": ANTHROPIC_API_KEY,
                     "anthropic-version":"2023-06-01"},
            data=_json.dumps({"model":"claude-haiku-4-5-20251001",
                              "max_tokens":1024,
                              "messages":[{"role":"user","content":prompt}]}),
            timeout=45)
        if r.status_code != 200:
            dest_kirim_teks(dest, f"❌ API error {r.status_code}: {r.text[:120]}"); return

        resp = r.json()["content"][0]["text"].strip()
        import re as _re
        resp = _re.sub(r"\*\*(.+?)\*\*", r"*\1*", resp)
        resp = _re.sub(r"^- ", "• ", resp, flags=_re.MULTILINE)
        pesan  = f"{icon_lbl} *ANALISA IHSG — {tgl_fmt.upper()}* ({hari_name})\n"
        pesan += f"_Powered by AI_\n"
        pesan += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
        pesan += resp
        pesan += f"\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
        pesan += f"_⚠️ Bukan saran investasi. DYOR._"
        dest_kirim_teks(dest, pesan)
    except requests.exceptions.Timeout:
        dest_kirim_teks(dest, "❌ Timeout — API tidak merespons. Coba lagi.")
    except Exception as e:
        dest_kirim_teks(dest, f"❌ Error analisa AI: {str(e)[:80]}")

def ambil_news(ticker, dest):
    kode = ticker.replace(".JK","")
    import xml.etree.ElementTree as ET
    import html as html_lib, email.utils

    def parse_rss(query):
        try:
            q_enc  = requests.utils.quote(query)
            url    = f"https://news.google.com/rss/search?q={q_enc}&hl=id&gl=ID&ceid=ID:id"
            r      = _http.get(url, headers={"User-Agent":"Mozilla/5.0"}, timeout=12)
            if r.status_code != 200: return []
            root   = ET.fromstring(r.content)
            hasil  = []
            for item in root.findall(".//item"):
                judul_raw = html_lib.unescape(item.findtext("title") or "")
                # Buang nama sumber dari akhir judul Google News (format: "Judul - Sumber")
                if " - " in judul_raw:
                    judul_raw = judul_raw.rsplit(" - ", 1)[0]
                src = item.findtext("source") or ""
                pub = item.findtext("pubDate") or ""
                tgl = ""
                try:
                    dt  = email.utils.parsedate_to_datetime(pub)
                    tgl = dt.strftime("%d/%m/%Y")
                except: pass
                hasil.append({"title": judul_raw.strip(), "source": src, "date": tgl})
            return hasil
        except: return []

    # Query berurutan — makin spesifik ke saham IDX
    all_items = []
    for q in [f"saham {kode}", f"{kode} IHSG", f"emiten {kode}"]:
        found = parse_rss(q)
        # Filter: berita yang menyebut kode di judul
        relevan = [x for x in found if kode.upper() in x["title"].upper()]
        if relevan:
            all_items = relevan
            break

    # Fallback: ambil saja 5 teratas tanpa filter ketat
    if not all_items:
        all_items = parse_rss(f"saham {kode} Indonesia")[:5]

    if not all_items:
        dest_kirim_teks(dest, f"📰 Belum ada berita terbaru untuk *{kode}*.")
        return

    pesan = f"📰 *Berita Terbaru — {kode}*\n━━━━━━━━━━━━━━━━\n"
    for i, item in enumerate(all_items[:5], 1):
        judul  = item["title"][:90]
        source = item.get("source","")
        tgl    = item.get("date","")
        pesan += f"*{i}.* {judul}\n"
        if source or tgl:
            pesan += f"_— {source}  {tgl}_\n"
        pesan += "\n"
    pesan += f"⏰ {now_wib().strftime('%H:%M:%S')} WIB"
    dest_kirim_teks(dest, pesan)

def ambil_dsl(ticker, dest):
    """Data saham + Chart Super DSL (candle putih, S/R Step, Value Detector, StochRSI)."""
    kode = ticker.replace(".JK","")
    try:
        url  = f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}?range=1d&interval=1d"
        r    = _http.get(url, headers={"User-Agent":"Mozilla/5.0"}, timeout=10)
        meta = r.json()["chart"]["result"][0]["meta"]
        harga   = meta.get("regularMarketPrice",0)
        prev    = meta.get("previousClose",0) or meta.get("chartPreviousClose",0)
        high52  = meta.get("fiftyTwoWeekHigh",0)
        low52   = meta.get("fiftyTwoWeekLow",0)
        vol     = meta.get("regularMarketVolume",0)
        mkt_cap = meta.get("marketCap",0)
        gain_pct = (harga-prev)/prev*100 if prev>0 else 0
        arah_emj = "📈" if gain_pct>=0 else "📉"
        def fh(v): return f"{int(v):,}".replace(",",".")
        def fm(v):
            if v>=1e12: return f"{v/1e12:.2f}T"
            if v>=1e9:  return f"{v/1e9:.2f}M"
            if v>=1e6:  return f"{v/1e6:.1f}Jt"
            return str(int(v))
        if   harga>=high52*0.90: trend="🔥 Strong Uptrend (Dekat ATH)"
        elif harga<=low52*1.10:  trend="❄️ Strong Downtrend (Dekat ATL)"
        else:                     trend="〰️ Sideways / Konsolidasi"
        pesan  = f"*◈ DATA SAHAM — {kode}*\n"
        pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
        pesan += f"  Harga      : Rp {fh(harga)}  {arah_emj} {gain_pct:+.2f}%\n"
        pesan += f"📌 *Prev Close*: Rp {fh(prev)}\n"
        pesan += f"📦 *Volume*    : {fm(vol)} lot\n"
        pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
        pesan += f"📈 *Trend*     : {trend}\n"
        pesan += f"🔺 *52W High*  : Rp {fh(high52)}\n"
        pesan += f"🔻 *52W Low*   : Rp {fh(low52)}\n"
        if mkt_cap: pesan += f"🏢 *Mkt Cap*   : Rp {fm(mkt_cap)}\n"
        pesan += f"⏰ {now_wib().strftime('%H:%M:%S')} WIB"
        dest_kirim_teks(dest, pesan)
        buf = buat_chart_dsl(ticker)
        if buf:
            cap = (f"📊 *Chart Pro {kode}* | Rp {fh(harga)} ({gain_pct:+.2f}%)\n"
                   f"🔵 Maj Resistance (Step)  •  🔴 Maj Support (Step)\n"
                   f"📊 Value Detector  •  📉 StochRSI(14,3)")
            dest_kirim_foto_buf(dest, buf, cap)
        else:
            buf2 = buat_chart_buffer(ticker)
            if buf2: dest_kirim_foto_buf(dest, buf2, f"📊 Chart {kode}")
    except Exception as e:
        print(f"   ambil_dsl error: {e}")
        dest_kirim_teks(dest, f"❌ Gagal ambil data *{kode}*.")

def hitung_pivot(ticker, dest):
    """Pivot point — langsung kirim chart, info di caption."""
    kode = ticker.replace(".JK","")
    try:
        url = f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}?range=5d&interval=1d"
        r   = _http.get(url, headers={"User-Agent":"Mozilla/5.0"}, timeout=10)
        res = r.json()["chart"]["result"][0]
        q   = res["indicators"]["quote"][0]
        candles = [(h,l,c) for h,l,c in zip(q["high"],q["low"],q["close"])
                   if None not in (h,l,c)]
        if len(candles) < 2:
            dest_kirim_teks(dest, f"❌ Data tidak cukup untuk pivot *{kode}*."); return
        H, L, C = candles[-2]
        harga   = res["meta"].get("regularMarketPrice", C)
        P  = (H + L + C) / 3
        R1 = 2*P - L;   S1 = 2*P - H
        R2 = P + (H-L); S2 = P - (H-L)
        R3 = H + 2*(P-L); S3 = L - 2*(H-P)
        def fh(v): return f"{int(v):,}".replace(",",".")
        def pos(v):
            if   harga > v*1.002: return "✅ atas"
            elif harga < v*0.998: return "🔻 bawah"
            return "📍 tepat"
        levels = {"R3":R3,"R2":R2,"R1":R1,"PP":P,"S1":S1,"S2":S2,"S3":S3,"harga":harga}
        cap  = f"📐 *PIVOT POINT — {kode}*\n"
        cap += f"💰 Harga : Rp {fh(harga)}  |  _{now_wib().strftime('%d/%m %H:%M')} WIB_\n"
        cap += f"━━━━━━━━━━━━━━━━━━━━━━\n"
        cap += f"🔺 R3 : `{fh(R3)}`\n"
        cap += f"🔺 R2 : `{fh(R2)}`\n"
        cap += f"🔺 R1 : `{fh(R1)}`  — {pos(R1)}\n"
        cap += f"⭐ PP : `{fh(P)}`   — {pos(P)}\n"
        cap += f"🔻 S1 : `{fh(S1)}`  — {pos(S1)}\n"
        cap += f"🔻 S2 : `{fh(S2)}`\n"
        cap += f"🔻 S3 : `{fh(S3)}`\n"
        buf = buat_chart_pivot(ticker, levels)
        if buf:
            dest_kirim_foto_buf(dest, buf, cap)
        else:
            dest_kirim_teks(dest, cap)
    except Exception as e:
        print(f"   pivot error {kode}: {e}")
        dest_kirim_teks(dest, f"❌ Gagal hitung pivot *{kode}*.")

def compare_saham(kode1, kode2, dest):
    dest_kirim_teks(dest, f"📊 Membandingkan *{kode1}* vs *{kode2}*...")
    def ambil_info(kode):
        try:
            ticker = kode + ".JK"
            # Ambil data intraday hari ini (5m) untuk MF realtime
            url_5m = f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}?range=1d&interval=5m"
            r5m    = _http.get(url_5m, headers={"User-Agent":"Mozilla/5.0"}, timeout=10)
            res5m  = r5m.json()["chart"]["result"][0]
            meta   = res5m["meta"]
            q5m    = res5m["indicators"]["quote"][0]
            harga  = meta.get("regularMarketPrice") or meta.get("previousClose") or 0
            prev   = meta.get("previousClose") or meta.get("chartPreviousClose") or 0
            gain   = (harga - prev) / prev * 100 if prev > 0 else 0

            # Hitung MF dari candle intraday hari ini
            candles_5m = [(o,c,h,l,v) for o,c,h,l,v in zip(
                q5m.get("open",[]) or [], q5m.get("close",[]) or [],
                q5m.get("high",[]) or [],  q5m.get("low",[]) or [],
                q5m.get("volume",[]) or []) if None not in (o,c,h,l,v) and all(x > 0 for x in (o,c,h,l,v))]

            sm = bm = 0
            for o,c,h,l,v in candles_5m:
                tp = (h+l+c)/3; mf = tp*v
                if c >= o: sm += mf
                else:       bm += mf
            cm = sm - bm
            n_candles = len(candles_5m)

            # Fallback MF dari daily jika intraday kosong (saham kecil/baru)
            mf_source = "intraday"
            if n_candles < 5:
                try:
                    url_d2 = f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}?range=5d&interval=1d"
                    rd2    = _http.get(url_d2, headers={"User-Agent":"Mozilla/5.0"}, timeout=10)
                    resd2  = rd2.json()["chart"]["result"][0]
                    qd2    = resd2["indicators"]["quote"][0]
                    cl_d2  = [c for c in (qd2.get("close") or []) if c]
                    op_d2  = [o for o in (qd2.get("open") or []) if o]
                    hi_d2  = [h for h in (qd2.get("high") or []) if h]
                    lo_d2  = [l for l in (qd2.get("low") or []) if l]
                    vo_d2  = [v for v in (qd2.get("volume") or []) if v]
                    for o2,c2,h2,l2,v2 in zip(op_d2[-3:], cl_d2[-3:], hi_d2[-3:], lo_d2[-3:], vo_d2[-3:]):
                        tp = (h2+l2+c2)/3; mf = tp*v2
                        if c2 >= o2: sm += mf
                        else:         bm += mf
                    cm = sm - bm; mf_source = "daily(3d)"
                    if not harga and cl_d2: harga = cl_d2[-1]
                    if not prev and len(cl_d2) > 1: prev = cl_d2[-2]
                    if prev > 0: gain = (harga - prev) / prev * 100
                except: pass

            # Ambil RSI dari daily 1 tahun (fallback ke 3mo)
            url_d = f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}?range=1y&interval=1d"
            rd    = _http.get(url_d, headers={"User-Agent":"Mozilla/5.0"}, timeout=10)
            resd  = rd.json()["chart"]["result"][0]
            qd    = resd["indicators"]["quote"][0]
            cl_d  = [c for c in (qd.get("close") or []) if c]
            import pandas as pd
            rsi_val = float("nan")
            if len(cl_d) >= 15:
                cl_s   = pd.Series(cl_d)
                # Fix v4-15: 'close' was undefined — should be cl_s
                rsi_val= float(hitung_rsi_wilder(cl_s).iloc[-1])
                if not harga and cl_d: harga = cl_d[-1]
                if not prev and len(cl_d) > 1: prev = cl_d[-2]
                if prev > 0: gain = (harga - prev) / prev * 100

            # Volume
            vol_today = meta.get("regularMarketVolume") or 0
            vol_d_arr  = [v for v in (qd.get("volume") or []) if v]
            # Jika vol_today 0, ambil dari daily terakhir
            if vol_today == 0 and vol_d_arr: vol_today = vol_d_arr[-1]
            avg_vol    = sum(vol_d_arr[-20:]) / 20 if len(vol_d_arr) >= 5 else 1
            vol_ratio  = vol_today / avg_vol if avg_vol > 0 else 0

            return {
                "kode":kode, "harga":harga, "gain":gain,
                "cm":cm, "sm":sm, "bm":bm,
                "rsi":rsi_val, "vol_ratio":vol_ratio,
                "n_candles":n_candles, "mf_source":mf_source,
            }
        except Exception as e:
            print(f"compare ambil_info {kode} error: {e}")
            return None

    d1 = ambil_info(kode1)
    d2 = ambil_info(kode2)
    if not d1 or not d2:
        dest_kirim_teks(dest, "❌ Data salah satu saham tidak tersedia."); return

    def fh(v): return f"{int(v):,}".replace(",",".")
    def fm(v):
        abs_v=abs(v); pfx="+" if v>=0 else "-"
        if abs_v>=1e12: return f"{pfx}{abs_v/1e12:.2f}T"
        if abs_v>=1e9:  return f"{pfx}{abs_v/1e9:.2f}M"
        if abs_v>=1e6:  return f"{pfx}{abs_v/1e6:.1f}Jt"
        if abs_v>=1e3:  return f"{pfx}{abs_v/1e3:.0f}Rb"
        return f"{pfx}{abs_v:.0f}"
    def wn(a, b, higher=True):
        if higher: return "🏆" if a > b else ("🤝" if a==b else "  ")
        else:      return "🏆" if a < b else ("🤝" if a==b else "  ")

    now_s = now_wib().strftime("%H:%M:%S")
    mf_src1 = d1.get("mf_source","intraday"); mf_src2 = d2.get("mf_source","intraday")
    src_note = ""
    if "daily" in mf_src1 or "daily" in mf_src2:
        src_note = f"\n⚠️ _Intraday tipis — MF dari data daily ({mf_src1}/{mf_src2})_"
    pesan  = f"📊 *COMPARE: {kode1} vs {kode2}*\n"
    pesan += f"📅 {now_s} WIB{src_note}\n"
    pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
    pesan += f"{'Indikator':<16} {kode1:>7} {kode2:>7}\n"
    pesan += f"{'─'*32}\n"
    pesan += f"{'Harga':<16} {fh(int(d1['harga'])):>7} {fh(int(d2['harga'])):>7}\n"
    pesan += f"{'Gain%':<16} {d1['gain']:>+6.2f}% {d2['gain']:>+6.2f}% {wn(d1['gain'],d2['gain'])}\n"
    # MF — beri tanda jika 0 (tidak ada data)
    def fmt_mf(v):
        if v == 0: return "    N/A"
        return fm(v)
    pesan += f"{'Clean Money':<16} {fmt_mf(d1['cm']):>8} {fmt_mf(d2['cm']):>8}"
    if d1['cm'] != 0 or d2['cm'] != 0: pesan += f" {wn(d1['cm'],d2['cm'])}"
    pesan += "\n"
    pesan += f"{'Smart Money':<16} {fmt_mf(d1['sm']):>8} {fmt_mf(d2['sm']):>8}"
    if d1['sm'] != 0 or d2['sm'] != 0: pesan += f" {wn(d1['sm'],d2['sm'])}"
    pesan += "\n"
    pesan += f"{'Bad Money':<16} {fmt_mf(d1['bm']):>8} {fmt_mf(d2['bm']):>8}"
    if d1['bm'] != 0 or d2['bm'] != 0: pesan += f" {wn(d1['bm'],d2['bm'],False)}"
    pesan += "\n"
    import math
    rsi1_str = f"{d1['rsi']:>6.1f}" if not math.isnan(d1['rsi']) else "   N/A"
    rsi2_str = f"{d2['rsi']:>6.1f}" if not math.isnan(d2['rsi']) else "   N/A"
    pesan += f"{'RSI':<16} {rsi1_str}  {rsi2_str}\n"
    pesan += f"{'Vol Ratio':<16} {d1['vol_ratio']:>5.1f}x   {d2['vol_ratio']:>5.1f}x  {wn(d1['vol_ratio'],d2['vol_ratio'])}\n"
    pesan += f"{'Candles/Data':<16} {d1['n_candles']:>6}   {d2['n_candles']:>6}\n"
    pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
    # Verdikt
    score1 = (1 if d1['gain']>d2['gain'] else 0) + (1 if d1['cm']>d2['cm'] else 0) + (1 if d1['vol_ratio']>d2['vol_ratio'] else 0)
    score2 = 3 - score1
    if score1 > score2:   pesan += f"★ *{kode1} lebih unggul hari ini* ({score1}-{score2})\n"
    elif score2 > score1: pesan += f"★ *{kode2} lebih unggul hari ini* ({score2}-{score1})\n"
    else:                  pesan += f"🤝 Kedua saham seimbang hari ini\n"
    pesan += f"★ = unggul  |  ⚠️ DYOR\n"
    pesan += f"⏰ {now_s} WIB"
    dest_kirim_teks(dest, pesan)

