ADMIN_IDS = {7949449049}   # Keong Balap (@d02yu)

# ── Fix 9: Rate limiting per user — cegah spam command ───────
_user_last_cmd   = {}          # {user_id: timestamp_last_cmd}
_user_cmd_count  = {}          # {user_id: count dalam window}
_rate_lock       = threading.Lock()
RATE_LIMIT_DETIK = 15          # cooldown antar command berat (detik)
RATE_LIMIT_MAX   = 5           # max command per 60 detik

# ════════════════════════════════════════════════════════════
# SECURITY LAYER — Hardening bot dari akses tidak sah
# Physics: noise filter (Heisenberg) + exponential decay (N(t)=N₀e^{-λt})
# ════════════════════════════════════════════════════════════
_ACCESS_FAIL_LOG  = {}   # {uid_str: [timestamps]} — brute-force log
_TEMP_BLOCKED     = set()  # uid sementara diblokir
_SEC_LOCK         = threading.Lock()

def _sanitize_input(text: str, max_len: int = 500) -> str:
    """
    Hapus karakter berbahaya dari input command.
    Prevent null-byte injection, truncate payload oversized.
    """
    if not text:
        return ""
    text = text[:max_len]
    # Hapus karakter kontrol berbahaya
    cleaned = []
    for ch in text:
        cp = ord(ch)
        if cp == 0 or cp == 13:   # null byte, carriage return
            continue
        cleaned.append(ch)
    return "".join(cleaned).strip()

def _catat_akses_gagal(user_id):
    """
    Log akses gagal. Auto temp-block jika ≥10 fail dalam 60 detik.
    Exponential decay: entri lama (>60 dtk) dihapus = count memudar alami.
    """
    uid = str(user_id)
    now_ts = time.time()
    with _SEC_LOCK:
        _ACCESS_FAIL_LOG.setdefault(uid, [])
        _ACCESS_FAIL_LOG[uid] = [t for t in _ACCESS_FAIL_LOG[uid] if now_ts-t < 60]
        _ACCESS_FAIL_LOG[uid].append(now_ts)
        if len(_ACCESS_FAIL_LOG[uid]) >= 10:
            _TEMP_BLOCKED.add(uid)
            logger.warning("SECURITY: uid %s temp-blocked (%d fails/60s)", uid,
                           len(_ACCESS_FAIL_LOG[uid]))

def _is_temp_blocked(user_id):
    """Cek temp-block. Auto-release jika tidak ada fail dalam 10 menit."""
    uid = str(user_id)
    if uid not in _TEMP_BLOCKED:
        return False
    with _SEC_LOCK:
        recent = [t for t in _ACCESS_FAIL_LOG.get(uid,[]) if time.time()-t < 600]
    if not recent:
        _TEMP_BLOCKED.discard(uid)
        logger.info("SECURITY: uid %s temp-block released", uid)
        return False
    return True

def _cek_rate_limit(user_id):
    """
    Fix 9: Return True jika user boleh lanjut, False jika kena throttle.
    Admin tidak kena rate limit.
    """
    if is_admin(user_id):
        return True
    uid = str(user_id)
    now = time.time()
    with _rate_lock:
        last = _user_last_cmd.get(uid, 0)
        if now - last < RATE_LIMIT_DETIK:
            return False   # terlalu cepat
        # Reset count tiap 60 detik
        window_start = _user_cmd_count.get(uid + "_t", 0)
        if now - window_start > 60:
            _user_cmd_count[uid] = 0
            _user_cmd_count[uid + "_t"] = now
        count = _user_cmd_count.get(uid, 0) + 1
        if count > RATE_LIMIT_MAX:
            return False   # terlalu banyak dalam 1 menit
        _user_cmd_count[uid] = count
        _user_last_cmd[uid]  = now
        return True

