def daftar_member(user_id, nama):
    """Daftarkan ke pending — harus disetujui admin dulu."""
    if is_blacklisted(user_id):
        return "banned"
    data = db_load_members()
    uid  = str(user_id)
    if uid in data:
        return "sudah"
    pending = db_load_pending()
    if uid in pending:
        return "pending"
    db_save_pending(user_id, nama)
    for adm_id in get_admin_ids():
        kirim_dm(adm_id,
            f"\U0001f514 *Permintaan Daftar Member Baru*\n"
            f"\U0001f464 Nama   : *{nama}*\n"
            f"\U0001f194 UserID : `{user_id}`\n\n"
            f"Ketik salah satu:\n"
            f"`/approve {user_id}` \u2014 Setujui\n"
            f"`/reject {user_id}` \u2014 Tolak")
    return "menunggu"

def approve_member(user_id):
    """Admin setujui member pending."""
    pending = db_load_pending()
    uid = str(user_id)
    if uid not in pending:
        return None
    info = pending[uid]
    db_del_pending(uid)
    db_save_member(uid, info.get("nama", uid), "active")
    return info

def reject_member(user_id):
    """Admin tolak member pending."""
    pending = db_load_pending()
    uid = str(user_id)
    info = pending.get(uid)
    db_del_pending(uid)
    return info

def get_all_members():
    data = db_load_members()
    bl   = _load_blacklist()
    return [v for k, v in data.items() if k not in bl]

def kick_member(user_id):
    """Hapus dari member + masukkan ke blacklist."""
    uid  = str(user_id)
    data = db_load_members()
    nama = data.get(uid, {}).get("nama", uid)
    db_del_member(uid)
    db_blacklist_add(uid, nama)
    return nama

def unkick_member(user_id):
    """Hapus dari blacklist (restore akses)."""
    uid  = str(user_id)
    bl   = _load_blacklist()
    nama = bl.get(uid, {}).get("nama", uid)
    db_blacklist_del(uid)
    return nama


