# --- FUNGSI UNTUK RINGKASAN SINYAL (PERSISTENT DB) ---
# ============================================================
sinyal_hari_ini = []   # in-memory mirror; diisi dari DB saat startup
_sinyal_lock    = threading.Lock()

def _db_catat_sinyal(kode, pola, jam, sumber="SCAN"):
    """Simpan sinyal ke daily_signals — persist survive restart."""
    tgl = now_wib().strftime("%Y-%m-%d")
    try:
        with _db_lock:
            conn = _db_conn(); c = conn.cursor()
            c.execute("""INSERT INTO daily_signals(kode,pola,jam,sumber,tgl,ts)
                         VALUES(?,?,?,?,?,?)""",
                      (kode, pola, jam, sumber, tgl, time.time()))
            conn.commit(); conn.close()
    except Exception as _e:
        logger.warning("_db_catat_sinyal: %s", _e)

def _db_load_sinyal_hari(tgl_str=None):
    """Load sinyal dari DB untuk hari ini (atau tgl_str tertentu)."""
    if not tgl_str:
        tgl_str = now_wib().strftime("%Y-%m-%d")
    try:
        with _db_lock:
            conn = _db_conn(); c = conn.cursor()
            c.execute("""SELECT kode,pola,jam,sumber FROM daily_signals
                         WHERE tgl=? ORDER BY ts ASC""", (tgl_str,))
            rows = c.fetchall(); conn.close()
        return [{"kode":r[0],"pola":r[1],"jam":r[2],"sumber":r[3]} for r in rows]
    except Exception as _e:
        logger.warning("_db_load_sinyal_hari: %s", _e)
        return []

def _db_load_sinyal_minggu():
    """Load sinyal dari DB sejak Senin 00:00 WIB minggu ini."""
    now = now_wib()
    senin = (now - _dt.timedelta(days=now.weekday())).replace(
        hour=0, minute=0, second=0, microsecond=0)
    ts_senin = senin.timestamp()
    try:
        with _db_lock:
            conn = _db_conn(); c = conn.cursor()
            c.execute("""SELECT kode,pola,jam,sumber,tgl FROM daily_signals
                         WHERE ts >= ? ORDER BY ts ASC""", (ts_senin,))
            rows = c.fetchall(); conn.close()
        return [{"kode":r[0],"pola":r[1],"jam":r[2],"sumber":r[3],"tgl":r[4]}
                for r in rows]
    except Exception as _e:
        logger.warning("_db_load_sinyal_minggu: %s", _e)
        return []

def catat_sinyal_ringkasan(kode, pola, sumber="SCAN"):
    """Catat sinyal ke memory + DB. sumber: SCAN | ALGO | SCREENER."""
    jam = now_wib().strftime("%H:%M")
    with _sinyal_lock:
        sinyal_hari_ini.append({"kode":kode,"pola":pola,"jam":jam,"sumber":sumber})
    _db_catat_sinyal(kode, pola, jam, sumber)
    try:
        info = ambil_info_saham(kode + ".JK")
        harga_sinyal = info["harga"] if info else 0
        db_signal_add(kode, f"{sumber}:{pola[:40]}", harga_sinyal)
    except Exception as _e:
        logger.warning("catat_sinyal db: %s", _e)

def kirim_ringkasan(dest):
    """Tampilkan ringkasan dari DB — akurat meski bot pernah restart."""
    tgl    = now_wib().strftime("%d-%m-%Y")
    tgl_db = now_wib().strftime("%Y-%m-%d")
    rows = _db_load_sinyal_hari(tgl_db)
    if not rows:
        dest_kirim_teks(dest, f"📋 *Ringkasan {tgl}*\nBelum ada sinyal hari ini.")
        return
    scan_rows = [s for s in rows if s.get("sumber") == "SCAN"]
    algo_rows = [s for s in rows if s.get("sumber") == "ALGO"]
    scr_rows  = [s for s in rows if s.get("sumber") not in ("SCAN","ALGO")]
    pesan  = f"*▸ RINGKASAN SINYAL — {tgl}*\n"
    pesan += f"🔢 Total: *{len(rows)}* sinyal\n━━━━━━━━━━━━━━━━━━━━━━\n"
    if scan_rows:
        pesan += f"🔍 *Auto-Scan ({len(scan_rows)}):*\n"
        for s in scan_rows[:20]:
            pesan += f"  ⏰{s['jam']} *{s['kode']}* — {s['pola']}\n"
    if algo_rows:
        pesan += f"\n🤖 *Algo ({len(algo_rows)}):*\n"
        for s in algo_rows[:20]:
            pesan += f"  ⏰{s['jam']} *{s['kode']}* — {s['pola']}\n"
    if scr_rows:
        pesan += f"\n📡 *Screener ({len(scr_rows)}):*\n"
        for s in scr_rows[:10]:
            pesan += f"  ⏰{s['jam']} *{s['kode']}* — {s['pola']}\n"
    pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n⏰ {now_wib().strftime('%H:%M:%S')} WIB"
    dest_kirim_teks(dest, pesan)

def cek_jadwal_ringkasan():
    """Kirim ringkasan otomatis jam 16:15 ke Chart Konfirm."""
    now     = now_wib()
    hari    = now.weekday()
    jam_mnt = now.strftime("%H:%M")
