def proses_cmd_wl_strategy(tipe, user_id, args, dest):
    """
    Handler /bsjp dan /bpjs.
    - Tanpa args / "list" / "cek" → tampil kandidat terakhir dari auto-scan
    - "scan" → jalankan scan manual sekarang
    - add/del DIHAPUS — sepenuhnya auto-scan dari bot
    """
    label  = "BSJP — Beli Sore Jual Pagi" if tipe=="bsjp" else "BPJS — Beli Pagi Jual Siang"
    emoji  = "🌆" if tipe=="bsjp" else "🌅"
    # File cache hasil reko terakhir
    cache_file = os.path.join(DATA_DIR, f"cache_{tipe}_terakhir.json")

    cmd = (args[0].lower() if args else "")

    if cmd == "scan":
        # Jalankan scan manual sekarang
        dest_kirim_teks(dest, f"{emoji} Memulai scan *{label}* manual...")
        if tipe == "bsjp":
            threading.Thread(target=auto_scan_bsjp_kirim, args=(dest,), daemon=True).start()
        else:
            threading.Thread(target=auto_scan_bpjs_kirim, args=(dest,), daemon=True).start()
        return

    # Default: tampil hasil scan terakhir + cek harga terkini
    try:
        cache = json.load(open(cache_file)) if _os.path.exists(cache_file) else {}
    except: cache = {}

    kandidat = cache.get("kandidat", [])
    waktu    = cache.get("waktu", "")

    if not kandidat:
        jadwal_str = "• 15:00 WIB (sore)" if tipe=="bsjp" else "• 09:15 WIB (pagi)"
        dest_kirim_teks(dest,
            f"{emoji} *{label}*\n\n"
            f"ℹ️ Belum ada hasil scan tersimpan.\n\n"
            f"*Cara mendapatkan kandidat:*\n"
            f"• Bot kirim otomatis tiap {jadwal_str}\n"
            f"• Atau ketik `/{tipe} scan` untuk scan sekarang\n\n"
            f"💡 Setelah bot scan, ketik `/{tipe}` untuk lihat\n"
            f"kandidat + harga realtime kapanpun.")
        return

    # Tampil kandidat + refresh harga terkini
    def _cek_dan_kirim():
        pesan  = f"{emoji} *{label}*\n"
        pesan += f"📅 Hasil scan: {waktu}\n"
        pesan += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
        for i, kode in enumerate(kandidat[:10], 1):
            info = ambil_info_saham(kode+".JK")
            if info:
                h   = int(info["harga"])
                g   = info["gain"]
                gemj= "📈" if g>=0 else "📉"
                hstr= f"{h:,}".replace(",",".")
                pesan += f"*{i}.* *{kode}*  Rp {hstr}  {gemj} {g:+.2f}%\n"
            else:
                pesan += f"*{i}.* *{kode}*  —\n"
            time.sleep(0.15)
        pesan += f"\n⏰ Harga diperbarui {now_wib().strftime('%H:%M')} WIB\n"
        pesan += f"_Ketik `/{tipe} scan` untuk scan ulang sekarang_"
        dest_kirim_teks(dest, pesan)

    threading.Thread(target=_cek_dan_kirim, daemon=True).start()

def cek_jadwal_bsjp_bpjs():
    """
    Kirim alert otomatis BSJP & BPJS sesuai jadwal.
    BSJP BELI  → 15:00 WIB
    BSJP JUAL  → 09:15 WIB
    BPJS BELI  → 09:15 WIB
    BPJS JUAL  → 11:45 WIB & 15:00 WIB
    """
    now     = now_wib()
    hari    = now.weekday()
    if hari > 4: return   # Sabtu/Minggu skip

    jam_mnt = now.strftime("%H:%M")
    tgl_str = now.strftime("%Y-%m-%d")
    dest_auto = {"type": "topic", "thread_id": THREAD_ID_RADAR}

    jadwal = {
        # (jam, tipe, aksi, emoji, judul)
        "09:15": [
            ("bsjp", "JUAL", "🌅", "⚡ BSJP — WAKTU JUAL PAGI!"),
            ("bpjs", "BELI", "🌅", "⚡ BPJS — WAKTU BELI PAGI!"),
        ],
        "11:45": [
            ("bpjs", "JUAL_SIANG", "🌤️", "⚡ BPJS — OPSI JUAL SIANG"),
        ],
        "15:00": [
            ("bsjp", "BELI", "🌆", "⚡ BSJP — WAKTU BELI SORE!"),
            ("bpjs", "JUAL_SORE", "🌇", "⚡ BPJS — OPSI JUAL SORE"),
        ],
    }

    if jam_mnt not in jadwal: return

    for tipe, aksi, emoji, judul in jadwal[jam_mnt]:
        key = f"{tipe}_{aksi}_{tgl_str}"
        if key in jadwal_sudah_scan: continue
        jadwal_sudah_scan.add(key)

        path  = BSJP_FILE if tipe == "bsjp" else BPJS_FILE
        daftar = _load_wl_file(path)
        if not daftar: continue

        print(f"⏰ AUTO ALERT [{jam_mnt}] {judul}")
        # Kirim via DM ke semua member (bukan ke topic)
        def _do_alert_dm(judul=judul, emoji=emoji, daftar=daftar):
            members = _load_members()
            bl = _load_blacklist()
            aktif = [int(uid) for uid in members if uid not in bl]
            if not aktif:
                send_telegram_message(f"{emoji} {judul}\n_(tidak ada member aktif)_")
                return
            pesan = kirim_alert_watchlist_teks(judul, emoji, daftar)
            if not pesan: return
            ok = 0
            for uid in aktif:
                try:
                    kirim_dm(uid, pesan)
                    ok += 1
                    time.sleep(0.1)
                except: pass
            print(f"   📩 Alert {judul} → DM ke {ok} member")
        threading.Thread(target=_do_alert_dm, daemon=True).start()

def scan_bsjp_kriteria(ticker):
    """
    BSJP: Beli Sore Jual Pagi — kriteria DIPERKETAT v2.
    Filter wajib:
      - Body ratio candle hari ini >= 5x body candle kemarin (momentum kuat)
      - Buyer frequency >= 70% candle hijau 10 hari terakhir (dominan buyer)
      - Candle hari ini HIJAU (bullish konfirmasi)
      - Volume minimal 2x rata-rata 10 hari
      - Nilai transaksi > 1.5 Miliar
      - RSI 45-65 (momentum bullish, tidak overbought)
      - EMA20 slope positif (tren naik)
      - MACD histogram positif ATAU stochastic %K > %D (konfirmasi momentum)
      - Harga di atas EMA20 (trend following)
    """
    try:
        df, harga, prev = get_candles_tf(ticker, "1d", "3mo")
        if len(df) < 26 or harga < 50 or harga > 50000: return None
        close = df["Close"]; opn = df["Open"]
        high  = df["High"];  low = df["Low"]
        vol   = df["Volume"]

        # ── EMA20 + slope ──
        ema20 = close.ewm(span=20, adjust=False).mean()
        e20   = float(ema20.iloc[-1])
        e20_5 = float(ema20.iloc[-5]) if len(ema20) >= 5 else e20
        slope = (e20 - e20_5) / e20_5 * 100 if e20_5 > 0 else 0

        # ── RSI ──
        rsi = float(hitung_rsi_wilder(close).iloc[-1])
        if rsi != rsi: return None

        # ── MACD ──
        ema12 = close.ewm(span=12, adjust=False).mean()
        ema26 = close.ewm(span=26, adjust=False).mean()
        macd_line  = ema12 - ema26
        macd_sig   = macd_line.ewm(span=9, adjust=False).mean()
        macd_hist  = float((macd_line - macd_sig).iloc[-1])
        macd_hist_prev = float((macd_line - macd_sig).iloc[-2])

        # ── Stochastic ──
        low14  = low.rolling(14).min()
        high14 = high.rolling(14).max()
        k_raw  = 100 * (close - low14) / (high14 - low14 + 1e-9)
        k      = k_raw.rolling(3).mean()
        d      = k.rolling(3).mean()
        stoch_k = float(k.iloc[-1])
        stoch_d = float(d.iloc[-1])

        vol_now = float(vol.iloc[-1])
        vol_avg = float(vol.rolling(10).mean().iloc[-1])
        vol_x   = vol_now / vol_avg if vol_avg > 0 else 1
        gain    = (harga - prev) / prev * 100 if prev > 0 else 0
        nilai   = harga * vol_now * 100

        # ── Body ratio (candle sore belum selesai, pakai body relative kecil) ──
        body_curr  = abs(float(close.iloc[-1]) - float(opn.iloc[-1]))
        body_prev  = abs(float(close.iloc[-2]) - float(opn.iloc[-2]))
        body_ratio = body_curr / body_prev if body_prev > 0 else 1
        # Tidak hard-require hijau (scan 15:00 candle masih forming)
        # Tapi gain tidak boleh negatif parah
        if gain < -3: return None                              # tidak sedang crash bebas

        # ── Buyer frequency >= 40% ──
        green_days = sum(1 for i in range(-10, 0)
                         if float(close.iloc[i]) > float(opn.iloc[i]))
        buyer_freq_pct = green_days / 10 * 100
        if buyer_freq_pct < 40: return None      # minimal 4 dari 10 hari hijau

        # ── Filter utama ──
        if rsi < 35 or rsi > 75: return None     # RSI momentum bullish wajar
        if slope < -0.5: return None             # EMA20 tidak boleh turun tajam sekali
        if gain > 20: return None
        if nilai < 300_000_000: return None      # transaksi minimal 300 juta
        if vol_x < 1.0: return None              # volume minimal sama rata-rata

        # ── Konfirmasi momentum: MACD histogram naik ATAU Stoch bullish ──
        macd_ok  = macd_hist > 0 or (macd_hist > macd_hist_prev)  # histogram naik
        stoch_ok = stoch_k > stoch_d and stoch_k < 80             # stoch golden cross tidak overbought

        # ── Harga tidak jauh di bawah EMA20 ──
        if harga < e20 * 0.95: return None        # toleransi 5% di bawah EMA20

        # ── Skor ──
        skor = 0
        if 50 <= rsi <= 62: skor += 2
        if vol_x >= 3.0: skor += 2
        if body_ratio >= 8.0: skor += 2
        elif body_ratio >= 5.0: skor += 1
        if slope > 0.3: skor += 1
        if harga > e20: skor += 1
        if buyer_freq_pct >= 80: skor += 1
        if macd_ok and stoch_ok: skor += 2        # bonus kedua konfirmasi aktif

        return {"kode": ticker.replace(".JK",""), "harga": harga,
                "gain": gain, "rsi": rsi, "vol_x": vol_x,
                "body_ratio": body_ratio, "buyer_freq": buyer_freq_pct,
                "macd_ok": macd_ok, "stoch_ok": stoch_ok, "skor": skor}
    except: return None

def scan_bpjs_kriteria(ticker):
    """
    BPJS: Beli Pagi Jual Siang/Sore — kriteria DIPERKETAT v2.
    Filter wajib:
      - Body ratio candle hari ini >= 5x body candle kemarin (momentum kuat)
      - Buyer frequency >= 70% candle hijau 10 hari terakhir (dominan buyer)
      - Candle hari ini HIJAU (konfirmasi reversal)
      - Volume spike minimal 3x rata-rata (volume kuat)
      - Nilai transaksi > 1.5 Miliar
      - RSI 32-52 (oversold ringan, tidak crash bebas)
      - EMA50 masih sebagai support (harga tidak jauh di bawah)
      - MACD histogram naik ATAU stochastic golden cross (konfirmasi momentum)
    """
    try:
        df, harga, prev = get_candles_tf(ticker, "1d", "3mo")
        if len(df) < 52 or harga < 50 or harga > 50000: return None
        close = df["Close"]; opn = df["Open"]
        high  = df["High"];  low = df["Low"]
        vol   = df["Volume"]

        ema20 = close.ewm(span=20, adjust=False).mean()
        ema50 = close.ewm(span=50, adjust=False).mean()

        # ── RSI ──
        rsi = float(hitung_rsi_wilder(close).iloc[-1])
        if rsi != rsi: return None

        # ── MACD ──
        ema12 = close.ewm(span=12, adjust=False).mean()
        ema26 = close.ewm(span=26, adjust=False).mean()
        macd_line  = ema12 - ema26
        macd_sig   = macd_line.ewm(span=9, adjust=False).mean()
        macd_hist  = float((macd_line - macd_sig).iloc[-1])
        macd_hist_prev = float((macd_line - macd_sig).iloc[-2])

        # ── Stochastic ──
        low14  = low.rolling(14).min()
        high14 = high.rolling(14).max()
        k_raw  = 100 * (close - low14) / (high14 - low14 + 1e-9)
        k      = k_raw.rolling(3).mean()
        d      = k.rolling(3).mean()
        stoch_k = float(k.iloc[-1])
        stoch_d = float(d.iloc[-1])

        vol_now = float(vol.iloc[-1])
        vol_avg = float(vol.rolling(10).mean().iloc[-1])
        vol_x   = vol_now / vol_avg if vol_avg > 0 else 1
        e20     = float(ema20.iloc[-1])
        e50     = float(ema50.iloc[-1])
        gain    = (harga - prev) / prev * 100 if prev > 0 else 0
        nilai   = harga * vol_now * 100

        # ── Body ratio (BPJS pakai data kemarin, lebih reliable) ──
        body_curr  = abs(float(close.iloc[-1]) - float(opn.iloc[-1]))
        body_prev2 = abs(float(close.iloc[-2]) - float(opn.iloc[-2]))
        body_ratio = body_curr / body_prev2 if body_prev2 > 0 else 1
        # Cek candle KEMARIN hijau (lebih reliable utk prediksi pagi)
        yesterday_green = float(close.iloc[-1]) >= float(opn.iloc[-1]) * 0.99  # toleransi 1%
        if not yesterday_green and gain < -5: return None  # jika merah + jatuh, skip

        # ── Buyer frequency >= 40% ──
        green_days = sum(1 for i in range(-10, 0)
                         if float(close.iloc[i]) > float(opn.iloc[i]))
        buyer_freq_pct = green_days / 10 * 100
        if buyer_freq_pct < 40: return None      # minimal 4 dari 10 hari hijau

        # ── Filter utama ──
        if rsi < 20 or rsi > 65: return None     # RSI zona reversal/momentum
        if gain < -10 or gain > 15: return None
        if nilai < 300_000_000: return None      # transaksi minimal 300 juta
        if vol_x < 1.2: return None              # volume 1.2x rata-rata

        # EMA50 masih jadi support (tidak crash >20% dari EMA50)
        ema50_gap = (harga - e50) / e50 * 100 if e50 > 0 else 0
        if ema50_gap < -20: return None

        # ── Konfirmasi momentum: MACD naik ATAU Stoch golden cross ──
        macd_ok  = macd_hist > macd_hist_prev            # histogram naik = momentum membaik
        stoch_ok = stoch_k > stoch_d and stoch_k < 70   # stoch GC tidak overbought

        # ── Skor ──
        skor = 0
        if rsi < 42: skor += 3
        if vol_x >= 4.0: skor += 2
        elif vol_x >= 3.0: skor += 1
        if body_ratio >= 8.0: skor += 2
        elif body_ratio >= 5.0: skor += 1
        if harga < e20: skor += 1              # di bawah EMA20 = bounce lebih natural
        if harga > e50: skor += 1              # di atas EMA50 = tren jangka menengah oke
        if buyer_freq_pct >= 80: skor += 1
        if gain > -2: skor += 1
        if macd_ok and stoch_ok: skor += 2     # bonus kedua konfirmasi aktif

        return {"kode": ticker.replace(".JK",""), "harga": harga,
                "gain": gain, "rsi": rsi, "vol_x": vol_x,
                "body_ratio": body_ratio, "buyer_freq": buyer_freq_pct,
                "macd_ok": macd_ok, "stoch_ok": stoch_ok, "skor": skor}
    except: return None

def _simpan_cache_scan(tipe, kandidat):
    """Simpan hasil scan ke file cache."""
    cache_file = os.path.join(DATA_DIR, f"cache_{tipe}_terakhir.json")
    try:
        data = {
            "kandidat": [k["kode"] for k in kandidat],
            "detail"  : kandidat,
            "waktu"   : now_wib().strftime("%d/%m/%Y %H:%M WIB"),
        }
        json.dump(data, open(cache_file, "w"), indent=2)
    except: pass

def _get_scan_universe(tipe):
    """Ambil universe saham untuk scan BSJP/BPJS.
    Bisa dikustomisasi per tipe via db kv_store key: scan_universe_bsjp / scan_universe_bpjs.
    Format: "all" = seluruh watchlist, "lq45" = hanya LQ45, "kode,kode,..." = custom list.
    Default: seluruh watchlist."""
    try:
        key = f"scan_universe_{tipe}"
        val = db_kv_get(key)
        if not val or val == "all":
            return list(watchlist)
        elif val == "lq45":
            # Filter LQ45 dari watchlist
            lq45 = {"BBCA","BBRI","BMRI","BBNI","TLKM","ASII","GOTO","BREN","TOWR",
                     "AMRT","ICBP","INDF","MYOR","KLBF","SIDO","KAEF","SRTG","SMGR",
                     "INTP","BSDE","CTRA","PWON","JSMR","WIKA","PTPP","ADHI","WSKT",
                     "UNTR","UNVR","HMSP","GGRM","AALI","LSIP","SMDR","BNGA","ARTO",
                     "ISAT","EXCL","FREN","MTEL","AKRA","PTBA","ADRO","ITMG","HRUM",
                     "MEDC","PGAS","ELSA","PALM","SSMS"}
            universe = [t for t in watchlist if t.replace(".JK","") in lq45]
            return universe if universe else list(watchlist)
        elif val == "idx30":
            idx30 = {"BBCA","BBRI","BMRI","BBNI","TLKM","ASII","GOTO","BREN","TOWR",
                     "AMRT","ICBP","BSDE","CTRA","UNTR","HMSP","GGRM","ADRO","PTBA",
                     "PGAS","AKRA","JSMR","SMGR","KLBF","UNVR","INDF","MYOR","INTP",
                     "ARTO","ISAT","EXCL"}
            universe = [t for t in watchlist if t.replace(".JK","") in idx30]
            return universe if universe else list(watchlist)
        else:
            # Custom list: "BBCA,BBRI,TLKM"
            custom = [k.strip().upper() + ".JK" for k in val.split(",") if k.strip()]
            return custom if custom else list(watchlist)
    except:
        return list(watchlist)


