def _get_quote_realtime(ticker):
    """
    Ambil harga & gain dari Yahoo Finance.
    - Jam trading: v7 API → regularMarketChangePercent (cocok Stockbit)
    - Weekend/tutup: chart 5d → (close-open)/open hari trading terakhir
    Return (harga, prev, gain_pct) atau None kalau gagal.
    """
    try:
        # Coba v7 API dulu
        url = (f"https://query1.finance.yahoo.com/v7/finance/quote"
               f"?symbols={ticker}"
               f"&fields=regularMarketPrice,regularMarketPreviousClose,"
               f"regularMarketChangePercent,regularMarketOpen,"
               f"marketState")
        r = _http.get(url,
            headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"},
            timeout=10)
        if r.status_code == 200:
            result = r.json()["quoteResponse"]["result"]
            if result:
                q           = result[0]
                harga       = float(q.get("regularMarketPrice") or 0)
                prev_close  = float(q.get("regularMarketPreviousClose") or 0)
                gain_pct    = float(q.get("regularMarketChangePercent") or 0)
                market_state= q.get("marketState", "")  # REGULAR, PRE, POST, CLOSED

                # Kalau gain 0 dan market tidak sedang buka → pakai candle 5d
                market_open = market_state in ("REGULAR", "PRE", "POST")
                if abs(gain_pct) < 0.001 and not market_open:
                    raise ValueError("market closed, use candle fallback")

                if harga > 0 and prev_close > 0:
                    return harga, prev_close, gain_pct
    except Exception:
        pass

    # Fallback: chart 5d → intraday hari trading terakhir (open→close)
    # range=5d hanya berisi hari trading, tidak ada candle Sabtu/Minggu kosong
    try:
        url2 = (f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}"
                f"?range=5d&interval=1d")
        r2 = _http.get(url2,
            headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"},
            timeout=10)
        if r2.status_code == 200:
            res2   = r2.json()["chart"]["result"][0]
            q2     = res2["indicators"]["quote"][0]
            opens  = [o for o in q2.get("open",  []) if o is not None]
            closes = [c for c in q2.get("close", []) if c is not None]
            if opens and closes:
                last_open  = float(opens[-1])
                last_close = float(closes[-1])
                if last_open > 0:
                    gain = (last_close - last_open) / last_open * 100
                    prev = last_open
                    return last_close, prev, gain
    except Exception as e:
        logger.debug("_get_quote_realtime fallback %s: %s", ticker, e)

    return None

def _rekap_satu_saham(kode, dest_rekap, nomor=None, total=None):
    """
    Pipeline rekap satu saham → kirim SATU GAMBAR ringkasan + satu teks singkat.
    Tidak lagi kirim banyak pesan terpisah.
    """
    kode   = kode.upper()
    ticker = kode + ".JK"
    prefix = f"[{nomor}/{total}] " if nomor and total else ""
    fh = lambda v: f"{int(v):,}".replace(",",".")

    # ── FETCH DATA ────────────────────────────────────────────
    # Gain "Hari Ini" = (harga - previousClose) / previousClose
    # SAMA dengan Stockbit "Hari Ini" — bukan vs open, tapi vs close kemarin
    try:
        # Step 1: chart 1y untuk analisis teknikal
        # prev_meta = meta.previousClose dari Yahoo (= close kemarin, identik Stockbit)
        df, harga_meta, prev_meta = get_candles_tf(ticker, "1d", "1y")
        df = df.dropna()
        if len(df) < 26:
            dest_kirim_teks(dest_rekap, f"⚠️ Data chart {kode} tidak cukup"); return

        harga = float(harga_meta) if harga_meta else float(df["Close"].iloc[-1])

        # Step 2: Harga realtime + Gain "Hari Ini" vs previousClose (Stockbit style)
        gain = 0.0; prev = harga
        try:
            url1m = (f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}"
                     f"?range=1d&interval=1m")
            r1m = _http.get(url1m,
                headers={"User-Agent": "Mozilla/5.0"}, timeout=10)
            if r1m.status_code == 200:
                res1m   = r1m.json()["chart"]["result"][0]
                meta1m  = res1m["meta"]
                q1m     = res1m["indicators"]["quote"][0]

                # Harga realtime (regularMarketPrice paling akurat)
                harga_live = (meta1m.get("regularMarketPrice")
                              or ([c for c in q1m.get("close",[]) if c is not None] or [harga])[-1])
                harga = float(harga_live)

                # Baseline = previousClose (close kemarin) — IDENTIK dengan Stockbit
                prev_close_meta = (meta1m.get("chartPreviousClose")
                                   or meta1m.get("previousClose")
                                   or (float(prev_meta) if prev_meta else 0))
                if prev_close_meta and float(prev_close_meta) > 0:
                    prev = float(prev_close_meta)
                    gain = (harga - prev) / prev * 100
                else:
                    # Fallback: pakai open candle pertama kalau prev_close tidak ada
                    opens1m = [o for o in q1m.get("open", []) if o is not None]
                    if opens1m:
                        prev = float(opens1m[0])
                        gain = (harga - prev) / prev * 100 if prev > 0 else 0
        except Exception as _ge:
            logger.debug("gain intraday %s: %s", ticker, _ge)
            # Fallback terakhir: pakai prev_meta dari chart 1y
            if prev_meta and float(prev_meta) > 0:
                prev = float(prev_meta)
                gain = (harga - prev) / prev * 100

        # Step 3: Gain 5H (= "1 Minggu Terakhir" Stockbit)
        # Fetch range=5d interval=1d → ambil close bar pertama = ~5 hari lalu
        gain_5d = 0.0
        try:
            url5d = (f"https://query1.finance.yahoo.com/v8/finance/chart/{ticker}"
                     f"?range=5d&interval=1d")
            r5d = _http.get(url5d,
                headers={"User-Agent": "Mozilla/5.0"}, timeout=10)
            if r5d.status_code == 200:
                res5d   = r5d.json()["chart"]["result"][0]
                cls5d   = [c for c in res5d["indicators"]["quote"][0].get("close", [])
                           if c is not None]
                if len(cls5d) >= 2:
                    p_5d    = float(cls5d[0])   # close bar pertama = ~5 hari lalu
                    gain_5d = (harga - p_5d) / p_5d * 100 if p_5d > 0 else 0
        except Exception as _g5:
            logger.debug("gain 5d %s: %s", ticker, _g5)
            # Fallback: pakai df dari chart 1y
            if len(df) >= 6:
                p_5d    = float(df["Close"].iloc[-6])
                gain_5d = (harga - p_5d) / p_5d * 100 if p_5d > 0 else 0

    except Exception as e:
        dest_kirim_teks(dest_rekap, f"❌ Gagal ambil data {kode}: {str(e)[:60]}"); return

    dest_kirim_teks(dest_rekap, f"⏳ *REKAP {prefix}{kode}*  Rp {fh(int(harga))}  — sedang generate chart...")

    close = df["Close"]

    # ── 1. DIVERGENSI (compute, no send) ──────────────────────
    divergensi_findings = []
    try:
        n_look = min(50, len(df)-5)
        pr = close.values[-n_look:];
        dlt = close.diff()
        rsi_s = hitung_rsi_wilder(close)
        ema12 = close.ewm(span=12,adjust=False).mean()
        ema26 = close.ewm(span=26,adjust=False).mean()
        hist_s = ema12-ema26-(ema12-ema26).ewm(span=9,adjust=False).mean()
        rr = rsi_s.values[-n_look:]
        mr = hist_s.values[-n_look:]

        def _piv(arr, mode="low", w=5):
            pts=[]
            for i in range(w, len(arr)-w):
                seg=arr[i-w:i+w+1]
                if mode=="low" and arr[i]==min(seg): pts.append(i)
                if mode=="high" and arr[i]==max(seg): pts.append(i)
            return pts[-4:]

        p_lows  = _piv(pr, "low")
        p_highs = _piv(pr, "high")
        if len(p_lows)>=2:
            i1,i2=p_lows[-2],p_lows[-1]
            if pr[i2]<pr[i1] and rr[i2]>rr[i1]:
                divergensi_findings.append(("bullish", f"RSI: HL {rr[i1]:.1f}→{rr[i2]:.1f}"))
        if len(p_highs)>=2:
            i1,i2=p_highs[-2],p_highs[-1]
            if pr[i2]>pr[i1] and rr[i2]<rr[i1]:
                divergensi_findings.append(("bearish", f"RSI: LH {rr[i1]:.1f}→{rr[i2]:.1f}"))
        if len(p_lows)>=2:
            i1,i2=p_lows[-2],p_lows[-1]
            if pr[i2]<pr[i1] and mr[i2]>mr[i1]:
                if not any(d[0]=="bullish" for d in divergensi_findings):
                    divergensi_findings.append(("bullish", f"MACD: {mr[i1]:.0f}→{mr[i2]:.0f}"))
        if len(p_highs)>=2:
            i1,i2=p_highs[-2],p_highs[-1]
            if pr[i2]>pr[i1] and mr[i2]<mr[i1]:
                if not any(d[0]=="bearish" for d in divergensi_findings):
                    divergensi_findings.append(("bearish", f"MACD: {mr[i1]:.0f}→{mr[i2]:.0f}"))
    except Exception as e:
        logger.warning("rekap divergensi %s: %s", kode, e)

    # ── 2. ACCUMMF 15 HARI ────────────────────────────────────
    mf_data = None
    try:
        mf_data = hitung_accum_mf(ticker, 15)
    except Exception as e:
        logger.warning("rekap accummf %s: %s", kode, e)

    # ── 3. FIBONACCI ──────────────────────────────────────────
    fib_data = None
    try:
        df_look = df.tail(60)
        swing_high = float(df_look["High"].max())
        swing_low  = float(df_look["Low"].min())
        hi_idx = df_look["High"].idxmax()
        lo_idx = df_look["Low"].idxmin()
        is_up  = lo_idx < hi_idx
        rang   = swing_high - swing_low
        FIB_L  = [0.0, 0.236, 0.382, 0.5, 0.618, 0.786, 1.0]
        def fib_p(r):
            return swing_high - r*rang if is_up else swing_low + r*rang
        fib_data = {
            "levels": {r: fib_p(r) for r in FIB_L},
            "arah":   "Uptrend" if is_up else "Downtrend",
        }
    except Exception as e:
        logger.warning("rekap fib %s: %s", kode, e)

    # ── 4. LK SKOR ────────────────────────────────────────────
    lk_skor = None
    try:
        # Gunakan Yahoo Finance quoteSummary — SAMA dengan ambil_lk_chart_only
        crumb_q, cookie_q = get_yahoo_crumb()
        HDR_Q = {"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"}
        MODULES_Q = "defaultKeyStatistics,financialData,summaryDetail"
        fd_q = {}; ks_q = {}; sd_q = {}
        for ep_q in ["v10", "v11"]:
            try:
                url_q = f"https://query1.finance.yahoo.com/{ep_q}/finance/quoteSummary/{ticker}"
                r_q   = _http.get(url_q, headers=HDR_Q,
                                     params={"modules": MODULES_Q, "formatted": "true",
                                             **({"crumb": crumb_q} if crumb_q else {})},
                                     cookies=cookie_q or {}, timeout=15)
                res_q = (r_q.json().get("quoteSummary", {}).get("result") or [])
                if res_q:
                    fd_q = res_q[0].get("financialData", {}) or {}
                    ks_q = res_q[0].get("defaultKeyStatistics", {}) or {}
                    sd_q = res_q[0].get("summaryDetail", {}) or {}
                    if fd_q or ks_q: break
            except: pass

        def _rv_q(dicts, *keys):
            for d in dicts:
                if not isinstance(d, dict): continue
                for k in keys:
                    v = d.get(k, {})
                    if isinstance(v, dict): v = v.get("raw")
                    if v not in (None, "", "None"):
                        try: return float(str(v).replace(",",""))
                        except: pass
            return None

        raw_pe_q  = _rv_q([ks_q, sd_q], "trailingPE", "forwardPE")
        raw_pb_q  = _rv_q([ks_q],       "priceToBook")
        raw_roe_q = _rv_q([fd_q],        "returnOnEquity")
        raw_de_q  = _rv_q([fd_q],        "debtToEquity")

        # Sanitasi PE/PB untuk saham IDX (sama dengan ambil_lk_chart_only)
        if raw_pe_q and raw_pe_q > 300:  raw_pe_q = None
        if raw_pb_q and raw_pb_q > 50:   raw_pb_q = None
        # [FIX] D/E Yahoo untuk saham IDX sering dalam satuan % (mis. 47.0 = 0.47x)
        if raw_de_q is not None and raw_de_q > 20:
            raw_de_q = raw_de_q / 100

        # Hitung skor — IDENTIK dengan ambil_lk_chart_only
        skor_lk = 50
        if raw_pe_q is not None:
            if   0 < raw_pe_q < 10:       skor_lk += 20
            elif 0 < raw_pe_q < 15:       skor_lk += 15
            elif 0 < raw_pe_q < 25:       skor_lk += 5
            elif 0 < raw_pe_q < 40:       skor_lk -= 5
            elif raw_pe_q <= 0:           skor_lk -= 15  # [FIX] P/E negatif = perusahaan rugi
            else:                          skor_lk -= 15
        if raw_pb_q is not None:
            if   0 < raw_pb_q < 1.0:     skor_lk += 20
            elif 0 < raw_pb_q < 2.0:     skor_lk += 10
            elif raw_pb_q >= 4.0:        skor_lk -= 10
        if raw_roe_q is not None:
            if   raw_roe_q > 0.20:       skor_lk += 10
            elif raw_roe_q > 0.10:       skor_lk += 5
            elif raw_roe_q < 0:          skor_lk -= 10
        if raw_de_q is not None:
            if   raw_de_q < 0.5:         skor_lk += 5
            elif raw_de_q > 2.0:         skor_lk -= 10
        lk_skor = min(100, max(0, skor_lk))
        logger.info("Rekap LK %s: PE=%.1f PB=%.2f ROE=%.2f skor=%d",
                    kode, raw_pe_q or 0, raw_pb_q or 0, raw_roe_q or 0, lk_skor)
    except Exception as e:
        logger.warning("rekap lk %s: %s", kode, e)

    # ── Fetch company name ────────────────────────────────────
    co_name = ""
    try:
        import yfinance as _yf_name
        _tk_info = _yf_name.Ticker(ticker).info or {}
        co_name = _tk_info.get("longName") or _tk_info.get("shortName") or ""
    except Exception:
        pass

    # Bundle lk_data dict untuk chart
    # Ambil raw vars dari scope — sudah di-assign di blok LK Skor di atas
    # Kalau blok LK gagal, variabel tidak ter-assign → pakai None via walrus-safe
    _pe_q  = locals().get("raw_pe_q")
    _pb_q  = locals().get("raw_pb_q")
    _roe_q = locals().get("raw_roe_q")
    _de_q  = locals().get("raw_de_q")
    lk_data = {
        "skor": lk_skor,
        "pe":   _pe_q,
        "roe":  _roe_q,
        "pb":   _pb_q,
        "de":   _de_q,   # D/E ratio — dipakai dashboard chart
        "name": co_name,
    }

    # ── 5. S/R ────────────────────────────────────────────────
    sr_data = None
    try:
        sr_result = hitung_sr(df)
        if sr_result:
            # hitung_sr returns list of (type, price, count) tuples
            prices = [float(p) for (_t, p, _c) in sr_result]
            res_levels = sorted([p for p in prices if p > harga], reverse=True)
            sup_levels = sorted([p for p in prices if p <= harga], reverse=True)
            sr_data = {"resistance": res_levels, "support": sup_levels}
    except Exception as e:
        logger.warning("rekap sr %s: %s", kode, e)

    # ── KIRIM SATU GAMBAR ─────────────────────────────────────
    try:
        buf = buat_chart_rekap_summary(
            kode, df, harga, prev,
            divergensi_findings, mf_data, lk_data, fib_data, sr_data
        )
        if not buf:
            raise Exception("buat_chart_rekap_summary returned None")

        # Build caption
        bull_div = any(d[0]=="bullish" for d in divergensi_findings)
        bear_div = any(d[0]=="bearish" for d in divergensi_findings)
        div_str  = "🟢 Bullish Div" if bull_div else ("🔴 Bearish Div" if bear_div else "😴 No Div")
        cm_str   = ""
        if mf_data:
            cm      = mf_data.get("total_cm", 0)
            h_plus  = mf_data.get("hari_plus", 0)
            h_minus = mf_data.get("hari_minus", 0)
            pct     = h_plus / max(h_plus+h_minus, 1) * 100
            arah    = "Akumulasi" if cm >= 0 else "Distribusi"
            kuat    = "Kuat" if abs(cm)>1e9 else ("Sedang" if abs(cm)>3e8 else "Lemah")
            cm_str  = f"  |  💎 {arah} {kuat} ({pct:.0f}%)"
        lk_str   = f"  |  📊 Valuasi: {lk_skor:.0f}" if lk_skor else ""
        gain_sign  = "+" if gain >= 0 else ""
        gain5_sign = "+" if gain_5d >= 0 else ""
        gain5_str  = f"  |  4-5H: {gain5_sign}{gain_5d:.1f}%" if gain_5d != 0 else ""
        caption  = (
            f"🎯 *REKAP {prefix}{kode}*\n"
            f"💰 Rp {fh(int(harga))}  ({gain_sign}{gain:.2f}%){gain5_str}\n"
            f"{div_str}{cm_str}{lk_str}\n"
            f"⏰ {now_wib().strftime('%d/%m %H:%M')} WIB"
        )

        # Kirim ke dest_rekap — bisa DM, grup, atau topic
        # dest_kirim_foto_buf sudah handle semua tipe dest dengan benar
        try:
            buf.seek(0)
            dest_kirim_foto_buf(dest_rekap, buf, caption)
            logger.info("Rekap chart %s terkirim ke dest %s ✅", kode, dest_rekap)
        except Exception as _se:
            logger.error("Rekap chart %s gagal: %s", kode, _se)

        # ── AUTO TRADING PLAN — gambar chart + teks sizing ───
        try:
            sl_result = _hitung_sl_target(kode, harga, df, fib_data, sr_data)
            if sl_result:
                sl_pesan, tp_data = sl_result
                # Kirim sebagai gambar chart
                tp_buf = buat_chart_trading_plan(kode, harga, df, tp_data)
                if tp_buf:
                    dest_kirim_foto_buf(dest_rekap, tp_buf,
                        f"📐 *Trading Plan — {kode}*\n"
                        f"⏰ {now_wib().strftime('%d/%m %H:%M')} WIB")
                else:
                    # Fallback teks kalau chart gagal
                    dest_kirim_teks(dest_rekap, sl_pesan)
                # Catat ke signal_history
                db_signal_add(kode, "REKAP_SCAN", harga)
            else:
                # Guaranteed fallback: basic plan kalau _hitung_sl_target gagal
                logger.warning("rekap TP fallback %s: sl_result=None, kirim basic plan", kode)
                atr_est = harga * 0.03
                sl_fb   = round(harga * 0.95)
                t1_fb   = round(harga * 1.05)
                t2_fb   = round(harga * 1.10)
                fh_     = lambda v: f"{int(v):,}".replace(",",".")
                basic   = (f"📐 *Trading Plan — {kode}* _(estimasi dasar)_\n"
                           f"━━━━━━━━━━━━━━━━━━━━━━\n"
                           f"💰 Entry   : Rp {fh_(int(harga))}\n"
                           f"🛑 SL ~5%  : Rp {fh_(sl_fb)}\n"
                           f"🎯 T1 +5%  : Rp {fh_(t1_fb)}\n"
                           f"🎯 T2 +10% : Rp {fh_(t2_fb)}\n"
                           f"⚠️ _S/R & Fib tidak tersedia — DYOR_")
                dest_kirim_teks(dest_rekap, basic)
        except Exception as _sl_e:
            logger.warning("SL calculator %s: %s — %s", kode, type(_sl_e).__name__, _sl_e)

        # [FIX v2] Financial Dashboard dihapus — data valuasi sudah ada di rekap summary card.
        # buat_chart_rekap_dashboard() tidak dipakai lagi.


    except Exception as e:
        import traceback as _tb
        logger.error("rekap chart %s: %s\n%s", kode, e, _tb.format_exc())
        bull_div = any(d[0]=="bullish" for d in divergensi_findings)
        cm_net   = mf_data.get("total_cm", 0) if mf_data else 0
        gain_s   = "+" if gain >= 0 else ""
        err_msg  = (
            f"🎯 *REKAP {prefix}{kode}*\n"
            f"Rp {fh(int(harga))}  ({gain_s}{gain:.2f}%)\n"
            f"Div: {'🟢 Bullish' if bull_div else '😴 None'}  |  CM: {fmt_rupiah(cm_net)}\n"
            f"⚠️ Chart error: `{str(e)[:100]}`"
        )
        dest_kirim_teks(dest_rekap, err_msg)
        # Also try Chart Konfirm as fallback
        if dest_rekap.get("thread_id") != THREAD_ID_RADAR:
            dest_kirim_teks({"type":"topic","thread_id":THREAD_ID_RADAR}, err_msg)

    time.sleep(1.5)



def _detect_swings(highs, lows, length=10):
    """
    Detect swing highs/lows menggunakan pivot detection (identik logika FibStruct).
    Returns list of (index, price, 'H'|'L')
    """
    import numpy as np
    n = len(highs)
    swings = []
    for i in range(length, n - length):
        # Swing High: titik tertinggi dalam window
        if highs[i] == max(highs[i-length:i+length+1]):
            swings.append((i, highs[i], 'H'))
        # Swing Low: titik terendah dalam window
        elif lows[i] == min(lows[i-length:i+length+1]):
            swings.append((i, lows[i], 'L'))
    # Deduplicate: hapus consecutive same type, keep extreme
    deduped = []
    for s in swings:
        if deduped and deduped[-1][2] == s[2]:
            # Same type — keep the more extreme one
            if s[2] == 'H' and s[1] > deduped[-1][1]:
                deduped[-1] = s
            elif s[2] == 'L' and s[1] < deduped[-1][1]:
                deduped[-1] = s
        else:
            deduped.append(list(s))
    return deduped

def _label_market_structure(swings):
    """
    Beri label HH/HL/LH/LL pada swing points.
    Returns list of (index, price, type, label, bos_choch)
    bos_choch: None | 'BOS' | 'CHoCH'
    """
    labeled = []
    prev_h = None; prev_l = None
    trend = None  # 'bull' | 'bear'

    for idx, price, stype in swings:
        label = None; structure_event = None

        if stype == 'H':
            if prev_h is None:
                label = 'SH'
            elif price > prev_h[1]:
                label = 'HH'
                if trend == 'bear':
                    structure_event = 'CHoCH'
                    trend = 'bull'
                else:
                    structure_event = 'BOS'
                    trend = 'bull'
            else:
                label = 'LH'
                if trend == 'bull':
                    structure_event = 'CHoCH'
                    trend = 'bear'
            prev_h = (idx, price)

        elif stype == 'L':
            if prev_l is None:
                label = 'SL'
            elif price < prev_l[1]:
                label = 'LL'
                if trend == 'bull':
                    structure_event = 'CHoCH'
                    trend = 'bear'
                else:
                    structure_event = 'BOS'
                    trend = 'bear'
            else:
                label = 'HL'
                if trend == 'bear':
                    structure_event = 'CHoCH'
                    trend = 'bull'
            prev_l = (idx, price)

        labeled.append((idx, price, stype, label or stype, structure_event))

    return labeled

def _detect_eql_eqh(swings, tolerance_pct=0.003):
    """
    Detect Equal Highs (EQH) dan Equal Lows (EQL).
    tolerance_pct: harga dianggap equal jika selisih < 0.3%
    """
    eqh = []; eql = []
    highs_sw = [(i, p) for i, p, t in swings if t == 'H']
    lows_sw  = [(i, p) for i, p, t in swings if t == 'L']

    for a in range(len(highs_sw)):
        for b in range(a+1, len(highs_sw)):
            if abs(highs_sw[a][1] - highs_sw[b][1]) / highs_sw[a][1] < tolerance_pct:
                eqh.append((highs_sw[a][0], highs_sw[b][0], highs_sw[a][1]))
                break

    for a in range(len(lows_sw)):
        for b in range(a+1, len(lows_sw)):
            if abs(lows_sw[a][1] - lows_sw[b][1]) / lows_sw[a][1] < tolerance_pct:
                eql.append((lows_sw[a][0], lows_sw[b][0], lows_sw[a][1]))
                break

    return eqh, eql

def _calc_fib_levels(swing_high, swing_low):
    """Hitung Fibonacci retracement levels dari swing high ke swing low."""
    diff = swing_high - swing_low
    return {
        0.0:    swing_high,
        0.236:  swing_high - 0.236 * diff,
        0.382:  swing_high - 0.382 * diff,
        0.500:  swing_high - 0.500 * diff,
        0.618:  swing_high - 0.618 * diff,
        0.786:  swing_high - 0.786 * diff,
        1.0:    swing_low,
        -0.618: swing_high + 0.618 * diff,  # Extension target
    }

def buat_chart_trading_plan(kode, harga, df, tp_data):
    """
    Gambar trading plan: SMC/FibStruct-style chart (kiri) + tabel position sizing (kanan).
    Chart kiri menampilkan: candlestick, swing labels (HH/HL/LH/LL), BOS/CHoCH,
    Fibonacci retracement, EQH/EQL, premium/discount zones, market flow curve.
    """
    import matplotlib; matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    import matplotlib.gridspec as gridspec
    import matplotlib.patches as mpatches
    import matplotlib.patheffects as pe
    import numpy as np
    from scipy.interpolate import make_interp_spline
    _apply_dark_rc()   # [FIX v4-15]

    BG   = "#0D1117"; CARD = "#161B22"; GRN  = "#00CC55"
    RED  = "#FF3355"; YEL  = "#F9A825"; WHT  = "#E6EDF3"
    GRY  = "#8B949E"; BLU  = "#22D3EE"; ORG  = "#FF8C00"
    PRP  = "#A855F7"; TEAL = "#14B8A6"; GOLD = "#EAB308"

    sl_price      = tp_data["sl_price"]
    t1            = tp_data["t1"]
    t2            = tp_data["t2"]
    t3            = tp_data["t3"]
    rr1           = tp_data["rr1"]
    rr2           = tp_data["rr2"]
    rr3           = tp_data["rr3"]
    risk_pct      = tp_data["risk_pct"]
    modal_per_lot = tp_data["modal_per_lot"]
    total_per_lot = tp_data["total_beli_per_lot"]
    risk_per_lot  = tp_data["risk_per_lot"]

    def fh(v):
        try: return f"{int(v):,}".replace(",",".")
        except: return str(v)

    try:
        # ── DATA PREP ──────────────────────────────────────
        n_plot  = min(60, len(df))
        df_plot = df.tail(n_plot).copy()
        closes  = df_plot["Close"].values.astype(float)
        opens   = df_plot["Open"].values.astype(float)
        highs   = df_plot["High"].values.astype(float)
        lows    = df_plot["Low"].values.astype(float)
        xs      = np.arange(n_plot)

        # ── SWING DETECTION ────────────────────────────────
        swing_len = max(3, n_plot // 12)
        raw_swings = _detect_swings(highs, lows, length=swing_len)
        labeled_swings = _label_market_structure(raw_swings)
        eqh_list, eql_list = _detect_eql_eqh(raw_swings)

        # Fib: dari swing high dan swing low terbaru (bullish setup → retrace dari high ke low)
        fib_levels = None
        recent_H = [(i,p) for i,p,t,l,s in labeled_swings if t=='H']
        recent_L = [(i,p) for i,p,t,l,s in labeled_swings if t=='L']
        if recent_H and recent_L:
            # Ambil swing high & low paling kanan (terbaru) yang relevan
            last_h = recent_H[-1]; last_l = recent_L[-1]
            # Bullish retracement: dari high sebelum low terakhir
            hs_before_last_l = [(i,p) for i,p in recent_H if i < last_l[0]]
            if hs_before_last_l:
                fib_anchor_h = hs_before_last_l[-1]
                fib_anchor_l = last_l
                fib_levels = _calc_fib_levels(fib_anchor_h[1], fib_anchor_l[1])
                fib_x_start = fib_anchor_h[0]
                fib_x_end   = n_plot + 10  # extend ke kanan
            else:
                # Fallback: high dan low terbaru
                fib_levels = _calc_fib_levels(last_h[1], last_l[1])
                fib_x_start = min(last_h[0], last_l[0])
                fib_x_end   = n_plot + 10

        # ── FIGURE ─────────────────────────────────────────
        fig = plt.figure(figsize=(14, 8), facecolor=BG)
        gs  = gridspec.GridSpec(1, 2, figure=fig, width_ratios=[3, 2])
        fig.subplots_adjust(left=0.05, right=0.97, top=0.88, bottom=0.05, wspace=0.08)

        ax_c  = fig.add_subplot(gs[0])
        ax_tp = fig.add_subplot(gs[1])

        for ax in [ax_c, ax_tp]:
            ax.set_facecolor(CARD)
            ax.tick_params(colors=GRY, labelsize=7)
            for sp in ax.spines.values(): sp.set_color("#2D333B")

        # ── TITLE ──────────────────────────────────────────
        gain_prev = (harga - float(df["Close"].iloc[-2])) / float(df["Close"].iloc[-2]) * 100
        fig.suptitle(
            f"  TRADING PLAN — {kode.upper()}   Rp {fh(int(harga))}  "
            f"({'+'if gain_prev>=0 else ''}{gain_prev:.2f}%)",
            color=WHT, fontsize=13, fontweight="bold", x=0.02, ha="left", y=0.97)

        ax_c.set_title("SMC Structure + Fib Levels", color=GRY, fontsize=8, loc="left", pad=3)

        # ── PREMIUM / DISCOUNT ZONES (dari Fib) ────────────
        if fib_levels:
            mid_price = fib_levels[0.500]
            price_top = fib_levels[0.0]
            price_bot = fib_levels[1.0]
            # Premium zone: 0% – 50% (atas dari mid)
            ax_c.axhspan(mid_price, price_top, alpha=0.04, color=RED, zorder=0)
            ax_c.axhspan(price_bot, mid_price, alpha=0.04, color=GRN, zorder=0)
            # Label zona (kiri chart)
            ax_c.text(0.5, (price_top + mid_price)/2, "PREMIUM", color=RED,
                      fontsize=5.5, va="center", alpha=0.5, style="italic")
            ax_c.text(0.5, (price_bot + mid_price)/2, "DISCOUNT", color=GRN,
                      fontsize=5.5, va="center", alpha=0.5, style="italic")

        # ── FIBONACCI RETRACEMENT LINES ────────────────────
        if fib_levels:
            fib_config = {
                0.382: (BLU,    "--", 0.7, "0.382"),
                0.500: (PRP,    "--", 0.7, "0.500"),
                0.618: (GOLD,   "-",  1.0, "0.618 ●"),
                0.786: (BLU,    "--", 0.7, "0.786"),
                0.0:   (GRN,    "-",  0.5, "1.0"),
                1.0:   (RED,    "-",  0.5, "0"),
            }
            for ratio, (clr, ls, lw, label) in fib_config.items():
                price = fib_levels[ratio]
                ax_c.hlines(price, fib_x_start, fib_x_end, color=clr, lw=lw,
                            linestyle=ls, alpha=0.55, zorder=2)
                ax_c.text(fib_x_end + 0.2, price, label, color=clr,
                          fontsize=5.5, va="center", alpha=0.8)

        # ── CANDLESTICKS ───────────────────────────────────
        for i in range(n_plot):
            clr = GRN if closes[i] >= opens[i] else RED
            ax_c.plot([i,i],[lows[i],highs[i]], color=clr, lw=0.8, zorder=3)
            ax_c.bar(i, abs(closes[i]-opens[i]), bottom=min(opens[i],closes[i]),
                     color=clr, width=0.7, alpha=0.9, zorder=3)

        # ── SWING LABELS (HH / HL / LH / LL) ──────────────
        label_colors = {
            'HH': GRN, 'HL': GRN, 'LH': RED, 'LL': RED,
            'SH': WHT, 'SL': WHT
        }
        for idx, price, stype, label, struct_event in labeled_swings:
            if idx >= n_plot: continue
            clr = label_colors.get(label, GRY)
            offset = highs[idx] * 0.004 if stype == 'H' else -lows[idx] * 0.004
            va = 'bottom' if stype == 'H' else 'top'
            ax_c.text(idx, price + offset, label, color=clr,
                      fontsize=6, ha="center", va=va, fontweight="bold", zorder=5,
                      path_effects=[pe.withStroke(linewidth=1.5, foreground=CARD)])

        # ── SWING STRUCTURE LINES (koneksi swing ke swing) ─
        prev_H_pt = None; prev_L_pt = None
        for idx, price, stype, label, struct_event in labeled_swings:
            if idx >= n_plot: continue
            if stype == 'H':
                if prev_H_pt:
                    ax_c.plot([prev_H_pt[0], idx], [prev_H_pt[1], price],
                              color=GRN, lw=0.6, linestyle="--", alpha=0.35, zorder=2)
                prev_H_pt = (idx, price)
            else:
                if prev_L_pt:
                    ax_c.plot([prev_L_pt[0], idx], [prev_L_pt[1], price],
                              color=RED, lw=0.6, linestyle="--", alpha=0.35, zorder=2)
                prev_L_pt = (idx, price)

        # ── BOS / CHoCH LABELS ─────────────────────────────
        for idx, price, stype, label, struct_event in labeled_swings:
            if struct_event is None or idx >= n_plot: continue
            evt_clr = GRN if struct_event == "BOS" else YEL
            offset  = highs[idx] * 0.009 if stype == 'H' else -lows[idx] * 0.009
            va      = 'bottom' if stype == 'H' else 'top'
            # Kotak latar di belakang label
            ax_c.text(idx, price + offset, struct_event, color=evt_clr,
                      fontsize=5.5, ha="center", va=va, fontweight="bold", zorder=6,
                      bbox=dict(boxstyle="round,pad=0.15", facecolor=CARD,
                                edgecolor=evt_clr, linewidth=0.7, alpha=0.85),
                      path_effects=[pe.withStroke(linewidth=1, foreground=CARD)])

        # ── EQH / EQL LINES ────────────────────────────────
        eql_clr = PRP; eqh_clr = ORG
        for x1, x2, price in eqh_list[:2]:
            if x1 < n_plot and x2 < n_plot:
                ax_c.hlines(price, x1, min(x2+5, n_plot-1), color=eqh_clr,
                            lw=0.8, linestyle=":", alpha=0.7, zorder=4)
                ax_c.text(x2+1, price, "EQH ↑", color=eqh_clr, fontsize=5.5, va="center")
        for x1, x2, price in eql_list[:2]:
            if x1 < n_plot and x2 < n_plot:
                ax_c.hlines(price, x1, min(x2+5, n_plot-1), color=eql_clr,
                            lw=0.8, linestyle=":", alpha=0.7, zorder=4)
                ax_c.text(x2+1, price, "EQL ↓", color=eql_clr, fontsize=5.5, va="center")

        # ── MARKET FLOW CURVE (smooth spline melalui swing points) ──
        # Menggunakan swing highs+lows sebagai kontrol poin → kurva putih halus
        flow_pts = sorted([(i, p) for i,p,t,l,s in labeled_swings if i < n_plot],
                          key=lambda x: x[0])
        if len(flow_pts) >= 4:
            fx = np.array([p[0] for p in flow_pts])
            fy = np.array([p[1] for p in flow_pts])
            try:
                x_new = np.linspace(fx[0], fx[-1], 300)
                spl   = make_interp_spline(fx, fy, k=min(3, len(fx)-1))
                y_new = spl(x_new)
                ax_c.plot(x_new, y_new, color=WHT, lw=1.0, alpha=0.25,
                          linestyle="-", zorder=2)
            except Exception:
                pass

        # ── TRADING LEVEL LINES (Entry/SL/Target) ──────────
        # Shading zona profit/loss
        ax_c.axhspan(harga, t3, alpha=0.05, color=GRN, zorder=1)
        ax_c.axhspan(sl_price, harga, alpha=0.08, color=RED, zorder=1)

        tp_levels = [
            (t3,      f"T3  Rp {fh(int(t3))} (+{(t3-harga)/harga*100:.1f}%)",  GRN,      "--", 0.9),
            (t2,      f"T2  Rp {fh(int(t2))} (+{(t2-harga)/harga*100:.1f}%)",  GRN,      "--", 0.9),
            (t1,      f"T1  Rp {fh(int(t1))} (+{(t1-harga)/harga*100:.1f}%)",  "#88FF88","--", 0.8),
            (harga,   f"ENTRY  Rp {fh(int(harga))}",                            WHT,      "-",  1.3),
            (sl_price,f"SL  Rp {fh(int(sl_price))} (-{risk_pct:.1f}%)",        RED,      "--", 1.0),
        ]
        for price, label, clr, ls, lw in tp_levels:
            ax_c.axhline(y=price, color=clr, lw=lw, ls=ls, alpha=0.85, zorder=7)
            ax_c.text(n_plot + 0.4, price, label, color=clr,
                      fontsize=6.5, va="center",
                      fontweight="bold" if price==harga else "normal", zorder=8)

        ax_c.set_xlim(-1, n_plot + 20)
        ax_c.yaxis.tick_right(); ax_c.yaxis.set_label_position("right")
        ax_c.set_xticks([]); ax_c.grid(axis="y", color="#2D333B", lw=0.4, zorder=0)

        # ── TRADING PLAN PANEL ─────────────────────────────
        ax_tp.set_xticks([]); ax_tp.set_yticks([])
        ax_tp.set_xlim(0, 1); ax_tp.set_ylim(0, 1)

        y = 0.97
        # Right panel — pakai data coords (0-10 range) bukan transAxes
        ax_tp.set_xlim(0, 10); ax_tp.set_ylim(0, 10)

        def txt(x, yy, s, clr=WHT, sz=8.5, bold=False, ha="left"):
            ax_tp.text(x, yy, s, color=clr, fontsize=sz, va="top", ha=ha,
                       fontweight="bold" if bold else "normal")

        def hline(yy): ax_tp.axhline(y=yy, xmin=0.02, xmax=0.98, color="#2D333B", lw=0.8)

        y = 9.7
        txt(5, y, "TRADING PLAN", WHT, 10, bold=True, ha="center"); y -= 0.7
        txt(0.3, y, f"Entry     : Rp {fh(int(harga))}", WHT, 8.5); y -= 0.55
        txt(0.3, y, f"Stop Loss : Rp {fh(int(sl_price))}  (-{risk_pct:.1f}%)", RED, 8.5, bold=True); y -= 0.65
        hline(y + 0.1); y -= 0.15

        for t_val, t_lbl, rr_val in [(t1,"T1",rr1),(t2,"T2",rr2),(t3,"T3",rr3)]:
            rr_clr = GRN if rr_val >= 2 else (YEL if rr_val >= 1 else RED)
            emj    = "✓" if rr_val >= 2 else ("~" if rr_val >= 1 else "✗")
            txt(0.3, y, f"{t_lbl}: Rp {fh(int(t_val))}  +{(t_val-harga)/harga*100:.1f}%  R/R {rr_val:.1f}x {emj}",
                rr_clr, 8); y -= 0.55

        y -= 0.2; hline(y + 0.1); y -= 0.15
        txt(0.3, y, "POSITION SIZING", WHT, 8.5, bold=True); y -= 0.5
        txt(0.3, y, f"1 lot = 100 lbr × Rp {fh(int(harga))}", GRY, 7.5); y -= 0.42
        txt(0.3, y, f"Modal/lot : Rp {fh(int(modal_per_lot))}", WHT, 7.5); y -= 0.42
        txt(0.3, y, f"Total/lot : Rp {fh(int(total_per_lot))} (+fee)", WHT, 7.5); y -= 0.42
        txt(0.3, y, f"Risk/lot  : Rp {fh(int(risk_per_lot))}", RED, 7.5, bold=True); y -= 0.55

        hline(y + 0.1); y -= 0.1
        txt(0.3, y, "Modal", GRY, 7.5); txt(4.2, y, "1%", GRY, 7.5, ha="center")
        txt(6.5, y, "2%", GRY, 7.5, ha="center"); txt(8.8, y, "3%", GRY, 7.5, ha="center")
        y -= 0.08; hline(y + 0.05); y -= 0.38

        for modal_v, m_label in [(5e6,"5 jt"),(10e6,"10 jt"),(25e6,"25 jt"),(50e6,"50 jt")]:
            txt(0.3, y, m_label, WHT, 7.5)
            for col, rp in [(4.2,1),(6.5,2),(8.8,3)]:
                # Lot berdasarkan budget risiko (risk%)
                risk_budget    = modal_v * rp / 100
                lot_by_risk    = int(risk_budget / risk_per_lot)  if risk_per_lot  > 0 else 0
                # Lot berdasarkan kemampuan beli modal
                lot_by_capital = int(modal_v / total_per_lot)     if total_per_lot > 0 else 0
                # Ambil yang lebih kecil — tidak boleh beli melebihi modal
                lot  = min(lot_by_risk, lot_by_capital)
                clr2 = GRN if rp == 1 else (YEL if rp == 2 else ORG)
                if lot < 1:
                    txt(col, y, "❌", RED, 7.5, ha="center")
                else:
                    txt(col, y, f"{lot}L", clr2, 7.5, ha="center")
            y -= 0.42

        y -= 0.1
        txt(0.3, y, "L=lot | 1%=aman  2%=standar  3%=agresif", GRY, 6.5); y -= 0.4
        txt(0.3, y, "Fee estimasi. DYOR.", GRY, 6.5)

        # Timestamp
        fig.text(0.97, 0.01, f"{now_wib().strftime('%d/%m/%Y %H:%M')} WIB",
                 ha="right", color=GRY, fontsize=7)

        buf = io.BytesIO()
        plt.savefig(buf, format="png", dpi=130, facecolor=BG, bbox_inches="tight")
        plt.close(fig); buf.seek(0)
        return buf

    except Exception as e:
        logger.error("buat_chart_trading_plan %s: %s", kode, e)
        try: plt.close("all")
        except: pass
        return None

def _hitung_sl_target(kode, harga, df, fib_data, sr_data):
    """
    Hitung Stop Loss, Target, dan Risk/Reward otomatis.
    Prinsip profesional:
    - SL KETAT: maks 8% dari harga entry (untuk swing), idealnya 3-5%
    - SL = max dari: (support S/R terdekat, ATR 1.5x, Fib level bawah)
      TAPI tidak boleh lebih dari 8% di bawah entry
    - Target minimum R/R 1.5x dari risk
    """
    try:
        fh = lambda v: f"{int(v):,}".replace(",",".")

        # Hitung ATR 14 hari untuk baseline volatilitas (NaN-safe)
        import numpy as _np_sl
        high = _np_sl.array(df["High"].values, dtype=float)
        low  = _np_sl.array(df["Low"].values,  dtype=float)
        cls  = _np_sl.array(df["Close"].values, dtype=float)
        tr_list = []
        for i in range(1, min(15, len(cls))):
            tr_val = max(high[-i]-low[-i],
                         abs(high[-i]-cls[-i-1]),
                         abs(low[-i]-cls[-i-1]))
            if _np_sl.isfinite(tr_val):
                tr_list.append(tr_val)
        atr = sum(tr_list)/len(tr_list) if tr_list else harga * 0.03

        # Kandidat SL: support S/R, Fib 0%, ATR 1.5x
        sl_candidates = []

        # 1. Support S/R terdekat di bawah harga (maks 8% di bawah)
        if sr_data:
            for s in sr_data.get("support", [])[:5]:
                if s < harga * 0.99 and s >= harga * 0.92:
                    sl_candidates.append(s)

        # 2. Fibonacci level bawah terdekat (maks 8%)
        if fib_data:
            levels = fib_data.get("levels", {})
            for ratio in [0.236, 0.0]:
                p = levels.get(ratio)
                if p and p < harga * 0.99 and p >= harga * 0.92:
                    sl_candidates.append(p)

        # 3. ATR-based SL (1.5x ATR) — default kalau tidak ada S/R dekat
        sl_atr = harga - (atr * 1.5)

        import math as _math_sl
        if sl_candidates:
            sl_price = max(sl_candidates)
        else:
            sl_price = max(sl_atr, harga * 0.93)

        # Guard NaN/Inf sebelum round() — penyebab utama silent fail
        if not _math_sl.isfinite(sl_price) or sl_price <= 0:
            sl_price = harga * 0.93
        sl_price = round(sl_price)
        risk     = harga - sl_price
        risk_pct = risk / harga * 100

        # Kalau risk masih > 8%, paksa ke 7% (hard cap)
        if risk_pct > 8:
            sl_price = round(harga * 0.93)
            risk     = harga - sl_price
            risk_pct = risk / harga * 100

        # Ambil targets dari Fibonacci dan S/R
        res_candidates = []
        if sr_data:
            res_candidates += sr_data.get("resistance", [])[:4]
        if fib_data:
            levels = fib_data.get("levels", {})
            for ratio in [0.236, 0.382, 0.5, 0.618, 0.786, 1.0]:
                p = levels.get(ratio)
                if p and p > harga * 1.01:
                    res_candidates.append(p)

        res_candidates = sorted(set([round(r) for r in res_candidates if r > harga]))

        t1 = res_candidates[0] if len(res_candidates) >= 1 else harga * 1.05
        t2 = res_candidates[1] if len(res_candidates) >= 2 else harga * 1.10
        t3 = res_candidates[2] if len(res_candidates) >= 3 else harga * 1.15

        rr1 = (t1 - harga) / risk if risk > 0 else 0
        rr2 = (t2 - harga) / risk if risk > 0 else 0
        rr3 = (t3 - harga) / risk if risk > 0 else 0

        rr1_emj = "✅" if rr1 >= 2 else ("⚠️" if rr1 >= 1 else "❌")
        rr2_emj = "✅" if rr2 >= 2 else ("⚠️" if rr2 >= 1 else "❌")
        rr3_emj = "✅" if rr3 >= 2 else "⚠️"

        pesan  = f"🎯 *TRADING PLAN — {kode}*\n"
        pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
        pesan += f"💰 *Entry*   : Rp {fh(int(harga))}\n"
        pesan += f"🛑 *Stop Loss* : Rp {fh(int(sl_price))}  (-{risk_pct:.1f}%)\n"
        pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
        pesan += f"🎯 *Target 1*  : Rp {fh(int(t1))}  (+{(t1-harga)/harga*100:.1f}%)  R/R {rr1:.1f}x {rr1_emj}\n"
        pesan += f"🎯 *Target 2*  : Rp {fh(int(t2))}  (+{(t2-harga)/harga*100:.1f}%)  R/R {rr2:.1f}x {rr2_emj}\n"
        pesan += f"🎯 *Target 3*  : Rp {fh(int(t3))}  (+{(t3-harga)/harga*100:.1f}%)  R/R {rr3:.1f}x {rr3_emj}\n"
        pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"

        # ── POSITION SIZING ──────────────────────────────────
        # Fee beli rata-rata: 0.15% + PPN 11% = ~0.1665%
        # Fee jual rata-rata: 0.25% + PPN 11% = ~0.2775%
        FEE_BELI = 0.001665   # ~0.1665%
        FEE_JUAL = 0.002775   # ~0.2775%

        modal_per_lot     = harga * 100                         # harga pokok 1 lot
        fee_beli_per_lot  = round(modal_per_lot * FEE_BELI)     # fee beli
        total_beli_per_lot= modal_per_lot + fee_beli_per_lot    # total bayar beli

        # Risk per lot sudah termasuk fee jual di harga SL
        fee_jual_sl       = round(sl_price * 100 * FEE_JUAL)
        risk_per_lot      = risk * 100 + fee_beli_per_lot + fee_jual_sl  # real risk

        pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
        pesan += f"📐 *POSITION SIZING*\n"
        pesan += (
            f"```\n"
            f"1 lot = 100 lbr × Rp {fh(int(harga))} = Rp {fh(int(modal_per_lot))}\n"
            f"+ Fee beli (~0.17%)   = Rp {fh(int(fee_beli_per_lot))}\n"
            f"Total bayar/lot       = Rp {fh(int(total_beli_per_lot))}\n"
            f"Risk/lot (inc. fee)   = Rp {fh(int(risk_per_lot))}\n"
            f"```\n"
        )

        # Tabel sizing compact monospace
        pesan += f"\n*Position Sizing:*\n"
        pesan += "```\n"
        pesan += f"{'Modal':<7}| {'1%':>6} {'2%':>6} {'3%':>6}\n"
        pesan += f"{'─'*7}+{'─'*21}\n"
        for modal_contoh, label in [(5_000_000,"5jt"), (10_000_000,"10jt"), (25_000_000,"25jt"), (50_000_000,"50jt")]:
            row = f"{label:<7}|"
            for rp in [1, 2, 3]:
                lot = max(int(modal_contoh * rp / 100 / risk_per_lot), 1) if risk_per_lot > 0 else 1
                row += f" {lot:>5}L"
            pesan += row + "\n"
        pesan += "```\n"
        pesan += "_L=lot | 1%=aman 2%=standar 3%=agresif_\n"
        pesan += "⚠️ _Fee estimasi. DYOR._"

        return pesan, {
            "harga": harga, "sl_price": sl_price, "risk_pct": risk_pct,
            "t1": t1, "t2": t2, "t3": t3,
            "rr1": rr1, "rr2": rr2, "rr3": rr3,
            "modal_per_lot": modal_per_lot, "total_beli_per_lot": total_beli_per_lot,
            "risk_per_lot": risk_per_lot,
        }
    except Exception as e:
        logger.warning("_hitung_sl_target %s: %s — %s", kode, type(e).__name__, e)
        return None



