def proses_setuniverse(user_id, args, dest):
    """
    /setuniverse — Admin: atur universe saham untuk auto scan BSJP/BPJS.

    /setuniverse              → tampilkan pengaturan saat ini
    /setuniverse bsjp all     → semua saham di watchlist (default)
    /setuniverse bsjp lq45    → hanya LQ45
    /setuniverse bsjp idx30   → hanya IDX30
    /setuniverse bsjp BBCA,BBRI,TLKM,BMRI   → custom list
    /setuniverse bpjs lq45
    /setuniverse reset        → reset BSJP & BPJS ke default (all)
    """
    if not is_admin(user_id):
        tolak_bukan_admin(dest); return

    val_bsjp = db_kv_get("scan_universe_bsjp") or "all"
    val_bpjs = db_kv_get("scan_universe_bpjs") or "all"

    if not args:
        msg  = "🎯 *UNIVERSE AUTO SCAN*\n"
        msg += "━━━━━━━━━━━━━━━━━━━━━━\n"
        msg += f"📊 *BSJP* : `{val_bsjp}`\n"
        msg += f"🌅 *BPJS* : `{val_bpjs}`\n\n"
        msg += "*Cara ubah:*\n"
        msg += "`/setuniverse bsjp all` — semua watchlist\n"
        msg += "`/setuniverse bsjp lq45` — hanya LQ45\n"
        msg += "`/setuniverse bsjp idx30` — hanya IDX30\n"
        msg += "`/setuniverse bsjp BBCA,BBRI,TLKM` — custom list\n"
        msg += "`/setuniverse bpjs lq45` — sama untuk BPJS\n"
        msg += "`/setuniverse reset` — reset semua ke default\n\n"
        msg += f"📋 Watchlist saat ini: *{len(watchlist)} saham*"
        dest_kirim_teks(dest, msg); return

    if args[0].lower() == "reset":
        db_kv_set("scan_universe_bsjp", "all")
        db_kv_set("scan_universe_bpjs", "all")
        dest_kirim_teks(dest, "✅ Universe BSJP & BPJS direset ke *all* (semua watchlist)")
        return

    if len(args) < 2:
        dest_kirim_teks(dest, "⚠️ Format: `/setuniverse [bsjp|bpjs] [all|lq45|idx30|KODE1,KODE2,...]`")
        return

    tipe = args[0].lower()
    if tipe not in ("bsjp", "bpjs"):
        dest_kirim_teks(dest, "⚠️ Tipe harus `bsjp` atau `bpjs`"); return

    val = args[1].lower()
    if val in ("all", "lq45", "idx30"):
        db_kv_set(f"scan_universe_{tipe}", val)
        # Preview berapa saham
        universe = _get_scan_universe(tipe)
        dest_kirim_teks(dest,
            f"✅ Universe *{tipe.upper()}* diset ke *{val}*\n"
            f"📋 Jumlah saham: *{len(universe)}*\n"
            f"⏰ Berlaku di scan berikutnya")
    else:
        # Custom list — validasi format
        raw = " ".join(args[1:]).upper().replace(" ", "")
        kodes = [k.strip() for k in raw.split(",") if k.strip()]
        if not kodes:
            dest_kirim_teks(dest, "⚠️ Format custom: `BBCA,BBRI,TLKM,...`"); return
        val_save = ",".join(kodes)
        db_kv_set(f"scan_universe_{tipe}", val_save)
        dest_kirim_teks(dest,
            f"✅ Universe *{tipe.upper()}* diset ke custom list:\n"
            f"📋 *{len(kodes)} saham*: {val_save[:100]}{'...' if len(val_save)>100 else ''}\n"
            f"⏰ Berlaku di scan berikutnya")

def auto_scan_bsjp_kirim(dest=None):
    """Scan BSJP dan DM ke semua member + simpan cache."""
    label = "🌆 BSJP — REKOMENDASI BELI SORE"
    universe = _get_scan_universe("bsjp")
    kandidat = []
    with ThreadPoolExecutor(max_workers=12) as _ex:
        _futs = {_ex.submit(scan_bsjp_kriteria, tk): tk for tk in universe}
        for _f in as_completed(_futs):
            try:
                h = _f.result(timeout=20)
                if h: kandidat.append(h)
            except: pass
    kandidat.sort(key=lambda x: x["skor"], reverse=True)
    top = kandidat[:10]
    if not top:
        if dest: dest_kirim_teks(dest, "😴 Tidak ada kandidat BSJP hari ini.")
        return
    _simpan_cache_scan("bsjp", top)
    def fh(v): return f"{int(v):,}".replace(",",".")
    pesan  = f"🌆 *BSJP — REKOMENDASI BELI SORE*\n"
    pesan += f"📅 {now_wib().strftime('%d/%m/%Y %H:%M')} WIB\n"
    pesan += f"💡 _Beli sore hari ini, jual pagi besok_\n"
    pesan += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
