def auto_scan_bpjs_kirim(dest=None):
    """Scan BPJS dan DM ke semua member + simpan cache."""
    label = "🌅 BPJS — REKOMENDASI BELI PAGI"
    universe = _get_scan_universe("bpjs")
    kandidat = []
    with ThreadPoolExecutor(max_workers=12) as _ex:
        _futs = {_ex.submit(scan_bpjs_kriteria, tk): tk for tk in universe}
        for _f in as_completed(_futs):
            try:
                h = _f.result(timeout=20)
                if h: kandidat.append(h)
            except: pass
    kandidat.sort(key=lambda x: x["skor"], reverse=True)
    top = kandidat[:10]
    if not top:
        if dest: dest_kirim_teks(dest, "😴 Tidak ada kandidat BPJS hari ini.")
