def auto_scan_bsjp():
    logger.info("🌆 Auto BSJP scan dimulai...")
    auto_scan_bsjp_kirim(dest=None)
    logger.info("🌆 Auto BSJP scan selesai")

def auto_scan_bpjs():
    logger.info("🌅 Auto BPJS scan dimulai...")
    auto_scan_bpjs_kirim(dest=None)
    logger.info("🌅 Auto BPJS scan selesai")

def cek_jadwal_bsjp_bpjs_auto():
    now     = now_wib()
    hari    = now.weekday()
    if hari > 4: return          # skip weekend
    if bot_stop:   return        # skip jika bot di-stop
    jam_mnt = now.strftime("%H:%M")
    tgl_str = now.strftime("%Y-%m-%d")

    if jam_mnt == "15:00":
        key = f"bsjp_auto_{tgl_str}"
        if key not in jadwal_sudah_scan:
            jadwal_sudah_scan.add(key)
            logger.info("⏰ Jadwal BSJP auto triggered jam 15:00")
            threading.Thread(target=auto_scan_bsjp, daemon=True).start()

    if jam_mnt == "09:15":
        key = f"bpjs_auto_{tgl_str}"
        if key not in jadwal_sudah_scan:
            jadwal_sudah_scan.add(key)
            threading.Thread(target=auto_scan_bpjs, daemon=True).start()


