def get_ihsg_snapshot():
    """Ambil data IHSG dari IDX API."""
    try:
        HDR = {"User-Agent": "Mozilla/5.0", "Referer": "https://www.idx.co.id/"}
        # Coba endpoint IDX composite index
        urls = [
            "https://www.idx.co.id/primary/TradingSummary/GetStockSummary?stockCode=COMPOSITE",
            "https://idx.co.id/umbraco/Surface/StockData/GetStockSummary?stockCode=COMPOSITE",
        ]
        for url in urls:
            try:
                r = _http.get(url, headers=HDR, timeout=10)
                if r.status_code == 200:
                    d = r.json()
                    if d:
                        return d
            except: continue
    except: pass

    # Fallback: ambil dari yfinance IDX composite
    try:
        import yfinance as yf
        t = yf.Ticker("^JKSE")
        hist = _silent_history(t, period="2d")
        if not hist.empty:
            harga = float(hist["Close"].iloc[-1])
            prev  = float(hist["Close"].iloc[-2]) if len(hist) >= 2 else harga
            gain  = (harga - prev) / prev * 100
            return {"harga": harga, "prev": prev, "gain": gain, "source": "yf"}
    except: pass
    return None


# ============================================================
# --- /data KODE — Tabel Data Historis dari Yahoo Finance  ---
# ============================================================

def proses_cmd_data(kode_raw, dest, period_arg="10d"):
    """
    /data KODE [period]
    Tampilkan tabel OHLCV historis + ringkasan teknikal.
    Aman: pakai API chart v8 (bukan scrape HTML), delay 0.4 s,
    User-Agent browser, output teks biasa (bukan file/foto).

    Contoh:
        /data ihsg        -> 10 hari terakhir IHSG
        /data bbca        -> 10 hari terakhir BBCA.JK
        /data bbca 1mo    -> 1 bulan harian BBCA.JK
        /data ihsg 3mo    -> 3 bulan IHSG interval mingguan
    """
    import time as _t
    import pandas as pd

    kode = kode_raw.upper().strip()

    # Resolve ticker
    if kode in ("IHSG", "^JKSE", "JKSE"):
        ticker    = "^JKSE"
        nama_tpl  = "IHSG (^JKSE)"
    else:
        ticker    = kode + ".JK"
        nama_tpl  = kode

    # Resolve period & interval
    PERIOD_MAP = {
        "1d" : ("1d",  "5m",  "5 Menit",   True),
        "5d" : ("5d",  "15m", "15 Menit",  True),
        "1mo": ("1mo", "1d",  "Harian",    False),
        "3mo": ("3mo", "1wk", "Mingguan",  False),
        "6mo": ("6mo", "1wk", "Mingguan",  False),
        "1y" : ("1y",  "1mo", "Bulanan",   False),
        "2y" : ("2y",  "1mo", "Bulanan",   False),
        "5y" : ("5y",  "3mo", "Kuartalan", False),
    }
    p_key = period_arg.lower().strip() if period_arg else "10d"
    if p_key == "10d" or p_key not in PERIOD_MAP:
        rng       = "1mo"
        interval  = "1d"
        tf_lbl    = "Harian"
        limit_rows = 10
    else:
        rng, interval, tf_lbl, _ = PERIOD_MAP[p_key]
        limit_rows = None

    dest_kirim_teks(dest, "📊 Mengambil data *" + nama_tpl + "* (" + tf_lbl + ")...")

    # Fetch dari Yahoo Finance Chart API v8
    # Endpoint yang sama dipakai seluruh bot — aman & konsisten
    HDRS = {
        "User-Agent": (
            "Mozilla/5.0 (Windows NT 10.0; Win64; x64) "
            "AppleWebKit/537.36 (KHTML, like Gecko) "
            "Chrome/124.0.0.0 Safari/537.36"
        ),
        "Accept"         : "application/json, text/plain, */*",
        "Accept-Language": "en-US,en;q=0.9",
        "Referer"        : "https://finance.yahoo.com/",
    }
    _base_params = "?range=" + rng + "&interval=" + interval + "&includePrePost=false"
    url  = "https://query1.finance.yahoo.com/v8/finance/chart/" + ticker + _base_params
    url2 = "https://query2.finance.yahoo.com/v8/finance/chart/" + ticker + _base_params

    res = None
    _fetch_err = None
    try:
        _t.sleep(0.4)
        resp = _http.get(url, headers=HDRS, timeout=15)
        # Fallback ke query2 jika query1 ditolak
        if resp.status_code in (401, 403, 404):
            resp = _http.get(url2, headers=HDRS, timeout=15)
        resp.raise_for_status()
        data = resp.json()
        res  = data["chart"]["result"][0]
    except Exception as _e1:
        _fetch_err = _e1

    if res is None:
        # Final fallback: yfinance library
        try:
            import yfinance as _yf
            _ydf = _silent_yf_download(ticker, period=rng, interval=interval,
                                progress=False, auto_adjust=True)
            if _ydf is None or _ydf.empty:
                raise ValueError("empty")
            _ydf.columns = [c[0] if isinstance(c, tuple) else c for c in _ydf.columns]
            _ydf.index   = pd.to_datetime(_ydf.index)
            if _ydf.index.tz is None:
                _ydf.index = _ydf.index.tz_localize("UTC").tz_convert("Asia/Jakarta")
            else:
                _ydf.index = _ydf.index.tz_convert("Asia/Jakarta")
            _ydf.dropna(inplace=True)
            if _ydf.empty: raise ValueError("empty after dropna")
            res = {"_ydf": _ydf}
        except Exception:
            dest_kirim_teks(dest, "❌ Gagal ambil data *" + nama_tpl + "*: "
                            + str(_fetch_err)[:80])
            return

    try:
        # Handle yfinance fallback path
        if "_ydf" in res:
            df   = res["_ydf"]
            meta = {}
        else:
            ts   = res["timestamp"]
            q    = res["indicators"]["quote"][0]
            meta = res.get("meta", {})

            df = pd.DataFrame({
                "Open"  : q.get("open",   [None] * len(ts)),
                "High"  : q.get("high",   [None] * len(ts)),
                "Low"   : q.get("low",    [None] * len(ts)),
                "Close" : q.get("close",  [None] * len(ts)),
                "Volume": q.get("volume", [None] * len(ts)),
            }, index=pd.to_datetime(ts, unit="s", utc=True).tz_convert("Asia/Jakarta"))
            df.dropna(inplace=True)

        if df.empty:
            dest_kirim_teks(dest, "\u274c Data *" + nama_tpl + "* kosong atau ticker tidak ditemukan.")
            return

        if limit_rows and len(df) > limit_rows:
            df = df.tail(limit_rows)

        # Harga & gain hari ini
        harga_now  = float(meta.get("regularMarketPrice") or df["Close"].iloc[-1])
        prev_close = float(meta.get("previousClose") or meta.get("chartPreviousClose") or 0)
        if prev_close <= 0 and len(df) >= 2:
            prev_close = float(df["Close"].iloc[-2])
        gain_1d  = (harga_now - prev_close) / prev_close * 100 if prev_close > 0 else 0
        arah_emj = "\U0001f4c8" if gain_1d >= 0 else "\U0001f4c9"

        # Format helpers
        def fh(v):
            if v is None or (isinstance(v, float) and v != v): return "\u2014"
            if v >= 1_000_000: return "{:.2f}M".format(v / 1_000_000)
            if v >= 1_000:     return "{:,}".format(int(v)).replace(",", ".")
            return str(int(v))

        def fvol(v):
            if v is None or v <= 0: return "\u2014"
            if v >= 1_000_000_000: return "{:.1f}B".format(v / 1_000_000_000)
            if v >= 1_000_000:     return "{:.1f}M".format(v / 1_000_000)
            if v >= 1_000:         return "{:.0f}K".format(v / 1_000)
            return str(int(v))

        # Ringkasan periode
        h_max    = float(df["High"].max())
        h_min    = float(df["Low"].min())
        h_open   = float(df["Open"].iloc[0])
        h_close  = float(df["Close"].iloc[-1])
        gain_per = (h_close - h_open) / h_open * 100 if h_open > 0 else 0
        vol_vals = df["Volume"].replace(0, None).dropna()
        vol_avg  = float(vol_vals.mean()) if not vol_vals.empty else 0
        n_rows   = len(df)
        tgl_dari = df.index[0].strftime("%d/%m/%y")
        tgl_ke   = df.index[-1].strftime("%d/%m/%y")

        SEP = "\u2501" * 26

        # Header
        baris = []
        baris.append("\U0001f4ca *DATA " + nama_tpl + "*")
        baris.append("\U0001f4c5 " + tgl_dari + " s/d " + tgl_ke + "  (" + str(n_rows) + " candle " + tf_lbl + ")")
        baris.append(SEP)
        baris.append("\U0001f4b0 Harga    : Rp " + fh(harga_now) + "  " + arah_emj + " " + "{:+.2f}".format(gain_1d) + "% (1D)")
        baris.append("\U0001f4c8 High     : Rp " + fh(h_max))
        baris.append("\U0001f4c9 Low      : Rp " + fh(h_min))
        gain_emj2 = "\U0001f7e2" if gain_per >= 0 else "\U0001f534"
        baris.append(gain_emj2 + " Gain per : " + "{:+.2f}".format(gain_per) + "% (" + tgl_dari + "\u2192" + tgl_ke + ")")
        if vol_avg > 0:
            baris.append("\U0001f4e6 Vol avg  : " + fvol(vol_avg))
        baris.append(SEP)

        # Header tabel
        baris.append("`" + "{:<7}".format("Tgl") + " " + "{:>8}".format("Close") + " " + "{:>7}".format("Gain") + " " + "{:>7}".format("Vol") + "`")

        # Baris candle
        prev_c = None
        for idx, row in df.iterrows():
            tgl_str = idx.strftime("%d/%m")
            c = row["Close"]
            v = row["Volume"]
            if prev_c is not None and prev_c > 0:
                g = (c - prev_c) / prev_c * 100
                g_str = "{:+.1f}%".format(g)
                emj = "\U0001f7e2" if g >= 0 else "\U0001f534"
            else:
                g_str = "  \u2014  "
                emj = "\u2b1c"
            prev_c = c
            baris.append(
                "`" + "{:<7}".format(tgl_str) + " " + "{:>8}".format(fh(c)) + " " + "{:>7}".format(g_str) + "` "
                + emj + " `" + "{:>6}".format(fvol(v)) + "`"
            )

        baris.append("")
        baris.append("⚠️ _Bukan saran investasi. DYOR._")

        dest_kirim_teks(dest, "\n".join(baris))

    except Exception as e:
        import traceback
        traceback.print_exc()
        dest_kirim_teks(dest, "\u274c Parse data *" + nama_tpl + "* gagal: " + str(e)[:80])


def kirim_ihsg(dest):
    """Kirim snapshot IHSG ke dest."""
    import datetime as _dt2
    now = now_wib()
    tgl = now.strftime("%d/%m/%Y")
    jam = now.strftime("%H:%M")

    # Coba ambil data real IDX
    try:
        HDR = {"User-Agent": "Mozilla/5.0", "Referer": "https://www.idx.co.id/"}
        r = _http.get(
            "https://www.idx.co.id/primary/TradingSummary/GetMarketSummary",
            headers=HDR, timeout=12)
        if r.status_code == 200:
            d = r.json()
            # Coba berbagai format respon IDX
            ihsg = (d.get("CompositeIndex") or d.get("IHSG") or
                    d.get("IndexValue") or d.get("composite") or {})
            advance = d.get("Advance") or d.get("advance") or 0
            decline = d.get("Decline") or d.get("decline") or 0
            unchanged = d.get("Unchanged") or d.get("unchanged") or 0
            for_buy = d.get("ForeignBuy") or d.get("foreignBuy") or 0
            for_sell = d.get("ForeignSell") or d.get("foreignSell") or 0
            nilai_ihsg = (ihsg.get("IndexValue") or ihsg.get("Close") or
                         ihsg.get("value") or 0) if isinstance(ihsg, dict) else (ihsg or 0)
            prev_ihsg  = (ihsg.get("PreviousValue") or ihsg.get("Open") or
                         ihsg.get("prev") or 0) if isinstance(ihsg, dict) else 0
            if nilai_ihsg > 0:
                gain_ihsg = (nilai_ihsg - prev_ihsg) / prev_ihsg * 100 if prev_ihsg else 0
                emj = "🟢" if gain_ihsg >= 0 else "🔴"
                arrow = "▲" if gain_ihsg >= 0 else "▼"
                def fmt_milis(v):
                    v = abs(float(v)) if v else 0
                    if v >= 1e12: return f"Rp {v/1e12:.2f}T"
                    if v >= 1e9:  return f"Rp {v/1e9:.1f}M"
                    if v >= 1e6:  return f"Rp {v/1e6:.0f}jt"
                    return f"Rp {int(v):,}"
                for_net = float(for_buy) - float(for_sell)
                for_emj = "🟢" if for_net >= 0 else "🔴"
                pesan  = f"📊 *IHSG SNAPSHOT*\n"
                pesan += f"📅 {tgl}  ⏰ {jam} WIB\n"
                pesan += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
                pesan += f"{emj} *IHSG:* `{nilai_ihsg:,.2f}` {arrow} {gain_ihsg:+.2f}%\n"
                if advance or decline:
                    total_saham = int(advance) + int(decline) + int(unchanged)
                    pesan += f"📈 Advance : *{int(advance):,}* saham\n"
                    pesan += f"📉 Decline : *{int(decline):,}* saham\n"
                    pesan += f"➡️ Unchanged: *{int(unchanged):,}* saham\n"
                if for_buy or for_sell:
                    pesan += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
                    pesan += f"🌍 *Foreign Flow:*\n"
                    pesan += f"  Buy  : `{fmt_milis(for_buy)}`\n"
                    pesan += f"  Sell : `{fmt_milis(for_sell)}`\n"
                    pesan += f"  Net  : {for_emj} `{fmt_milis(for_net)}`\n"
                pesan += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
                pesan += f"⏰ Data: {jam} WIB"
                dest_kirim_teks(dest, pesan)
                return
    except Exception as e:
        print(f"   IHSG API error: {e}")

    # Fallback: Yahoo Finance direct HTTP (tanpa library yfinance)
    try:
        url_yf = "https://query1.finance.yahoo.com/v8/finance/chart/%5EJKSE?range=5d&interval=1d"
        r2 = _http.get(url_yf,
            headers={"User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64)"},
            timeout=12)
        if r2.status_code == 200:
            res2 = r2.json()["chart"]["result"][0]
            meta2 = res2["meta"]
            harga = float(meta2.get("regularMarketPrice") or meta2.get("previousClose") or 0)
            prev  = float(meta2.get("previousClose") or harga)
            vol   = float(meta2.get("regularMarketVolume") or 0)
            if harga > 0:
                gain  = (harga - prev) / prev * 100 if prev > 0 else 0
                emj   = "🟢" if gain >= 0 else "🔴"
                arrow = "▲" if gain >= 0 else "▼"
                pesan  = f"📊 *IHSG SNAPSHOT*\n"
                pesan += f"📅 {tgl}  ⏰ {jam} WIB\n"
                pesan += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
                pesan += f"{emj} *IHSG:* `{harga:,.2f}` {arrow} {gain:+.2f}%\n"
                pesan += f"📅 Prev Close: `{prev:,.2f}`\n"
                if vol: pesan += f"📊 Volume : `{int(vol):,}`\n"
                # Coba dapat advance/decline dari IDX endpoint lain
                try:
                    r3 = _http.get(
                        "https://www.idx.co.id/primary/TradingSummary/GetTradingSummary",
                        headers={"User-Agent":"Mozilla/5.0","Referer":"https://www.idx.co.id/"},
                        timeout=8)
                    if r3.status_code == 200:
                        d3 = r3.json()
                        adv = d3.get("Advance") or d3.get("advance") or 0
                        dec = d3.get("Decline") or d3.get("decline") or 0
                        if adv or dec:
                            pesan += f"📈 Advance: *{int(adv)}*  📉 Decline: *{int(dec)}*\n"
                except: pass
                pesan += f"⏰ {jam} WIB"
                dest_kirim_teks(dest, pesan)
                return
    except Exception as e:
        logger.warning("IHSG Yahoo fallback error: %s", e)

    dest_kirim_teks(dest,
        f"📊 *IHSG*\n"
        f"❌ Data real-time tidak tersedia saat ini.\n"
        f"_Cek manual di idx.co.id atau RTI Business_")


