# --- FUNGSI /porto — PORTFOLIO TRACKER ---
# ============================================================

PORTO_FILE = os.path.join(DATA_DIR, "porto_member.json")  # kept for reference — now using SQLite

def _load_porto():
    """Backward-compat: baca porto dari SQLite, return format lama."""
    with _db_lock:
        conn = _db_conn(); c = conn.cursor()
        c.execute("SELECT user_id, kode, harga_beli, lot, tgl FROM porto")
        rows = c.fetchall(); conn.close()
    result = {}
    for uid, kode, hb, lot, tgl in rows:
        if uid not in result:
            result[uid] = {}
        result[uid][kode] = {"harga_beli": hb, "lot": lot, "tgl": tgl}
    return result

def _save_porto(data):
    """Backward-compat: sync dict ke SQLite (bulk overwrite per user)."""
    try:
        with _db_lock:
            conn = _db_conn(); c = conn.cursor()
            for uid, posisi in data.items():
                c.execute("DELETE FROM porto WHERE user_id=?", (uid,))
                for kode, pos in posisi.items():
                    c.execute("INSERT OR REPLACE INTO porto VALUES(?,?,?,?,?)",
                              (uid, kode, pos["harga_beli"], pos["lot"],
                               pos.get("tgl", now_wib().strftime("%d/%m/%Y"))))
            conn.commit(); conn.close()
    except Exception as e:
        logger.error("_save_porto: %s", e)


# ──────────────────────────────────────────────────────────
# AI CHART READING — /aichart KODE [TF]
# ──────────────────────────────────────────────────────────
def proses_ai_chart(kode, tf_input, user_id, dest):
    """
    Generate chart saham, kirim ke Claude AI untuk analisis visual.
    Claude akan membaca pola candlestick, tren, support/resistance,
    dan berikan rekomendasi entry/exit dalam bahasa natural.
    """
    if not ANTHROPIC_API_KEY or "GANTI_DENGAN" in ANTHROPIC_API_KEY:
        dest_kirim_teks(dest, "❌ ANTHROPIC_API_KEY belum diisi di script."); return

    kode   = kode.upper()
    ticker = kode + ".JK"
    tf_key = tf_input.lower() if tf_input else "1d"

    dest_kirim_teks(dest, f"*▸ AI Chart Reading* — Menganalisis *{kode}*...\n_Harap tunggu 10-20 detik_")

    try:
        # Buat chart
        df, harga, prev = get_candles_tf(ticker, tf_key, "3mo")
        if len(df) < 10:
            dest_kirim_teks(dest, f"❌ Data {kode} tidak cukup"); return

        sr_levels = hitung_sr(df)
        sr_clean  = [(t, p, c) for t, p, c in sr_levels] if sr_levels else []
        eng_info  = cek_engulfing_df(df)

        tf_label  = tf_key.upper()
        buf = buat_chart_c(ticker, df, harga, tf_key, tf_label, sr_clean, eng_info)
        if not buf:
            dest_kirim_teks(dest, f"❌ Gagal buat chart {kode}"); return

        # Encode ke base64
        import base64 as _b64
        buf.seek(0)
        img_b64 = _b64.b64encode(buf.read()).decode("utf-8")

        # Hitung indikator ringkas untuk context
        close  = df["Close"]
        rsi    = float(hitung_rsi_wilder(close).iloc[-1])
        ema20  = float(close.ewm(span=20, adjust=False).mean().iloc[-1])
        ema50  = float(close.ewm(span=50, adjust=False).mean().iloc[-1])
        gain   = (harga - prev)/prev*100 if prev > 0 else 0

        ema12  = close.ewm(span=12, adjust=False).mean()
        ema26  = close.ewm(span=26, adjust=False).mean()
        macd_h = float((ema12-ema26-(ema12-ema26).ewm(span=9,adjust=False).mean()).iloc[-1])

        context = (
            f"Saham: {kode} (IDX Indonesia)\n"
            f"Harga: Rp {int(harga):,} | Gain hari ini: {gain:+.2f}%\n"
            f"RSI(14): {rsi:.1f} | MACD Hist: {macd_h:+.2f}\n"
            f"EMA20: {int(ema20):,} | EMA50: {int(ema50):,}\n"
            f"Harga vs EMA20: {'ATAS' if harga > ema20 else 'BAWAH'}\n"
            f"Timeframe: {tf_label}"
        )

        prompt = (
            f"Kamu adalah analis teknikal profesional saham IDX Indonesia.\n\n"
            f"Analisis chart berikut untuk saham {kode}:\n{context}\n\n"
            f"Berikan analisis dalam format:\n"
            f"1. **Tren saat ini** — uptrend/downtrend/sideways, jelaskan singkat\n"
            f"2. **Pola candlestick** — pola yang terlihat dan artinya\n"
            f"3. **Support & Resistance** — level kunci yang terlihat di chart\n"
            f"4. **Sinyal teknikal** — RSI, MACD, volume — bullish/bearish/neutral\n"
            f"5. **Rekomendasi** — entry ideal, stop loss, target\n"
            f"6. **Risiko** — apa yang perlu diwaspadai\n\n"
            f"Gunakan bahasa Indonesia yang ringkas dan profesional. Maksimal 400 kata."
        )

        # Call Claude Vision API
        resp = _http.post(
            "https://api.anthropic.com/v1/messages",
            headers={
                "x-api-key":         ANTHROPIC_API_KEY,
                "anthropic-version": "2023-06-01",
                "content-type":      "application/json",
            },
            json={
                "model":      "claude-opus-4-5",
                "max_tokens": 1024,
                "messages": [{
                    "role": "user",
                    "content": [
                        {"type": "image",
                         "source": {"type": "base64", "media_type": "image/png", "data": img_b64}},
                        {"type": "text", "text": prompt},
                    ]
                }]
            },
            timeout=60
        )

        if resp.status_code != 200:
            dest_kirim_teks(dest, f"❌ AI API error {resp.status_code}"); return

        ai_text = resp.json()["content"][0]["text"]

        # Kirim chart + analisis AI
        buf.seek(0)
        caption = f"🤖 *AI Chart Analysis — {kode}*\n⏰ {now_wib().strftime('%H:%M')} WIB"
        dest_kirim_foto_buf(dest, buf, caption)

        # Kirim teks analisis (potong kalau terlalu panjang)
        if len(ai_text) > 3800:
            ai_text = ai_text[:3800] + "...\n_(dipotong)_"

        dest_kirim_teks(dest,
            f"🤖 *Analisis AI — {kode}*\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"{ai_text}\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"⚠️ _AI analysis — bukan saran investasi. DYOR._")

    except Exception as e:
        logger.error("proses_ai_chart %s: %s", kode, e)
        dest_kirim_teks(dest, f"❌ AI Chart error: `{str(e)[:80]}`")


