def db_paper_setup():
    """Buat tabel paper trading di SQLite."""
    try:
        conn = sqlite3.connect(DB_FILE, check_same_thread=False)
        c = conn.cursor()
        c.execute("""CREATE TABLE IF NOT EXISTS paper_positions(
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            user_id     TEXT NOT NULL,
            kode        TEXT NOT NULL,
            lot         INTEGER NOT NULL,
            harga_beli  REAL NOT NULL,
            harga_sl    REAL,
            harga_t1    REAL,
            harga_t2    REAL,
            ts_beli     REAL NOT NULL,
            status      TEXT DEFAULT 'OPEN',
            harga_jual  REAL,
            ts_jual     REAL,
            profit_rp   REAL,
            profit_pct  REAL
        )""")
        c.execute("""CREATE TABLE IF NOT EXISTS paper_balance(
            user_id TEXT PRIMARY KEY,
            saldo   REAL DEFAULT 100000000
        )""")
        conn.commit(); conn.close()
    except Exception as e:
        logger.error("db_paper_setup: %s", e)

db_paper_setup()

def paper_get_balance(user_id):
    try:
        conn = sqlite3.connect(DB_FILE, check_same_thread=False)
        c = conn.cursor()
        c.execute("INSERT OR IGNORE INTO paper_balance(user_id,saldo) VALUES(?,?)", (str(user_id), 100_000_000))
        c.execute("SELECT saldo FROM paper_balance WHERE user_id=?", (str(user_id),))
        row = c.fetchone(); conn.commit(); conn.close()
        return row[0] if row else 100_000_000
    except: return 100_000_000

def paper_set_balance(user_id, saldo):
    try:
        conn = sqlite3.connect(DB_FILE, check_same_thread=False)
        c = conn.cursor()
        c.execute("INSERT OR REPLACE INTO paper_balance(user_id,saldo) VALUES(?,?)", (str(user_id), saldo))
        conn.commit(); conn.close()
    except Exception as e: logger.error("paper_set_balance: %s", e)

def paper_get_positions(user_id, status="OPEN"):
    try:
        conn = sqlite3.connect(DB_FILE, check_same_thread=False)
        c = conn.cursor()
        c.execute("""SELECT id,kode,lot,harga_beli,harga_sl,harga_t1,harga_t2,ts_beli
                     FROM paper_positions WHERE user_id=? AND status=?
                     ORDER BY ts_beli DESC""", (str(user_id), status))
        rows = c.fetchall(); conn.close()
        return rows
    except: return []

def proses_paper(user_id, args, dest):
    """
    /paper buy KODE LOT [SL=xxx] [T1=xxx]
    /paper sell KODE [LOT]
    /paper porto
    /paper history
    /paper reset
    Modal awal: Rp 100.000.000 (virtual)
    """
    fh  = lambda v: f"{int(v):,}".replace(",",".")
    uid = str(user_id)

    if not args:
        pesan  = "📋 *PAPER TRADING*\n"
        pesan += "Modal virtual Rp 100 juta untuk latihan trading\n\n"
        pesan += "*Perintah:*\n"
        pesan += "`/paper buy KODE LOT` — beli saham\n"
        pesan += "`/paper buy KODE LOT SL=xxx` — beli + set SL\n"
        pesan += "`/paper sell KODE` — jual semua posisi\n"
        pesan += "`/paper sell KODE LOT` — jual sebagian\n"
        pesan += "`/paper porto` — lihat portofolio\n"
        pesan += "`/paper history` — riwayat transaksi\n"
        pesan += "`/paper reset` — reset ke 100jt\n"
        dest_kirim_teks(dest, pesan); return

    sub = args[0].lower()

    # BUY
    if sub == "buy" and len(args) >= 3:
        kode_p = args[1].upper()
        try: lot_p = int(args[2])
        except:
            dest_kirim_teks(dest, "❌ Format: `/paper buy KODE LOT`"); return

        # Parse optional SL dan T1
        sl_p = t1_p = t2_p = None
        for a in args[3:]:
            a_up = a.upper()
            try:
                if a_up.startswith("SL="):  sl_p = float(a_up[3:])
                elif a_up.startswith("T1="): t1_p = float(a_up[3:])
                elif a_up.startswith("T2="): t2_p = float(a_up[3:])
            except: pass

        try:
            df_p, harga_p, _ = get_candles_tf(kode_p+".JK", "1d", "5d")
            harga_p = float(harga_p)
        except:
            dest_kirim_teks(dest, f"❌ Gagal ambil harga {kode_p}"); return

        modal_needed = harga_p * lot_p * 100
        saldo        = paper_get_balance(uid)

        if modal_needed > saldo:
            dest_kirim_teks(dest,
                f"❌ Saldo tidak cukup\n"
                f"Perlu: Rp {fh(int(modal_needed))}\n"
                f"Saldo: Rp {fh(int(saldo))}"); return

        # Simpan posisi
        try:
            conn = sqlite3.connect(DB_FILE, check_same_thread=False)
            c = conn.cursor()
            c.execute("""INSERT INTO paper_positions
                (user_id,kode,lot,harga_beli,harga_sl,harga_t1,harga_t2,ts_beli,status)
                VALUES(?,?,?,?,?,?,?,?,?)""",
                (uid, kode_p, lot_p, harga_p, sl_p, t1_p, t2_p, time.time(), "OPEN"))
            conn.commit(); conn.close()
            paper_set_balance(uid, saldo - modal_needed)

            pesan  = f"✅ *PAPER BUY — {kode_p}*\n"
            pesan += f"💰 Harga beli : Rp {fh(int(harga_p))}\n"
            pesan += f"📦 Lot        : {lot_p} lot ({lot_p*100:,} lembar)\n"
            pesan += f"💸 Modal      : Rp {fh(int(modal_needed))}\n"
            if sl_p:  pesan += f"🛑 Stop Loss  : Rp {fh(int(sl_p))}  ({(sl_p-harga_p)/harga_p*100:+.1f}%)\n"
            if t1_p:  pesan += f"🎯 Target 1   : Rp {fh(int(t1_p))}  ({(t1_p-harga_p)/harga_p*100:+.1f}%)\n"
            if t2_p:  pesan += f"🎯 Target 2   : Rp {fh(int(t2_p))}  ({(t2_p-harga_p)/harga_p*100:+.1f}%)\n"
            pesan += f"🏦 Sisa saldo : Rp {fh(int(saldo-modal_needed))}"
            dest_kirim_teks(dest, pesan)
        except Exception as e:
            dest_kirim_teks(dest, f"❌ Error: {str(e)[:60]}")

    # SELL
    elif sub == "sell" and len(args) >= 2:
        kode_p = args[1].upper()
        lot_jual = None
        if len(args) >= 3:
            try: lot_jual = int(args[2])
            except: pass

        positions = [p for p in paper_get_positions(uid) if p[1] == kode_p]
        if not positions:
            dest_kirim_teks(dest, f"❌ Tidak ada posisi OPEN untuk {kode_p}"); return

        try:
            df_p, harga_now, _ = get_candles_tf(kode_p+".JK", "1d", "5d")
            harga_now = float(harga_now)
        except:
            dest_kirim_teks(dest, f"❌ Gagal ambil harga {kode_p}"); return

        total_profit = 0
        total_lot_jual = 0
        saldo = paper_get_balance(uid)

        conn = sqlite3.connect(DB_FILE, check_same_thread=False)
        c = conn.cursor()

        for pos in positions:
            pos_id, _, lot_p, harga_beli, _, _, _, _ = pos
            lot_close = min(lot_jual or lot_p, lot_p)
            profit_rp  = (harga_now - harga_beli) * lot_close * 100
            profit_pct = (harga_now - harga_beli) / harga_beli * 100
            hasil      = harga_now * lot_close * 100

            c.execute("""UPDATE paper_positions
                SET status='CLOSED', harga_jual=?, ts_jual=?, profit_rp=?, profit_pct=?
                WHERE id=?""",
                (harga_now, time.time(), profit_rp, profit_pct, pos_id))
            saldo += hasil
            total_profit += profit_rp
            total_lot_jual += lot_close
            if lot_jual: break  # jual sebagian — stop setelah 1 posisi

        conn.commit(); conn.close()
        paper_set_balance(uid, saldo)

        emj = "🟢" if total_profit >= 0 else "🔴"
        pesan  = f"{emj} *PAPER SELL — {kode_p}*\n"
        pesan += f"💰 Harga jual : Rp {fh(int(harga_now))}\n"
        pesan += f"📦 Lot jual   : {total_lot_jual} lot\n"
        pesan += f"{'✅' if total_profit>=0 else '❌'} Profit/Loss : Rp {fh(int(abs(total_profit)))} ({'PROFIT' if total_profit>=0 else 'LOSS'})\n"
        pesan += f"📊 Return     : {(total_profit/(harga_beli*total_lot_jual*100))*100:+.2f}%\n"
        pesan += f"🏦 Saldo      : Rp {fh(int(saldo))}"
        dest_kirim_teks(dest, pesan)

    # PORTO
    elif sub == "porto":
        positions = paper_get_positions(uid)
        saldo     = paper_get_balance(uid)

        pesan  = f"📊 *PAPER PORTFOLIO*\n"
        pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
        pesan += f"🏦 Kas         : Rp {fh(int(saldo))}\n\n"

        if not positions:
            pesan += "_(Tidak ada posisi open)_\n"
        else:
            total_value = 0
            for pos in positions:
                pos_id, kode_p, lot_p, harga_beli, sl_p, t1_p, t2_p, ts = pos
                try:
                    _, harga_now, _ = get_candles_tf(kode_p+".JK", "1d", "3d")
                    harga_now = float(harga_now)
                except: harga_now = harga_beli

                nilai_pos  = harga_now * lot_p * 100
                profit_rp  = (harga_now - harga_beli) * lot_p * 100
                profit_pct = (harga_now - harga_beli) / harga_beli * 100
                total_value += nilai_pos
                emj = "🟢" if profit_pct >= 0 else "🔴"

                tgl = _dt.datetime.fromtimestamp(ts, tz=WIB).strftime("%d/%m")
                pesan += f"{emj} *{kode_p}*  {lot_p}lot  @{fh(int(harga_beli))} → {fh(int(harga_now))}\n"
                pesan += f"    P/L: Rp {fh(int(abs(profit_rp)))} ({profit_pct:+.1f}%)  [{tgl}]\n"
                if sl_p: pesan += f"    SL: {fh(int(sl_p))}"
                if t1_p: pesan += f"  T1: {fh(int(t1_p))}"
                pesan += "\n"

            total_assets = saldo + total_value
            init_capital = 100_000_000
            total_return = (total_assets - init_capital) / init_capital * 100
            pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
            pesan += f"💼 Total aset : Rp {fh(int(total_assets))}\n"
            pesan += f"📈 Return total: {total_return:+.1f}%"

        dest_kirim_teks(dest, pesan)

    # HISTORY
    elif sub == "history":
        try:
            conn = sqlite3.connect(DB_FILE, check_same_thread=False)
            c = conn.cursor()
            c.execute("""SELECT kode,lot,harga_beli,harga_jual,profit_rp,profit_pct,ts_jual
                         FROM paper_positions WHERE user_id=? AND status='CLOSED'
                         ORDER BY ts_jual DESC LIMIT 15""", (uid,))
            rows = c.fetchall(); conn.close()
        except: rows = []

        if not rows:
            dest_kirim_teks(dest, "_(Belum ada riwayat transaksi)_"); return

        win   = sum(1 for r in rows if (r[4] or 0) >= 0)
        loss  = len(rows) - win
        total_pl = sum(r[4] or 0 for r in rows)
        wr    = win / len(rows) * 100

        pesan  = f"📋 *PAPER HISTORY* (15 terakhir)\n"
        pesan += f"Winrate: {wr:.0f}%  |  Total P/L: Rp {fh(int(abs(total_pl)))} ({'profit' if total_pl>=0 else 'loss'})\n"
        pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
        for kode_p, lot_p, hbeli, hjual, prl, pct, ts in rows:
            emj = "✅" if (prl or 0) >= 0 else "❌"
            tgl = _dt.datetime.fromtimestamp(ts, tz=WIB).strftime("%d/%m") if ts else "?"
            pesan += f"{emj} *{kode_p}*  {lot_p}lot  {fh(int(hbeli))}→{fh(int(hjual or 0))}  {(pct or 0):+.1f}%  [{tgl}]\n"
        dest_kirim_teks(dest, pesan)

    # RESET
    elif sub == "reset":
        try:
            conn = sqlite3.connect(DB_FILE, check_same_thread=False)
            c = conn.cursor()
            c.execute("DELETE FROM paper_positions WHERE user_id=?", (uid,))
            conn.commit(); conn.close()
            paper_set_balance(uid, 100_000_000)
            dest_kirim_teks(dest, "✅ Paper trading direset.\nModal: Rp 100.000.000")
        except Exception as e:
            dest_kirim_teks(dest, f"❌ Error reset: {str(e)[:60]}")

    else:
        dest_kirim_teks(dest, "❌ Perintah tidak dikenal. Ketik `/paper` untuk bantuan.")

def proses_porto(user_id, args, dest):
    """Handler lengkap /porto — SQLite-backed + position sizing."""
    porto = db_porto_load(user_id)
    uid   = str(user_id)

    def fh(v): return f"{int(v):,}".replace(",",".")
    def fp(v): return f"{v:+.2f}%"

    if not args:
        # Tampil semua posisi + P&L
        if not porto:
            dest_kirim_teks(dest,
                "📂 *Porto kamu kosong.*\n\n"
                "Tambah posisi: `/porto add BBCA 9200 10`\n"
                "_(kode harga lot)_")
            return

        def _cek_porto():
            pesan  = f"📊 *PORTOFOLIO*\n"
            pesan += f"📅 {now_wib().strftime('%d/%m/%Y %H:%M')} WIB\n"
            pesan += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
            total_modal = 0; total_nilai = 0
            for kode, pos in porto.items():
                info = ambil_info_saham(kode+".JK")
                harga_now  = info["harga"] if info else pos["harga_beli"]
                harga_beli = pos["harga_beli"]
                lot        = pos["lot"]
                modal      = harga_beli * lot * 100
                nilai_now  = harga_now  * lot * 100
                pl         = nilai_now - modal
                pl_pct     = (pl / modal * 100) if modal > 0 else 0
                emj        = "🟢" if pl >= 0 else "🔴"
                total_modal += modal; total_nilai += nilai_now
                pesan += f"*{kode}*  {fh(harga_beli)} → {fh(harga_now)}\n"
                pesan += f"   {lot} lot | {emj} P&L: Rp {fh(pl)} ({fp(pl_pct)})\n"
                time.sleep(0.1)
            total_pl = total_nilai - total_modal
            total_pl_pct = (total_pl / total_modal * 100) if total_modal > 0 else 0
            emj_total = "🟢" if total_pl >= 0 else "🔴"
            pesan += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
            pesan += f"💰 *Total Modal:* Rp {fh(total_modal)}\n"
            pesan += f"💼 *Nilai Kini :* Rp {fh(total_nilai)}\n"
            pesan += f"{emj_total} *Net P&L    :* Rp {fh(total_pl)} ({fp(total_pl_pct)})\n"
            dest_kirim_teks(dest, pesan)
        threading.Thread(target=_cek_porto, daemon=True).start()
        return

    cmd = args[0].lower()

    if cmd == "add" and len(args) >= 4:
        kode = args[1].upper()
        try:
            harga_beli = float(args[2])
            lot        = int(args[3])
        except:
            dest_kirim_teks(dest, "⚠️ Format: `/porto add BBCA 9200 10`"); return
        tgl   = now_wib().strftime("%d/%m/%Y")
        db_porto_add(user_id, kode, harga_beli, lot, tgl)
        modal = harga_beli * lot * 100
        dest_kirim_teks(dest,
            f"✅ *{kode}* ditambahkan ke porto\n"
            f"💰 Harga beli : Rp {fh(harga_beli)}\n"
            f"📦 Lot        : {lot} lot\n"
            f"💵 Modal      : Rp {fh(modal)}")
        return

    if cmd == "del" and len(args) >= 2:
        kode = args[1].upper()
        if kode in porto:
            db_porto_del(user_id, kode)
            dest_kirim_teks(dest, f"✅ *{kode}* dihapus dari porto.")
        else:
            dest_kirim_teks(dest, f"⚠️ *{kode}* tidak ada di porto kamu.")
        return

    if cmd == "clear":
        db_porto_clear(user_id)
        dest_kirim_teks(dest, "🗑️ Semua posisi porto dihapus.")
        return

    if cmd == "pl":
        if not porto:
            dest_kirim_teks(dest, "📂 Porto kosong."); return
        def _cek_pl():
            pesan = f"📈 *P&L PORTO*\n━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
            total_modal = 0; total_nilai = 0
            for kode, pos in porto.items():
                info = ambil_info_saham(kode+".JK")
                hn   = info["harga"] if info else pos["harga_beli"]
                hb   = pos["harga_beli"]; lot = pos["lot"]
                modal = hb*lot*100; nilai = hn*lot*100
                pl    = nilai - modal; pp = (pl/modal*100) if modal>0 else 0
                emj   = "🟢" if pl>=0 else "🔴"
                total_modal+=modal; total_nilai+=nilai
                pesan += f"*{kode}*: {emj} Rp {fh(pl)} ({fp(pp)})\n"
                time.sleep(0.1)
            tp = total_nilai-total_modal; tpp=(tp/total_modal*100) if total_modal>0 else 0
            emjt = "🟢" if tp>=0 else "🔴"
            pesan += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n{emjt} *Total: Rp {fh(tp)} ({fp(tpp)})*"
            dest_kirim_teks(dest, pesan)
        threading.Thread(target=_cek_pl, daemon=True).start()
        return

    if cmd == "rr" and len(args) >= 4:
        kode = args[1].upper()
        try:
            harga_beli = float(args[2])
            target_tp  = float(args[3])
            sl_pct     = float(args[4]) if len(args)>=5 else 2.0
            harga_sl   = harga_beli * (1 - sl_pct/100)
        except:
            dest_kirim_teks(dest, "⚠️ Format: `/porto rr BBCA 9200 9800 [sl%]`"); return
        reward      = target_tp - harga_beli
        risk        = harga_beli - harga_sl
        rr          = reward / risk if risk > 0 else 0
        gain_target = (reward/harga_beli*100)
        loss_sl     = (risk/harga_beli*100)
        emj_rr      = "✅" if rr >= 2 else ("⚠️" if rr >= 1 else "❌")
        dest_kirim_teks(dest,
            f"📐 *Risk/Reward — {kode}*\n"
            f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
            f"💰 Harga Beli  : Rp {fh(harga_beli)}\n"
            f"🎯 Target (TP) : Rp {fh(target_tp)} (+{gain_target:.1f}%)\n"
            f"🛡️ Stop Loss    : Rp {fh(harga_sl)} (-{loss_sl:.1f}%)\n"
            f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
            f"📊 Risk  : Rp {fh(risk)}/lembar\n"
            f"📊 Reward: Rp {fh(reward)}/lembar\n"
            f"{emj_rr} *R/R Ratio: 1 : {rr:.1f}*\n"
            f"_R/R ≥ 1:2 = layak trading_")
        return

    # ── /porto size — Position Sizing Calculator ─────────────
    if cmd == "size":
        proses_porto_size(user_id, args[1:], dest)
        return

    # Default: tampil menu
    dest_kirim_teks(dest,
        "📂 *Perintah /porto:*\n"
        "`/porto` — Lihat semua posisi + P&L\n"
        "`/porto add BBCA 9200 10` — Tambah posisi\n"
        "`/porto del BBCA` — Hapus posisi\n"
        "`/porto pl` — Lihat P&L saja\n"
        "`/porto rr BBCA 9200 9800` — Kalkulator R/R\n"
        "`/porto size BBCA 9500 9200 10000000 2` — 🔥 Position sizing\n"
        "`/porto clear` — Hapus semua posisi")


