def kirim_kurs(dest):
    """Kirim data kurs dan komoditas."""
    now = now_wib()
    tgl = now.strftime("%d/%m/%Y")
    jam = now.strftime("%H:%M")
    try:
        # Ambil kurs via IDX API proxy
        kurs_data = {}
        try:
            HDR = {"User-Agent": "Mozilla/5.0", "Referer": "https://www.idx.co.id/"}
            r = _http.get("https://www.idx.co.id/primary/ExchangeRate/GetExchangeRate",
                             headers=HDR, timeout=10)
            if r.status_code == 200:
                d = r.json()
                rows = d.get("Data") or d.get("data") or []
                for row in rows:
                    kode = row.get("CurrencyCode","").upper()
                    val  = row.get("MiddleRate") or row.get("Rate") or 0
                    if kode and val:
                        kurs_data[kode] = float(str(val).replace(",",""))
        except: pass

        # Fallback: Yahoo Finance direct HTTP (tanpa yfinance library)
        if not kurs_data:
            try:
                pairs = {"USD":"USDIDR=X","SGD":"SGDIDR=X","EUR":"EURIDR=X","JPY":"JPYIDR=X"}
                for kode_k, sym in pairs.items():
                    try:
                        url_k = f"https://query1.finance.yahoo.com/v8/finance/chart/{sym}?range=2d&interval=1d"
                        rk = _http.get(url_k,
                            headers={"User-Agent":"Mozilla/5.0"}, timeout=8)
                        if rk.status_code == 200:
                            meta_k = rk.json()["chart"]["result"][0]["meta"]
                            val_k = (meta_k.get("regularMarketPrice") or
                                     meta_k.get("previousClose") or 0)
                            if val_k: kurs_data[kode_k] = float(val_k)
                    except: pass
            except: pass

        # Komoditas via Yahoo Finance direct HTTP
        komoditas = {}
        try:
            items = {"Emas":"GC=F","Minyak Mentah":"CL=F","Tembaga":"HG=F"}
            for nm, sym in items.items():
                try:
                    url_c = f"https://query1.finance.yahoo.com/v8/finance/chart/{sym}?range=2d&interval=1d"
                    rc = _http.get(url_c,
                        headers={"User-Agent":"Mozilla/5.0"}, timeout=8)
                    if rc.status_code == 200:
                        res_c = rc.json()["chart"]["result"][0]
                        meta_c = res_c["meta"]
                        h_c = float(meta_c.get("regularMarketPrice") or 0)
                        p_c = float(meta_c.get("previousClose") or h_c)
                        if h_c: komoditas[nm] = {"harga": h_c, "prev": p_c}
                except: pass
        except: pass

        def fk(v): return f"{int(v):,}".replace(",",".")
        pesan  = f"💱 *KURS & KOMODITAS*\n"
        pesan += f"📅 {tgl}  ⏰ {jam} WIB\n"
        pesan += f"━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n"
        if kurs_data:
            pesan += f"💵 *KURS IDR:*\n"
            for kode in ["USD","SGD","EUR","JPY"]:
                if kode in kurs_data:
                    v = kurs_data[kode]
                    unit = "per 100 JPY" if kode == "JPY" else ""
                    pesan += f"  {kode}/IDR : Rp {fk(v)} {unit}\n"
        if komoditas:
            pesan += f"\n🪨 *KOMODITAS:*\n"
            for nm, d in komoditas.items():
                h = d["harga"]; p = d["prev"]
                g = (h-p)/p*100 if p>0 else 0
                emj = "🟢" if g>=0 else "🔴"
                pesan += f"  {nm}: {emj} `{h:.2f}` ({g:+.2f}%)\n"
        pesan += f"\n⏰ Data: {jam} WIB"

        if not kurs_data and not komoditas:
            dest_kirim_teks(dest, "❌ Data kurs tidak tersedia saat ini.")
        else:
            dest_kirim_teks(dest, pesan)
    except Exception as e:
        dest_kirim_teks(dest, f"❌ Error ambil data kurs: {e}")


