def kirim_sektoral(dest):
    """Kirim performa 10 sektor IDX + heatmap chart."""
    dest_kirim_teks(dest, "📊 Menghitung performa sektor... ⏳")
    try:
        hasil = []
        for sektor, saham_list in SEKTOR_MAP.items():
            gains = []
            for kode in saham_list[:5]:
                info = ambil_info_saham(kode+".JK")
                if info and info.get("gain") is not None:
                    gains.append(info["gain"])
                time.sleep(0.1)
            if gains:
                avg_gain = sum(gains)/len(gains)
                hasil.append({"sektor": sektor, "gain": avg_gain,
                              "saham_ok": len(gains)})
        hasil.sort(key=lambda x: x["gain"], reverse=True)
        now = now_wib()

        # ── Teks summary ──────────────────────────────────────
        pesan  = f"🗺 *PERFORMA SEKTOR IDX*\n"
        pesan += f"📅 {now.strftime('%d/%m/%Y %H:%M')} WIB\n"
        pesan += f"{'═'*26}\n"
        medals = ["🥇","🥈","🥉"]
        for i, h in enumerate(hasil):
            rank  = medals[i] if i < 3 else f"{i+1:>2}."
            emj   = "🟢" if h["gain"] >= 0 else "🔴"
            bar_w = min(8, int(abs(h["gain"]) * 1.5))
            bar_s = ("▓" if h["gain"] >= 0 else "░") * bar_w
            pesan += f"{rank} *{h['sektor']:<16}*  {emj} `{h['gain']:+.2f}%`  {bar_s}\n"
            if i == 4:
                pesan += f"{'─'*26}\n"
        pesan += f"{'═'*26}\n⏰ {now.strftime('%H:%M')} WIB"
        dest_kirim_teks(dest, pesan)

        # ── Heatmap chart ─────────────────────────────────────
        time.sleep(0.5)
        buf_hm = buat_chart_heatmap_sektoral(hasil)
        if buf_hm:
            dest_kirim_foto_buf(dest, buf_hm,
                f"🗺 *Heatmap Sektor IDX*  ·  {now.strftime('%H:%M')} WIB\n"
                f"Merah=jual, Hijau=beli, ukuran=gain magnitude")
    except Exception as e:
        dest_kirim_teks(dest, f"❌ Error sektoral: {e}")


