# ─────────────────────────────────────────────────────────────
# /fbb — Fibonacci Retracement + Chart
# ─────────────────────────────────────────────────────────────
def proses_cmd_fbb(kode, dest):
    ticker = kode.upper() + ".JK"
    dest_kirim_teks(dest, f"🌀 Menghitung Fibonacci *{kode.upper()}*...")
    try:
        df, harga, prev = get_candles_tf(ticker, "1d", "1y")
        if len(df) < 10:
            df, harga, prev = get_candles_tf(ticker, "1d", "2y")
        if len(df) < 5:
            dest_kirim_teks(dest, f"❌ Data *{kode.upper()}* tidak cukup (hanya {len(df)} hari)."); return

        # Cari swing high & low dalam 60 candle terakhir
        df_look = df.tail(60)
        swing_high = df_look["High"].max()
        swing_low  = df_look["Low"].min()
        hi_idx     = df_look["High"].idxmax()
        lo_idx     = df_look["Low"].idxmin()

        # Tentukan arah: apakah sekarang dalam uptrend atau downtrend?
        is_uptrend = lo_idx < hi_idx  # low dulu, high belakangan

        if is_uptrend:
            fib_high = swing_high; fib_low = swing_low
            arah_str = "📈 Uptrend (Retracement)"
        else:
            fib_high = swing_high; fib_low = swing_low
            arah_str = "📉 Downtrend (Retracement)"

        rang  = fib_high - fib_low
        FIB_LEVELS = [0.0, 0.236, 0.382, 0.5, 0.618, 0.786, 1.0]
        FIB_EXT    = [1.272, 1.618]

        def fib_price(ratio):
            if is_uptrend: return fib_high - ratio * rang
            else:          return fib_low  + ratio * rang

        levels = {r: fib_price(r) for r in FIB_LEVELS}
        ext    = {r: fib_price(-r+1) for r in FIB_EXT}

        def fh(v): return f"{int(v):,}".replace(",",".")
        def pos(p, h): return "✅" if abs(p-h)/h < 0.02 else ("🔴" if p > h else "🟢")

        pesan  = f"🌀 *FIBONACCI — {kode.upper()}*\n"
        pesan += f"💰 Harga : Rp {fh(int(harga))}  |  {arah_str}\n"
        pesan += f"📊 Range : Rp {fh(int(fib_low))} → Rp {fh(int(fib_high))}\n"
        pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
        pesan += f"📌 *Level Fibonacci*\n"

        # Urutkan dari atas ke bawah
        sorted_lvl = sorted(levels.items(), key=lambda x: x[1], reverse=True)
        for ratio, price in sorted_lvl:
            label  = f"Fib {ratio:.3f}"
            is_cur = abs(price - harga) / harga < 0.025
            mark   = " ◀ SEKARANG" if is_cur else ""
            emj    = pos(price, harga)
            pesan += f"{emj} {label:<12} Rp {fh(int(price))}{mark}\n"

        pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
        pesan += f"🎯 *Extension (Target)*\n"
        for ratio, price in sorted(ext.items(), key=lambda x: x[1]):
            pesan += f"  Ext {ratio:.3f}  Rp {fh(int(price))}\n"

        # Nearest support & resistance dari fib
        above = [(r,p) for r,p in levels.items() if p > harga]
        below = [(r,p) for r,p in levels.items() if p <= harga]
        if above: nr = min(above, key=lambda x: x[1]); pesan += f"\n🔴 Resistance terdekat : Fib {nr[0]:.3f} — Rp {fh(int(nr[1]))}"
        if below: ns = max(below, key=lambda x: x[1]); pesan += f"\n🟢 Support terdekat    : Fib {ns[0]:.3f} — Rp {fh(int(ns[1]))}"
        pesan += f"\n⏰ {now_wib().strftime('%H:%M')} WIB  |  Lookback 60 candle daily"
        dest_kirim_teks(dest, pesan)

        # Chart Fibonacci
        try:
            import matplotlib; matplotlib.use("Agg")
            import matplotlib.pyplot as plt

            df_plot = df.tail(60); n = len(df_plot)
            opens   = df_plot["Open"].values;  closes = df_plot["Close"].values
            highs   = df_plot["High"].values;  lows   = df_plot["Low"].values
            dates   = df_plot.index.tolist()

            FIB_COLORS = {
                0.0:   ("#E53935", "Fib 0.000"),
                0.236: ("#FF7043", "Fib 0.236"),
                0.382: ("#FFD600", "Fib 0.382"),
                0.5:   ("#00BCD4", "Fib 0.500"),
                0.618: ("#43A047", "Fib 0.618"),
                0.786: ("#7B1FA2", "Fib 0.786"),
                1.0:   ("#1565C0", "Fib 1.000"),
            }

            fig, ax = plt.subplots(figsize=(13,7), facecolor="#0D1117")
            ax.set_facecolor("#0D1117")

            for i,(o,h,l,c) in enumerate(zip(opens,highs,lows,closes)):
                clr = "#00AA44" if c>=o else "#FF2222"
                ax.plot([i,i],[l,h], color=clr, linewidth=0.8)
                ax.add_patch(plt.Rectangle((i-0.38,min(o,c)),0.76,abs(c-o)+1e-9,color=clr,zorder=3))

            for ratio, price in sorted(levels.items(), key=lambda x: x[1], reverse=True):
                clr  = FIB_COLORS[ratio][0]
                lbl  = FIB_COLORS[ratio][1]
                lw   = 1.8 if ratio in [0.382, 0.5, 0.618] else 1.0
                ax.axhline(y=price, color=clr, linestyle="--", linewidth=lw, alpha=0.85)
                ax.text(n+0.3, price, f" {lbl}  {fh(int(price))}",
                    va="center", ha="left", fontsize=6.5, color=clr, fontweight="bold")

            ax.axhline(y=harga, color="#BB86FC", linestyle=":", linewidth=1.5, alpha=0.9)
            ax.text(n+0.3, harga, f" Now {fh(int(harga))}",
                va="center", ha="left", fontsize=7, color="#BB86FC", fontweight="bold")

            step = max(1, n//8)
            ax.set_xticks(range(0,n,step))
            ax.set_xticklabels([dates[i].strftime("%d/%m") for i in range(0,n,step)],
                fontsize=6.5, color="#8B949E", rotation=15)
            ax.tick_params(axis="y", colors="#8B949E", labelsize=7)
            ax.set_xlim(-0.5, n+9); ax.set_title(
                f"{kode.upper()} | Fibonacci Retracement | Daily",
                fontsize=10.5, fontweight="bold", color="#E6EDF3", pad=8)
            for sp in ax.spines.values(): sp.set_visible(False)

            plt.tight_layout()
            buf = io.BytesIO()
            plt.savefig(buf, format="png", dpi=125, bbox_inches="tight", facecolor="#0D1117")
            plt.close(); buf.seek(0)
            dest_kirim_foto_buf(dest, buf, f"🌀 *{kode.upper()}* | Fibonacci Retracement | {arah_str}")
        except Exception as e:
            print(f"fbb chart error: {e}")
    except Exception as e:
        import traceback; traceback.print_exc()
        dest_kirim_teks(dest, f"❌ Gagal Fibonacci *{kode.upper()}*: {str(e)[:60]}")


def hitung_sr(df, n_levels=8):
    """Hitung level Support & Resistance dari swing high/low + clustering."""
    highs=df["High"].values; lows=df["Low"].values; n=len(highs); sr=[]
    window=max(3,n//15)
    for i in range(window,n-window):
        if highs[i]==max(highs[i-window:i+window+1]): sr.append(("R",highs[i]))
        if lows[i]==min(lows[i-window:i+window+1]):   sr.append(("S",lows[i]))
    sr.sort(key=lambda x:x[1]); clustered=[]; used=[False]*len(sr)
    for i,(t,v) in enumerate(sr):
        if used[i]: continue
        group=[v]
        for j in range(i+1,len(sr)):
            if not used[j] and abs(sr[j][1]-v)/v<0.015:
                group.append(sr[j][1]); used[j]=True
        clustered.append((t,sum(group)/len(group),len(group)))
    clustered.sort(key=lambda x:x[2],reverse=True)
    top=clustered[:n_levels*2]; top.sort(key=lambda x:x[1]); return top



