import numpy as np
import pandas as pd


# ═══════════════════════════════════════════════════════════════════════
# PATCH LUX v1.1 — Liquidity Zones · Institutional Flow · Scalp Pro
# Bug fixes v1.1:
#   - buat_chart_lux: hapus matplotlib.use() di dalam fungsi (sudah di-set global)
#   - IVF panel: twin-axis dipisah dengan benar (vol bars kiri, flow % kanan)
#   - vol_max guard: pastikan tidak NaN/zero
#   - Exception logging: print traceback supaya bisa debug di Railway logs
# ═══════════════════════════════════════════════════════════════════════


# ───────────────────────────────────────────────────────────────────────
# 1. LIQUIDITY ZONES
# ───────────────────────────────────────────────────────────────────────
def calc_liquidity_zones(df, swing_len=10, wick_mult=1.5):
    """
    Swing High → Supply zone  (wick tip → body top)
    Swing Low  → Demand zone  (wick tip → body bot)
    Wick Extremity → candle dgn wick > wick_mult × body (liquidity grab)
    Zone "active" selama harga belum close menembus zone tsb.
    """
    close  = df["Close"].values.astype(float)
    high   = df["High"].values.astype(float)
    low    = df["Low"].values.astype(float)
    open_  = df["Open"].values.astype(float)
    vol    = df["Volume"].values.astype(float)
    n      = len(close)

    vol_ma = pd.Series(vol).rolling(20, min_periods=5).mean().values

    supply_zones  = []
    demand_zones  = []
    wick_extremes = []

    half = max(3, swing_len)
    for i in range(half, n - half):
        win_hi = high[i - half: i + half + 1]
        win_lo = low[i  - half: i + half + 1]
        vma    = vol_ma[i] if (vol_ma[i] and not np.isnan(vol_ma[i]) and vol_ma[i] > 0) else 1.0
        v_ratio = vol[i] / vma

        if high[i] >= np.max(win_hi) - 1e-9:
            top = high[i]
            bot = max(close[i], open_[i])
            if top > bot:
                supply_zones.append({"top": top, "bot": bot, "idx": i,
                                     "vol_ratio": v_ratio, "active": True})

        if low[i] <= np.min(win_lo) + 1e-9:
            bot = low[i]
            top = min(close[i], open_[i])
            if top > bot:
                demand_zones.append({"top": top, "bot": bot, "idx": i,
                                     "vol_ratio": v_ratio, "active": True})

        body       = abs(close[i] - open_[i])
        rng_c      = high[i] - low[i]
        body_eff   = max(body, rng_c * 0.05)
        upper_wick = high[i] - max(close[i], open_[i])
        lower_wick = min(close[i], open_[i]) - low[i]
        if upper_wick > wick_mult * body_eff:
            wick_extremes.append({"price": high[i], "idx": i, "dir": "bear"})
        if lower_wick > wick_mult * body_eff:
            wick_extremes.append({"price": low[i],  "idx": i, "dir": "bull"})

    last_close = close[-1]
    for z in supply_zones:
        if last_close > z["top"]: z["active"] = False
    for z in demand_zones:
        if last_close < z["bot"]: z["active"] = False

    supply_zones  = sorted(supply_zones,  key=lambda x: x["idx"])[-6:]
    demand_zones  = sorted(demand_zones,  key=lambda x: x["idx"])[-6:]
    wick_extremes = [w for w in wick_extremes if w["idx"] >= n - 80]

    return {"supply": supply_zones, "demand": demand_zones,
            "wicks": wick_extremes, "last_close": last_close}


# ───────────────────────────────────────────────────────────────────────
# 2. INSTITUTIONAL VOLUME FLOW
# ───────────────────────────────────────────────────────────────────────
def calc_institutional_flow(df, fast=10, slow=50, signal=20):
    """
    Net delta = bull_vol − bear_vol per bar.
    Rolling sum (slow bars) → normalize 0-100.
    Buy  signal: normalized flow crosses up  through 30.
    Sell signal: normalized flow crosses down through 70.
    """
    close  = pd.Series(df["Close"].values.astype(float))
    open_  = pd.Series(df["Open"].values.astype(float))
    high   = pd.Series(df["High"].values.astype(float))
    low    = pd.Series(df["Low"].values.astype(float))
    vol    = pd.Series(df["Volume"].values.astype(float))
    n      = len(close)

    rng_c    = (high - low).replace(0, np.nan)
    body     = (close - open_).abs()
    body_pct = (body / rng_c).fillna(0.5).clip(0.1, 1.0)

    bull_arr = np.where(close >= open_, vol * body_pct, vol * (1.0 - body_pct))
    bear_arr = np.where(close <  open_, vol * body_pct, vol * (1.0 - body_pct))

    delta     = pd.Series(bull_arr - bear_arr)
    cum_delta = delta.rolling(slow, min_periods=1).sum()

    roll_max  = cum_delta.rolling(slow, min_periods=1).max()
    roll_min  = cum_delta.rolling(slow, min_periods=1).min()
    rng_d     = (roll_max - roll_min).replace(0, np.nan)
    flow_norm = ((cum_delta - roll_min) / rng_d * 100).fillna(50)
    flow_sm   = flow_norm.ewm(span=3, adjust=False).mean()

    buy_sigs  = []
    sell_sigs = []
    for i in range(1, n):
        prev = float(flow_sm.iloc[i - 1])
        curr = float(flow_sm.iloc[i])
        if prev < 30 and curr >= 30: buy_sigs.append(i)
        if prev > 70 and curr <= 70: sell_sigs.append(i)

    score = float(flow_sm.iloc[-1])
    state = "BULL" if score >= 60 else ("BEAR" if score <= 40 else "NEUTRAL")

    return {"flow_norm": flow_sm.values, "bull_vol": bull_arr,
            "bear_vol": bear_arr, "buy_sigs": buy_sigs,
            "sell_sigs": sell_sigs, "state": state, "score": score}


# ───────────────────────────────────────────────────────────────────────
# 3. SCALP PRO OSCILLATOR
# ───────────────────────────────────────────────────────────────────────
def calc_scalp_pro(df, length=10, smooth=3, ob=75, os_=25):
    """
    Raw  = (close − LL[length]) / (HH[length] − LL[length]) × 100
    EMA(smooth) → oscillator line.
    Signal = EMA(smooth×3).
    Buy : osc crosses above signal AND osc < 60.
    Sell: osc crosses below signal AND osc > 40.
    """
    close   = pd.Series(df["Close"].values.astype(float))
    high    = pd.Series(df["High"].values.astype(float))
    low     = pd.Series(df["Low"].values.astype(float))
    n       = len(close)

    highest = high.rolling(length, min_periods=1).max()
    lowest  = low.rolling(length,  min_periods=1).min()
    rng_hl  = (highest - lowest).replace(0, np.nan)
    raw     = ((close - lowest) / rng_hl * 100).fillna(50)
    osc     = raw.ewm(span=smooth,     adjust=False).mean()
    sig     = osc.ewm(span=smooth * 3, adjust=False).mean()

    buy_sigs = []; sell_sigs = []
    for i in range(1, n):
        o_p, o_c = float(osc.iloc[i-1]), float(osc.iloc[i])
        s_p, s_c = float(sig.iloc[i-1]), float(sig.iloc[i])
        if o_p < s_p and o_c >= s_c and o_c < 60: buy_sigs.append(i)
        if o_p > s_p and o_c <= s_c and o_c > 40: sell_sigs.append(i)

    val   = float(osc.iloc[-1])
    state = ("OVERBOUGHT" if val >= ob else
             "OVERSOLD"   if val <= os_ else
             "BULLISH"    if val > 50 else "BEARISH")

    return {"osc": osc.values, "sig_line": sig.values,
            "buy_sigs": buy_sigs, "sell_sigs": sell_sigs,
            "state": state, "value": val, "ob": ob, "os": os_}


# ───────────────────────────────────────────────────────────────────────
# 4. CHART — buat_chart_lux()  [v1.1 — chart render fixes]
# ───────────────────────────────────────────────────────────────────────
def buat_chart_lux(ticker, df, harga, tf_key, tf_label, dest=None):
    """
    3-panel chart:
      Panel 1 (4×) : Candle + EMA9/21 ribbon + Liquidity Zones + Wick marks
      Panel 2 (1.5×): Scalp Pro oscillator + Buy/Sell labels
      Panel 3 (1.5×): Volume bars (bull/bear) + IVF flow line (twin-axis)
    """
    import io
    import traceback as _tb
    import matplotlib.pyplot as plt
    import matplotlib.patches as mpatches

    # ── Palette ─────────────────────────────────────────────────────
    BG    = "#131722"; PANEL = "#0d1117"; GRID = "#1e222d"
    C_UP  = "#26a69a"; C_DN  = "#ef5350"
    C_E9  = "#26a69a"; C_E21 = "#ef5350"
    C_SUP = "#ef5350"; C_DEM = "#26a69a"
    C_WCK = "#FFD700"
    C_OSC = "#00e676"; C_SIG = "#ff9800"
    C_BUY = "#00e676"; C_SLL = "#ff1744"
    C_IVF = "#e040fb"                        # IVF flow line

    n_show = _TF_CANDLES.get(tf_key, 80)

    try:
        _apply_dark_rc()                     # gunakan fungsi existing bot

        df_plot = df.tail(n_show).copy()
        n = len(df_plot)
        if n < 10:
            return None

        opens  = df_plot["Open"].values.astype(float)
        highs  = df_plot["High"].values.astype(float)
        lows   = df_plot["Low"].values.astype(float)
        closes = df_plot["Close"].values.astype(float)
        dates  = list(df_plot.index)
        vols   = df_plot["Volume"].values.astype(float)

        y_min = float(np.nanmin(lows));  y_max = float(np.nanmax(highs))
        y_rng = (y_max - y_min) if y_max > y_min else max(y_max * 0.05, 1)

        # ── Indicators (full df untuk warmup) ───────────────────────
        liq  = calc_liquidity_zones(df, swing_len=max(5, n_show // 16))
        ivf  = calc_institutional_flow(df)
        scl  = calc_scalp_pro(df)

        full_cl = pd.Series(df["Close"].values.astype(float))
        e9_full  = full_cl.ewm(span=9,  adjust=False).mean().values[-n:]
        e21_full = full_cl.ewm(span=21, adjust=False).mean().values[-n:]

        # Slice ke window plot
        ivf_flow = ivf["flow_norm"][-n:]    # 0-100
        ivf_bull = ivf["bull_vol"][-n:]
        ivf_bear = ivf["bear_vol"][-n:]
        sp_osc   = scl["osc"][-n:]
        sp_sig   = scl["sig_line"][-n:]
        x        = np.arange(n)

        # Map global idx → plot idx
        offset = len(df) - n
        def to_plot_idx(gi):
            p = gi - offset
            return p if 0 <= p < n else None

        # ── Figure ──────────────────────────────────────────────────
        fig, (ax_p, ax_sp, ax_ivf) = plt.subplots(
            3, 1, figsize=(14, 9),
            gridspec_kw={"height_ratios": [4, 1.5, 1.5], "hspace": 0.06},
            facecolor=BG
        )
        for ax_ in (ax_p, ax_sp, ax_ivf):
            ax_.set_facecolor(PANEL)
            ax_.grid(True, color=GRID, lw=0.4, ls="--", alpha=0.5, zorder=0)
            for sp in ax_.spines.values(): sp.set_color("#2a2d3a")

        cw = max(0.3, 0.55 * min(1.0, 80 / max(n, 1)))

        # ════════════════════════════════════════════════════════════
        # PANEL 1 — Price + Liquidity Zones
        # ════════════════════════════════════════════════════════════

        # Candles
        for i in range(n):
            o, h, l, c = opens[i], highs[i], lows[i], closes[i]
            if any(np.isnan(v) for v in (o, h, l, c)): continue
            clr = C_UP if c >= o else C_DN
            ax_p.plot([i, i], [l, h], color=clr, lw=0.8, zorder=2)
            ax_p.add_patch(mpatches.Rectangle(
                (i - cw/2, min(o, c)), cw, max(abs(c - o), y_rng * 0.001),
                lw=0, fc=clr, zorder=3))

        # EMA9/21 ribbon
        for i in range(1, n):
            v = [e9_full[i-1], e9_full[i], e21_full[i-1], e21_full[i]]
            if any(np.isnan(x_) for x_ in v): continue
            bull = e9_full[i] >= e21_full[i]
            ax_p.fill_between([i-1, i],
                              [e9_full[i-1], e9_full[i]],
                              [e21_full[i-1], e21_full[i]],
                              color=C_UP if bull else C_DN, alpha=0.25, zorder=1)
        ax_p.plot(x, e9_full,  color=C_E9,  lw=1.1, alpha=0.9, label="EMA9",  zorder=4)
        ax_p.plot(x, e21_full, color=C_E21, lw=1.1, alpha=0.9, label="EMA21", zorder=4)

        # Supply zones (merah)
        for z in liq["supply"]:
            pi = to_plot_idx(z["idx"])
            if pi is None: continue
            alpha = 0.40 if z["active"] else 0.12
            ax_p.add_patch(mpatches.Rectangle(
                (pi, z["bot"]), n - pi, z["top"] - z["bot"],
                lw=0.5, ec=C_SUP, fc=C_SUP, alpha=alpha, zorder=1))
            if z["active"]:
                ax_p.text(n + 0.3, (z["top"] + z["bot"]) / 2,
                          f"S {z['top']:.0f}", va="center", ha="left",
                          fontsize=6, color=C_SUP, alpha=0.9, zorder=9,
                          clip_on=False)

        # Demand zones (hijau)
        for z in liq["demand"]:
            pi = to_plot_idx(z["idx"])
            if pi is None: continue
            alpha = 0.40 if z["active"] else 0.12
            ax_p.add_patch(mpatches.Rectangle(
                (pi, z["bot"]), n - pi, z["top"] - z["bot"],
                lw=0.5, ec=C_DEM, fc=C_DEM, alpha=alpha, zorder=1))
            if z["active"]:
                ax_p.text(n + 0.3, (z["top"] + z["bot"]) / 2,
                          f"D {z['bot']:.0f}", va="center", ha="left",
                          fontsize=6, color=C_DEM, alpha=0.9, zorder=9,
                          clip_on=False)

        # Wick extremes
        for w in liq["wicks"]:
            pi = to_plot_idx(w["idx"])
            if pi is None: continue
            ax_p.plot(pi, w["price"], "D",
                      color=C_DEM if w["dir"] == "bull" else C_SUP,
                      ms=4, alpha=0.8, zorder=7, markeredgewidth=0)

        # Harga sekarang
        ax_p.axhline(harga, color=C_WCK, lw=0.7, ls="--", alpha=0.7, zorder=5)
        ax_p.text(n - 1, harga + y_rng * 0.012,
                  f" {int(harga):,}".replace(",", "."),
                  color=C_WCK, fontsize=7.5, va="bottom", ha="right", zorder=9)

        ax_p.set_xlim(-1, n + 5)
        ax_p.set_ylim(y_min - y_rng * 0.1, y_max + y_rng * 0.18)
        ax_p.set_title(
            f"⚡ {ticker.replace('.JK','')} │ {tf_label} │ "
            f"IVF:{ivf['state']}  ScalpPro:{scl['value']:.0f}",
            color="#D1D4DC", fontsize=9, pad=5)
        ax_p.yaxis.tick_right()
        ax_p.tick_params(axis="x", labelbottom=False)
        ax_p.tick_params(axis="y", labelsize=7, colors="#8892A4")
        ax_p.legend(loc="upper left", fontsize=7,
                    facecolor="#131722", edgecolor="#2a2d3a",
                    labelcolor="#D1D4DC", framealpha=0.7)

        # ════════════════════════════════════════════════════════════
        # PANEL 2 — Scalp Pro
        # ════════════════════════════════════════════════════════════
        ax_sp.set_title("  Scalp Pro", color="#8892A4", fontsize=7.5,
                        loc="left", pad=2)
        ax_sp.plot(x, sp_osc, color=C_OSC, lw=1.3, zorder=4)
        ax_sp.plot(x, sp_sig, color=C_SIG, lw=0.9, ls="--", zorder=3)
        ax_sp.axhline(scl["ob"], color=C_SLL, lw=0.5, ls=":", alpha=0.5)
        ax_sp.axhline(scl["os"], color=C_BUY, lw=0.5, ls=":", alpha=0.5)
        ax_sp.axhline(50, color="#444", lw=0.4, ls="--", alpha=0.4)
        ax_sp.fill_between(x, sp_osc, 50,
                           where=np.array(sp_osc) >= 50,
                           color=C_OSC, alpha=0.08)
        ax_sp.fill_between(x, sp_osc, 50,
                           where=np.array(sp_osc) < 50,
                           color=C_DN, alpha=0.08)

        bbox_b = dict(boxstyle="round,pad=0.2", fc=C_BUY, ec="none")
        bbox_s = dict(boxstyle="round,pad=0.2", fc=C_SLL, ec="none")
        for gi in scl["buy_sigs"]:
            pi = to_plot_idx(gi)
            if pi is not None and 0 <= pi < n:
                ax_sp.text(pi, max(0, sp_osc[pi] - 5), "Buy",
                           ha="center", va="top", fontsize=6,
                           color="white", bbox=bbox_b, zorder=8)
        for gi in scl["sell_sigs"]:
            pi = to_plot_idx(gi)
            if pi is not None and 0 <= pi < n:
                ax_sp.text(pi, min(100, sp_osc[pi] + 5), "Sell",
                           ha="center", va="bottom", fontsize=6,
                           color="white", bbox=bbox_s, zorder=8)

        ax_sp.set_xlim(-1, n + 5)
        ax_sp.set_ylim(-8, 112)
        ax_sp.yaxis.tick_right()
        ax_sp.tick_params(axis="x", labelbottom=False)
        ax_sp.tick_params(axis="y", labelsize=6.5, colors="#8892A4")

        # ════════════════════════════════════════════════════════════
        # PANEL 3 — Institutional Volume Flow
        # Volume bars pada ax_ivf (kiri), IVF % pada ax_ivf_r (kanan twin)
        # ════════════════════════════════════════════════════════════
        ax_ivf.set_title("  Institutional Volume Flow", color="#8892A4",
                         fontsize=7.5, loc="left", pad=2)

        # Volume bars — kiri axis
        total_vol = ivf_bull + ivf_bear
        v_max = float(np.nanmax(total_vol)) if np.any(~np.isnan(total_vol)) else 1.0
        if v_max <= 0: v_max = 1.0
        for i in range(n):
            b  = float(ivf_bull[i]); br = float(ivf_bear[i])
            tv = b + br
            if np.isnan(tv) or tv <= 0: continue
            clr = C_UP if b >= br else C_DN
            ax_ivf.bar(i, tv, color=clr, alpha=0.5, width=cw * 1.1, zorder=2)

        ax_ivf.set_ylim(0, v_max * 1.35)
        ax_ivf.yaxis.tick_left()
        ax_ivf.tick_params(axis="y", labelsize=6, colors="#555")

        # IVF flow line — twin axis kanan (0-100)
        ax_r = ax_ivf.twinx()
        ax_r.set_facecolor("none")
        for sp_ in ax_r.spines.values(): sp_.set_color("#2a2d3a")
        ax_r.plot(x, ivf_flow, color=C_IVF, lw=1.5, zorder=6, label="IVF%")
        ax_r.axhline(70, color=C_SLL, lw=0.5, ls=":", alpha=0.5)
        ax_r.axhline(30, color=C_BUY, lw=0.5, ls=":", alpha=0.5)
        ax_r.axhline(50, color="#444", lw=0.4, ls="--", alpha=0.35)
        ax_r.fill_between(x, ivf_flow, 50,
                          where=np.array(ivf_flow) >= 50,
                          color=C_IVF, alpha=0.07)
        ax_r.set_ylim(-5, 115)
        ax_r.tick_params(axis="y", labelsize=6.5, colors=C_IVF)
        ax_r.set_ylabel("IVF %", color=C_IVF, fontsize=6, rotation=270, labelpad=10)

        # IVF buy/sell signals → triangle markers pada flow line
        for gi in ivf["buy_sigs"]:
            pi = to_plot_idx(gi)
            if pi is not None and 0 <= pi < n:
                ax_r.plot(pi, ivf_flow[pi], "^",
                          color=C_BUY, ms=6, zorder=8, markeredgewidth=0)
        for gi in ivf["sell_sigs"]:
            pi = to_plot_idx(gi)
            if pi is not None and 0 <= pi < n:
                ax_r.plot(pi, ivf_flow[pi], "v",
                          color=C_SLL, ms=6, zorder=8, markeredgewidth=0)

        # X-axis labels (hanya di panel bawah)
        step = max(1, n // 10)
        ax_ivf.set_xticks(range(0, n, step))
        lbls = []
        for i in range(0, n, step):
            d = dates[i]
            lbls.append(d.strftime("%d/%m %H:%M") if hasattr(d, "strftime") else str(d)[:13])
        ax_ivf.set_xticklabels(lbls, rotation=25, ha="right",
                               fontsize=6.5, color="#8892A4")
        ax_ivf.set_xlim(-1, n + 5)
        ax_r.set_xlim(-1, n + 5)

        # Watermark
        fig.text(0.99, 0.005, "LUX · IVF · ScalpPro  @bot_radar",
                 ha="right", va="bottom", fontsize=5.5,
                 color="#ffffff18", style="italic")

        plt.tight_layout(pad=0.5)
        buf = io.BytesIO()
        plt.savefig(buf, format="png", dpi=130, bbox_inches="tight",
                    facecolor=BG, edgecolor="none")
        plt.close(fig)
        buf.seek(0)
        return buf

    except Exception as _e:
        _tb.print_exc()                      # terlihat di Railway logs
        try: plt.close("all")
        except: pass
        return None


# ───────────────────────────────────────────────────────────────────────
# 5. SCANNER HELPER
# ───────────────────────────────────────────────────────────────────────
def skor_lux(ticker, tf_key="5"):
    """Skor LUX 0-100 untuk /luxscan batch screening."""
    try:
        iv, rng, tf_lbl, rs = TF_MAP.get(tf_key, ("5m","5d","5 Menit",None))
        df, harga, prev = get_candles_tf(ticker, iv, rng, rs)
        if df is None or len(df) < 30 or harga < 50: return None

        ivf = calc_institutional_flow(df)
        scl = calc_scalp_pro(df)
        liq = calc_liquidity_zones(df)
        n   = len(df)
        lc  = float(df["Close"].iloc[-1])

        ivf_sc = 0
        if ivf["state"] == "BULL":   ivf_sc += 20
        elif ivf["state"] == "NEUTRAL": ivf_sc += 8
        if ivf["buy_sigs"]  and ivf["buy_sigs"][-1]  >= n - 5: ivf_sc += 15
        if ivf["sell_sigs"] and ivf["sell_sigs"][-1] >= n - 5: ivf_sc -= 15

        sp_sc = 0
        if scl["state"] in ("BULLISH","OVERSOLD"):     sp_sc += 15
        if scl["buy_sigs"]  and scl["buy_sigs"][-1]  >= n - 4: sp_sc += 20
        if scl["sell_sigs"] and scl["sell_sigs"][-1] >= n - 4: sp_sc -= 20

        liq_sc = 0
        if any(z["active"] and lc > z["top"] for z in liq["demand"]):  liq_sc += 10
        if not any(z["active"] and z["bot"] <= lc <= z["top"] for z in liq["supply"]): liq_sc += 10
        if not any(w["dir"]=="bear" and w["idx"] >= n-3 for w in liq["wicks"]): liq_sc += 10

        return {
            "ticker": ticker, "kode": ticker.replace(".JK",""),
            "harga": harga, "skor": max(0, min(100, ivf_sc + sp_sc + liq_sc)),
            "ivf_state": ivf["state"], "sp_state": scl["state"],
            "sp_val": scl["value"],
        }
    except:
        return None


# ───────────────────────────────────────────────────────────────────────
# 6. COMMAND — /lux KODE [TF]
# ───────────────────────────────────────────────────────────────────────
def cmd_lux(kode_raw, tf_input, dest):
    kode   = kode_raw.upper().replace(".JK","")
    ticker = kode + ".JK"
    tf_key = (tf_input or "5").lower().strip()
    if tf_key not in TF_MAP: tf_key = "5"
    iv, rng, tf_lbl, rs = TF_MAP[tf_key]

    dest_kirim_teks(dest,
        f"⚡ _Menganalisis *{kode}* [{tf_lbl}] — LUX · IVF · ScalpPro..._")

    try:
        df, harga, prev = get_candles_tf(ticker, iv, rng, rs)
        if df is None or len(df) < 20:
            dest_kirim_teks(dest, f"❌ Data tidak cukup untuk {kode} [{tf_lbl}].")
            return
    except Exception as e:
        dest_kirim_teks(dest, f"❌ Gagal ambil data: {e}"); return

    n        = len(df)
    gain_pct = (harga - prev) / prev * 100 if prev and prev > 0 else 0

    liq = calc_liquidity_zones(df)
    ivf = calc_institutional_flow(df)
    scl = calc_scalp_pro(df)

    def fh(v): return f"{int(v):,}".replace(",",".")

    # ── Liquidity summary ───────────────────────────────────────────
    active_sup = [z for z in liq["supply"] if z["active"]]
    active_dem = [z for z in liq["demand"] if z["active"]]

    nearest_sup = next(
        (z for z in sorted(active_sup, key=lambda z: z["bot"])
         if z["bot"] >= harga), None)
    nearest_dem = next(
        (z for z in sorted(active_dem, key=lambda z: z["top"], reverse=True)
         if z["top"] <= harga), None)

    sup_txt = (f"Rp{fh(nearest_sup['bot'])}–{fh(nearest_sup['top'])} ({nearest_sup['vol_ratio']:.1f}×vol)"
               if nearest_sup else "—")
    dem_txt = (f"Rp{fh(nearest_dem['bot'])}–{fh(nearest_dem['top'])} ({nearest_dem['vol_ratio']:.1f}×vol)"
               if nearest_dem else "—")

    wick_recent = [w for w in liq["wicks"] if w["idx"] >= n - 10]
    wick_txt    = ("—" if not wick_recent else
                   ", ".join(f"{'🐻' if w['dir']=='bear' else '🐂'} Rp{fh(w['price'])}"
                             for w in wick_recent[-2:]))

    # ── IVF summary ─────────────────────────────────────────────────
    ivf_emj        = {"BULL":"🟢","BEAR":"🔴","NEUTRAL":"🟡"}.get(ivf["state"],"⚪")
    ivf_fresh_buy  = bool(ivf["buy_sigs"]  and ivf["buy_sigs"][-1]  >= n - 4)
    ivf_fresh_sell = bool(ivf["sell_sigs"] and ivf["sell_sigs"][-1] >= n - 4)
    ivf_sig_txt    = ("🚀 *FRESH BUY SIGNAL*"  if ivf_fresh_buy  else
                      "⚠️ *FRESH SELL SIGNAL*" if ivf_fresh_sell else
                      f"Score: {ivf['score']:.1f}/100")

    # ── Scalp Pro summary ───────────────────────────────────────────
    sp_emj        = {"OVERBOUGHT":"🔴","OVERSOLD":"🟢",
                     "BULLISH":"🟢","BEARISH":"🔴"}.get(scl["state"],"🟡")
    sp_fresh_buy  = bool(scl["buy_sigs"]  and scl["buy_sigs"][-1]  >= n - 3)
    sp_fresh_sell = bool(scl["sell_sigs"] and scl["sell_sigs"][-1] >= n - 3)
    sp_sig_txt    = ("🚀 *BELI SEKARANG*" if sp_fresh_buy  else
                     "⛔ *JUAL / EXIT*"   if sp_fresh_sell else
                     f"Osc: {scl['value']:.1f}")

    # ── Verdict ─────────────────────────────────────────────────────
    bull_pts = sum([
        ivf["state"] == "BULL",
        ivf_fresh_buy,
        scl["state"] in ("BULLISH","OVERSOLD"),
        sp_fresh_buy,
        nearest_dem is not None,
    ])
    verdict = ("🟢 STRONG BUY — Semua indikator align bullish" if bull_pts >= 4 else
               "🟢 BUY — Mayoritas bullish, cari entry"        if bull_pts >= 3 else
               "🟡 NETRAL — Sinyal mixed, tunggu konfirmasi"   if bull_pts == 2 else
               "🟠 WEAK — Bias bearish, hindari long"          if bull_pts == 1 else
               "🔴 BEARISH — Skip, tidak ada konfluensi")

    # ── Compose message ─────────────────────────────────────────────
    pesan  = f"⚡ *{kode}* — LUX Analysis [{tf_lbl}]\n"
    pesan += f"💰 Harga: Rp{fh(harga)}  {'📈' if gain_pct >= 0 else '📉'} {gain_pct:+.2f}%\n"
    pesan += "━━━━━━━━━━━━━━━━━━━━━━\n"
    pesan += "🏗 *LIQUIDITY ZONES*\n"
    pesan += f"   🔴 Supply: {sup_txt}\n"
    pesan += f"   🟢 Demand: {dem_txt}\n"
    pesan += f"   ⚡ Wick Extremes: _{wick_txt}_\n\n"
    pesan += f"{ivf_emj} *INSTITUTIONAL FLOW*: `{ivf['state']}`\n"
    pesan += f"   {ivf_sig_txt}\n\n"
    pesan += f"{sp_emj} *SCALP PRO*: `{scl['state']}` (osc: {scl['value']:.1f})\n"
    pesan += f"   {sp_sig_txt}\n\n"
    pesan += "━━━━━━━━━━━━━━━━━━━━━━\n"
    pesan += f"🚦 *VERDICT: {verdict}*\n"
    pesan += "━━━━━━━━━━━━━━━━━━━━━━\n"
    pesan += f"📊 `/lux {kode} 15`  `/lux {kode} 1j`  `/lux {kode} 1d`\n"
    pesan += f"📊 `/c {kode} {tf_key}` — Chart standar\n"
    pesan += "⚠️ _Bukan saran investasi. DYOR & SL wajib._"
    dest_kirim_teks(dest, pesan)

    # ── Chart ───────────────────────────────────────────────────────
    try:
        buf = buat_chart_lux(ticker, df, harga, tf_key, tf_lbl, dest=dest)
        if buf:
            cap = (f"⚡ *{kode}* │ {tf_lbl} │ IVF:{ivf['state']} │ "
                   f"SP:{scl['value']:.0f} │ {'📈' if gain_pct>=0 else '📉'}{gain_pct:+.2f}%")
            dest_kirim_foto_buf(dest, buf, cap)
        else:
            dest_kirim_teks(dest, "⚠️ Chart gagal di-render. Cek Railway logs.")
    except Exception as _ce:
        logger.warning("cmd_lux chart error %s: %s", kode, _ce)
        dest_kirim_teks(dest, f"⚠️ Chart error: {str(_ce)[:80]}")


# ───────────────────────────────────────────────────────────────────────
# 7. COMMAND — /luxscan [TF]
# ───────────────────────────────────────────────────────────────────────
def cmd_luxscan(tf_input, dest, top_n=8):
    """Batch scan watchlist dgn skor_lux(). Kirim TOP-N hasil."""
    import random

    tf_key = (tf_input or "5").lower().strip()
    if tf_key not in TF_MAP: tf_key = "5"
    _, _, tf_lbl, _ = TF_MAP[tf_key]

    sample = list(watchlist)
    random.shuffle(sample)
    sample = sample[:120]

    dest_kirim_teks(dest,
        f"🔍 _LUX Scanner [{tf_lbl}] — scanning {len(sample)} saham..._")

    hasil = []
    for ticker in sample:
        if bot_stop: break
        try:
            sk = skor_lux(ticker, tf_key)
            if sk and sk["skor"] >= 50: hasil.append(sk)
            time.sleep(0.15)
        except: pass

    hasil.sort(key=lambda x: x["skor"], reverse=True)
    top = hasil[:top_n]

    if not top:
        dest_kirim_teks(dest,
            f"📭 *LUX Scanner [{tf_lbl}]*\n"
            "Tidak ada saham dengan sinyal cukup kuat saat ini.")
        return

    def fh(v): return f"{int(v):,}".replace(",",".")
    medals  = ["🥇","🥈","🥉","4️⃣","5️⃣","6️⃣","7️⃣","8️⃣"]
    ivf_emj = {"BULL":"🟢","BEAR":"🔴","NEUTRAL":"🟡"}
    sp_emj  = {"OVERBOUGHT":"🔴","OVERSOLD":"🟢","BULLISH":"🟢","BEARISH":"🔴"}

    now_str = now_wib().strftime("%d-%m-%Y %H:%M")
    pesan   = f"⚡ *LUX SCANNER [{tf_lbl}]*\n"
    pesan  += f"📅 {now_str} WIB | Top {len(top)} dari {len(sample)} dicek\n"
    pesan  += "━━━━━━━━━━━━━━━━━━━━━━\n"
    for i, sk in enumerate(top):
        m  = medals[i] if i < len(medals) else f"{i+1}."
        ie = ivf_emj.get(sk["ivf_state"],"⚪")
        se = sp_emj.get(sk["sp_state"],"🟡")
        pesan += (f"{m} *{sk['kode']}*  Rp{fh(sk['harga'])}\n"
                  f"   Skor: *{sk['skor']}/100*  "
                  f"IVF:{ie}`{sk['ivf_state']}`  SP:{se}`{sk['sp_val']:.0f}`\n"
                  f"   `/lux {sk['kode']} {tf_key}`\n"
                  "━━━━━━━━━━━━━━━━━━━━━━\n")
    pesan += "\n⚠️ _Bukan saran investasi. DYOR & SL wajib._"
    dest_kirim_teks(dest, pesan)

