def _detect_rbs_sbr(df, harga, tol_pct=2.0):
    """
    Deteksi level RBS (Resistance Becomes Support) dan SBR (Support Becomes Resistance).

    RBS: Level yang dulu swing-HIGH (resistance), kemudian price break di atasnya,
         sekarang price pullback mendekati level itu dari atas → zona beli/bounce.

    SBR: Level yang dulu swing-LOW (support), kemudian price break di bawahnya,
         sekarang price retest dari bawah → zona waspada/rejection.

    Args:
        df      : DataFrame OHLCV harian (setidaknya 60 bar)
        harga   : harga saat ini (regularMarketPrice / close terakhir)
        tol_pct : toleransi proximity dalam % dari level (default 2%)

    Returns:
        (rbs_levels, sbr_levels) — list of float (kosong jika tidak ada)
    """
    try:
        if df is None or len(df) < 60:
            return [], []

        closes = df["Close"].values.astype(float)
        highs  = df["High"].values.astype(float)
        lows   = df["Low"].values.astype(float)
        n      = len(closes)

        # ── Split history / recent ─────────────────────────────
        # History: bar awal s/d 20 bar sebelum terakhir (zona pembentukan level)
        # Recent : 20 bar terakhir (zona konfirmasi flip)
        hist_end = n - 20
        if hist_end < 30:
            return [], []

        # ── Swing detection di history ─────────────────────────
        w = max(3, hist_end // 15)
        swing_highs, swing_lows = [], []
        for i in range(w, hist_end - w):
            if highs[i] == max(highs[max(0, i - w): i + w + 1]):
                swing_highs.append(highs[i])
            if lows[i]  == min(lows[max(0, i - w): i + w + 1]):
                swing_lows.append(lows[i])

        # ── Cluster levels yang berdekatan (<1.5%) ─────────────
        def _cluster(vals, cl_tol=0.015):
            if not vals:
                return []
            vals = sorted(vals)
            used = [False] * len(vals)
            res  = []
            for i, v in enumerate(vals):
                if used[i]: continue
                grp = [v]
                for j in range(i + 1, len(vals)):
                    if not used[j] and abs(vals[j] - v) / (v or 1) < cl_tol:
                        grp.append(vals[j]); used[j] = True
                res.append(sum(grp) / len(grp))
            return res

        res_candidates = _cluster(swing_highs)  # dulu resistance
        sup_candidates = _cluster(swing_lows)   # dulu support

        tol           = tol_pct / 100.0
        recent_closes = closes[hist_end:]  # 20 bar terakhir
        n_recent      = len(recent_closes)
        min_break     = max(3, int(n_recent * 0.55))  # ≥55% bar harus sudah flip

        # ── RBS: resistance ditembus ke atas, harga retest dari atas ──
        rbs_levels = []
        for lvl in res_candidates:
            if lvl <= 0:
                continue
            breaks_above = sum(1 for c in recent_closes if c > lvl * 1.005)
            if breaks_above < min_break:
                continue  # belum dikonfirmasi breakout
            # Retest: harga dalam [lvl*(1-tol), lvl*(1+tol)] dan masih >= lvl*(1-tol)
            if lvl * (1 - tol) <= harga <= lvl * (1 + tol):
                rbs_levels.append(round(lvl, 0))

        # ── SBR: support ditembus ke bawah, harga retest dari bawah ──
        sbr_levels = []
        for lvl in sup_candidates:
            if lvl <= 0:
                continue
            breaks_below = sum(1 for c in recent_closes if c < lvl * 0.995)
            if breaks_below < min_break:
                continue  # belum dikonfirmasi break
            if lvl * (1 - tol) <= harga <= lvl * (1 + tol):
                sbr_levels.append(round(lvl, 0))

        return rbs_levels, sbr_levels

    except Exception:
        return [], []


# ─── Jumlah candle yang ditampilkan per TF ───────────────────
_TF_CANDLES = {
    "1":80, "1m":80, "2":80, "2m":80, "3":80, "3m":80,
    "5":100,"5m":100,"10":80,"10m":80,
    "15":80,"15m":80,"30":60,"30m":60,
    "1j":60,"1jam":60,"1h":60,"2j":50,"4j":50,"4jam":50,"4h":50,"h":50,
    "1d":60,"1hari":60,"24h":60,"d":60,
    "1mg":52,"1w":52,"1minggu":52,"w":52,
}
_TF_INTRADAY = {"1","1m","2","2m","3","3m","5","5m","10","10m","15","15m","30","30m",
                "1j","1jam","1h","2j","4j","4jam","4h","h"}

def buat_chart_c(ticker, df, harga, tf_key, tf_label, sr_levels, engulfing_info=None, dest=None):
    """
    Chart /c — KhanSaab Sniper style:
    • EMA9/EMA21 ribbon (fill hijau=bullish, merah=bearish)
    • EMA50 line
    • VWAP line
    • BUY label hijau di bawah candle saat entry signal
    • SELL label merah di atas candle saat exit/short signal
    • Volume panel
    • S/R lines + harga sekarang
    """
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    import matplotlib.patches as mpatches
    import pandas as pd
    import numpy as np
    import traceback

    BG      = "#131722"
    C_UP    = "#26a69a"   # teal — candle bullish
    C_DN    = "#ef5350"   # red  — candle bearish
    C_E9    = "#26a69a"   # EMA9
    C_E21   = "#ef5350"   # EMA21
    C_E50   = "#ff9800"   # EMA50
    C_VWAP  = "#e040fb"   # VWAP
    C_BUY   = "#00e676"   # BUY label bg
    C_SELL  = "#ff1744"   # SELL label bg
    GRID    = "#1e222d"

    n_show   = _TF_CANDLES.get(tf_key, 80)
    is_intra = tf_key in _TF_INTRADAY

    try:
        df_plot = df.tail(n_show).copy()
        n = len(df_plot)
        if n < 5:
            if dest: dest_kirim_teks(dest, f"⚠️ Chart: data hanya {n} candle, tidak cukup.")
            return None

        opens  = np.array(df_plot["Open"].values,  dtype=float)
        highs  = np.array(df_plot["High"].values,  dtype=float)
        lows   = np.array(df_plot["Low"].values,   dtype=float)
        closes = np.array(df_plot["Close"].values, dtype=float)
        vols   = np.array(df_plot["Volume"].values, dtype=float)
        dates  = list(df_plot.index)

        y_min = float(np.nanmin(lows))
        y_max = float(np.nanmax(highs))
        y_rng = y_max - y_min if y_max > y_min else y_max * 0.05

        fig, (ax, ax_vol) = plt.subplots(
            2, 1, figsize=(14, 7),
            gridspec_kw={"height_ratios": [4, 1]},
            facecolor=BG)
        ax.set_facecolor(BG)
        ax_vol.set_facecolor(BG)
        ax.grid(True, color=GRID, linewidth=0.4, ls="--", alpha=0.6, zorder=0)

        # ── Candle body + wick ───────────────────────────────
        cw = max(0.3, 0.6 * min(1.0, 80 / max(n, 1)))
        for i in range(n):
            o, h, l, c = opens[i], highs[i], lows[i], closes[i]
            if any(np.isnan(x) for x in (o, h, l, c)): continue
            clr = C_UP if c >= o else C_DN
            ax.plot([i, i], [l, h], color=clr, linewidth=0.8, zorder=2)
            body_h = max(abs(c - o), y_rng * 0.001)
            rect = mpatches.Rectangle(
                (i - cw/2, min(o, c)), cw, body_h,
                linewidth=0, facecolor=clr, zorder=3)
            ax.add_patch(rect)

        # ── Volume bar ──────────────────────────────────────
        valid_vols = vols[~np.isnan(vols)]
        avg_vol    = float(valid_vols.mean()) if len(valid_vols) > 0 else 1.0
        for i in range(n):
            if np.isnan(vols[i]): continue
            clr   = C_UP if closes[i] >= opens[i] else C_DN
            alpha = min(0.85, 0.3 + 0.55 * (vols[i] / max(avg_vol * 2, 1)))
            ax_vol.bar(i, vols[i], color=clr, alpha=alpha, width=cw * 1.1)
        # volume MA20
        if n >= 20:
            vol_ma = pd.Series(vols).rolling(20).mean().values
            ax_vol.plot(range(n), vol_ma, color="#e65100", lw=0.8, alpha=0.8)

        # ── Indicators (dari full df untuk warmup EMA50) ────
        full_cl   = pd.Series(df["Close"].values.astype(float))
        full_hi   = pd.Series(df["High"].values.astype(float))
        full_lo   = pd.Series(df["Low"].values.astype(float))
        full_vol  = pd.Series(df["Volume"].values.astype(float))

        e9_full   = full_cl.ewm(span=9,  adjust=False).mean()
        e21_full  = full_cl.ewm(span=21, adjust=False).mean()
        e50_full  = full_cl.ewm(span=50, adjust=False).mean()

        # VWAP (cumulative, reset not feasible without session data — use last n bars)
        tp_full   = (full_hi + full_lo + full_cl) / 3
        vwap_full = (tp_full * full_vol).cumsum() / full_vol.cumsum().replace(0, np.nan)

        e9   = e9_full.values[-n:]
        e21  = e21_full.values[-n:]
        e50  = e50_full.values[-n:]
        vwap = vwap_full.values[-n:]
        x    = np.arange(n)

        # ── EMA9/21 Ribbon — fill hijau/merah ────────────────
        # Ribbon = area antara EMA9 dan EMA21
        for i in range(1, n):
            if any(np.isnan(v) for v in [e9[i-1], e9[i], e21[i-1], e21[i]]): continue
            bull_now  = e9[i]   >= e21[i]
            bull_prev = e9[i-1] >= e21[i-1]
            fill_col  = "#26a69a" if (bull_now or bull_prev) else "#ef5350"
            ax.fill_between(
                [i-1, i],
                [e9[i-1],  e9[i]],
                [e21[i-1], e21[i]],
                color=fill_col, alpha=0.35, zorder=1)

        ax.plot(x, e9,   color=C_E9,   linewidth=1.2, alpha=0.9,  label="EMA9",  zorder=4)
        ax.plot(x, e21,  color=C_E21,  linewidth=1.2, alpha=0.9,  label="EMA21", zorder=4)
        ax.plot(x, e50,  color=C_E50,  linewidth=1.0, alpha=0.85, label="EMA50", zorder=4)
        ax.plot(x, vwap, color=C_VWAP, linewidth=1.0, alpha=0.8,  label="VWAP",  zorder=4, linestyle="--")

        # ── BUY / SELL Signal Detection ───────────────────────
        # BUY: EMA9 crosses above EMA21 (golden cross)
        # SELL: EMA9 crosses below EMA21 (death cross)
        buy_idx  = []
        sell_idx = []
        for i in range(1, n):
            if any(np.isnan(v) for v in [e9[i-1], e21[i-1], e9[i], e21[i]]): continue
            cross_up   = e9[i-1] <  e21[i-1] and e9[i] >= e21[i]
            cross_down = e9[i-1] >= e21[i-1] and e9[i] <  e21[i]
            if cross_up:   buy_idx.append(i)
            if cross_down: sell_idx.append(i)

        # Tambah: RSI oversold bounce (<35) → BUY
        try:
            rsi_full = hitung_rsi_wilder(full_cl, 14)
            rsi_plot = rsi_full.values[-n:]
            for i in range(1, n):
                if not np.isnan(rsi_plot[i]) and not np.isnan(rsi_plot[i-1]):
                    if rsi_plot[i-1] < 35 and rsi_plot[i] >= 35 and i not in buy_idx:
                        buy_idx.append(i)
        except: pass

        # ── Label BUY (hijau, di bawah candle) ───────────────
        bbox_buy  = dict(boxstyle="round,pad=0.3", facecolor=C_BUY,  edgecolor="none")
        bbox_sell = dict(boxstyle="round,pad=0.3", facecolor=C_SELL, edgecolor="none")
        shown_buy = set(); shown_sell = set()

        for i in sorted(set(buy_idx)):
            if i in shown_buy: continue
            if i >= n: continue
            y_lbl = lows[i] - y_rng * 0.06
            ax.text(i, y_lbl, "BUY",
                    ha="center", va="top", fontsize=7.5, fontweight="bold",
                    color="white", bbox=bbox_buy, zorder=8)
            shown_buy.add(i)

        for i in sorted(set(sell_idx)):
            if i in shown_sell: continue
            if i >= n: continue
            y_lbl = highs[i] + y_rng * 0.04
            ax.text(i, y_lbl, "SELL",
                    ha="center", va="bottom", fontsize=7.5, fontweight="bold",
                    color="white", bbox=bbox_sell, zorder=8)
            shown_sell.add(i)

        # ── S/R lines ────────────────────────────────────────
        def fh(v):
            try: return f"{int(v):,}".replace(",", ".")
            except: return str(v)

        sr_below = sorted([x for x in (sr_levels or []) if len(x) >= 2 and x[1] <= harga],
                          key=lambda x: x[1], reverse=True)[:3]
        sr_above = sorted([x for x in (sr_levels or []) if len(x) >= 2 and x[1] > harga],
                          key=lambda x: x[1])[:3]

        for item in sr_below:
            val = item[1]
            ax.axhline(y=val, color="#1B5E20", linestyle="--", linewidth=0.9, alpha=0.7)
            ax.text(n + 0.3, val, f"  S {fh(val)}", va="bottom", ha="left",
                    fontsize=6.5, color="#4CAF50", fontweight="bold")
        for item in sr_above:
            val = item[1]
            ax.axhline(y=val, color="#B71C1C", linestyle="--", linewidth=0.9, alpha=0.7)
            ax.text(n + 0.3, val, f"  R {fh(val)}", va="bottom", ha="left",
                    fontsize=6.5, color="#EF5350", fontweight="bold")

        # ── Harga sekarang ───────────────────────────────────
        ax.axhline(y=harga, color="#BB86FC", linestyle=":", linewidth=1.2, alpha=0.9)
        ax.text(n + 0.3, harga, f"  {fh(harga)}", va="bottom", ha="left",
                fontsize=7, color="#BB86FC", fontweight="bold")

        # ── Legend ───────────────────────────────────────────
        ax.legend(fontsize=6, loc="upper left",
                  facecolor="#1e222d", labelcolor="#d1d4dc",
                  framealpha=0.85, ncol=4, edgecolor=GRID)

        # ── X-axis (di ax_vol = subplot bawah, bukan ax atas) ──
        try:
            step = max(1, n // 10)
            tick_idx = list(range(0, n, step))

            # Normalize timezone-aware timestamps
            def _fmt(ts):
                try:
                    if hasattr(ts, 'tzinfo') and ts.tzinfo is not None:
                        import pytz
                        ts = ts.astimezone(pytz.timezone("Asia/Jakarta"))
                    if is_intra:
                        return ts.strftime("%H:%M")
                    else:
                        return ts.strftime("%d/%m")
                except:
                    return str(ts)[:5]

            labels = [_fmt(dates[i]) for i in tick_idx]

            # Sembunyikan x labels di ax (atas), tampilkan di ax_vol (bawah)
            ax.set_xticks(tick_idx)
            ax.set_xticklabels([""] * len(tick_idx))  # blank di atas

            ax_vol.set_xticks(tick_idx)
            ax_vol.set_xticklabels(
                labels,
                fontsize=7,
                color="#8B949E",
                rotation=30 if not is_intra else 0,
                ha="right" if not is_intra else "center"
            )
        except Exception as _xe:
            print(f"xaxis error: {_xe}")
            ax.set_xticks([])
            ax_vol.set_xticks([])

        # ── Styling ──────────────────────────────────────────
        ax.set_xlim(-1, n + 8)
        ax.set_ylim(y_min - y_rng * 0.10, y_max + y_rng * 0.18)
        ax.tick_params(axis="y", colors="#8B949E", labelsize=7)
        for sp in ax.spines.values(): sp.set_color(GRID)
        ax_vol.set_yticks([])
        for sp in ax_vol.spines.values(): sp.set_color(GRID)
        ax_vol.set_xlim(-1, n + 8)

        # jumlah sinyal di title
        kode = ticker.replace(".JK", "")
        n_buy  = len(shown_buy)
        n_sell = len(shown_sell)
        sinyal_str = f"BUY:{n_buy}×  SELL:{n_sell}×"
        ax.set_title(
            f"{kode}  |  TF {tf_label}  |  {n} candle  |  {sinyal_str}",
            fontsize=10.5, fontweight="bold", color="#E6EDF3", pad=8)

        plt.subplots_adjust(hspace=0.04)
        fig.patch.set_facecolor(BG)
        ax.set_facecolor(BG)
        ax_vol.set_facecolor(BG)
        buf = io.BytesIO()
        plt.savefig(buf, format="png", dpi=130, bbox_inches="tight", facecolor=BG)
        plt.close()
        buf.seek(0)
        return buf

    except Exception as e:
        err_detail = traceback.format_exc()
        print(f"=== buat_chart_c ERROR ({ticker} {tf_key}) ===\n{err_detail}")
        if dest:
            dest_kirim_teks(dest, f"⚠️ Chart error: `{type(e).__name__}: {str(e)[:80]}`")
        try: plt.close("all")
        except: pass
        return None


# ─────────────────────────────────────────────────────────────
# /swing KODE — Multi-TF Swing Analyzer (Weekly + Daily + 15m)
# ─────────────────────────────────────────────────────────────

# ─────────────────────────────────────────────────────────────
# /scalping KODE — Multi-TF Scalping Analyzer (1j + 15m + 5m)
# ─────────────────────────────────────────────────────────────
def cmd_scalping(kode_raw, dest):
    """
    /scalping KODE
    Auto-check 3 TF untuk scalping:
      1. 1 Jam   (HTF konteks intraday)
      2. 15 Menit (entry zone)
      3. 5 Menit  (timing masuk presisi)
    Verdict lebih ketat dari swing — semua TF harus align.
    """
    import numpy as np
    import pandas as pd

    kode   = kode_raw.upper().replace(".JK", "")
    ticker = kode + ".JK"

    dest_kirim_teks(dest, f"⚡ _Scalping Analysis *{kode}* — mengambil data 3 TF..._")

    def _analisa_tf_scalp(tf_key):
        iv, rng, tf_lbl, rs = TF_MAP[tf_key]
        try:
            df, harga, prev = get_candles_tf(ticker, iv, rng, rs)
            if df is None or len(df) < 10:
                return {"ok": False, "lbl": tf_lbl, "tf_key": tf_key}
        except Exception as e:
            return {"ok": False, "lbl": tf_lbl, "tf_key": tf_key, "err": str(e)}

        close  = pd.Series(df["Close"].values.astype(float))
        high_s = pd.Series(df["High"].values.astype(float))
        low_s  = pd.Series(df["Low"].values.astype(float))
        vol_s  = pd.Series(df["Volume"].values.astype(float))
        n      = len(close)

        e9  = float(close.ewm(span=9,  adjust=False).mean().iloc[-1])
        e21 = float(close.ewm(span=21, adjust=False).mean().iloc[-1])
        e50 = float(close.ewm(span=50, adjust=False).mean().iloc[-1])

        macd_l = close.ewm(span=12,adjust=False).mean() - close.ewm(span=26,adjust=False).mean()
        macd_s = macd_l.ewm(span=9, adjust=False).mean()
        macd_h = float(macd_l.iloc[-1] - macd_s.iloc[-1])
        macd_m = float(macd_l.iloc[-1])
        macd_sig_v = float(macd_s.iloc[-1])

        try:
            rsi = float(hitung_rsi_wilder(close, 14).iloc[-1])
            if np.isnan(rsi): rsi = 50.0
        except: rsi = 50.0

        vol_avg = float(vol_s.rolling(20).mean().iloc[-1]) if n >= 20 else float(vol_s.mean())
        vol_x   = float(vol_s.iloc[-1]) / vol_avg if vol_avg > 0 else 1.0

        # VWAP
        tp   = (high_s + low_s + close) / 3
        vwap = float((tp * vol_s).cumsum().iloc[-1] / vol_s.cumsum().iloc[-1]) if vol_s.sum() > 0 else float(close.iloc[-1])
        price = float(close.iloc[-1])

        # ATR14 — untuk SL suggestion
        prev_c = close.shift(1)
        tr_s   = (high_s-low_s).combine((high_s-prev_c).abs(),max).combine((low_s-prev_c).abs(),max)
        atr    = float(tr_s.ewm(span=14,adjust=False).mean().iloc[-1])

        # EMA cross count di 10 bar terakhir (scalp: window lebih pendek)
        e9_s  = close.ewm(span=9,  adjust=False).mean()
        e21_s = close.ewm(span=21, adjust=False).mean()
        n_buy = n_sell = 0
        for i in range(max(1, n-10), n):
            if e9_s.iloc[i-1] < e21_s.iloc[i-1] and e9_s.iloc[i] >= e21_s.iloc[i]: n_buy  += 1
            if e9_s.iloc[i-1] >= e21_s.iloc[i-1] and e9_s.iloc[i] < e21_s.iloc[i]: n_sell += 1

        ribbon_bull = e9 >= e21

        # Momentum candle: 2 candle hijau berturut-turut
        momentum_ok = (n >= 2 and
                       float(close.iloc[-1]) > float(close.iloc[-2]) and
                       float(close.iloc[-2]) > float(close.iloc[-3])) if n >= 3 else False

        # Score 0-7 (scalp lebih banyak kondisi dikeceknya)
        score = sum([
            ribbon_bull,           # 1. EMA9 > EMA21
            e9 > e21,              # 2. (same, explicit)
            macd_h > 0,            # 3. MACD hist +
            macd_m > macd_sig_v,   # 4. MACD line > signal
            rsi > 50,              # 5. RSI > 50
            rsi < 70,              # 6. RSI bukan OB (scalp: hindari OB)
            price > vwap,          # 7. Price > VWAP
        ])

        # Label — scalp lebih ketat: butuh score >= 5 untuk GREEN
        if   score >= 5: state = "🟢 BULLISH";  color = "GREEN"
        elif score >= 3: state = "🟡 NETRAL";   color = "YELLOW"
        else:            state = "🔴 BEARISH";  color = "RED"

        # SL suggestion berdasarkan ATR
        sl_tight  = round(price - 1.0 * atr)
        sl_pct    = abs(price - sl_tight) / price * 100

        # Saran spesifik per TF scalping
        if tf_key in ("1j", "1h"):
            if color == "GREEN":   saran = "Bias 1 jam bullish — aman scalp long"
            elif color == "YELLOW":saran = "Sideways — scalp hanya di dekat support"
            else:                  saran = "1 jam bearish — jangan scalp long hari ini"
        elif tf_key == "15":
            if color == "GREEN":   saran = "Setup 15m valid, cari entry di 5m"
            elif color == "YELLOW":saran = "Belum bersih, tunggu EMA cross konfirmasi"
            else:                  saran = "15m bearish — skip"
        else:  # 5m
            if color == "GREEN":   saran = f"MASUK SEKARANG — SL Rp{int(sl_tight):,} (-{sl_pct:.1f}%)"
            elif color == "YELLOW":saran = "Tunggu 1-2 candle konfirmasi lagi"
            else:                  saran = "5m bearish — jangan masuk"

        return {
            "ok": True, "tf_key": tf_key, "lbl": tf_lbl,
            "df": df, "harga": harga, "atr": atr,
            "score": score, "state": state, "color": color, "saran": saran,
            "ribbon_bull": ribbon_bull, "momentum_ok": momentum_ok,
            "rsi": rsi, "vol_x": vol_x, "macd_h": macd_h,
            "n_buy": n_buy, "n_sell": n_sell, "vwap": vwap,
            "sl_tight": sl_tight, "sl_pct": sl_pct,
        }

    # ── Fetch 3 TF ─────────────────────────────────────────────
    r_1j  = _analisa_tf_scalp("1j")
    r_15  = _analisa_tf_scalp("15")
    r_5   = _analisa_tf_scalp("5")

    results = [r_1j, r_15, r_5]
    icons   = ["🕐", "⏱", "⚡"]
    roles   = ["Konteks (1 Jam)", "Entry (15 Menit)", "Timing (5 Menit)"]

    # ── Verdict Scalping — lebih ketat dari swing ───────────────
    colors = [r.get("color","RED") if r.get("ok") else "RED" for r in results]

    all_green   = all(c == "GREEN"  for c in colors)
    htf_ok      = colors[0] == "GREEN"
    entry_ok    = colors[1] == "GREEN"
    timing_ok   = colors[2] == "GREEN"
    any_red     = any(c == "RED"    for c in colors)

    # SL dari 5m ATR
    atr5 = r_5.get("atr", 0) if r_5.get("ok") else 0
    harga_now = r_5.get("harga", 0) if r_5.get("ok") else 0
    sl_val = round(harga_now - 1.0 * atr5) if atr5 > 0 else 0
    sl_pct = abs(harga_now - sl_val) / harga_now * 100 if harga_now > 0 else 0
    tp_val = round(harga_now + 1.5 * atr5) if atr5 > 0 else 0
    tp_pct = abs(tp_val - harga_now) / harga_now * 100 if harga_now > 0 else 0

    if all_green:
        verdict     = "🟢 GO — Scalp sekarang!"
        verdict_tip = (f"Semua TF align bullish.\n"
                       f"Entry: Rp{int(harga_now):,} | SL: Rp{int(sl_val):,} (-{sl_pct:.1f}%) | TP: Rp{int(tp_val):,} (+{tp_pct:.1f}%)\n"
                       f"R:R = 1:{1.5:.1f} — Target quick exit +{tp_pct:.1f}% dalam 15-30 menit.")
    elif htf_ok and entry_ok and not timing_ok:
        verdict     = "⏳ ALMOST — Tunggu 5m konfirmasi"
        verdict_tip = (f"1j + 15m sudah bullish tapi 5m belum.\n"
                       f"Tunggu EMA9 cross EMA21 di 5m atau candle hijau konfirmasi.\n"
                       f"Jangan FOMO masuk — 1 candle saja bisa beda.")
    elif htf_ok and not entry_ok:
        verdict     = "⏳ WAIT — 1j oke, 15m belum"
        verdict_tip = (f"Bias 1 jam bullish tapi setup 15m belum bersih.\n"
                       f"Pantau 15m sampai EMA9 > EMA21 + MACD hijau.")
    elif not htf_ok:
        verdict     = "🔴 NO GO — 1 Jam bearish"
        verdict_tip = (f"Bias intraday bearish — scalp long sangat berisiko hari ini.\n"
                       f"Tunggu 1j ribbon balik hijau dulu, atau scalp saham lain.\n"
                       f"Gunakan `/algo VWAPBounce` untuk cari setup yang lebih bersih.")
    else:
        verdict     = "🟡 MIXED — Sinyal tidak seragam"
        verdict_tip = (f"Ada konflik antar TF — skip dulu.\n"
                       f"Scalping butuh semua TF searah, kalau tidak = chop zone = kena SL bolak-balik.")

    # ── Teks output ─────────────────────────────────────────────
    pesan  = f"⚡ *{kode}* — Scalping Analysis 3-TF\n"
    pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"

    for r, icon, role in zip(results, icons, roles):
        if not r.get("ok"):
            pesan += f"{icon} *{role}* : ❌ Data tidak tersedia\n\n"
            continue
        ribbon_str = "ribbon 🟢" if r["ribbon_bull"] else "ribbon 🔴"
        mom_str    = " ⚡mom" if r.get("momentum_ok") else ""
        pesan += (
            f"{icon} *{role}*\n"
            f"   {r['state']} — {ribbon_str}{mom_str}\n"
            f"   RSI:`{r['rsi']:.0f}`  Vol:`{r['vol_x']:.1f}x`  MACD hist:`{r['macd_h']:+.2f}`\n"
            f"   BUY:`{r['n_buy']}×`  SELL:`{r['n_sell']}×` _(10 bar terakhir)_\n"
            f"   💡 _{r['saran']}_\n\n"
        )

    pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
    pesan += f"🚦 *VERDICT : {verdict}*\n"
    pesan += f"💡 _{verdict_tip}_\n"
    pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
    pesan += f"📊 `/c {kode} 5` — Chart 5 menit\n"
    pesan += f"📊 `/c {kode} 15` — Chart 15 menit\n"
    pesan += f"📊 `/mf {kode}` — Money flow real-time\n"

    dest_kirim_teks(dest, pesan)

    # ── Kirim 3 chart (5m, 15m, 1j) ────────────────────────────
    for r in [r_5, r_15, r_1j]:
        if not r.get("ok"): continue
        try:
            sr_levels = hitung_sr(r["df"])
            buf = buat_chart_c(
                ticker, r["df"], r["harga"],
                r["tf_key"], r["lbl"], sr_levels,
                dest=dest
            )
            if buf:
                dest_kirim_foto_buf(dest, buf,
                    f"⚡ *{kode}* | {r['lbl']} | {r['state']} | RSI {r['rsi']:.0f} | MACD {r['macd_h']:+.2f}")
        except Exception as _ec:
            logger.warning("cmd_scalping chart error %s %s: %s", kode, r["tf_key"], _ec)



def _buat_chart_pria_solo(ticker, df_daily, harga, mtf_results, trend_label, targets, step_pct=3.0):
    """
    Render chart PRIA SOLO ala TradingView:
    - Candlestick 1D + EMA9/21 ribbon + EMA50 + Volume
    - Overlay panel kanan atas  : PRIA SOLO Forecast (trend, target 7C, C+1..C+7)
    - Overlay panel kanan bawah : 7C MTF table (TF, Sinyal, MA%, MACD FC%)
    - Dotted forecast line dari harga terakhir ke target 7C
    Return BytesIO buffer PNG.
    """
    import matplotlib
    matplotlib.use("Agg")
    import matplotlib.pyplot as plt
    import matplotlib.patches as mpatches
    import numpy as np

    BG     = "#131722"
    GRID   = "#1e222d"
    C_UP   = "#26a69a"
    C_DN   = "#ef5350"
    C_E9   = "#26a69a"
    C_E21  = "#ef5350"
    C_E50  = "#ff9800"
    C_TXT  = "#d1d4dc"
    C_HEAD = "#1e2a3a"
    C_BUY_TXT  = "#00e676"
    C_SELL_TXT = "#ff5252"
    C_FORE = "#00bcd4"  # forecast line color

    n_show = 60
    try:
        df_plot = df_daily.tail(n_show).copy()
        n = len(df_plot)
        if n < 5:
            return None

        opens  = np.array(df_plot["Open"].values,   dtype=float)
        highs  = np.array(df_plot["High"].values,   dtype=float)
        lows   = np.array(df_plot["Low"].values,    dtype=float)
        closes = np.array(df_plot["Close"].values,  dtype=float)
        vols   = np.array(df_plot["Volume"].values, dtype=float)
        dates  = list(df_plot.index)

        y_min = float(np.nanmin(lows))
        y_max = float(np.nanmax(highs))
        y_rng = y_max - y_min if y_max > y_min else y_max * 0.05

        # ── Figure: lebar ekstra di kanan untuk panel overlay ──
        fig = plt.figure(figsize=(16, 8), facecolor=BG)
        # Subplot: main chart (lebar 68%), volume panel kecil di bawah
        ax     = fig.add_axes([0.04, 0.22, 0.62, 0.72], facecolor=BG)
        ax_vol = fig.add_axes([0.04, 0.05, 0.62, 0.15], facecolor=BG)

        ax.grid(True, color=GRID, linewidth=0.4, ls="--", alpha=0.5, zorder=0)

        # ── Candles ────────────────────────────────────────────
        cw = max(0.3, 0.6 * min(1.0, 80 / max(n, 1)))
        for i in range(n):
            o, h, l, c = opens[i], highs[i], lows[i], closes[i]
            if any(np.isnan(x) for x in (o, h, l, c)): continue
            clr = C_UP if c >= o else C_DN
            ax.plot([i, i], [l, h], color=clr, linewidth=0.8, zorder=2)
            body_h = max(abs(c - o), y_rng * 0.001)
            ax.add_patch(mpatches.Rectangle(
                (i - cw/2, min(o, c)), cw, body_h,
                linewidth=0, facecolor=clr, zorder=3))

        # ── Volume ─────────────────────────────────────────────
        valid_v = vols[~np.isnan(vols)]
        avg_v   = float(valid_v.mean()) if len(valid_v) > 0 else 1.0
        for i in range(n):
            if np.isnan(vols[i]): continue
            clr   = C_UP if closes[i] >= opens[i] else C_DN
            alpha = min(0.85, 0.3 + 0.55 * (vols[i] / max(avg_v * 2, 1)))
            ax_vol.bar(i, vols[i], color=clr, alpha=alpha, width=cw * 1.1)
        if n >= 20:
            vol_ma = pd.Series(vols).rolling(20).mean().values
            ax_vol.plot(range(n), vol_ma, color="#e65100", lw=0.8, alpha=0.8)

        # ── EMAs (warmup dari full df) ─────────────────────────
        full_cl  = pd.Series(df_daily["Close"].values.astype(float))
        e9_full  = full_cl.ewm(span=9,  adjust=False).mean().values[-n:]
        e21_full = full_cl.ewm(span=21, adjust=False).mean().values[-n:]
        e50_full = full_cl.ewm(span=50, adjust=False).mean().values[-n:]
        x        = np.arange(n)

        # Ribbon EMA9/21
        for i in range(1, n):
            if any(np.isnan(v) for v in [e9_full[i-1], e9_full[i], e21_full[i-1], e21_full[i]]): continue
            bull = e9_full[i] >= e21_full[i]
            ax.fill_between([i-1, i],
                            [e9_full[i-1], e9_full[i]],
                            [e21_full[i-1], e21_full[i]],
                            color=C_UP if bull else C_DN, alpha=0.30, zorder=1)

        ax.plot(x, e9_full,  color=C_E9,  linewidth=1.2, alpha=0.9,  label="EMA9",  zorder=4)
        ax.plot(x, e21_full, color=C_E21, linewidth=1.2, alpha=0.9,  label="EMA21", zorder=4)
        ax.plot(x, e50_full, color=C_E50, linewidth=1.0, alpha=0.85, label="EMA50", zorder=4)

        # ── BUY/SELL labels on chart ────────────────────────────
        bbox_buy  = dict(boxstyle="round,pad=0.25", facecolor="#00e676", edgecolor="none")
        bbox_sell = dict(boxstyle="round,pad=0.25", facecolor="#ff1744", edgecolor="none")
        for i in range(1, n):
            if any(np.isnan(v) for v in [e9_full[i-1], e21_full[i-1], e9_full[i], e21_full[i]]): continue
            if e9_full[i-1] < e21_full[i-1] and e9_full[i] >= e21_full[i]:
                ax.text(i, lows[i] - y_rng*0.05, "BUY",
                        ha="center", va="top", fontsize=7, fontweight="bold",
                        color="white", bbox=bbox_buy, zorder=8)
            elif e9_full[i-1] >= e21_full[i-1] and e9_full[i] < e21_full[i]:
                ax.text(i, highs[i] + y_rng*0.04, "SELL",
                        ha="center", va="bottom", fontsize=7, fontweight="bold",
                        color="white", bbox=bbox_sell, zorder=8)

        # ── Harga sekarang line ─────────────────────────────────
        ax.axhline(y=harga, color="#BB86FC", linestyle=":", linewidth=1.1, alpha=0.85)
        ax.text(n - 0.5, harga, f" {int(harga):,}".replace(",","."),
                va="bottom", ha="left", fontsize=7, color="#BB86FC", fontweight="bold")

        # ── Forecast dotted line (harga → target 7C, directional) ─
        target_7c  = targets[-1][1]
        n_proj     = 7
        x_proj     = [n - 1 + i for i in range(n_proj + 1)]
        step_factor = 1 + step_pct / 100
        y_proj      = [harga * (step_factor ** i) for i in range(n_proj + 1)]
        fore_color  = C_FORE if step_pct >= 0 else C_SELL_TXT
        ax.plot(x_proj, y_proj, color=fore_color, linewidth=1.4,
                linestyle="--", alpha=0.85, zorder=5)
        ax.text(x_proj[-1] + 0.3, y_proj[-1],
                f" Rp{int(target_7c):,}".replace(",","."),
                va="center", ha="left", fontsize=7, color=fore_color, fontweight="bold")

        # ── Styling axes ────────────────────────────────────────
        ax.set_xlim(-1, n + n_proj + 3)
        y_fore_min = min(y_proj); y_fore_max = max(y_proj)
        ax.set_ylim(min(y_min, y_fore_min) - y_rng * 0.10,
                    max(y_max, y_fore_max) + y_rng * 0.22)
        ax_vol.set_xlim(-1, n + n_proj + 3)
        for sp in ax_vol.spines.values(): sp.set_color(GRID)

        # X-axis ticks
        try:
            step = max(1, n // 10)
            tick_idx = list(range(0, n, step))
            def _fmt(ts):
                try:
                    return ts.strftime("%d/%m")
                except: return str(ts)[:5]
            ax.set_xticks(tick_idx)
            ax.set_xticklabels([""] * len(tick_idx))
            ax_vol.set_xticks(tick_idx)
            ax_vol.set_xticklabels([_fmt(dates[i]) for i in tick_idx],
                                   fontsize=7, color="#8B949E", rotation=30, ha="right")
        except: pass

        ax.legend(fontsize=6, loc="upper left",
                  facecolor="#1e222d", labelcolor="#d1d4dc",
                  framealpha=0.85, ncol=3, edgecolor=GRID)

        kode = ticker.replace(".JK","")
        ax.set_title(f"{kode}  ·  1D  ·  PRIA SOLO Forecast",
                     fontsize=11, fontweight="bold", color="#E6EDF3", pad=8)

        # ══════════════════════════════════════════════════════
        # PANEL KANAN ATAS — PRIA SOLO Forecast Box
        # ══════════════════════════════════════════════════════
        px_l, px_b, px_w, px_h = 0.68, 0.45, 0.30, 0.49
        ax_box1 = fig.add_axes([px_l, px_b, px_w, px_h])
        ax_box1.set_facecolor(C_HEAD)
        ax_box1.set_xlim(0, 1); ax_box1.set_ylim(0, 1)
        ax_box1.axis("off")

        total_pct = ((target_7c - harga) / harga) * 100
        STEP_PCT  = step_pct
        fore_col  = C_BUY_TXT if step_pct >= 0 else C_SELL_TXT
        fore_sign = "+" if step_pct >= 0 else ""

        # Trend color
        if "Breakout" in trend_label:
            trend_col = C_BUY_TXT
        elif "Distribusi" in trend_label:
            trend_col = C_SELL_TXT
        else:
            trend_col = "#ffd740"

        # Header
        ax_box1.add_patch(mpatches.FancyBboxPatch(
            (0, 0.88), 1.0, 0.12, boxstyle="square,pad=0",
            facecolor="#0d1b2a", edgecolor="none"))
        ax_box1.text(0.5, 0.935, "PRIA SOLO Forecast",
                     ha="center", va="center", fontsize=9, fontweight="bold", color=C_TXT)

        # Trend row
        ax_box1.text(0.03, 0.82, "Trend", va="center", fontsize=8, color="#8B949E")
        ax_box1.text(0.97, 0.82, trend_label, va="center", ha="right",
                     fontsize=8, fontweight="bold", color=trend_col)

        # Forecast Price row
        ax_box1.text(0.03, 0.73, "Forecast Price", va="center", fontsize=8, color="#8B949E")
        ax_box1.text(0.97, 0.73, f"Rp{int(target_7c):,}".replace(",","."),
                     va="center", ha="right", fontsize=8, fontweight="bold", color=fore_col)

        # Forecast % row
        ax_box1.text(0.03, 0.64, "Forecast %", va="center", fontsize=8, color="#8B949E")
        ax_box1.text(0.97, 0.64, f"{fore_sign}{total_pct:.2f}%",
                     va="center", ha="right", fontsize=8, fontweight="bold", color=fore_col)

        # Divider
        ax_box1.axhline(y=0.60, color=GRID, linewidth=0.7)

        # 7C Forecast header row
        ax_box1.text(0.03, 0.55, "7C Forecast", va="center", fontsize=7.5,
                     fontweight="bold", color="#8B949E")
        ax_box1.text(0.55, 0.55, "MA%", va="center", ha="center", fontsize=7.5, color="#8B949E")
        ax_box1.text(0.97, 0.55, f"{fore_sign}{STEP_PCT:.2f}%", va="center", ha="right",
                     fontsize=7.5, fontweight="bold", color=fore_col)

        # C+1 to C+7
        for idx, (lbl, tp) in enumerate(targets):
            y_row = 0.48 - idx * 0.068
            ax_box1.text(0.03, y_row, lbl, va="center", fontsize=7.5, color="#8B949E")
            ax_box1.text(0.55, y_row, f"{fore_sign}{STEP_PCT:.2f}%",
                         va="center", ha="center", fontsize=7.5, color=fore_col)
            ax_box1.text(0.97, y_row,
                         f"Rp{int(tp):,}".replace(",","."),
                         va="center", ha="right", fontsize=7.5, fontweight="bold", color=C_TXT)

        # Border
        for sp in ax_box1.spines.values():
            sp.set_color("#263248"); sp.set_linewidth(1.2)

        # ══════════════════════════════════════════════════════
        # PANEL KANAN BAWAH — 7C MTF Table
        # ══════════════════════════════════════════════════════
        px2_l, px2_b, px2_w, px2_h = 0.68, 0.05, 0.30, 0.37
        ax_box2 = fig.add_axes([px2_l, px2_b, px2_w, px2_h])
        ax_box2.set_facecolor(C_HEAD)
        ax_box2.set_xlim(0, 1); ax_box2.set_ylim(0, 1)
        ax_box2.axis("off")

        # Header
        ax_box2.add_patch(mpatches.FancyBboxPatch(
            (0, 0.88), 1.0, 0.12, boxstyle="square,pad=0",
            facecolor="#0d1b2a", edgecolor="none"))
        ax_box2.text(0.5, 0.935, "7C Forecast MTF",
                     ha="center", va="center", fontsize=9, fontweight="bold", color=C_TXT)

        # Column headers
        hdrs = [("TF", 0.05), ("Last Sig", 0.33), ("MA%", 0.60), ("MACD FC%", 0.90)]
        for hdr, hx in hdrs:
            ax_box2.text(hx, 0.80, hdr, va="center", fontsize=7,
                         fontweight="bold", color="#8B949E")
        ax_box2.axhline(y=0.76, color=GRID, linewidth=0.7)

        n_mtf = len(mtf_results)
        for idx, r in enumerate(mtf_results):
            y_row = 0.69 - idx * (0.64 / max(n_mtf, 1))
            is_buy = r["signal"] == "BUY"
            sig_col = C_BUY_TXT if is_buy else C_SELL_TXT
            sig_txt = "● BUY" if is_buy else "● SELL"

            ax_box2.text(0.05, y_row, r["lbl"].strip(), va="center", fontsize=7.5, color=C_TXT)
            ax_box2.text(0.33, y_row, sig_txt, va="center", fontsize=7.5, color=sig_col, fontweight="bold")
            ma_col  = C_BUY_TXT if r["ma_pct"]      > 0 else C_SELL_TXT
            mcd_col = C_BUY_TXT if r["macd_fc_pct"] > 0 else C_SELL_TXT
            ax_box2.text(0.60, y_row, f"▲{r['ma_pct']:+.2f}%" if r["ma_pct"] > 0 else f"▼{r['ma_pct']:+.2f}%",
                         va="center", fontsize=7.5, color=ma_col)
            ax_box2.text(0.90, y_row, f"▲{r['macd_fc_pct']:+.2f}%" if r["macd_fc_pct"] > 0 else f"▼{r['macd_fc_pct']:+.2f}%",
                         va="center", fontsize=7.5, color=mcd_col)

        for sp in ax_box2.spines.values():
            sp.set_color("#263248"); sp.set_linewidth(1.2)

        # ── Export ─────────────────────────────────────────────
        buf = io.BytesIO()
        plt.savefig(buf, format="png", dpi=130, bbox_inches="tight", facecolor=BG)
        plt.close("all")
        buf.seek(0)
        return buf

    except Exception as _e:
        logger.error("buat_chart_pria_solo error: %s", _e, exc_info=True)
        try: plt.close("all")
        except: pass
        return None


def cmd_pria_solo(kode_raw, dest):
    """
    /solo KODE
    PRIA SOLO — chart gambar ala TradingView:
      - Candlestick 1D + EMA ribbon + BUY/SELL labels
      - Panel kanan atas : PRIA SOLO Forecast (trend + 7C targets)
      - Panel kanan bawah: 7C MTF table (1M/15M/30M/1H/4H/1D)
      - Dotted forecast line ke target C+7
    """
    import numpy as np

    kode   = kode_raw.upper().replace(".JK", "")
    ticker = kode + ".JK"

    dest_kirim_teks(dest, f"🔍 _PRIA SOLO sedang menganalisa *{kode}*..._")

    MTF_CONFIG = [
        ("1m",  "1M"),
        ("15",  "15M"),
        ("30",  "30M"),
        ("1j",  "1H"),
        ("4j",  "4H"),
        ("1d",  "1D"),
    ]

    def _compute_tf(tf_key, lbl):
        try:
            iv, rng, _, rs = TF_MAP[tf_key]
            df, harga, _   = get_candles_tf(ticker, iv, rng, rs)
            if df is None or len(df) < 30:
                return None
            close = pd.Series(df["Close"].values.astype(float))
            ema20 = close.ewm(span=20, adjust=False).mean()
            ma_pct = float(((close.iloc[-1] - ema20.iloc[-1]) / ema20.iloc[-1]) * 100)

            ef = close.ewm(span=12, adjust=False).mean()
            es = close.ewm(span=26, adjust=False).mean()
            hist = ef - es - (ef - es).ewm(span=9, adjust=False).mean()
            macd_fc_pct = float((hist.iloc[-1] / close.iloc[-1]) * 100)

            is_buy = (close.iloc[-1] > ema20.iloc[-1]) and (hist.iloc[-1] > hist.iloc[-2])
            return {
                "lbl"        : lbl,
                "signal"     : "BUY" if is_buy else "SELL",
                "ma_pct"     : round(ma_pct, 2),
                "macd_fc_pct": round(macd_fc_pct, 2),
                "price"      : float(close.iloc[-1]),
            }
        except Exception as _e:
            logger.warning("pria_solo tf=%s: %s", tf_key, _e)
            return None

    # ── Fetch MTF signals ──────────────────────────────────────
    mtf_results = []
    last_price  = None
    for tf_k, tf_lbl in MTF_CONFIG:
        r = _compute_tf(tf_k, tf_lbl)
        if r:
            mtf_results.append(r)
            if last_price is None:
                last_price = r["price"]

    # ── Fetch daily df untuk chart ─────────────────────────────
    try:
        iv_d, rng_d, _, rs_d = TF_MAP["1d"]
        df_daily, hp, _       = get_candles_tf(ticker, iv_d, rng_d, rs_d)
    except:
        df_daily = None; hp = last_price

    if df_daily is None or last_price is None:
        dest_kirim_teks(dest, f"❌ *{kode}* — data tidak tersedia atau ticker salah.")
        return

    if hp:
        last_price = float(hp)

    # ── Trend Phase + Dynamic Step % ──────────────────────────
    def _trend_and_step():
        try:
            close = pd.Series(df_daily["Close"].values.astype(float))
            e9    = close.ewm(span=9,  adjust=False).mean()
            e20   = close.ewm(span=20, adjust=False).mean()
            e50   = close.ewm(span=50, adjust=False).mean()
            last  = close.iloc[-1]
            e9v   = e9.iloc[-1];  e9p = e9.iloc[-2]
            e20v  = e20.iloc[-1]; e50v = e50.iloc[-1]

            # MA% dari EMA20 — jadi step per candle
            ma_pct  = (last - e20v) / e20v * 100
            step    = round(ma_pct / 7, 2)          # distribusi 7 candle

            # Trend label granular
            e9_up   = e9v > e9p                     # EMA9 naik
            above20 = last > e20v
            above50 = last > e50v

            if above20 and above50 and e9_up and e9v > e20v:
                label = "Breakout"
            elif above20 and above50 and not e9_up:
                label = "Early Downtrend"
            elif above20 and not above50 and e9_up:
                label = "Akumulasi"
            elif above20 and not above50:
                label = "Konsolidasi"
            elif not above20 and not above50 and not e9_up:
                label = "Distribusi"
            elif not above20 and not above50 and e9_up:
                label = "Early Uptrend"
            else:
                label = "Konsolidasi"

            return label, step
        except:
            return "Konsolidasi", 3.0

    trend_label, step_pct = _trend_and_step()

    # ── 7-Candle Targets (directional) ────────────────────────
    targets     = []
    p           = last_price
    step_factor = 1 + step_pct / 100
    for i in range(1, 8):
        p = p * step_factor
        targets.append((f"C+{i}", round(p, 0)))

    # ── Render chart ───────────────────────────────────────────
    buf = _buat_chart_pria_solo(ticker, df_daily, last_price, mtf_results,
                                trend_label, targets, step_pct)

    if buf:
        target_7c = targets[-1][1]
        total_pct = ((target_7c - last_price) / last_price) * 100
        sign      = "+" if total_pct >= 0 else ""
        caption = (
            f"🎯 *PRIA SOLO — {kode}*\n"
            f"💰 Harga: Rp{int(last_price):,} | "
            f"Trend: {trend_label} | "
            f"Target 7C: Rp{int(target_7c):,} ({sign}{total_pct:.2f}%)"
        ).replace(",", ".")
        dest_kirim_foto_buf(dest, buf, caption)
    else:
        dest_kirim_teks(dest, f"❌ *{kode}* — gagal render chart.")


def cmd_swing(kode_raw, dest):
    """
    /swing KODE
    Auto-check 3 TF sekaligus:
      1. 1 Minggu (HTF — arah besar)
      2. 1 Hari   (entry zone)
      3. 15 Menit (timing masuk)
    Kirim 3 chart + verdict GO / WAIT / NO GO.
    """
    import numpy as np
    import pandas as pd

    kode   = kode_raw.upper().replace(".JK", "")
    ticker = kode + ".JK"

    dest_kirim_teks(dest, f"🔍 _Swing Analysis *{kode}* — mengambil data 3 TF..._")

    # ── Helper: analisa satu TF ────────────────────────────────
    def _analisa_tf(tf_key):
        """Return dict result untuk satu TF."""
        iv, rng, tf_lbl, rs = TF_MAP[tf_key]
        try:
            df, harga, prev = get_candles_tf(ticker, iv, rng, rs)
            if df is None or len(df) < 10:
                return {"ok": False, "lbl": tf_lbl, "tf_key": tf_key}
        except Exception as e:
            return {"ok": False, "lbl": tf_lbl, "tf_key": tf_key, "err": str(e)}

        close  = pd.Series(df["Close"].values.astype(float))
        high_s = pd.Series(df["High"].values.astype(float))
        low_s  = pd.Series(df["Low"].values.astype(float))
        vol_s  = pd.Series(df["Volume"].values.astype(float))
        n      = len(close)

        # EMAs
        e9  = float(close.ewm(span=9,  adjust=False).mean().iloc[-1])
        e21 = float(close.ewm(span=21, adjust=False).mean().iloc[-1])
        e50 = float(close.ewm(span=50, adjust=False).mean().iloc[-1])
        e200= float(close.ewm(span=200, adjust=False).mean().iloc[-1]) if n >= 50 else e50

        # MACD
        macd_l = close.ewm(span=12,adjust=False).mean() - close.ewm(span=26,adjust=False).mean()
        macd_s = macd_l.ewm(span=9, adjust=False).mean()
        macd_h = float(macd_l.iloc[-1] - macd_s.iloc[-1])
        macd_trend = "BULL" if macd_h > 0 else "BEAR"

        # RSI
        try:
            rsi = float(hitung_rsi_wilder(close, 14).iloc[-1])
            if np.isnan(rsi): rsi = 50.0
        except: rsi = 50.0

        # Volume
        vol_avg = float(vol_s.rolling(20).mean().iloc[-1]) if n >= 20 else float(vol_s.mean())
        vol_x   = float(vol_s.iloc[-1]) / vol_avg if vol_avg > 0 else 1.0

        # VWAP
        tp   = (high_s + low_s + close) / 3
        vwap = float((tp * vol_s).cumsum().iloc[-1] / vol_s.cumsum().iloc[-1]) if vol_s.sum() > 0 else float(close.iloc[-1])
        price = float(close.iloc[-1])

        # EMA ribbon signal count (berapa kali EMA9 cross EMA21 naik/turun di 20 bar terakhir)
        e9_s  = close.ewm(span=9,  adjust=False).mean()
        e21_s = close.ewm(span=21, adjust=False).mean()
        n_buy = n_sell = 0
        for i in range(max(1, n-20), n):
            if e9_s.iloc[i-1] < e21_s.iloc[i-1] and e9_s.iloc[i] >= e21_s.iloc[i]: n_buy  += 1
            if e9_s.iloc[i-1] >= e21_s.iloc[i-1] and e9_s.iloc[i] < e21_s.iloc[i]: n_sell += 1

        # Ribbon state sekarang
        ribbon_bull = e9 >= e21

        # HTF bull
        htf_bull = e50 >= e200

        # Scoring 0-6
        score = sum([
            ribbon_bull,           # 1. EMA9 > EMA21
            e21 > e50,             # 2. EMA21 > EMA50
            htf_bull,              # 3. HTF (EMA50 > EMA200)
            macd_h > 0,            # 4. MACD bullish
            rsi > 50,              # 5. RSI > 50
            price > vwap,          # 6. Price > VWAP
        ])

        # Label state
        if   score >= 5: state = "🟢 BULLISH";  color = "GREEN"
        elif score >= 3: state = "🟡 NETRAL";   color = "YELLOW"
        else:            state = "🔴 BEARISH";  color = "RED"

        # Saran per TF
        if color == "GREEN":
            if tf_key in ("1mg", "1w"):     saran = "HTF mendukung swing entry"
            elif tf_key in ("1d", "d"):     saran = "Setup entry valid, cari timing"
            else:                            saran = "Timing bagus, bisa masuk sekarang"
        elif color == "YELLOW":
            if tf_key in ("1mg", "1w"):     saran = "HTF transisi — sizing kecil dulu"
            elif tf_key in ("1d", "d"):     saran = "Entry dengan konfirmasi tambahan"
            else:                            saran = "Tunggu breakout konfirmasi 1-2 candle"
        else:
            if tf_key in ("1mg", "1w"):     saran = "HTF bearish — hindari swing beli"
            elif tf_key in ("1d", "d"):     saran = "Belum ada setup — tunggu reversal"
            else:                            saran = "Intraday bearish — jangan masuk"

        return {
            "ok": True, "tf_key": tf_key, "lbl": tf_lbl,
            "df": df, "harga": harga,
            "score": score, "state": state, "color": color, "saran": saran,
            "ribbon_bull": ribbon_bull, "htf_bull": htf_bull,
            "rsi": rsi, "vol_x": vol_x, "macd_trend": macd_trend,
            "n_buy": n_buy, "n_sell": n_sell,
            "e9": e9, "e21": e21, "e50": e50,
        }

    # ── Fetch 3 TF ─────────────────────────────────────────────
    r_wk = _analisa_tf("1mg")
    r_1d = _analisa_tf("1d")
    r_15 = _analisa_tf("15")

    results = [r_wk, r_1d, r_15]
    icons   = ["🗓", "📅", "⏱"]
    roles   = ["HTF (Weekly)", "Entry (Daily)", "Timing (15m)"]

    # ── Verdict Logic ───────────────────────────────────────────
    # Catatan: 15m dari YF untuk IDX bisa delay/missing — bukan hard gate
    colors = [r.get("color","RED") if r.get("ok") else "RED" for r in results]
    htf_ok    = colors[0] == "GREEN"
    entry_ok  = colors[1] in ("GREEN", "YELLOW")
    timing_ok = colors[2] in ("GREEN", "YELLOW") if r_15.get("ok") else True  # 15m missing → tidak blok

    timing_note = "" if r_15.get("ok") else "\n   ⚠️ _Data 15m tidak tersedia (YF delay) — gunakan chart `/rencana` untuk timing_"

    if htf_ok and entry_ok and timing_ok:
        verdict     = "🟢 GO — Setup lengkap, siap entry"
        verdict_tip = (f"EMA Weekly bullish + Daily setup valid + 15m timing oke.\n"
                       f"Entry saat ini, SL -6%, target +15%. Validasi: `/backtest {kode} MODAL swing`"
                       f"{timing_note}")
    elif not htf_ok and entry_ok:
        verdict     = "⚠️ WAIT — Counter-trend setup"
        verdict_tip = (f"HTF (Weekly) masih bearish — gelombang besar belum berpihak.\n"
                       f"Kalau tetap masuk: sizing maks 30%, SL ketat -3%, target realistis +5%.\n"
                       f"Tunggu Weekly ribbon balik hijau untuk full sizing.{timing_note}")
    elif htf_ok and not entry_ok:
        verdict     = "⏳ WAIT — HTF oke, entry belum"
        verdict_tip = (f"Weekly sudah bullish tapi Daily belum setup.\n"
                       f"Sabar tunggu pullback ke EMA21 Daily lalu bounce, atau MACD GC konfirmasi.")
    elif not htf_ok and not entry_ok:
        verdict     = "🔴 NO GO — Semua TF bearish"
        verdict_tip = (f"Tidak ada setup valid di semua TF.\n"
                       f"Skip dulu. Cari saham lain dengan `/algo SwingHook` atau `/radar`.")
    else:
        verdict     = "🟡 MIXED — Setup sebagian"
        verdict_tip = (f"Sinyal tidak seragam antar TF — risiko lebih tinggi.\n"
                       f"Tunggu konfirmasi lebih kuat sebelum masuk.")

    # ── Bangun teks output ──────────────────────────────────────
    pesan = f"📊 *{kode}* — Swing Analysis 3-TF\n"
    pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"

    for r, icon, role in zip(results, icons, roles):
        if not r.get("ok"):
            pesan += f"{icon} *{role}* : ❌ Data tidak tersedia\n\n"
            continue
        ribbon_str = "ribbon 🟢" if r["ribbon_bull"] else "ribbon 🔴"
        htf_str    = "HTF 🟢" if r["htf_bull"] else "HTF 🔴"
        pesan += (
            f"{icon} *{role}* ({r['lbl']})\n"
            f"   {r['state']} — {ribbon_str}, {htf_str}\n"
            f"   RSI:`{r['rsi']:.0f}`  Vol:`{r['vol_x']:.1f}x`  MACD:`{r['macd_trend']}`\n"
            f"   BUY:`{r['n_buy']}×`  SELL:`{r['n_sell']}×` _(20 bar terakhir)_\n"
            f"   💡 _{r['saran']}_\n\n"
        )

    pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
    pesan += f"🚦 *VERDICT : {verdict}*\n"
    pesan += f"💡 _{verdict_tip}_\n"
    pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
    pesan += f"📈 `/rencana {kode}` — Sniper chart 6mo\n"
    pesan += f"📊 `/backtest {kode} MODAL swing` — Validasi\n"

    dest_kirim_teks(dest, pesan)

    # ── Kirim 3 chart ──────────────────────────────────────────
    tf_chart_map = [("1mg", "1 Minggu"), ("1d", "1 Hari"), ("15", "15 Menit")]
    for r, (_, tf_lbl_c) in zip(results, tf_chart_map):
        if not r.get("ok"): continue
        try:
            sr_levels = hitung_sr(r["df"])
            buf = buat_chart_c(
                ticker, r["df"], r["harga"],
                r["tf_key"], r["lbl"], sr_levels,
                dest=dest
            )
            if buf:
                dest_kirim_foto_buf(dest, buf,
                    f"📊 *{kode}* | {r['lbl']} | {r['state']} | RSI {r['rsi']:.0f} | Vol {r['vol_x']:.1f}x")
        except Exception as _ec:
            logger.warning("cmd_swing chart error %s %s: %s", kode, r["tf_key"], _ec)


def _sniper_dashboard_txt(df):
    """
    Replika dashboard 'Sniper Entry/Exit with SL&TP by KhanSaab V.02'
    dalam format teks Telegram.
    Metrics: Bear Score, Market Bias, Price/VWAP, MACD Trend,
             ADX Power, EMA Cross, ATR14, Vol Status, RSI,
             MACD vals, Strength, Status.
    """
    import numpy as np
    try:
        close  = df["Close"].astype(float)
        high   = df["High"].astype(float)
        low    = df["Low"].astype(float)
        volume = df["Volume"].astype(float)
        n = len(close)
        if n < 26:
            return ""

        # ── EMA 9 & 21 ───────────────────────────────────────
        ema9  = close.ewm(span=9,  adjust=False).mean()
        ema21 = close.ewm(span=21, adjust=False).mean()
        e9    = float(ema9.iloc[-1])
        e21   = float(ema21.iloc[-1])
        ema_cross = "BULL" if e9 > e21 else "BEAR"

        # ── MACD (12,26,9) ───────────────────────────────────
        macd_line = close.ewm(span=12,adjust=False).mean() - \
                    close.ewm(span=26,adjust=False).mean()
        macd_sig  = macd_line.ewm(span=9, adjust=False).mean()
        macd_hist = macd_line - macd_sig
        m_main = float(macd_line.iloc[-1])
        m_sig  = float(macd_sig.iloc[-1])
        macd_trend = "BULL" if m_main > m_sig else "BEAR"

        # ── ATR 14 ────────────────────────────────────────────
        prev_c = close.shift(1)
        tr_s   = (high - low).combine(
                    (high - prev_c).abs(), max).combine(
                    (low  - prev_c).abs(), max)
        atr14  = float(tr_s.ewm(span=14, adjust=False).mean().iloc[-1])

        # ── ADX 14 ────────────────────────────────────────────
        ph = high.diff(); pl = -low.diff()
        pdm = ph.where((ph > pl) & (ph > 0), 0.0)
        ndm = pl.where((pl > ph) & (pl > 0), 0.0)
        atr_s  = tr_s.ewm(span=14, adjust=False).mean()
        pdi14  = 100 * pdm.ewm(span=14,adjust=False).mean() / atr_s.replace(0, np.nan)
        ndi14  = 100 * ndm.ewm(span=14,adjust=False).mean() / atr_s.replace(0, np.nan)
        dx     = (100 * (pdi14 - ndi14).abs() / (pdi14 + ndi14).replace(0, np.nan))
        adx14  = float(dx.ewm(span=14, adjust=False).mean().iloc[-1])
        if np.isnan(adx14): adx14 = 0.0

        # ── VWAP (session — typical price weighted) ───────────
        tp   = (high + low + close) / 3
        vwap = (tp * volume).cumsum() / volume.cumsum().replace(0, np.nan)
        vwap_val = float(vwap.iloc[-1]) if not np.isnan(float(vwap.iloc[-1])) else float(close.iloc[-1])
        price_now = float(close.iloc[-1])
        vwap_pos  = "ABOVE" if price_now >= vwap_val else "BELOW"

        # ── RSI 14 ────────────────────────────────────────────
        rsi_val = float(hitung_rsi_wilder(close, 14).iloc[-1])
        if np.isnan(rsi_val): rsi_val = 50.0

        # ── Volume Status ─────────────────────────────────────
        vol_avg20 = float(volume.rolling(20).mean().iloc[-1]) if n >= 20 else float(volume.mean())
        vol_last  = float(volume.iloc[-1])
        vol_x     = vol_last / vol_avg20 if vol_avg20 > 0 else 1.0
        if   vol_x >= 1.5: vol_status = "HIGH"
        elif vol_x >= 0.7: vol_status = "NORMAL"
        else:              vol_status = "LOW"

        # ── Bear Score (0-100%) — count bearish conditions ───
        bear_conds = [
            price_now < e9,              # price < EMA9
            e9        < e21,             # EMA9 < EMA21  (bear cross)
            m_main    < m_sig,           # MACD bearish
            rsi_val   < 50,              # RSI < 50
            price_now < vwap_val,        # price < VWAP
            adx14     < 20,              # no trend (ambiguous → mild bear penalty)
            vol_status == "LOW",         # low volume (weak conviction)
        ]
        bear_score = int(sum(bear_conds) / len(bear_conds) * 100)

        # ── Market Bias ───────────────────────────────────────
        if   bear_score <= 15: bias = "STRONG BULL"; bias_emj = "🟢"
        elif bear_score <= 35: bias = "BULL";         bias_emj = "💚"
        elif bear_score <= 64: bias = "NEUTRAL";      bias_emj = "🟡"
        elif bear_score <= 84: bias = "BEAR";         bias_emj = "🟠"
        else:                  bias = "STRONG BEAR";  bias_emj = "🔴"

        # ── Strength ──────────────────────────────────────────
        if   adx14 >= 35: strength = "STRONG"
        elif adx14 >= 20: strength = "MODERATE"
        else:             strength = "WEAK"

        # ── Status ────────────────────────────────────────────
        if   adx14 < 15:   status = "NO TRADE"
        elif bear_score > 50: status = "WAIT"
        elif bear_score <= 35 and adx14 >= 20: status = "ACTIVE"
        else:                  status = "WAIT"

        # ── Warna emojis ─────────────────────────────────────
        def _clr(val, good="BULL"): return "🟢" if val == good else "🔴"

        txt = (
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"🎯 *Sniper Dashboard*\n"
            f"━━━━━━━━━━━━━━━━━━━━━━\n"
            f"🐻 Bear Score   : `{bear_score}%`\n"
            f"{bias_emj} Market Bias  : `{bias}`\n"
            f"💧 Price/VWAP  : `{vwap_pos}` _(Rp{int(vwap_val):,})_\n"
            f"━━━\n"
            f"〰 EMA Cross   : {_clr(ema_cross)} `{ema_cross}`\n"
            f"⚡ MACD Trend  : {_clr(macd_trend)} `{macd_trend}`\n"
            f"    Main:`{m_main:+.2f}` Sig:`{m_sig:+.2f}`\n"
            f"📐 ADX Power   : `{adx14:.1f}` — `{strength}`\n"
            f"📏 ATR14       : `{atr14:.2f}`\n"
            f"📊 RSI(14)     : `{rsi_val:.1f}`\n"
            f"🔊 Vol Status  : `{vol_status}` _({vol_x:.1f}×avg)_\n"
            f"━━━\n"
            f"🚦 Status      : `{status}`\n"
        )
        return txt
    except Exception as _e:
        return ""


def proses_cmd_c(kode, tf_input, dest):
    """Handler /c — analisa entry + trend + SELALU kirim chart."""
    tf_key = tf_input.lower().strip()
    if tf_key not in TF_MAP:
        dest_kirim_teks(dest,
            "⚠️ Timeframe tidak dikenal.\n"
            "Pilihan: `1` `2` `3` `5` `10` `15` `30` `1j` `2j` `4j` `1d` `1mg`\n"
            "Contoh: `/c bbca 3` (3 menit)  `/c bbca 15`  `/c bbca 1j`")
        return
    interval,rng,tf_label,resample=TF_MAP[tf_key]
    ticker=kode+".JK"
    dest_kirim_teks(dest, f"🔍 Analisa *{kode}* TF {tf_label}...")
    try:
        df,harga,prev=get_candles_tf(ticker,interval,rng,resample)
        if len(df)<5:
            dest_kirim_teks(dest, f"❌ Data {kode} TF {tf_label} tidak cukup."); return
        eng=cek_engulfing_df(df); sr_levels=hitung_sr(df); tr=analisa_trend(df)
        def fh(v): return f"{int(v):,}".replace(",",".")

        # Gain sesuai konteks TF:
        # - Daily/intraday → gain hari ini (meta previousClose)
        # - Weekly  (1wk) → WoW, Quarterly (3mo) → QoQ
        # - Yearly (1mo interval) → YoY (12 candle bulanan ke belakang)
        if interval in ("1wk", "3mo", "1mo"):
            if len(df) >= 2:
                harga = float(df["Close"].iloc[-1])
                if interval == "1mo":
                    lookback = min(12, len(df) - 1)
                    prev = float(df["Close"].iloc[-1 - lookback])
                else:
                    prev = float(df["Close"].iloc[-2])
        else:
            # Daily & intraday (1m,2m,5m,15m,30m,60m,1d):
            # pakai meta previousClose dari 3mo — sama persis dengan /scan
            try:
                _, meta3 = _ambil_data_harian_radar(ticker, "3mo")
                harga = float(meta3.get("regularMarketPrice") or harga)
                prev  = float(meta3.get("previousClose") or prev)
            except: pass
        gain=(harga-prev)/prev*100 if prev>0 else 0; arah="📈" if gain>=0 else "📉"
        if interval == "1mo":   gain_lbl = "YoY"
        elif interval == "3mo": gain_lbl = "QoQ"
        elif interval == "1wk": gain_lbl = "WoW"
        else:                   gain_lbl = "1D"
        sr_below=sorted([x for x in sr_levels if x[1]<=harga],key=lambda x:x[1],reverse=True)[:2]
        sr_above=sorted([x for x in sr_levels if x[1]>harga],key=lambda x:x[1])[:2]
        pesan  = f"🔍 *ANALISA ENTRY — {kode}*\n"
        pesan += f"⏱️ TF : *{tf_label}*  |  {now_wib().strftime('%H:%M')} WIB\n"
        pesan += f"💰 Harga : Rp {fh(harga)}  {arah} {gain:+.2f}% ({gain_lbl})\n"
        pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
        pesan += f"{tr['warna']} *Trend : {tr['trend']}*\n"
        pesan += f"📌 {tr['saran']}\n"
        pesan += f"📊 RSI    : *{tr['rsi']}* {tr['rsi_emj']}\n"
        _vol_str = f"{tr['vol_x']:.1f}x" if tr['vol_x'] is not None else "N/A"
        pesan += f"📦 Volume : *{_vol_str}* avg {tr['vol_emj']}\n"
        pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
        c=df.iloc[-1]; body=abs(float(c["Close"])-float(c["Open"]))
        lower_wick=float(min(c["Open"],c["Close"]))-float(c["Low"])
        upper_wick=float(c["High"])-float(max(c["Open"],c["Close"]))
        hammer=body>0 and lower_wick>=2*body and upper_wick<=0.5*body
        inside=(float(df.iloc[-1]["High"])<=float(df.iloc[-2]["High"]) and
                float(df.iloc[-1]["Low"])>=float(df.iloc[-2]["Low"])) if len(df)>=2 else False
        if eng:
            ratio=eng["ratio"]; kekuatan="🔥 KUAT" if ratio>=2.0 else ("💪 SEDANG" if ratio>=1.5 else "✅ VALID")
            c0=eng["c0"]; sl=min(float(df["Low"].iloc[-2]),float(df["Low"].iloc[-1]))
            tp1=sr_above[0][1] if sr_above else harga*1.03
            pesan+=f"🐂 *BULLISH ENGULFING!*  {kekuatan}\n"
            pesan+=f"🟢 Entry  : Rp {fh(c0['Open'])} – Rp {fh(c0['Close'])}\n"
            pesan+=f"🛑 SL     : < Rp {fh(sl)}\n"
            pesan+=f"🎯 Target : Rp {fh(tp1)}\n"
        elif hammer:
            sl=float(c["Low"])*0.998; tp1=sr_above[0][1] if sr_above else harga*1.02
            pesan+=f"🔨 *HAMMER* — Potensi reversal bullish\n"
            pesan+=f"🛑 SL     : < Rp {fh(sl)}\n"
            pesan+=f"🎯 Target : Rp {fh(tp1)}\n"
        elif inside:
            pesan+=f"📦 *INSIDE BAR* — Konsolidasi ketat\n"
            pesan+=f"💡 Tunggu breakout candle berikutnya\n"
        else:
            pesan+=f"😴 Belum ada sinyal entry jelas\n"
            if "UPTREND" in tr["trend"]:
                pesan+=f"💡 Tunggu pullback ke EMA20 (Rp {fh(tr['ema20'])})\n"
            elif "DOWNTREND" in tr["trend"]:
                pesan+=f"💡 Hindari beli — tunggu reversal\n"
            else:
                pesan+=f"💡 Pantau breakout dari S/R berikut\n"
        pesan+=f"━━━━━━━━━━━━━━━━━━━━━━\n"
        for _,val,_ in sr_above[:2]: pesan+=f"🔴 R: Rp {fh(val)} (+{(val-harga)/harga*100:.1f}%)\n"
        for _,val,_ in sr_below[:2]: pesan+=f"🟢 S: Rp {fh(val)} (-{(harga-val)/harga*100:.1f}%)\n"
        # ── Sniper Dashboard (KhanSaab-style) ─────────────────
        pesan += _sniper_dashboard_txt(df)
        dest_kirim_teks(dest, pesan)
        # ── Chart: pakai buat_chart_c yang TF-aware ──────────
        buf = buat_chart_c(ticker, df, harga, tf_key, tf_label, sr_levels, eng, dest=dest)
        if buf:
            sinyal_str = "🐂 Engulfing" if eng else ("🔨 Hammer" if hammer else tr["trend"])
            _vx_c = f"{tr['vol_x']:.1f}x" if tr['vol_x'] is not None else "N/A"
            cap = (f"📊 *{kode}* | TF {tf_label} | {sinyal_str}\n"
                   f"RSI {tr['rsi']} | Vol {_vx_c} | {now_wib().strftime('%H:%M')} WIB")
            dest_kirim_foto_buf(dest, buf, cap)
        else:
            # fallback ke DSL chart dengan TF yang benar
            buf2 = buat_chart_dsl(ticker, tf_key)
            if buf2: dest_kirim_foto_buf(dest, buf2, f"📊 {kode} | {tf_label}")
    except Exception as e:
        import traceback; traceback.print_exc()
        dest_kirim_teks(dest, f"❌ Gagal analisa *{kode}*: {str(e)[:60]}")

