def skor_teknikal(ticker):
    """Skor teknikal 0-100 untuk ranking saham rekomendasi."""
    try:
        df, harga, prev = get_candles_tf(ticker, "1d", "3mo")
        if len(df) < 30 or harga < 50 or harga > 50000: return None
        close = df["Close"]; vol = df["Volume"]
        ema20  = close.ewm(span=20, adjust=False).mean()
        ema50  = close.ewm(span=50, adjust=False).mean()
        ema12  = close.ewm(span=12, adjust=False).mean()
        ema26  = close.ewm(span=26, adjust=False).mean()
        macd   = (ema12-ema26).iloc[-1]
        signal = (ema12-ema26).ewm(span=9,adjust=False).mean().iloc[-1]
        rsi    = float(hitung_rsi_wilder(close).iloc[-1])
        if rsi != rsi: return None
        vol_avg  = float(vol.rolling(10).mean().iloc[-1])
        vol_x    = float(vol.iloc[-1])/vol_avg if vol_avg>0 else 0
        gain_pct = (harga-prev)/prev*100 if prev>0 else 0
        e20      = float(ema20.iloc[-1]); e50 = float(ema50.iloc[-1])
        e20_5    = float(ema20.iloc[-5]) if len(ema20)>=5 else e20
        slope20  = (e20-e20_5)/e20_5*100 if e20_5>0 else 0
        skor=0; detail=[]
        if harga>e20:  skor+=20; detail.append("Di atas EMA20")
        if harga>e50:  skor+=15; detail.append("Di atas EMA50")
        if 40<=rsi<=65: skor+=20; detail.append(f"RSI optimal ({rsi:.0f})")
        elif 30<=rsi<40: skor+=10; detail.append(f"RSI oversold ({rsi:.0f})")
        elif rsi>70: skor-=10
        if macd>signal: skor+=15; detail.append("MACD bullish")
        if vol_x>=1.5: skor+=15; detail.append(f"Volume {vol_x:.1f}x")
        elif vol_x>=1.0: skor+=5
        if 0.3<=gain_pct<=3.0: skor+=10; detail.append(f"+{gain_pct:.1f}%")
        elif gain_pct>5.0: skor-=5
        if slope20>0.1: skor+=5; detail.append("EMA20 naik")
        return {"ticker":ticker,"kode":ticker.replace(".JK",""),"harga":harga,
                "gain_pct":gain_pct,"rsi":rsi,"vol_x":vol_x,
                "skor":max(0,min(100,skor)),"detail":detail[:3]}
    except: return None


def jalankan_auto_rekomendasi(sesi):
    """Scan TOP 5 rekomendasi → DM ke semua member (bukan ke topic)."""
    import random
    now_str = now_wib().strftime("%d-%m-%Y %H:%M")
    label = "🌅 REKOMENDASI PAGI — Beli di Open" if sesi=="pagi" else "🌆 REKOMENDASI SORE — Swing Overnight"
    sub   = "📌 Kandidat beli saat market buka" if sesi=="pagi" else "📌 Kandidat hold overnight"
    thr   = 50 if sesi=="pagi" else 55
    print(f"⏰ Auto Rekom [{sesi}] scanning...")
    sample = list(watchlist); random.shuffle(sample)
    hasil=[]; dicek=0
    for ticker in sample:
        if bot_stop: break
        try:
            sk = skor_teknikal(ticker)
            if sk and sk["skor"]>=thr: hasil.append(sk)
            dicek+=1
            if len(hasil)>=20: break
            time.sleep(0.25)
        except: pass
    hasil.sort(key=lambda x: x["skor"], reverse=True); top5=hasil[:5]
    def fh(v): return f"{int(v):,}".replace(",",".")
    if not top5:
        pesan = f"📭 *{label}*\nTidak ada saham memenuhi kriteria hari ini.\n_Market mungkin sedang bearish._"
    else:
        pesan  = f"🏆 *{label}*\n📅 {now_str} WIB\n━━━━━━━━━━━━━━━━━━━━━━\n"
        medals = ["🥇","🥈","🥉","4️⃣","5️⃣"]
        for i, sk in enumerate(top5):
            g=sk["gain_pct"]; g_emj="📈" if g>=0 else "📉"
            alasan=" • ".join(sk["detail"]) if sk["detail"] else "Teknikal bagus"
            pesan += f"{medals[i]} *{sk['kode']}*  Rp {fh(sk['harga'])}  {g_emj} {g:+.1f}%\n"
            pesan += f"   Skor: *{sk['skor']}/100*  RSI:{sk['rsi']:.0f}  Vol:{sk['vol_x']:.1f}x\n"
            pesan += f"   _{alasan}_\n━━━━━━━━━━━━━━━━━━━━━━\n"
        pesan += "\n⚠️ _Bukan saran investasi. DYOR & gunakan SL._"
    # DM ke semua member
    members = _load_members(); bl = _load_blacklist()
    aktif = [int(uid) for uid in members if uid not in bl]
    ok = 0
    for uid in aktif:
        try:
            kirim_dm(uid, pesan); ok += 1; time.sleep(0.1)
        except: pass
    print(f"   📩 Rekom [{sesi}] → DM ke {ok} member")


def get_top_broker_market(tipe="buy"):
    """Top broker seluruh market IDX hari ini — multi-endpoint fallback."""
    HDR = {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
        "Accept"    : "application/json, text/plain, */*",
        "Referer"   : "https://www.idx.co.id/",
    }
    # Mundur s/d 5 hari kerja jika hari libur/weekend
    for delta in range(6):
        dt = now_wib() - __import__("datetime").timedelta(days=delta)
        while dt.weekday() >= 5:
            dt -= __import__("datetime").timedelta(days=1)
        today = dt.strftime("%Y%m%d")
        URLS = [
            f"https://www.idx.co.id/primary/StockData/GetTopBroker?type={tipe}&date={today}",
            f"https://www.idx.co.id/primary/TradingSummary/GetTopBroker?type={tipe}&date={today}",
            f"https://idx.co.id/umbraco/Surface/StockData/GetTopBroker?type={tipe}&startdate={today}&enddate={today}",
            f"https://idx.co.id/umbraco/Surface/StockData/GetTopBroker?type={tipe}&date={today}",
            f"https://www.idx.co.id/secondary/TradingSummary/GetTopBroker?type={tipe}&date={today}",
        ]
        for url in URLS:
            try:
                r = _http.get(url, headers=HDR, timeout=15)
                if r.status_code != 200:
                    continue
                d = r.json()
                rows = d.get("data") or d.get("Data") or d.get("result") or []
                if rows:
                    return rows
            except Exception as e:
                logger.warning("topbroker url gagal: %s — %s", url, e)
                continue
    logger.warning("get_top_broker_market: semua endpoint gagal")
    return []

def format_top_broker_market(data, tipe):
    if not data: return None
    label = "TOP BUYER" if tipe=="buy" else "TOP SELLER"
    emj   = "🟢" if tipe=="buy" else "🔴"
    pesan  = f"{emj} *{label} SELURUH MARKET IDX*\n"
    pesan += f"📅 {now_wib().strftime('%d-%m-%Y %H:%M')} WIB\n"
    pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
    medals = ["🥇","🥈","🥉","4️⃣","5️⃣","6️⃣","7️⃣","8️⃣","9️⃣","🔟"]
    for i, row in enumerate(data[:10]):
        kd  = row.get("KodeBroker") or row.get("broker") or row.get("Code","?")
        nm  = (row.get("NamaBroker") or row.get("name",""))[:20]
        vol = row.get("Volume") or row.get("Lot",0)
        asing = "🌏" if str(kd).upper() in BROKER_ASING else ""
        pesan += f"{medals[i]} *{kd}* {asing}  {nm}\n"
        pesan += f"   Volume: {fmt_lot(vol)} lot\n"
    return pesan


