def buat_weekly_summary():
    """
    Weekly summary gabung sinyal dari daily_signals (SCAN+ALGO+SCREENER)
    + win/loss track record dari signal_history.
    Dihitung sejak Senin 00:00 WIB hingga sekarang.
    """
    try:
        from collections import Counter as _Counter
        fh = lambda v: f"{int(v):,}".replace(",",".")

        # ── Part 1: Sinyal harian dari daily_signals ──────────────────────
        rows_daily = _db_load_sinyal_minggu()

        # ── Part 2: Win/loss track record dari signal_history ─────────────
        now  = now_wib()
        senin = (now - _dt.timedelta(days=now.weekday())).replace(
            hour=0, minute=0, second=0, microsecond=0)
        ts_senin = senin.timestamp()
        with _db_lock:
            conn = _db_conn(); c = conn.cursor()
            c.execute("""SELECT kode,harga_sinyal,harga_check,result,ts_signal,pola
                         FROM signal_history WHERE ts_signal >= ?
                         ORDER BY ts_signal DESC""", (ts_senin,))
            rows_hist = c.fetchall(); conn.close()

        total_sinyal  = len(rows_daily)
        unique_kode   = len(set(s["kode"] for s in rows_daily)) if rows_daily else 0
        sumber_count  = {}
        for s in rows_daily:
            src = s.get("sumber","SCAN")
            sumber_count[src] = sumber_count.get(src,0)+1

        win  = sum(1 for r in rows_hist if r[3]=="WIN")
        loss = sum(1 for r in rows_hist if r[3]=="LOSS")
        be   = sum(1 for r in rows_hist if r[3]=="BE")
        pend = sum(1 for r in rows_hist if r[3] is None)
        resolved = win+loss+be
        winrate  = win/max(win+loss,1)*100

        tgl_mulai = senin.strftime("%d/%m")
        tgl_skrg  = now.strftime("%d/%m/%Y")

        pesan  = f"📊 *WEEKLY SUMMARY — Radar Saham*\n"
        pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
        pesan += f"📅 {tgl_mulai} – {tgl_skrg} WIB\n\n"
        pesan += f"📡 *Sinyal minggu ini: {total_sinyal}* | {unique_kode} saham unik\n"
        for src, cnt in sorted(sumber_count.items()):
            emj = {"SCAN":"🔍","ALGO":"🤖"}.get(src,"📡")
            pesan += f"  {emj} {src}: {cnt}\n"
        pesan += f"\n🏆 *Track Record (3-hari):*\n"
        pesan += f"  ✅ WIN: *{win}*  ❌ LOSS: *{loss}*  ⚖️ BE: *{be}*  ⏳ Pending: *{pend}*\n"
        pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
        if resolved > 0:
            pesan += f"🎯 *Winrate: {winrate:.0f}%*  ({win}W/{loss}L/{be}BE)\n"
        else:
            pesan += f"🎯 *Winrate: menunggu resolved (≥3 hari)*\n"

        if rows_daily:
            top = _Counter(s["kode"] for s in rows_daily).most_common(10)
            pesan += f"\n*Top saham minggu ini:*\n"
            for kode, cnt in top:
                pesan += f"  📌 *{kode}* ×{cnt}\n"

        if rows_hist:
            def _sk(r): return {"WIN":0,"LOSS":1,"BE":2,None:3}.get(r[3],3)
            res_h = [r for r in sorted(rows_hist,key=_sk) if r[3] is not None]
            if res_h:
                pesan += f"\n*Hasil terbaru:*\n"
                for kode,h_s,h_c,res,ts,pola in res_h[:10]:
                    tgl2 = _dt.datetime.fromtimestamp(ts,tz=WIB).strftime("%d/%m")
                    emj2 = {"WIN":"✅","LOSS":"❌","BE":"⚖️"}.get(res,"⏳")
                    gstr = ""
                    if h_c and h_s and h_s>0:
                        g=(h_c-h_s)/h_s*100; gstr=f" ({'+' if g>=0 else ''}{g:.1f}%)"
                    src_tag = pola.split(":")[0] if pola and ":" in pola else ""
                    pesan += f"  {emj2} *{kode}*{gstr} [{tgl2}] _{src_tag}_\n"

        pesan += f"\n⚠️ _Bukan saran investasi. DYOR._"
        return pesan
    except Exception as e:
        logger.error("buat_weekly_summary: %s", e)
        return f"❌ Error weekly summary: {str(e)[:80]}"


def kirim_weekly_summary():
    """Kirim weekly summary ke topic Rekap Analisis."""
    dest_rekap = _get_rekap_dest()
    pesan = buat_weekly_summary()
    dest_kirim_teks(dest_rekap, pesan)
    logger.info("Weekly summary terkirim")


