# Tabel laporan keuangan IDX — jadwal rilis tetap per kuartal
# Q1 (Jan-Mar) → deadline laporan 30 April
# Q2 (Apr-Jun) → deadline laporan 31 Juli
# Q3 (Jul-Sep) → deadline laporan 31 Oktober
# Q4 (Okt-Des) → deadline laporan 31 Maret tahun berikutnya

def db_earnings_setup():
    try:
        conn = sqlite3.connect(DB_FILE, check_same_thread=False)
        c = conn.cursor()
        c.execute("""CREATE TABLE IF NOT EXISTS earnings_watchlist(
            user_id TEXT,
            kode    TEXT,
            PRIMARY KEY(user_id, kode)
        )""")
        c.execute("""CREATE TABLE IF NOT EXISTS earnings_alerted(
            kode TEXT, kuartal TEXT, PRIMARY KEY(kode, kuartal)
        )""")
        conn.commit(); conn.close()
    except Exception as e:
        logger.error("db_earnings_setup: %s", e)

db_earnings_setup()

def get_earnings_deadlines(tahun=None):
    """Return jadwal deadline laporan keuangan IDX per kuartal."""
    if tahun is None:
        tahun = now_wib().year
    return [
        ("Q4 "+str(tahun-1), _dt.date(tahun,  3, 31)),
        ("Q1 "+str(tahun),   _dt.date(tahun,  4, 30)),
        ("Q2 "+str(tahun),   _dt.date(tahun,  7, 31)),
        ("Q3 "+str(tahun),   _dt.date(tahun, 10, 31)),
        ("Q4 "+str(tahun),   _dt.date(tahun+1, 3, 31)),
    ]

def cek_earnings_alert():
    """
    Cek apakah ada deadline laporan keuangan dalam 3 hari ke depan.
    Kalau ada, kirim alert ke semua user yang punya saham bersangkutan di watchlist.
    Dipanggil dari cek_jadwal_auto setiap hari jam 09:00.
    """
    try:
        hari_ini   = now_wib().date()
        deadlines  = get_earnings_deadlines()
        alert_days = 3  # H-3 sebelum deadline

        conn = sqlite3.connect(DB_FILE, check_same_thread=False)
        c    = conn.cursor()

        for kuartal, deadline in deadlines:
            sisa_hari = (deadline - hari_ini).days
            if sisa_hari < 0 or sisa_hari > alert_days:
                continue

            # Cek apakah sudah pernah alert kuartal ini
            c.execute("SELECT 1 FROM earnings_alerted WHERE kuartal=?", (kuartal,))
            if c.fetchone():
                continue

            # Ambil semua user yang punya watchlist earnings
            c.execute("SELECT DISTINCT user_id, kode FROM earnings_watchlist")
            user_saham = c.fetchall()

            if not user_saham:
                # Alert umum ke topic Chart Konfirm
                pesan  = f"📅 *EARNINGS ALERT — {kuartal}*\n"
                pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
                pesan += f"⏰ Deadline rilis LK: *{deadline.strftime('%d %B %Y')}*\n"
                pesan += f"📆 Sisa waktu: *{sisa_hari} hari*\n\n"
                pesan += f"Perusahaan wajib merilis Laporan Keuangan {kuartal} sebelum tanggal ini.\n"
                pesan += f"💡 Saham yang LK-nya bagus biasanya naik setelah rilis.\n"
                pesan += f"Pantau saham watchlist kamu!"
                dest_radar = {{"type": "topic", "thread_id": THREAD_ID_RADAR}}
                dest_kirim_teks(dest_radar, pesan)
            else:
                # Group per user
                user_dict = {{}}
                for uid, kode in user_saham:
                    user_dict.setdefault(uid, []).append(kode)

                for uid, kode_list in user_dict.items():
                    pesan  = f"📅 *EARNINGS ALERT — {kuartal}*\n"
                    pesan += f"Deadline rilis LK: *{deadline.strftime('%d %B %Y')}* (H-{sisa_hari})\n\n"
                    pesan += f"Saham watchlist kamu yang perlu dipantau:\n"
                    for kode in kode_list[:10]:
                        pesan += f"  • *{kode}* — cek apakah LK sudah rilis\n"
                    pesan += f"\n💡 LK bagus = potensi naik. LK jelek = waspada turun."
                    kirim_dm(uid, pesan)

            # Tandai sudah alert
            c.execute("INSERT OR IGNORE INTO earnings_alerted(kode,kuartal) VALUES(?,?)",
                      ("ALL", kuartal))
            conn.commit()

        conn.close()
    except Exception as e:
        logger.error("cek_earnings_alert: %s", e)

def proses_earnings(user_id, args, dest):
    """
    /earnings                  — lihat jadwal deadline LK terdekat
    /earnings watch KODE       — tambah saham ke watchlist earnings
    /earnings unwatch KODE     — hapus dari watchlist
    /earnings list             — lihat watchlist kamu
    """
    uid = str(user_id)
    fh  = lambda v: f"{int(v):,}".replace(",",".")

    hari_ini  = now_wib().date()
    deadlines = get_earnings_deadlines()

    if not args or args[0].lower() in ["", "info", "jadwal"]:
        pesan  = f"📅 *EARNINGS CALENDAR IDX*\n"
        pesan += f"━━━━━━━━━━━━━━━━━━━━━━\n"
        pesan += f"Jadwal deadline rilis Laporan Keuangan:\n\n"

        for kuartal, deadline in deadlines:
            sisa = (deadline - hari_ini).days
            if sisa < 0:
                status = "✅ Sudah lewat"
            elif sisa == 0:
                status = "🔴 HARI INI!"
            elif sisa <= 3:
                status = f"⚠️ H-{sisa} — SEGERA!"
            elif sisa <= 14:
                status = f"🟡 H-{sisa}"
            else:
                status = f"🟢 H-{sisa}"
            pesan += f"*{kuartal}*  —  {deadline.strftime('%d %b %Y')}  {status}\n"

        pesan += f"\n💡 Gunakan `/earnings watch KODE` untuk alert personal"
        dest_kirim_teks(dest, pesan)

    elif args[0].lower() == "watch" and len(args) >= 2:
        kode_e = args[1].upper()
        try:
            conn = sqlite3.connect(DB_FILE, check_same_thread=False)
            c = conn.cursor()
            c.execute("INSERT OR IGNORE INTO earnings_watchlist(user_id,kode) VALUES(?,?)",
                      (uid, kode_e))
            conn.commit(); conn.close()
            dest_kirim_teks(dest,
                f"✅ *{kode_e}* ditambahkan ke earnings watchlist\n"
                f"Kamu akan dapat alert H-3 sebelum deadline LK")
        except Exception as e:
            dest_kirim_teks(dest, f"❌ Error: {str(e)[:60]}")

    elif args[0].lower() == "unwatch" and len(args) >= 2:
        kode_e = args[1].upper()
        try:
            conn = sqlite3.connect(DB_FILE, check_same_thread=False)
            c = conn.cursor()
            c.execute("DELETE FROM earnings_watchlist WHERE user_id=? AND kode=?", (uid, kode_e))
            conn.commit(); conn.close()
            dest_kirim_teks(dest, f"✅ *{kode_e}* dihapus dari earnings watchlist")
        except Exception as e:
            dest_kirim_teks(dest, f"❌ Error: {str(e)[:60]}")

    elif args[0].lower() == "list":
        try:
            conn = sqlite3.connect(DB_FILE, check_same_thread=False)
            c = conn.cursor()
            c.execute("SELECT kode FROM earnings_watchlist WHERE user_id=? ORDER BY kode", (uid,))
            rows = c.fetchall(); conn.close()
            if rows:
                kode_list = [r[0] for r in rows]
                dest_kirim_teks(dest,
                    f"📋 *Earnings Watchlist kamu:*\n" +
                    "\n".join(f"  • *{k}*" for k in kode_list))
            else:
                dest_kirim_teks(dest,
                    "_(Watchlist kosong)_\n"
                    "Tambahkan dengan `/earnings watch KODE`")
        except Exception as e:
            dest_kirim_teks(dest, f"❌ Error: {str(e)[:60]}")
    else:
        dest_kirim_teks(dest,
            "❌ Perintah tidak dikenal.\n"
            "Ketik `/earnings` untuk bantuan.")

def cek_jadwal_auto():
    """Cek jadwal: rekomendasi 08:00/15:00 + scan sinyal 16:15 + radar V3 09:05/13:35."""
    now  = now_wib(); hari = now.weekday()
    if hari > 4: return

    # Skip semua auto task saat mode libur
    if db_kv_get("holiday_mode") == "1":
        return

    jam_mnt = now.strftime("%H:%M"); tgl_str = now.strftime("%Y-%m-%d")
    for jr in JADWAL_REKOM:
        key = f"REKOM_{jr}_{tgl_str}"
        if jam_mnt == jr and key not in jadwal_sudah_scan:
            jadwal_sudah_scan.add(key)
            sesi = "pagi" if jr == "08:00" else "sore"
            print(f"⏰ AUTO REKOMENDASI [{jr}] sesi={sesi}")
            threading.Thread(target=jalankan_auto_rekomendasi, args=(sesi,), daemon=True).start()
    global sedang_scan
    if sedang_scan or bot_stop: return
    for jadwal in JADWAL_AUTO:
        key = f"SCAN_{jadwal}_{tgl_str}"
        if jam_mnt == jadwal and key not in jadwal_sudah_scan:
            jadwal_sudah_scan.add(key)
            dest_auto = {"type": "topic", "thread_id": THREAD_ID_RADAR}
            label = "🌆 Penutupan Bursa"
            send_telegram_message(
                f"⏰ *Auto Scan {label}*\n"
                f"🕐 {jadwal} WIB — {now.strftime('%d-%m-%Y')}\n"
                f"📋 {len(watchlist)} saham akan dicek..."
            )
            print(f"⏰ AUTO SCAN [{jadwal}] dimulai...")
            threading.Thread(target=jalankan_scan, args=(f"Auto {label}", dest_auto), daemon=True).start()

    # ── Auto Radar V3 Quant Engine ─────────────────────────

    # ── Auto Rekap Buyer Dominant — jam 18:30 WIB ───────────
    key_rekap = f"REKAP_18:30_{tgl_str}"
    if jam_mnt == "18:30" and key_rekap not in jadwal_sudah_scan:
        jadwal_sudah_scan.add(key_rekap)
        def _auto_rekap():
            dest_rekap = _get_rekap_dest()
            dest_kirim_teks(dest_rekap,
                f"🎯 *AUTO REKAP — BUYER DOMINANT*\n"
                f"📅 {now_wib().strftime('%d/%m/%Y %H:%M')} WIB\n"
                f"🔍 Mencari kandidat buyer dominant...")
            universe = list(watchlist)  # scan semua saham
            kandidat = []
            with ThreadPoolExecutor(max_workers=15) as _ex:
                _futs = {_ex.submit(cek_buyer_dominant, tk): tk for tk in universe}
                for _f in as_completed(_futs):
                    try:
                        h = _f.result(timeout=20)
                        if h: kandidat.append(h)
                    except: pass
            kandidat.sort(key=lambda x: x["skor"], reverse=True)
            top = kandidat[:10]
            if not top:
                dest_kirim_teks(dest_rekap, "😴 Tidak ada kandidat buyer dominant pagi ini.")
                return
            fh_r = lambda v: f"{int(v):,}".replace(",",".")
            tgl_r = now_wib().strftime("%d/%m/%Y %H:%M")
            msg_sum  = f"🎯 *BUYER DOMINANT — {len(kandidat)} kandidat*\n"
            msg_sum += f"📅 {tgl_r} WIB  |  Top {len(top)}:\n━━━━━━━━━━━━━━━━━━━━━━\n"
            for i, h in enumerate(top, 1):
                emj      = "📈" if h["gain"] >= 0 else "📉"
                fib_str  = f"Fib:{h.get('fib_pos',0):.0f}%"
                accum_str= f"Accum:{h.get('pct_accum',0):.0f}%"
                jalur_str= "🔄" if h.get("jalur") == "reversal" else "✅"
                msg_sum += (f"*{i}.* *{h['kode']}*  Rp {fh_r(int(h['harga']))}  "
                            f"{emj}{h['gain']:+.2f}%  {jalur_str}\n"
                            f"   RSI:{h['rsi']:.0f}  Vol:{h['vol_x']:.1f}x  "
                            f"{fib_str}  {accum_str}\n")
            msg_sum += f"\n📊 Pipeline rekap dikirim di bawah..."
            dest_kirim_teks(dest_rekap, msg_sum)
            for i, h in enumerate(top, 1):
                _rekap_satu_saham(h["kode"], dest_rekap, nomor=i, total=len(top))
                time.sleep(2.0)
            dest_kirim_teks(dest_rekap,
                f"✅ *Auto Rekap selesai — {len(top)} saham*\n"
                f"⏰ {now_wib().strftime('%H:%M:%S')} WIB")
            logger.info("Auto rekap selesai: %d saham", len(top))
        threading.Thread(target=_auto_rekap, daemon=True).start()
        logger.info("🎯 Auto rekap buyer dominant dimulai (09:30)")

    # ── Earnings Calendar Alert — tiap hari jam 09:00 ────────
    if jam_mnt == "09:00":
        key_ea = f"EARNINGS_{tgl_str}"
        if key_ea not in jadwal_sudah_scan:
            jadwal_sudah_scan.add(key_ea)
            threading.Thread(target=cek_earnings_alert, daemon=True).start()

    # ── Weekly Summary — Jumat jam 15:30 WIB ─────────────────
    if hari == 4 and jam_mnt == "15:30":  # 4 = Jumat
        key_ws = f"WEEKLY_{tgl_str}"
        if key_ws not in jadwal_sudah_scan:
            jadwal_sudah_scan.add(key_ws)
            threading.Thread(target=kirim_weekly_summary, daemon=True).start()
            logger.info("📊 Weekly summary dimulai (Jumat 15:30)")

    for jadwal_rv3 in JADWAL_RADAR:
        key_rv3 = f"RADARV3_{jadwal_rv3}_{tgl_str}"
        if jam_mnt == jadwal_rv3 and key_rv3 not in jadwal_sudah_scan:
            jadwal_sudah_scan.add(key_rv3)
            dest_rv3 = _get_radar_dest()   # ikuti /setradartopic — default Chart Konfirm
            sesi_rv3 = "🌅 PRE-MARKET" if "08" in jadwal_rv3 else "☀️ Siang"
            print(f"⚡ AUTO RADAR V8 PRE-MARKET [{jadwal_rv3}] dimulai...")
            send_telegram_message(
                f"⚡ *Auto Radar V8 — {sesi_rv3}*\n"
                f"🕐 {jadwal_rv3} WIB — {now.strftime('%d-%m-%Y')}\n"
                f"🔍 Scanning {len(watchlist)} saham *sebelum pasar buka*\n"
                f"📌 Entry zone valid: Rp prev_close s/d +2%\n"
                f"⏰ Pasar buka 09:00 — siapkan order sekarang!"
            )
            threading.Thread(
                target=jalankan_radar_v3,
                args=(dest_rv3,),
                daemon=True
            ).start()

# ============================================================
# ═══════════════════════════════════════════════════════════
#   🧲 ACCUMULATION → EXPANSION SCANNER   (/ae)
#   Data: Yahoo Finance harian (delayed) → untuk WATCHLIST,
#   BUKAN trigger entry real-time.
# ═══════════════════════════════════════════════════════════
# ============================================================
AE_MIN_PRICE     = 50                 # harga minimum (Rp)
AE_MIN_TURNOVER  = 1_000_000_000      # median nilai transaksi 20 hari (Rp)
AE_SCORE_WATCH   = 80                 # >= ini → MOMENTUM WATCH
AE_SCORE_SETUP   = 60                 # >= ini → SETUP


def _ae_ema(s, n):
    return s.ewm(span=n, adjust=False).mean()


def _ae_rsi(close, n=14):
    d    = close.diff()
    up   = d.clip(lower=0).ewm(alpha=1 / n, adjust=False).mean()
    down = (-d.clip(upper=0)).ewm(alpha=1 / n, adjust=False).mean()
    rs   = up / down.replace(0, np.nan)
    return 100 - 100 / (1 + rs)


def _ae_analisa(df):
    """
    Hitung skor Accumulation → Expansion (0-100) dari data harian.
    Return dict hasil, atau {"skip": alasan} kalau tidak lolos filter,
    atau None kalau data kurang.

    Akumulasi dihitung dari data SEBELUM hari ini (pre), supaya candle
    breakout hari ini tidak menggelembungkan CMF/OBV.
    """
    if df is None or len(df) < 62:
        return None

    d = df.copy()
    o, h, l, c = d["Open"], d["High"], d["Low"], d["Close"]
    v = d["Volume"].astype(float)

    harga     = float(c.iloc[-1])
    turnover  = float((c * v).tail(20).median())
    if harga < AE_MIN_PRICE:
        return {"skip": f"harga < Rp{AE_MIN_PRICE}"}
    if turnover < AE_MIN_TURNOVER:
        return {"skip": f"likuiditas rendah (median Rp{turnover/1e9:.2f}M/hari)"}

    pre = d.iloc[:-1]
    pc, ph, pl, pv = pre["Close"], pre["High"], pre["Low"], pre["Volume"].astype(float)

    # ── A. AKUMULASI (40) ────────────────────────────────────
    hh60 = float(ph.tail(60).max())
    ll60 = float(pl.tail(60).min())
    rng  = max(hh60 - ll60, 1e-9)
    base_pct   = rng / ll60 * 100
    pos_dlm    = (float(pc.iloc[-1]) - ll60) / rng          # posisi harga kemarin di range 60D
    near_base  = (base_pct <= 45) and (pos_dlm <= 0.65)

    mfm = ((pc - pl) - (ph - pc)) / (ph - pl).replace(0, np.nan)
    cmf = float((mfm * pv).tail(20).sum() / max(pv.tail(20).sum(), 1))
    cmf_pos = cmf > 0.05

    obv      = (np.sign(pc.diff().fillna(0)) * pv).cumsum()
    obv_up   = bool(obv.iloc[-1] > obv.iloc[-21] and obv.iloc[-1] > obv.rolling(20).mean().iloc[-1])

    tr = pd.concat([ph - pl, (ph - pc.shift()).abs(), (pl - pc.shift()).abs()], axis=1).max(axis=1)
    atr_ratio = float(tr.tail(10).mean() / max(tr.tail(40).mean(), 1e-9))
    compress  = atr_ratio < 0.85

    sc_acc = 10 * near_base + 10 * cmf_pos + 10 * obv_up + 10 * compress

    # ── B. BREAKOUT (30) ─────────────────────────────────────
    hh20 = float(ph.tail(20).max())
    b20  = harga > hh20
    b60  = harga > hh60
    rg   = max(float(h.iloc[-1] - l.iloc[-1]), 1e-9)
    body = abs(float(c.iloc[-1] - o.iloc[-1])) / rg
    candle_kuat = (body > 0.60) and (c.iloc[-1] > o.iloc[-1])
    wick_atas   = (float(h.iloc[-1]) - max(float(o.iloc[-1]), harga)) / rg

    sc_brk = 10 * b20 + 10 * b60 + 10 * candle_kuat

    # ── C. VOLUME (20) ───────────────────────────────────────
    rvol = float(v.iloc[-1] / max(v.iloc[-21:-1].mean(), 1))
    sc_vol = 10 * (rvol > 2) + 10 * (rvol > 3)

    # ── D. MOMENTUM (10) ─────────────────────────────────────
    rsi   = float(_ae_rsi(c).iloc[-1])
    e20   = float(_ae_ema(c, 20).iloc[-1])
    e50   = float(_ae_ema(c, 50).iloc[-1])
    rsi_ok   = 55 <= rsi <= 75
    trend_ok = harga > e20 > e50
    sc_mom = 5 * rsi_ok + 5 * trend_ok

    score = int(sc_acc + sc_brk + sc_vol + sc_mom)
    gain  = (harga / float(c.iloc[-2]) - 1) * 100

    if score >= AE_SCORE_WATCH:
        status = "MOMENTUM WATCH"
    elif score >= AE_SCORE_SETUP:
        status = "SETUP"
    else:
        status = "LEMAH"

    warn = []
    if wick_atas > 0.45:
        warn.append("wick atas panjang (rawan rejection)")
    if b20 and rvol < 1.5:
        warn.append("breakout tanpa volume")
    if gain > 20:
        warn.append("sudah naik >20% hari ini, rawan kejar pucuk")

    return {
        "score": score, "status": status, "harga": harga, "gain": gain,
        "rvol": rvol, "rsi": rsi, "cmf": cmf, "atr_ratio": atr_ratio,
        "base_pct": base_pct, "hh20": hh20, "hh60": hh60, "ll60": ll60,
        "turnover": turnover, "body": body,
        "cek": {   # (label, lolos)
            "Base 60D sideways": near_base, "CMF positif": cmf_pos,
            "OBV akumulasi": obv_up, "Volatilitas mengerut": compress,
            "Break high 20D": b20, "Break high 60D": b60,
            "Candle body kuat": candle_kuat, f"RVOL {rvol:.1f}x": rvol > 2,
            "RSI 55-75": rsi_ok, "Harga>EMA20>EMA50": trend_ok,
        },
        "sub": {"Akumulasi": (sc_acc, 40), "Breakout": (sc_brk, 30),
                "Volume": (sc_vol, 20), "Momentum": (sc_mom, 10)},
        "warn": warn,
    }


def _ae_scan_satu(ticker):
    try:
        df, _ = _ambil_data_harian_radar(ticker, "6mo")
        a = _ae_analisa(df)
        if a and "score" in a:
            a["kode"] = ticker.replace(".JK", "")
            a["df"]   = df
            return a
    except Exception as e:
        logger.debug("ae_scan %s: %s", ticker, e)
    return None


def _ae_chart(kode, df, a, n=70):
    """Candlestick + base 60D + level breakout + EMA + volume (dark theme)."""
    _apply_dark_rc()
    d = df.tail(n).copy()
    x = np.arange(len(d))
    e20 = _ae_ema(df["Close"], 20).tail(n).values
    e50 = _ae_ema(df["Close"], 50).tail(n).values

    fig = plt.figure(figsize=(9, 6.6), facecolor=THEME["bg"])
    gs  = gridspec.GridSpec(2, 1, height_ratios=[3.2, 1], hspace=0.05, figure=fig)
    ax  = fig.add_subplot(gs[0]); axv = fig.add_subplot(gs[1], sharex=ax)
    for _a in (ax, axv):
        _a.set_facecolor(THEME["card"])
        _a.grid(True, color=THEME["grid"], ls=":", lw=0.6)
        for s in _a.spines.values():
            s.set_color(THEME["border"])
        _a.tick_params(colors=THEME["sub"], labelsize=7.5)
        _a.yaxis.tick_right()

    up = d["Close"].values >= d["Open"].values
    col = np.where(up, THEME["up"], THEME["dn"])
    ax.vlines(x, d["Low"].values, d["High"].values, colors=col, lw=0.9, zorder=2)
    ax.bar(x, (d["Close"] - d["Open"]).abs().clip(lower=1e-9).values,
           bottom=np.minimum(d["Open"].values, d["Close"].values),
           width=0.65, color=col, zorder=3)

    # base 60D (kotak akumulasi) + level breakout
    ax.axhspan(a["ll60"], a["hh60"], color=THEME["acc"], alpha=0.06, zorder=1)
    ax.axhline(a["hh60"], color=THEME["prp"], lw=1.0, ls="--", zorder=2)
    ax.axhline(a["hh20"], color=THEME["ylw"], lw=1.0, ls="--", zorder=2)
    xr = len(d) - 0.3
    ax.text(xr, a["hh60"], " High 60D", color=THEME["prp"], fontsize=7, va="bottom", ha="right")
    ax.text(xr, a["hh20"], " High 20D", color=THEME["ylw"], fontsize=7, va="bottom", ha="right")
    ax.plot(x, e20, color=THEME["gold"], lw=1.0, label="EMA20", zorder=4)
    ax.plot(x, e50, color=THEME["orng"], lw=1.0, label="EMA50", zorder=4)
    ax.legend(loc="upper left", fontsize=7, framealpha=0.4)
    ax.set_xlim(-1, len(d) + 1)
    plt.setp(ax.get_xticklabels(), visible=False)

    # volume + garis rata-rata 20 hari
    axv.bar(x, d["Volume"].values, width=0.65, color=col, alpha=0.85)
    vavg = float(df["Volume"].iloc[-21:-1].mean())
    axv.axhline(vavg, color=THEME["acc"], lw=0.9, ls=":")
    axv.text(0.01, 0.82, f"Vol rata-rata 20D  •  RVOL hari ini {a['rvol']:.1f}x",
             transform=axv.transAxes, color=THEME["sub"], fontsize=7)
    axv.yaxis.set_major_formatter(
        matplotlib.ticker.FuncFormatter(lambda y, _: f"{y/1e6:.0f}M" if y >= 1e6 else f"{y/1e3:.0f}K"))
    tick_i = list(range(0, len(d), 10))
    axv.set_xticks(tick_i)
    axv.set_xticklabels([d.index[i].strftime("%d %b") for i in tick_i])

    warna = THEME["grn"] if a["score"] >= AE_SCORE_WATCH else (
        THEME["ylw"] if a["score"] >= AE_SCORE_SETUP else THEME["red"])
    fig.suptitle(f"{kode}   Accumulation → Expansion   |   SCORE {a['score']}/100  ({a['status']})",
                 color=warna, fontsize=11, fontweight="bold", x=0.5, y=0.955)
    ax.set_title(f"Rp{a['harga']:,.0f}  ({a['gain']:+.1f}%)   •   RSI {a['rsi']:.0f}   •   CMF {a['cmf']:+.2f}   •   base 60D {a['base_pct']:.0f}%",
                 color=THEME["sub"], fontsize=8, loc="left")
    _add_watermark(ax)
    fig.text(0.5, 0.005, "Data Yahoo (delayed) • watchlist, bukan sinyal beli",
             ha="center", color=THEME["sub"], fontsize=6.5, alpha=0.7)

    buf = io.BytesIO()
    fig.savefig(buf, format="png", dpi=110, bbox_inches="tight", facecolor=THEME["bg"])
    plt.close(fig)
    buf.seek(0)
    return buf


def _ae_kartu(a):
    """Teks kartu ringkas (Markdown aman: tanpa underscore)."""
    cek = "\n".join(f"{'✅' if ok else '▫️'} {lbl}" for lbl, ok in a["cek"].items())
    sub = "  ".join(f"{k} {s}/{m}" for k, (s, m) in a["sub"].items())
    w   = ("\n⚠️ " + "; ".join(a["warn"])) if a["warn"] else ""
    return (f"*{a['kode']}*  —  *{a['score']}/100*  ({a['status']})\n"
            f"Rp{a['harga']:,.0f} ({a['gain']:+.1f}%)  •  RVOL {a['rvol']:.1f}x  •  RSI {a['rsi']:.0f}\n"
            f"{sub}\n{cek}\n🕐 Retest: WAIT{w}")


def _ae_kirim_chart(dest, a):
    try:
        buf = _ae_chart(a["kode"], a["df"], a)
        cap = _ae_kartu(a)
        dest_kirim_foto_buf(dest, buf, cap[:1000])
    except Exception as e:
        logger.warning("ae chart %s: %s", a.get("kode"), e)
        dest_kirim_teks(dest, _ae_kartu(a))


def proses_cmd_ae_scan(dest, top_n=5, n_chart=3, min_score=AE_SCORE_SETUP):
    """Scan seluruh watchlist, ranking skor, kirim ringkasan + chart top N."""
    kodes = watchlist.copy()
    dest_kirim_teks(dest,
        f"🧲 *ACCUMULATION → EXPANSION*\n🔍 Scanning *{len(kodes)}* saham (data harian Yahoo)...")
    t0, hasil = time.time(), []
    with ThreadPoolExecutor(max_workers=12) as ex:
        futs = [ex.submit(_ae_scan_satu, t) for t in kodes]
        for f in as_completed(futs):
            try:
                r = f.result(timeout=30)
                if r and r["score"] >= min_score:
                    hasil.append(r)
            except Exception:
                pass
    hasil.sort(key=lambda r: (r["score"], r["rvol"]), reverse=True)
    top = hasil[:top_n]
    dur = round(time.time() - t0, 1)
    if not top:
        dest_kirim_teks(dest,
            f"📊 *AE Scan selesai* ({dur}s)\nTidak ada saham dengan skor ≥ {min_score}.")
        return
    pesan = (f"*▸ ACCUMULATION → EXPANSION — TOP {len(top)}*\n"
             f"📅 {now_wib().strftime('%d-%m-%Y %H:%M')} WIB  •  {dur}s  •  {len(hasil)} kandidat\n"
             f"━━━━━━━━━━━━━━━━━━━━━━\n")
    for i, r in enumerate(top, 1):
        pesan += (f"{i}. *{r['kode']}*  {r['score']}/100  {r['status']}\n"
                  f"    Rp{r['harga']:,.0f} ({r['gain']:+.1f}%)  RVOL {r['rvol']:.1f}x\n")
    pesan += ("━━━━━━━━━━━━━━━━━━━━━━\n"
              "⚠️ Watchlist, bukan BUY. Data Yahoo delayed: konfirmasi di sesi, tunggu retest/hold.")
    dest_kirim_teks(dest, pesan)
    for r in top[:n_chart]:
        _ae_kirim_chart(dest, r)


def proses_cmd_ae_kode(kode, dest):
    """Analisa satu saham + chart."""
    kode = kode.upper().replace(".JK", "")
    dest_kirim_teks(dest, f"🧲 Menganalisa *{kode}*...")
    df, _ = _ambil_data_harian_radar(kode + ".JK", "6mo")
    a = _ae_analisa(df)
    if a is None:
        dest_kirim_teks(dest, f"❌ Data *{kode}* tidak cukup (butuh minimal 62 hari bursa)."); return
    if "skip" in a:
        dest_kirim_teks(dest, f"🚫 *{kode}* tidak lolos filter: {a['skip']}."); return
    a["kode"], a["df"] = kode, df
    _ae_kirim_chart(dest, a)


